// EXPERIMENTAL, standalone A/B sibling of mv_fp32_16_transpose_
// atomiconly_scaled_mblock_fast_normal_vec4_kernel above -- byte-for-
// byte IDENTICAL structure (same M_BLOCK/shared-mem staging, same vec4/
// ushort4 vectorized-load-with-alignment-check playbook), the ONLY
// change is decoding via fp32_16_combine_fast_normal_wrapborrow instead
// of fp32_16_combine_fast_normal -- a bit-identical (exhaustively
// verified, see its own comment in fp32_16_pack.hpp) but structurally
// different reformulation that replaces the is_carry ternary/SEL logic
// with branchless wraparound-subtraction arithmetic. Motivated by a
// direct SASS instruction-count profile of the sibling kernel above
// (cuobjdump --dump-sass on a compiled .cubin): 736 total instructions,
// dominated by integer/bit-manipulation ops (132 LOP3.LUT, 80 IADD3, 57
// SHF.R.U32.HI, 53 IMAD.SHL.U32, 38 SEL) vs only 19 FFMA -- i.e. decode
// overhead, not the actual multiply-accumulate math, dominates this
// kernel's static instruction count. This experiment targets exactly
// the is_carry branch's own share of that overhead.
//
// UNTESTED: no SASS re-profile or GEMV performance measurement has been
// run yet for this variant.
__global__ void mv_fp32_16_transpose_atomiconly_scaled_mblock_fast_normal_wrapborrow_vec4_kernel(
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr,
    const float* __restrict__ x, float* __restrict__ y,
    int m, int k, int M_BLOCK, float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    // BUG FIX (see mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_
    // vec4_split_kernel's own comment for the full derivation): col_valid
    // is deliberately NOT an early return, so every thread in the block
    // reaches __syncthreads() below regardless of whether its own column
    // is in range -- an early return here (when k is not a multiple of
    // warpsPerBlock) would leave sx partially unfilled for the surviving
    // warps to read as uninitialized shared memory.
    const int col = blockIdx.y * warpsPerBlock + warpId;
    const bool col_valid = col < k;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;  // safe: block-uniform, depends only on blockIdx.x

    extern __shared__ float sx[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    const int sBeg = (mStart + 3) & ~3;
    const int sEnd = mEnd & ~3;

    for (int r = mStart + tid; r < min(sBeg, mEnd); r += nt) {
        sx[r - mStart] = __ldg(&x[r]);
    }
    if (sBeg < sEnd) {
        const uintptr_t pXg = reinterpret_cast<uintptr_t>(&x[sBeg]);
        const uintptr_t pXs = reinterpret_cast<uintptr_t>(&sx[sBeg - mStart]);
        const bool stageAligned16 = ((pXg & 0xF) == 0) && ((pXs & 0xF) == 0);

        if (stageAligned16) {
            for (int r = sBeg + tid * 4; r + 3 < sEnd; r += nt * 4) {
                const float4 xv = *reinterpret_cast<const float4*>(&x[r]);
                *reinterpret_cast<float4*>(&sx[r - mStart]) = xv;
            }
        } else {
            for (int r = sBeg + tid; r < sEnd; r += nt) {
                sx[r - mStart] = __ldg(&x[r]);
            }
        }
    }
    for (int r = sEnd + tid; r < mEnd; r += nt) {
        sx[r - mStart] = __ldg(&x[r]);
    }
    __syncthreads();

    if (!col_valid) return;  // safe now: every thread already reached the barrier above

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    float accum = 0.f;

    const int vBeg = (mStart + 3) & ~3;
    const int vEnd = mEnd & ~3;

    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        float a = fp32_16_combine_fast_normal_wrapborrow(wh[idx], wr[idx]);
        accum = fmaf(a, sx[r - mStart], accum);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pWh = reinterpret_cast<uintptr_t>(&wh[idxBeg]);
        const uintptr_t pWr = reinterpret_cast<uintptr_t>(&wr[idxBeg]);
        const uintptr_t pX = reinterpret_cast<uintptr_t>(&sx[vBeg - mStart]);
        const bool aligned = ((pWh & 0x7) == 0) && ((pWr & 0x7) == 0) && ((pX & 0xF) == 0);

        if (aligned) {
            for (int r = vBeg + lane * 4; r + 3 < vEnd; r += 32 * 4) {
                const size_t idx = colBase + static_cast<size_t>(r);
                const ushort4 whv = *reinterpret_cast<const ushort4*>(&wh[idx]);
                const ushort4 wrv = *reinterpret_cast<const ushort4*>(&wr[idx]);
                const float4 xv = *reinterpret_cast<const float4*>(&sx[r - mStart]);
                float a0 = fp32_16_combine_fast_normal_wrapborrow(whv.x, wrv.x);
                float a1 = fp32_16_combine_fast_normal_wrapborrow(whv.y, wrv.y);
                float a2 = fp32_16_combine_fast_normal_wrapborrow(whv.z, wrv.z);
                float a3 = fp32_16_combine_fast_normal_wrapborrow(whv.w, wrv.w);
                accum = fmaf(a0, xv.x, accum);
                accum = fmaf(a1, xv.y, accum);
                accum = fmaf(a2, xv.z, accum);
                accum = fmaf(a3, xv.w, accum);
            }
        } else {
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                float a = fp32_16_combine_fast_normal_wrapborrow(wh[idx], wr[idx]);
                accum = fmaf(a, sx[r - mStart], accum);
            }
        }
    }

    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        float a = fp32_16_combine_fast_normal_wrapborrow(wh[idx], wr[idx]);
        accum = fmaf(a, sx[r - mStart], accum);
    }

    unsigned mask2 = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask2, accum, off);

    if (lane == 0) atomicAdd(&y[col], alpha * accum);
}

