// ====================================================================
// tomos::cuda::experimental -- every dense GEMM kernel/wrapper in this
// range EXCEPT the small set actually used by a plotted benchmark or by
// the production dispatch layer (src/dispatch/fp32_16_registries.cpp),
// which are re-exposed via thin forwarding wrappers right after this
// namespace closes. Purely organizational -- no behavior change. GEVM
// (mv_-prefixed) content immediately before and after this namespace is
// untouched, left at plain tomos::cuda scope as always.
// ====================================================================
namespace experimental {

// One thread per output element C(i, j); mirrors the simple, non-tiled style
// already used for mm_csr_csr in this codebase rather than a tensor-core /
// shared-memory-tiled kernel.
__global__ void mm_fp32_16_accurate_kernel(
    TransposeType transA, TransposeType transB, double alpha, size_t m,
    size_t k, size_t n, const uint16_t* wh, const uint16_t* wr, size_t ld_a,
    const float* B, size_t ld_b, double beta, float* C, size_t ld_c) {
    size_t i = blockIdx.y * blockDim.y + threadIdx.y;
    size_t j = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= m || j >= n) return;

    double acc = 0.0;
    for (size_t l = 0; l < k; ++l) {
        size_t a_row = (transA == TransposeType::NO_TRANSPOSE) ? i : l;
        size_t a_col = (transA == TransposeType::NO_TRANSPOSE) ? l : i;
        size_t idx = a_row + a_col * ld_a;
        double a_val = static_cast<double>(fp32_16_combine(wh[idx], wr[idx]));
        double b_val = (transB == TransposeType::NO_TRANSPOSE)
                          ? static_cast<double>(B[l + j * ld_b])
                          : static_cast<double>(B[j + l * ld_b]);
        acc += a_val * b_val;
    }
    C[i + j * ld_c] = (beta != 0.0)
                          ? static_cast<float>(alpha * acc + beta * static_cast<double>(
                                                                 C[i + j * ld_c]))
                          : static_cast<float>(alpha * acc);
}

void mm_fp32_16_accurate(TransposeType transA, TransposeType transB,
                         double alpha, dim<2> size_A, const uint16_t* wh,
                         const uint16_t* wr, size_t ld_a, dim<2> size_B,
                         const float* B, size_t ld_b, double beta, float* C,
                         size_t ld_c) {
    size_t m = (transA == TransposeType::NO_TRANSPOSE) ? size_A[0] : size_A[1];
    size_t k = (transA == TransposeType::NO_TRANSPOSE) ? size_A[1] : size_A[0];
    size_t n = (transB == TransposeType::NO_TRANSPOSE) ? size_B[1] : size_B[0];

    dim3 threads(32, 8);
    dim3 blocks((n + threads.x - 1) / threads.x, (m + threads.y - 1) / threads.y);
    mm_fp32_16_accurate_kernel<<<blocks, threads>>>(
        transA, transB, alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
    cudaDeviceSynchronize();
}

namespace {
constexpr int kMmFp32_16BM = 128;
constexpr int kMmFp32_16BN = 128;
constexpr int kMmFp32_16BK = 8;
constexpr int kMmFp32_16TM = 8;
constexpr int kMmFp32_16TN = 8;
}  // namespace

// Shared-memory-tiled version of mm_fp32_16_accurate_kernel, same
// register-blocked (8x8 per thread) structure as gemm_fp32_tiled_kernel in
// mm_cuda_kernels.cu. The only real change from the untiled kernel above is
// A's load: each wh/wr pair is decoded into a float via fp32_16_combine
// ONCE, when it's loaded into shared memory, instead of once per USE --
// mm_fp32_16_accurate_kernel has zero reuse at all (every thread computing
// a different output column j independently re-reads and re-decodes the
// same A(i,l)), whereas here kBN/kTN = 16 threads share one decode. That
// eliminated redundant global traffic AND redundant decode work is the
// bulk of why the untiled kernel was ~15x further behind cuBLAS than the
// plain-fp32 naive kernel was.
__global__ void mm_fp32_16_tiled_kernel(double alpha, size_t m, size_t k, size_t n,
                                        const uint16_t* __restrict__ wh,
                                        const uint16_t* __restrict__ wr, size_t ld_a,
                                        const float* __restrict__ B, size_t ld_b,
                                        double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ float As[kMmFp32_16BK][kMmFp32_16BM];
    __shared__ float Bs[kMmFp32_16BK][kMmFp32_16BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16BN;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * (kMmFp32_16BN / kMmFp32_16TN) + tx;
    constexpr int kNumThreads =
        (kMmFp32_16BM / kMmFp32_16TM) * (kMmFp32_16BN / kMmFp32_16TN);

    float acc[kMmFp32_16TM][kMmFp32_16TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16TN; ++j) acc[i][j] = 0.0f;

    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16BK) {
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16BM * kMmFp32_16BK; idx += kNumThreads) {
            int i = idx % kMmFp32_16BM;
            int kk = idx / kMmFp32_16BM;
            size_t row = block_row + i;
            size_t kg = k0 + kk;
            if (row < m && kg < k) {
                size_t a_idx = row + kg * ld_a;
                As[kk][i] = fp32_16_combine(wh[a_idx], wr[a_idx]);
            } else {
                As[kk][i] = 0.0f;
            }
        }
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16BK * kMmFp32_16BN; idx += kNumThreads) {
            int j = idx % kMmFp32_16BN;
            int kk = idx / kMmFp32_16BN;
            size_t col = block_col + j;
            size_t kg = k0 + kk;
            Bs[kk][j] = (col < n && kg < k) ? B[kg + col * ld_b] : 0.0f;
        }
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16BK; ++kk) {
            float a_reg[kMmFp32_16TM];
            float b_reg[kMmFp32_16TN];
#pragma unroll
            for (int i = 0; i < kMmFp32_16TM; ++i) a_reg[i] = As[kk][ty * kMmFp32_16TM + i];
#pragma unroll
            for (int j = 0; j < kMmFp32_16TN; ++j) b_reg[j] = Bs[kk][tx * kMmFp32_16TN + j];
#pragma unroll
            for (int i = 0; i < kMmFp32_16TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }
        __syncthreads();
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16TM; ++i) {
        size_t row = block_row + ty * kMmFp32_16TM + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16TN; ++j) {
            size_t col = block_col + tx * kMmFp32_16TN + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled(TransposeType transA, TransposeType transB, double alpha,
                      dim<2> size_A, const uint16_t* wh, const uint16_t* wr, size_t ld_a,
                      dim<2> size_B, const float* B, size_t ld_b, double beta, float* C,
                      size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        // Transposed fast path not implemented yet -- fall back to the
        // always-correct untiled kernel rather than getting it wrong.
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    dim3 threads(kMmFp32_16BN / kMmFp32_16TN, kMmFp32_16BM / kMmFp32_16TM);
    dim3 blocks((n + kMmFp32_16BN - 1) / kMmFp32_16BN, (m + kMmFp32_16BM - 1) / kMmFp32_16BM);
    mm_fp32_16_tiled_kernel<<<blocks, threads>>>(alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Same 128x128/8x8 tiling as mm_fp32_16_tiled_kernel, plus two
// vectorizations mirroring gemm_fp32_tiled_cpasync_vec2_kernel's biggest
// wins in the plain-fp32 series (see mm_cuda_kernels.cu) -- applied here
// without cp.async/double-buffering, since gemm_fp32_tiled_db_kernel showed
// double-buffering alone barely moves the needle at this occupancy; the
// real gains were the vectorization/coalescing fixes, so this goes
// straight to those:
//
//  1. A's wh/wr load: 4 contiguous rows' wh (and separately wr) are read
//     as a single ushort4 (8 bytes) each instead of 4 separate uint16_t
//     reads, decoded via fp32_16_combine, then scattered into shared
//     memory -- same "vectorize the read, scatter the decode" shape as
//     vec2's B handling, just with a decode step in between instead of a
//     straight copy (fp32_16_combine can't run inside a cp.async transfer,
//     so this path is a synchronous load, not async).
//
//  2. B's load: the same float4-per-column vectorization vec2 used for
//     plain fp32 B -- see that kernel's comment for why 4 threads sharing
//     a column beats the untiled kernel's one-column-per-thread strided
//     access.
//
//  3. The compute loop's shared-memory reads become float4 reads instead
//     of scalar ones, same as vec/vec2.
//
// Requires ld_a, m, ld_b, and k to all be multiples of 4 (same alignment/
// boundary reasoning as vec2's A and B requirements combined); falls back
// to mm_fp32_16_tiled otherwise -- see mm_fp32_16_tiled_vec's dispatch.
__global__ void mm_fp32_16_tiled_vec_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __align__(16) float As[kMmFp32_16BK][kMmFp32_16BM];
    __shared__ __align__(16) float Bs[kMmFp32_16BK][kMmFp32_16BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16BN;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * (kMmFp32_16BN / kMmFp32_16TN) + tx;

    // A: one ushort4 (4 contiguous rows, fixed k-slice) per thread for wh
    // and separately for wr -- (BM/4)*BK = 32*8 = 256 groups, one per
    // thread (matches gemm_fp32_tiled_cpasync_vec_kernel's A mapping).
    const int a_kk = tid / (kMmFp32_16BM / 4);
    const int a_i0 = (tid % (kMmFp32_16BM / 4)) * 4;

    // B: one float4 (4 contiguous K-values, fixed column) per thread --
    // BN*(BK/4) = 128*2 = 256 groups, one per thread (matches
    // gemm_fp32_tiled_cpasync_vec2_kernel's B mapping).
    const int b_kk0 = (tid % (kMmFp32_16BK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16BK / 4);

    float acc[kMmFp32_16TM][kMmFp32_16TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16TN; ++j) acc[i][j] = 0.0f;

    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16BK) {
        size_t a_row0 = block_row + a_i0;
        size_t a_kg = k0 + a_kk;
        if (a_row0 < m && a_kg < k) {
            size_t a_idx = a_row0 + a_kg * ld_a;
            ushort4 wh4 = *reinterpret_cast<const ushort4*>(&wh[a_idx]);
            ushort4 wr4 = *reinterpret_cast<const ushort4*>(&wr[a_idx]);
            As[a_kk][a_i0 + 0] = fp32_16_combine(wh4.x, wr4.x);
            As[a_kk][a_i0 + 1] = fp32_16_combine(wh4.y, wr4.y);
            As[a_kk][a_i0 + 2] = fp32_16_combine(wh4.z, wr4.z);
            As[a_kk][a_i0 + 3] = fp32_16_combine(wh4.w, wr4.w);
        } else {
#pragma unroll
            for (int e = 0; e < 4; ++e) As[a_kk][a_i0 + e] = 0.0f;
        }

        size_t b_col = block_col + b_j;
        size_t b_kg0 = k0 + b_kk0;
        if (b_col < n && b_kg0 < k) {
            float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
            Bs[b_kk0 + 0][b_j] = t.x;
            Bs[b_kk0 + 1][b_j] = t.y;
            Bs[b_kk0 + 2][b_j] = t.z;
            Bs[b_kk0 + 3][b_j] = t.w;
        } else {
#pragma unroll
            for (int e = 0; e < 4; ++e) Bs[b_kk0 + e][b_j] = 0.0f;
        }
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16BK; ++kk) {
            float a_reg[kMmFp32_16TM];
            float b_reg[kMmFp32_16TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&As[kk][ty * kMmFp32_16TM + v * 4]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&Bs[kk][tx * kMmFp32_16TN + v * 4]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }
        __syncthreads();
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16TM; ++i) {
        size_t row = block_row + ty * kMmFp32_16TM + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16TN; ++j) {
            size_t col = block_col + tx * kMmFp32_16TN + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_vec(TransposeType transA, TransposeType transB, double alpha,
                          dim<2> size_A, const uint16_t* wh, const uint16_t* wr, size_t ld_a,
                          dim<2> size_B, const float* B, size_t ld_b, double beta, float* C,
                          size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    // A's ushort4 load needs every 4-row group fully in/out of range (m a
    // multiple of 4) and 8-byte-aligned addresses (ld_a a multiple of 4);
    // B's float4 load needs the analogous ld_b/k requirement -- see the
    // kernel's comment. Falls back to the scalar-load tiled kernel (still
    // correct, just without these vectorizations) otherwise.
    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b, beta, C, ld_c);
        return;
    }

    dim3 threads(kMmFp32_16BN / kMmFp32_16TN, kMmFp32_16BM / kMmFp32_16TM);
    dim3 blocks((n + kMmFp32_16BN - 1) / kMmFp32_16BN, (m + kMmFp32_16BM - 1) / kMmFp32_16BM);
    mm_fp32_16_tiled_vec_kernel<<<blocks, threads>>>(alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Same tiling/vectorization as mm_fp32_16_tiled_vec_kernel, but A's raw
// wh/wr bytes are prefetched one tile ahead via cp.async into a small
// staging buffer, instead of being read synchronously right before their
// decode. fp32_16_combine can't run inside a cp.async transfer (it's a
// raw byte copy, no compute), so the decode itself still happens
// synchronously -- what this hides is the *global memory fetch* latency
// for wh/wr behind the previous tile's compute, leaving only the much
// cheaper "already-in-shared-memory bit manipulation" on the critical
// path between tiles. B's load stays exactly as in mm_fp32_16_tiled_vec
// (synchronous, no benefit from async since it's already a plain float
// copy with nothing to hide behind).
//
// Zero-fill for an out-of-range A group happens directly in load_tile_
// async (skipping cp.async entirely, since reading out of bounds when
// a_kg >= k would go past wh/wr's allocated extent) rather than through
// the staging buffer -- decode_tile re-checks the identical validity
// condition and only touches As for groups that were actually staged, so
// it never overwrites that zero-fill with garbage staging contents.
namespace {
constexpr int kMmFp32_16CpAsyncBM = 128;
constexpr int kMmFp32_16CpAsyncBN = 128;
constexpr int kMmFp32_16CpAsyncBK = 8;
constexpr int kMmFp32_16CpAsyncTM = 8;
constexpr int kMmFp32_16CpAsyncTN = 8;
}  // namespace

__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_vec_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __align__(16) uint16_t stagingWh[2][kMmFp32_16CpAsyncBK][kMmFp32_16CpAsyncBM];
    __shared__ __align__(16) uint16_t stagingWr[2][kMmFp32_16CpAsyncBK][kMmFp32_16CpAsyncBM];
    __shared__ __align__(16) float As[2][kMmFp32_16CpAsyncBK][kMmFp32_16CpAsyncBM];
    __shared__ __align__(16) float Bs[2][kMmFp32_16CpAsyncBK][kMmFp32_16CpAsyncBN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16CpAsyncBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16CpAsyncBN;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * (kMmFp32_16CpAsyncBN / kMmFp32_16CpAsyncTN) + tx;

    const int a_kk = tid / (kMmFp32_16CpAsyncBM / 4);
    const int a_i0 = (tid % (kMmFp32_16CpAsyncBM / 4)) * 4;
    const int b_kk0 = (tid % (kMmFp32_16CpAsyncBK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16CpAsyncBK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
        size_t a_row0 = block_row + a_i0;
        size_t a_kg = k0 + a_kk;
        if (a_row0 < m && a_kg < k) {
            size_t a_idx = a_row0 + a_kg * ld_a;
            __pipeline_memcpy_async(&stagingWh[buf][a_kk][a_i0], &wh[a_idx], sizeof(ushort4));
            __pipeline_memcpy_async(&stagingWr[buf][a_kk][a_i0], &wr[a_idx], sizeof(ushort4));
        } else {
#pragma unroll
            for (int e = 0; e < 4; ++e) As[buf][a_kk][a_i0 + e] = 0.0f;
        }
        __pipeline_commit();

        size_t b_col = block_col + b_j;
        size_t b_kg0 = k0 + b_kk0;
        if (b_col < n && b_kg0 < k) {
            float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
            Bs[buf][b_kk0 + 0][b_j] = t.x;
            Bs[buf][b_kk0 + 1][b_j] = t.y;
            Bs[buf][b_kk0 + 2][b_j] = t.z;
            Bs[buf][b_kk0 + 3][b_j] = t.w;
        } else {
#pragma unroll
            for (int e = 0; e < 4; ++e) Bs[buf][b_kk0 + e][b_j] = 0.0f;
        }
    };

    // Decodes this thread's A group from the staging buffer into As, once
    // its cp.async has landed -- re-derives the same validity condition
    // load_tile_async used for this (buf, k0) so it skips exactly the
    // groups that were zero-filled directly instead of staged.
    auto decode_tile = [&](int buf, size_t k0) {
        size_t a_row0 = block_row + a_i0;
        size_t a_kg = k0 + a_kk;
        if (a_row0 < m && a_kg < k) {
            ushort4 wh4 = *reinterpret_cast<const ushort4*>(&stagingWh[buf][a_kk][a_i0]);
            ushort4 wr4 = *reinterpret_cast<const ushort4*>(&stagingWr[buf][a_kk][a_i0]);
            As[buf][a_kk][a_i0 + 0] = fp32_16_combine(wh4.x, wr4.x);
            As[buf][a_kk][a_i0 + 1] = fp32_16_combine(wh4.y, wr4.y);
            As[buf][a_kk][a_i0 + 2] = fp32_16_combine(wh4.z, wr4.z);
            As[buf][a_kk][a_i0 + 3] = fp32_16_combine(wh4.w, wr4.w);
        }
    };

    float acc[kMmFp32_16CpAsyncTM][kMmFp32_16CpAsyncTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16CpAsyncTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16CpAsyncTN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    decode_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16CpAsyncBK) {
        size_t next_k0 = k0 + kMmFp32_16CpAsyncBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16CpAsyncBK; ++kk) {
            float a_reg[kMmFp32_16CpAsyncTM];
            float b_reg[kMmFp32_16CpAsyncTN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16CpAsyncTM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[cur][kk][ty * kMmFp32_16CpAsyncTM + v * 4]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16CpAsyncTN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[cur][kk][tx * kMmFp32_16CpAsyncTN + v * 4]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16CpAsyncTM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16CpAsyncTN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            decode_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16CpAsyncTM; ++i) {
        size_t row = block_row + ty * kMmFp32_16CpAsyncTM + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16CpAsyncTN; ++j) {
            size_t col = block_col + tx * kMmFp32_16CpAsyncTN + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_vec(TransposeType transA, TransposeType transB, double alpha,
                                  dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                  size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                  double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_vec(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                             beta, C, ld_c);
        return;
    }

    dim3 threads(kMmFp32_16CpAsyncBN / kMmFp32_16CpAsyncTN,
                kMmFp32_16CpAsyncBM / kMmFp32_16CpAsyncTM);
    dim3 blocks((n + kMmFp32_16CpAsyncBN - 1) / kMmFp32_16CpAsyncBN,
               (m + kMmFp32_16CpAsyncBM - 1) / kMmFp32_16CpAsyncBM);
    mm_fp32_16_tiled_cpasync_vec_kernel<<<blocks, threads>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Same idea as mm_fp32_16_tiled_cpasync_vec_kernel, but with the K-tile
// doubled from 8 to 16 -- same reasoning as gemm_fp32_tiled_cpasync_vec3_
// kernel in mm_cuda_kernels.cu: B's float4 load groups BK/4 threads onto
// each column, so doubling BK doubles that group from 2 threads (32-byte
// span) to 4 (64-byte span) before the address jumps a full ld_b stride to
// the next column.
//
// B goes back to a single shared buffer here (not double-buffered like A's
// staging): its load was always synchronous, never prefetched via
// cp.async, so double-buffering it never bought anything -- it's loaded
// fresh for the *current* tile at the top of each loop iteration instead
// of being issued a tile ahead. This isn't just tidiness: at BK=16, double-
// buffering everything (2 staging buffers + 2 As + 2 Bs) would land at
// exactly 48KB, the default static-shared-memory limit, with no margin for
// anything else. Dropping Bs to one buffer brings it to 40KB.
namespace {
constexpr int kMmFp32_16V2BM = 128;
constexpr int kMmFp32_16V2BN = 128;
constexpr int kMmFp32_16V2BK = 16;
constexpr int kMmFp32_16V2TM = 8;
constexpr int kMmFp32_16V2TN = 8;
}  // namespace

__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_vec2_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __align__(16) uint16_t stagingWh[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) uint16_t stagingWr[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float As[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float Bs[kMmFp32_16V2BK][kMmFp32_16V2BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16V2BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16V2BN;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * (kMmFp32_16V2BN / kMmFp32_16V2TN) + tx;
    constexpr int kNumThreads = (kMmFp32_16V2BM / kMmFp32_16V2TM) * (kMmFp32_16V2BN / kMmFp32_16V2TN);

    // A: (BM/4)*BK = 32*16 = 512 groups -- 2 per thread (same two-pass
    // mapping as gemm_fp32_tiled_cpasync_vec3_kernel's A).
    const int a_i0 = (tid % (kMmFp32_16V2BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16V2BM / 4);

    // B: BN*(BK/4) = 128*4 = 512 groups -- 2 per thread (same two-pass
    // mapping as that kernel's B).
    const int b_kk0_base = (tid % (kMmFp32_16V2BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16V2BK / 4);

    auto load_A_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[buf][a_kk][a_i0], &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[buf][a_kk][a_i0], &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[buf][a_kk][a_i0 + e] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    // Re-derives the same validity condition load_A_async used for this
    // (buf, k0) so it only decodes groups that were actually staged,
    // leaving load_A_async's direct zero-fill untouched otherwise.
    auto decode_A = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 = *reinterpret_cast<const ushort4*>(&stagingWh[buf][a_kk][a_i0]);
                ushort4 wr4 = *reinterpret_cast<const ushort4*>(&stagingWr[buf][a_kk][a_i0]);
                As[buf][a_kk][a_i0 + 0] = fp32_16_combine(wh4.x, wr4.x);
                As[buf][a_kk][a_i0 + 1] = fp32_16_combine(wh4.y, wr4.y);
                As[buf][a_kk][a_i0 + 2] = fp32_16_combine(wh4.z, wr4.z);
                As[buf][a_kk][a_i0 + 3] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
    };

    auto load_B_sync = [&](size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kNumThreads / (kMmFp32_16V2BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
                Bs[b_kk0_base + 0][b_j] = t.x;
                Bs[b_kk0_base + 1][b_j] = t.y;
                Bs[b_kk0_base + 2][b_j] = t.z;
                Bs[b_kk0_base + 3][b_j] = t.w;
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[b_kk0_base + e][b_j] = 0.0f;
            }
        }
    };

    float acc[kMmFp32_16V2TM][kMmFp32_16V2TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] = 0.0f;

    load_A_async(0, 0);
    __pipeline_wait_prior(0);
    decode_A(0, 0);

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16V2BK) {
        size_t next_k0 = k0 + kMmFp32_16V2BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_A_async(nxt, next_k0);

        load_B_sync(k0);
        // Guards both directions: makes decode_A(0,0)'s writes (first
        // iteration) or the previous iteration's decode_A(nxt,...) writes
        // visible, AND makes this iteration's Bs writes visible, before
        // the compute loop below reads either.
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16V2BK; ++kk) {
            float a_reg[kMmFp32_16V2TM];
            float b_reg[kMmFp32_16V2TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&As[cur][kk][ty * kMmFp32_16V2TM + v * 4]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&Bs[kk][tx * kMmFp32_16V2TN + v * 4]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            decode_A(nxt, next_k0);
        }
        // Guards both: this iteration's As[cur] reads above are done
        // (safe for decode_A to have written As[nxt], already done by
        // this point) and this iteration's Bs reads are done (safe for
        // the next iteration's load_B_sync to overwrite it).
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i) {
        size_t row = block_row + ty * kMmFp32_16V2TM + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) {
            size_t col = block_col + tx * kMmFp32_16V2TN + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_vec2(TransposeType transA, TransposeType transB, double alpha,
                                   dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                   size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                   double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                     beta, C, ld_c);
        return;
    }

    dim3 threads(kMmFp32_16V2BN / kMmFp32_16V2TN, kMmFp32_16V2BM / kMmFp32_16V2TM);
    dim3 blocks((n + kMmFp32_16V2BN - 1) / kMmFp32_16V2BN, (m + kMmFp32_16V2BM - 1) / kMmFp32_16V2BM);
    mm_fp32_16_tiled_cpasync_vec2_kernel<<<blocks, threads>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// EXPERIMENTAL: identical to mm_fp32_16_tiled_cpasync_vec2_kernel in every
// respect except decode_A's two fp32_16_combine calls become fp32_16_
// combine_branchless -- isolates whether removing per-element decode
// divergence (see that function's comment) is worth anything on top of
// vec2's memory-side vectorizations, or whether decode was already too
// small a fraction of the kernel's time (it only runs BM*BK/kNumThreads
// times per tile, not in the per-kk inner loop) for divergence there to
// matter much.
__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_vec2_branchless_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __align__(16) uint16_t stagingWh[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) uint16_t stagingWr[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float As[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float Bs[kMmFp32_16V2BK][kMmFp32_16V2BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16V2BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16V2BN;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * (kMmFp32_16V2BN / kMmFp32_16V2TN) + tx;
    constexpr int kNumThreads = (kMmFp32_16V2BM / kMmFp32_16V2TM) * (kMmFp32_16V2BN / kMmFp32_16V2TN);

    const int a_i0 = (tid % (kMmFp32_16V2BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16V2BM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16V2BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16V2BK / 4);

    auto load_A_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[buf][a_kk][a_i0], &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[buf][a_kk][a_i0], &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[buf][a_kk][a_i0 + e] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto decode_A = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 = *reinterpret_cast<const ushort4*>(&stagingWh[buf][a_kk][a_i0]);
                ushort4 wr4 = *reinterpret_cast<const ushort4*>(&stagingWr[buf][a_kk][a_i0]);
                As[buf][a_kk][a_i0 + 0] = fp32_16_combine_branchless(wh4.x, wr4.x);
                As[buf][a_kk][a_i0 + 1] = fp32_16_combine_branchless(wh4.y, wr4.y);
                As[buf][a_kk][a_i0 + 2] = fp32_16_combine_branchless(wh4.z, wr4.z);
                As[buf][a_kk][a_i0 + 3] = fp32_16_combine_branchless(wh4.w, wr4.w);
            }
        }
    };

    auto load_B_sync = [&](size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kNumThreads / (kMmFp32_16V2BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
                Bs[b_kk0_base + 0][b_j] = t.x;
                Bs[b_kk0_base + 1][b_j] = t.y;
                Bs[b_kk0_base + 2][b_j] = t.z;
                Bs[b_kk0_base + 3][b_j] = t.w;
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[b_kk0_base + e][b_j] = 0.0f;
            }
        }
    };

    float acc[kMmFp32_16V2TM][kMmFp32_16V2TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] = 0.0f;

    load_A_async(0, 0);
    __pipeline_wait_prior(0);
    decode_A(0, 0);

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16V2BK) {
        size_t next_k0 = k0 + kMmFp32_16V2BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_A_async(nxt, next_k0);

        load_B_sync(k0);
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16V2BK; ++kk) {
            float a_reg[kMmFp32_16V2TM];
            float b_reg[kMmFp32_16V2TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&As[cur][kk][ty * kMmFp32_16V2TM + v * 4]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&Bs[kk][tx * kMmFp32_16V2TN + v * 4]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            decode_A(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i) {
        size_t row = block_row + ty * kMmFp32_16V2TM + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) {
            size_t col = block_col + tx * kMmFp32_16V2TN + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_vec2_branchless(TransposeType transA, TransposeType transB,
                                              double alpha, dim<2> size_A, const uint16_t* wh,
                                              const uint16_t* wr, size_t ld_a, dim<2> size_B,
                                              const float* B, size_t ld_b, double beta, float* C,
                                              size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                     beta, C, ld_c);
        return;
    }

    dim3 threads(kMmFp32_16V2BN / kMmFp32_16V2TN, kMmFp32_16V2BM / kMmFp32_16V2TM);
    dim3 blocks((n + kMmFp32_16V2BN - 1) / kMmFp32_16V2BN, (m + kMmFp32_16V2BM - 1) / kMmFp32_16V2BM);
    mm_fp32_16_tiled_cpasync_vec2_branchless_kernel<<<blocks, threads>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Bigger tile, targeting the fp32_16-specific bottleneck directly: each
// decoded A(i,l) value is reused by BN/TN threads (one per output-column
// group in the block). vec2's BN=128, TN=8 gives a reuse factor of 16;
// doubling BN to 256 doubles that to 32, halving the effective decode
// cost per FLOP without touching the decode itself. BM stays at 128 (A's
// side, unaffected by this) and BK stays at 16 (unaffected -- B's
// coalescing is already at its BK=16 sweet spot).
//
// At this size (BM=128, BN=256, BK=16), the shared memory footprint --
// double-buffered wh/wr staging + double-buffered decoded As + single-
// buffered Bs -- lands at exactly 48KB, the default static-shared-memory
// limit, with zero margin. Rather than risk that boundary (some toolchains
// reserve a few bytes for other purposes, making exactly 48KB fail to
// compile), this kernel uses dynamic shared memory instead: one `extern
// __shared__` array, manually partitioned into the four regions via
// mm_fp32_16_v3_a_idx/mm_fp32_16_v3_bs_idx below, with cudaFuncSetAttribute
// explicitly granting it the space at first use (A100 supports up to
// 164KB/block that way; 48KB is comfortably inside that, this just avoids
// the static-allocation boundary case entirely).
//
// Register pressure this bumps into a different limiter than earlier
// kernels: with 512 threads/block, only 1 block/SM fits in the 65536-
// register budget regardless of shared memory headroom -- but 512 threads
// = 16 warps, the SAME warp-level occupancy vec2's two 256-thread blocks
// already had, just consolidated into one bigger block. No occupancy
// regression, more arithmetic intensity per tile load.
namespace {
constexpr int kMmFp32_16V3BM = 128;
constexpr int kMmFp32_16V3BN = 256;
constexpr int kMmFp32_16V3BK = 16;
constexpr int kMmFp32_16V3TM = 8;
constexpr int kMmFp32_16V3TN = 8;
constexpr int kMmFp32_16V3NumThreads =
    (kMmFp32_16V3BM / kMmFp32_16V3TM) * (kMmFp32_16V3BN / kMmFp32_16V3TN);  // 512

constexpr size_t kMmFp32_16V3StagingWhBytes =
    2 * static_cast<size_t>(kMmFp32_16V3BK) * kMmFp32_16V3BM * sizeof(uint16_t);
constexpr size_t kMmFp32_16V3StagingWrBytes = kMmFp32_16V3StagingWhBytes;
constexpr size_t kMmFp32_16V3AsBytes =
    2 * static_cast<size_t>(kMmFp32_16V3BK) * kMmFp32_16V3BM * sizeof(float);
constexpr size_t kMmFp32_16V3BsBytes =
    static_cast<size_t>(kMmFp32_16V3BK) * kMmFp32_16V3BN * sizeof(float);
constexpr size_t kMmFp32_16V3StagingWhOffset = 0;
constexpr size_t kMmFp32_16V3StagingWrOffset =
    kMmFp32_16V3StagingWhOffset + kMmFp32_16V3StagingWhBytes;
constexpr size_t kMmFp32_16V3AsOffset = kMmFp32_16V3StagingWrOffset + kMmFp32_16V3StagingWrBytes;
constexpr size_t kMmFp32_16V3BsOffset = kMmFp32_16V3AsOffset + kMmFp32_16V3AsBytes;
constexpr size_t kMmFp32_16V3SharedBytes = kMmFp32_16V3BsOffset + kMmFp32_16V3BsBytes;  // 48KB

// stagingWh/stagingWr/As all share this [2][BK][BM] shape.
__device__ __forceinline__ int mm_fp32_16_v3_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16V3BK + kk) * kMmFp32_16V3BM + i;
}
__device__ __forceinline__ int mm_fp32_16_v3_bs_idx(int kk, int j) {
    return kk * kMmFp32_16V3BN + j;
}
}  // namespace

__global__ void mm_fp32_16_tiled_cpasync_vec3_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    // float4-typed extern declaration guarantees 16-byte alignment for the
    // whole region regardless of toolchain, then reinterpreted to bytes for
    // manual offsetting into the four sections below (each section's own
    // byte size is itself a multiple of 16, so every section boundary and
    // every ushort4/float4 access within it lands 16-byte-aligned too).
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16V3StagingWhOffset);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16V3StagingWrOffset);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16V3AsOffset);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16V3BsOffset);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16V3BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16V3BN;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * (kMmFp32_16V3BN / kMmFp32_16V3TN) + tx;

    // A: (BM/4)*BK = 32*16 = 512 = kNumThreads -- exactly one group per
    // thread, single pass (BN doesn't affect A's mapping at all).
    const int a_i0 = (tid % (kMmFp32_16V3BM / 4)) * 4;
    const int a_kk = tid / (kMmFp32_16V3BM / 4);

    // B: BN*(BK/4) = 256*4 = 1024 = 2*kNumThreads -- 2 passes per thread.
    const int b_kk0 = (tid % (kMmFp32_16V3BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16V3BK / 4);

    auto load_A_async = [&](int buf, size_t k0) {
        size_t a_row0 = block_row + a_i0;
        size_t a_kg = k0 + a_kk;
        if (a_row0 < m && a_kg < k) {
            size_t a_idx = a_row0 + a_kg * ld_a;
            __pipeline_memcpy_async(&stagingWh[mm_fp32_16_v3_a_idx(buf, a_kk, a_i0)], &wh[a_idx],
                                    sizeof(ushort4));
            __pipeline_memcpy_async(&stagingWr[mm_fp32_16_v3_a_idx(buf, a_kk, a_i0)], &wr[a_idx],
                                    sizeof(ushort4));
        } else {
#pragma unroll
            for (int e = 0; e < 4; ++e) As[mm_fp32_16_v3_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
        }
        __pipeline_commit();
    };

    auto decode_A = [&](int buf, size_t k0) {
        size_t a_row0 = block_row + a_i0;
        size_t a_kg = k0 + a_kk;
        if (a_row0 < m && a_kg < k) {
            ushort4 wh4 = *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_v3_a_idx(buf, a_kk, a_i0)]);
            ushort4 wr4 = *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_v3_a_idx(buf, a_kk, a_i0)]);
            As[mm_fp32_16_v3_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
            As[mm_fp32_16_v3_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
            As[mm_fp32_16_v3_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
            As[mm_fp32_16_v3_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
        }
    };

    auto load_B_sync = [&](size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16V3NumThreads / (kMmFp32_16V3BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
                Bs[mm_fp32_16_v3_bs_idx(b_kk0 + 0, b_j)] = t.x;
                Bs[mm_fp32_16_v3_bs_idx(b_kk0 + 1, b_j)] = t.y;
                Bs[mm_fp32_16_v3_bs_idx(b_kk0 + 2, b_j)] = t.z;
                Bs[mm_fp32_16_v3_bs_idx(b_kk0 + 3, b_j)] = t.w;
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[mm_fp32_16_v3_bs_idx(b_kk0 + e, b_j)] = 0.0f;
            }
        }
    };

    float acc[kMmFp32_16V3TM][kMmFp32_16V3TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16V3TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16V3TN; ++j) acc[i][j] = 0.0f;

    load_A_async(0, 0);
    __pipeline_wait_prior(0);
    decode_A(0, 0);

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16V3BK) {
        size_t next_k0 = k0 + kMmFp32_16V3BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_A_async(nxt, next_k0);

        load_B_sync(k0);
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16V3BK; ++kk) {
            float a_reg[kMmFp32_16V3TM];
            float b_reg[kMmFp32_16V3TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16V3TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_v3_a_idx(cur, kk, ty * kMmFp32_16V3TM + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16V3TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_v3_bs_idx(kk, tx * kMmFp32_16V3TN + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16V3TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16V3TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            decode_A(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16V3TM; ++i) {
        size_t row = block_row + ty * kMmFp32_16V3TM + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16V3TN; ++j) {
            size_t col = block_col + tx * kMmFp32_16V3TN + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_vec3(TransposeType transA, TransposeType transB, double alpha,
                                   dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                   size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                   double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_vec3_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16V3SharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16V3BN / kMmFp32_16V3TN, kMmFp32_16V3BM / kMmFp32_16V3TM);
    dim3 blocks((n + kMmFp32_16V3BN - 1) / kMmFp32_16V3BN, (m + kMmFp32_16V3BM - 1) / kMmFp32_16V3BM);
    mm_fp32_16_tiled_cpasync_vec3_kernel<<<blocks, threads, kMmFp32_16V3SharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// A qualitatively different lever than vec3's: instead of enlarging the
// BLOCK tile (which shrinks the grid -- fewer, bigger blocks -- and cost
// vec3 its concurrent-block-per-GPU parallelism, worst at small N), this
// reshapes the THREAD tile at the exact same block/grid size as vec2
// (BM=128, BN=128, BK=16 -- identical shared memory footprint, identical
// number of blocks in the grid). TN drops from 8 to 4, which *doubles*
// BN/TN (how many threads share each decoded A value) from 16 to 32 --
// the same decode-reuse improvement vec3 was chasing, but achieved by
// giving each thread a narrower output slice instead of by covering more
// output per block. More threads per block (512 vs vec2's 256) with half
// the accumulators each (TM*TN=32 vs 64) -- register pressure per thread
// drops accordingly, and since the grid itself is unchanged, this doesn't
// touch the total-blocks-in-flight-across-the-GPU count vec3 lost.
//
// A bonus simplification: with kNumThreads now 512, (BM/4)*BK = 512 and
// BN*(BK/4) = 512 both divide evenly into ONE group per thread each --
// unlike vec2/vec3's two-pass A and/or B loads, this kernel's loads are
// single-pass for both.
namespace {
constexpr int kMmFp32_16V4BM = 128;
constexpr int kMmFp32_16V4BN = 128;
constexpr int kMmFp32_16V4BK = 16;
constexpr int kMmFp32_16V4TM = 8;
constexpr int kMmFp32_16V4TN = 4;
constexpr int kMmFp32_16V4NumThreads =
    (kMmFp32_16V4BM / kMmFp32_16V4TM) * (kMmFp32_16V4BN / kMmFp32_16V4TN);  // 512
}  // namespace

__global__ void mm_fp32_16_tiled_cpasync_vec4_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __align__(16) uint16_t stagingWh[2][kMmFp32_16V4BK][kMmFp32_16V4BM];
    __shared__ __align__(16) uint16_t stagingWr[2][kMmFp32_16V4BK][kMmFp32_16V4BM];
    __shared__ __align__(16) float As[2][kMmFp32_16V4BK][kMmFp32_16V4BM];
    __shared__ __align__(16) float Bs[kMmFp32_16V4BK][kMmFp32_16V4BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16V4BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16V4BN;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * (kMmFp32_16V4BN / kMmFp32_16V4TN) + tx;

    // A: (BM/4)*BK = 32*16 = 512 = kNumThreads -- single pass.
    const int a_i0 = (tid % (kMmFp32_16V4BM / 4)) * 4;
    const int a_kk = tid / (kMmFp32_16V4BM / 4);

    // B: BN*(BK/4) = 128*4 = 512 = kNumThreads -- single pass.
    const int b_kk0 = (tid % (kMmFp32_16V4BK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16V4BK / 4);

    auto load_A_async = [&](int buf, size_t k0) {
        size_t a_row0 = block_row + a_i0;
        size_t a_kg = k0 + a_kk;
        if (a_row0 < m && a_kg < k) {
            size_t a_idx = a_row0 + a_kg * ld_a;
            __pipeline_memcpy_async(&stagingWh[buf][a_kk][a_i0], &wh[a_idx], sizeof(ushort4));
            __pipeline_memcpy_async(&stagingWr[buf][a_kk][a_i0], &wr[a_idx], sizeof(ushort4));
        } else {
#pragma unroll
            for (int e = 0; e < 4; ++e) As[buf][a_kk][a_i0 + e] = 0.0f;
        }
        __pipeline_commit();
    };

    auto decode_A = [&](int buf, size_t k0) {
        size_t a_row0 = block_row + a_i0;
        size_t a_kg = k0 + a_kk;
        if (a_row0 < m && a_kg < k) {
            ushort4 wh4 = *reinterpret_cast<const ushort4*>(&stagingWh[buf][a_kk][a_i0]);
            ushort4 wr4 = *reinterpret_cast<const ushort4*>(&stagingWr[buf][a_kk][a_i0]);
            As[buf][a_kk][a_i0 + 0] = fp32_16_combine(wh4.x, wr4.x);
            As[buf][a_kk][a_i0 + 1] = fp32_16_combine(wh4.y, wr4.y);
            As[buf][a_kk][a_i0 + 2] = fp32_16_combine(wh4.z, wr4.z);
            As[buf][a_kk][a_i0 + 3] = fp32_16_combine(wh4.w, wr4.w);
        }
    };

    auto load_B_sync = [&](size_t k0) {
        size_t b_col = block_col + b_j;
        size_t b_kg0 = k0 + b_kk0;
        if (b_col < n && b_kg0 < k) {
            float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
            Bs[b_kk0 + 0][b_j] = t.x;
            Bs[b_kk0 + 1][b_j] = t.y;
            Bs[b_kk0 + 2][b_j] = t.z;
            Bs[b_kk0 + 3][b_j] = t.w;
        } else {
#pragma unroll
            for (int e = 0; e < 4; ++e) Bs[b_kk0 + e][b_j] = 0.0f;
        }
    };

    float acc[kMmFp32_16V4TM][kMmFp32_16V4TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16V4TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16V4TN; ++j) acc[i][j] = 0.0f;

    load_A_async(0, 0);
    __pipeline_wait_prior(0);
    decode_A(0, 0);

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16V4BK) {
        size_t next_k0 = k0 + kMmFp32_16V4BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_A_async(nxt, next_k0);

        load_B_sync(k0);
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16V4BK; ++kk) {
            float a_reg[kMmFp32_16V4TM];
            float b_reg[kMmFp32_16V4TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16V4TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&As[cur][kk][ty * kMmFp32_16V4TM + v * 4]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
            {
                // TN==4, exactly one float4 read -- no v-loop needed.
                float4 t = *reinterpret_cast<const float4*>(&Bs[kk][tx * kMmFp32_16V4TN]);
                b_reg[0] = t.x;
                b_reg[1] = t.y;
                b_reg[2] = t.z;
                b_reg[3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16V4TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16V4TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            decode_A(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16V4TM; ++i) {
        size_t row = block_row + ty * kMmFp32_16V4TM + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16V4TN; ++j) {
            size_t col = block_col + tx * kMmFp32_16V4TN + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_vec4(TransposeType transA, TransposeType transB, double alpha,
                                   dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                   size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                   double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    dim3 threads(kMmFp32_16V4BN / kMmFp32_16V4TN, kMmFp32_16V4BM / kMmFp32_16V4TM);
    dim3 blocks((n + kMmFp32_16V4BN - 1) / kMmFp32_16V4BN, (m + kMmFp32_16V4BM - 1) / kMmFp32_16V4BM);
    mm_fp32_16_tiled_cpasync_vec4_kernel<<<blocks, threads>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// A controlled test of cutlass-style warp tiling, isolated from every
// other variable tried so far: identical block tile, thread count, and
// per-thread work to mm_fp32_16_tiled_cpasync_vec2 (BM=128, BN=128, BK=16,
// 256 threads, 8x8 accumulators/thread -- same shared memory, same A/B
// load logic, reused verbatim) -- the ONLY change is how threads map to
// output positions. vec2 uses a flat 16x16 (tx, ty) grid, where a warp (32
// consecutive linear thread IDs) spans two different ty values (since
// blockDim.x=16 < 32): half the warp shares one As row-slice, the other
// half shares a different one. This kernel instead decomposes the 256
// threads into an explicit 4x2 grid of 8 warps (WARPS_M x WARPS_N), each
// warp's 32 lanes into a 4x8 grid (LANES_M x LANES_N) -- so the row/column
// offset a thread owns comes from (warp_row, lane_row) and (warp_col,
// lane_col) instead of directly from (ty, tx). Every warp now owns a
// contiguous, warp-aligned 32x64 region of the block's output, the
// structural property cutlass's warp-tile hierarchy is built around.
//
// If this alone measures the same as vec2, that's a real (if negative)
// finding: it means the warp/thread-ID-to-output-position mapping isn't
// where vec2's remaining gap to cuBLAS lives, at least not on top of
// everything else already tried (branchless decode, bigger block tile,
// narrower thread tile -- all regressions, see those kernels' comments).
namespace {
constexpr int kMmFp32_16WtWarpsM = 4;
constexpr int kMmFp32_16WtWarpsN = 2;
constexpr int kMmFp32_16WtLanesM = 4;
constexpr int kMmFp32_16WtLanesN = 8;
}  // namespace

__global__ void mm_fp32_16_tiled_cpasync_warptile_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __align__(16) uint16_t stagingWh[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) uint16_t stagingWr[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float As[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float Bs[kMmFp32_16V2BK][kMmFp32_16V2BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16V2BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16V2BN;

    const int tid = threadIdx.x;  // 1D block -- see the warp/lane decomposition below.

    // Warp-tile decomposition: replaces vec2's flat ty*TM / tx*TN with a
    // warp-aligned row_off/col_off. A/B loads below are untouched (they
    // already index purely by tid, same as vec2).
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16WtWarpsN;
    const int warp_col = warp_id % kMmFp32_16WtWarpsN;
    const int lane_row = lane_id / kMmFp32_16WtLanesN;
    const int lane_col = lane_id % kMmFp32_16WtLanesN;
    const int row_off = warp_row * (kMmFp32_16V2BM / kMmFp32_16WtWarpsM) + lane_row * kMmFp32_16V2TM;
    const int col_off = warp_col * (kMmFp32_16V2BN / kMmFp32_16WtWarpsN) + lane_col * kMmFp32_16V2TN;

    // A: (BM/4)*BK = 32*16 = 512 groups -- 2 per thread (same as vec2).
    const int a_i0 = (tid % (kMmFp32_16V2BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16V2BM / 4);

    // B: BN*(BK/4) = 128*4 = 512 groups -- 2 per thread (same as vec2).
    const int b_kk0_base = (tid % (kMmFp32_16V2BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16V2BK / 4);

    constexpr int kNumThreads = (kMmFp32_16V2BM / kMmFp32_16V2TM) * (kMmFp32_16V2BN / kMmFp32_16V2TN);

    auto load_A_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[buf][a_kk][a_i0], &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[buf][a_kk][a_i0], &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[buf][a_kk][a_i0 + e] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto decode_A = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 = *reinterpret_cast<const ushort4*>(&stagingWh[buf][a_kk][a_i0]);
                ushort4 wr4 = *reinterpret_cast<const ushort4*>(&stagingWr[buf][a_kk][a_i0]);
                As[buf][a_kk][a_i0 + 0] = fp32_16_combine(wh4.x, wr4.x);
                As[buf][a_kk][a_i0 + 1] = fp32_16_combine(wh4.y, wr4.y);
                As[buf][a_kk][a_i0 + 2] = fp32_16_combine(wh4.z, wr4.z);
                As[buf][a_kk][a_i0 + 3] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
    };

    auto load_B_sync = [&](size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kNumThreads / (kMmFp32_16V2BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
                Bs[b_kk0_base + 0][b_j] = t.x;
                Bs[b_kk0_base + 1][b_j] = t.y;
                Bs[b_kk0_base + 2][b_j] = t.z;
                Bs[b_kk0_base + 3][b_j] = t.w;
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[b_kk0_base + e][b_j] = 0.0f;
            }
        }
    };

    float acc[kMmFp32_16V2TM][kMmFp32_16V2TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] = 0.0f;

    load_A_async(0, 0);
    __pipeline_wait_prior(0);
    decode_A(0, 0);

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16V2BK) {
        size_t next_k0 = k0 + kMmFp32_16V2BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_A_async(nxt, next_k0);

        load_B_sync(k0);
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16V2BK; ++kk) {
            float a_reg[kMmFp32_16V2TM];
            float b_reg[kMmFp32_16V2TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&As[cur][kk][row_off + v * 4]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&Bs[kk][col_off + v * 4]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            decode_A(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_warptile(TransposeType transA, TransposeType transB, double alpha,
                                       dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                       size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                       double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    dim3 threads(kMmFp32_16V2BN / kMmFp32_16V2TN * kMmFp32_16V2BM / kMmFp32_16V2TM);  // 256, 1D
    dim3 blocks((n + kMmFp32_16V2BN - 1) / kMmFp32_16V2BN, (m + kMmFp32_16V2BM - 1) / kMmFp32_16V2BM);
    mm_fp32_16_tiled_cpasync_warptile_kernel<<<blocks, threads>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Identical to mm_fp32_16_tiled_cpasync_warptile in every respect except
// the warp/lane grid's SHAPE: 2x4 warps (was 4x2) with 8x4 lanes (was
// 4x8), giving each warp a 64x32 region (was 32x64) -- same total warp
// tile area, same total resources, just transposed aspect ratio. Isolates
// whether warptile's small win came from the warp-aligned addressing
// itself (in which case shape shouldn't matter much) or from this
// specific shape happening to interact well with the tile's row/column
// access patterns (in which case it should).
namespace {
constexpr int kMmFp32_16Wt2WarpsM = 2;
constexpr int kMmFp32_16Wt2WarpsN = 4;
constexpr int kMmFp32_16Wt2LanesM = 8;
constexpr int kMmFp32_16Wt2LanesN = 4;
}  // namespace

__global__ void mm_fp32_16_tiled_cpasync_warptile2_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __align__(16) uint16_t stagingWh[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) uint16_t stagingWr[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float As[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float Bs[kMmFp32_16V2BK][kMmFp32_16V2BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16V2BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16V2BN;

    const int tid = threadIdx.x;

    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16Wt2WarpsN;
    const int warp_col = warp_id % kMmFp32_16Wt2WarpsN;
    const int lane_row = lane_id / kMmFp32_16Wt2LanesN;
    const int lane_col = lane_id % kMmFp32_16Wt2LanesN;
    const int row_off = warp_row * (kMmFp32_16V2BM / kMmFp32_16Wt2WarpsM) + lane_row * kMmFp32_16V2TM;
    const int col_off = warp_col * (kMmFp32_16V2BN / kMmFp32_16Wt2WarpsN) + lane_col * kMmFp32_16V2TN;

    const int a_i0 = (tid % (kMmFp32_16V2BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16V2BM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16V2BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16V2BK / 4);

    constexpr int kNumThreads = (kMmFp32_16V2BM / kMmFp32_16V2TM) * (kMmFp32_16V2BN / kMmFp32_16V2TN);

    auto load_A_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[buf][a_kk][a_i0], &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[buf][a_kk][a_i0], &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[buf][a_kk][a_i0 + e] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto decode_A = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 = *reinterpret_cast<const ushort4*>(&stagingWh[buf][a_kk][a_i0]);
                ushort4 wr4 = *reinterpret_cast<const ushort4*>(&stagingWr[buf][a_kk][a_i0]);
                As[buf][a_kk][a_i0 + 0] = fp32_16_combine(wh4.x, wr4.x);
                As[buf][a_kk][a_i0 + 1] = fp32_16_combine(wh4.y, wr4.y);
                As[buf][a_kk][a_i0 + 2] = fp32_16_combine(wh4.z, wr4.z);
                As[buf][a_kk][a_i0 + 3] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
    };

    auto load_B_sync = [&](size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kNumThreads / (kMmFp32_16V2BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
                Bs[b_kk0_base + 0][b_j] = t.x;
                Bs[b_kk0_base + 1][b_j] = t.y;
                Bs[b_kk0_base + 2][b_j] = t.z;
                Bs[b_kk0_base + 3][b_j] = t.w;
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[b_kk0_base + e][b_j] = 0.0f;
            }
        }
    };

    float acc[kMmFp32_16V2TM][kMmFp32_16V2TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] = 0.0f;

    load_A_async(0, 0);
    __pipeline_wait_prior(0);
    decode_A(0, 0);

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16V2BK) {
        size_t next_k0 = k0 + kMmFp32_16V2BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_A_async(nxt, next_k0);

        load_B_sync(k0);
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16V2BK; ++kk) {
            float a_reg[kMmFp32_16V2TM];
            float b_reg[kMmFp32_16V2TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&As[cur][kk][row_off + v * 4]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&Bs[kk][col_off + v * 4]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            decode_A(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_warptile2(TransposeType transA, TransposeType transB, double alpha,
                                        dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                        size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                        double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    dim3 threads(kMmFp32_16V2BN / kMmFp32_16V2TN * kMmFp32_16V2BM / kMmFp32_16V2TM);  // 256, 1D
    dim3 blocks((n + kMmFp32_16V2BN - 1) / kMmFp32_16V2BN, (m + kMmFp32_16V2BM - 1) / kMmFp32_16V2BM);
    mm_fp32_16_tiled_cpasync_warptile2_kernel<<<blocks, threads>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Continues the trend from warptile -> warptile2 (32x64 warp tile ->
// 64x32, taller won) to its extreme: 1x8 warps x 16x2 lanes, giving each
// warp a 128x16 tile -- as tall (spanning the full BM=128) and narrow as
// this geometry allows. Same total resources as warptile/warptile2 (256
// threads, 8x8 accumulators/thread, identical shared memory and A/B load
// logic) -- only the warp/lane shape changes again.
namespace {
constexpr int kMmFp32_16Wt3WarpsM = 1;
constexpr int kMmFp32_16Wt3WarpsN = 8;
constexpr int kMmFp32_16Wt3LanesM = 16;
constexpr int kMmFp32_16Wt3LanesN = 2;
}  // namespace

__global__ void mm_fp32_16_tiled_cpasync_warptile3_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __align__(16) uint16_t stagingWh[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) uint16_t stagingWr[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float As[2][kMmFp32_16V2BK][kMmFp32_16V2BM];
    __shared__ __align__(16) float Bs[kMmFp32_16V2BK][kMmFp32_16V2BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16V2BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16V2BN;

    const int tid = threadIdx.x;

    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16Wt3WarpsN;
    const int warp_col = warp_id % kMmFp32_16Wt3WarpsN;
    const int lane_row = lane_id / kMmFp32_16Wt3LanesN;
    const int lane_col = lane_id % kMmFp32_16Wt3LanesN;
    const int row_off = warp_row * (kMmFp32_16V2BM / kMmFp32_16Wt3WarpsM) + lane_row * kMmFp32_16V2TM;
    const int col_off = warp_col * (kMmFp32_16V2BN / kMmFp32_16Wt3WarpsN) + lane_col * kMmFp32_16V2TN;

    const int a_i0 = (tid % (kMmFp32_16V2BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16V2BM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16V2BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16V2BK / 4);

    constexpr int kNumThreads = (kMmFp32_16V2BM / kMmFp32_16V2TM) * (kMmFp32_16V2BN / kMmFp32_16V2TN);

    auto load_A_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[buf][a_kk][a_i0], &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[buf][a_kk][a_i0], &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[buf][a_kk][a_i0 + e] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto decode_A = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16V2BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 = *reinterpret_cast<const ushort4*>(&stagingWh[buf][a_kk][a_i0]);
                ushort4 wr4 = *reinterpret_cast<const ushort4*>(&stagingWr[buf][a_kk][a_i0]);
                As[buf][a_kk][a_i0 + 0] = fp32_16_combine(wh4.x, wr4.x);
                As[buf][a_kk][a_i0 + 1] = fp32_16_combine(wh4.y, wr4.y);
                As[buf][a_kk][a_i0 + 2] = fp32_16_combine(wh4.z, wr4.z);
                As[buf][a_kk][a_i0 + 3] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
    };

    auto load_B_sync = [&](size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kNumThreads / (kMmFp32_16V2BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
                Bs[b_kk0_base + 0][b_j] = t.x;
                Bs[b_kk0_base + 1][b_j] = t.y;
                Bs[b_kk0_base + 2][b_j] = t.z;
                Bs[b_kk0_base + 3][b_j] = t.w;
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[b_kk0_base + e][b_j] = 0.0f;
            }
        }
    };

    float acc[kMmFp32_16V2TM][kMmFp32_16V2TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] = 0.0f;

    load_A_async(0, 0);
    __pipeline_wait_prior(0);
    decode_A(0, 0);

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16V2BK) {
        size_t next_k0 = k0 + kMmFp32_16V2BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_A_async(nxt, next_k0);

        load_B_sync(k0);
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16V2BK; ++kk) {
            float a_reg[kMmFp32_16V2TM];
            float b_reg[kMmFp32_16V2TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&As[cur][kk][row_off + v * 4]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16V2TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&Bs[kk][col_off + v * 4]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16V2TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16V2TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            decode_A(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16V2TM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16V2TN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_warptile3(TransposeType transA, TransposeType transB, double alpha,
                                        dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                        size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                        double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    dim3 threads(kMmFp32_16V2BN / kMmFp32_16V2TN * kMmFp32_16V2BM / kMmFp32_16V2TM);  // 256, 1D
    dim3 blocks((n + kMmFp32_16V2BN - 1) / kMmFp32_16V2BN, (m + kMmFp32_16V2BM - 1) / kMmFp32_16V2BM);
    mm_fp32_16_tiled_cpasync_warptile3_kernel<<<blocks, threads>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// A genuinely different mechanism from every warptile/vecN variant so
// far: B gets real cp.async prefetching too, not just A. Every prior
// kernel in this file kept B's load synchronous because B's natural
// global-contiguous direction (K) conflicts with Bs's compute-friendly
// layout ([BK][BN], N fast) -- cp.async copies a contiguous byte range
// straight through with no scatter capability, so it can't land B's
// K-contiguous source directly into that N-fast destination.
//
// The fix mirrors A's own decode step exactly: stage B's raw bytes into a
// SEPARATE, K-contiguous staging buffer ([BN][BK], matching B's natural
// layout, a valid cp.async destination), then -- once staged -- do a
// cheap shared-to-shared "transpose" scatter into the real, compute-
// friendly Bs[BK][BN], the same shape decode_A already has for A (there:
// bit-decode from staging into As; here: no decode needed, just a
// layout transpose). Both A and B are now double-buffered and prefetched
// one tile ahead; only ONE __syncthreads() per iteration is needed
// (instead of every other kernel's two), since B no longer has its own
// separate synchronous-load-then-sync step partway through the loop body.
//
// The extra staging buffer pushes shared memory to 64KB, requiring
// dynamic shared memory (same mechanism as vec3, via cudaFuncSetAttribute)
// -- comfortably inside A100's 164KB/block ceiling.
namespace {
constexpr int kMmFp32_16DualBM = 128;
constexpr int kMmFp32_16DualBN = 128;
constexpr int kMmFp32_16DualBK = 16;
constexpr int kMmFp32_16DualTM = 8;
constexpr int kMmFp32_16DualTN = 8;
constexpr int kMmFp32_16DualWarpsM = 2;
constexpr int kMmFp32_16DualWarpsN = 4;
constexpr int kMmFp32_16DualLanesM = 8;
constexpr int kMmFp32_16DualLanesN = 4;
constexpr int kMmFp32_16DualNumThreads =
    (kMmFp32_16DualBM / kMmFp32_16DualTM) * (kMmFp32_16DualBN / kMmFp32_16DualTN);  // 256

constexpr size_t kMmFp32_16DualStagingWhBytes =
    2 * static_cast<size_t>(kMmFp32_16DualBK) * kMmFp32_16DualBM * sizeof(uint16_t);
constexpr size_t kMmFp32_16DualStagingWrBytes = kMmFp32_16DualStagingWhBytes;
constexpr size_t kMmFp32_16DualAsBytes =
    2 * static_cast<size_t>(kMmFp32_16DualBK) * kMmFp32_16DualBM * sizeof(float);
constexpr size_t kMmFp32_16DualStagingBBytes =
    2 * static_cast<size_t>(kMmFp32_16DualBN) * kMmFp32_16DualBK * sizeof(float);
constexpr size_t kMmFp32_16DualBsBytes =
    2 * static_cast<size_t>(kMmFp32_16DualBK) * kMmFp32_16DualBN * sizeof(float);

constexpr size_t kMmFp32_16DualStagingWhOff = 0;
constexpr size_t kMmFp32_16DualStagingWrOff =
    kMmFp32_16DualStagingWhOff + kMmFp32_16DualStagingWhBytes;
constexpr size_t kMmFp32_16DualAsOff = kMmFp32_16DualStagingWrOff + kMmFp32_16DualStagingWrBytes;
constexpr size_t kMmFp32_16DualStagingBOff = kMmFp32_16DualAsOff + kMmFp32_16DualAsBytes;
constexpr size_t kMmFp32_16DualBsOff = kMmFp32_16DualStagingBOff + kMmFp32_16DualStagingBBytes;
constexpr size_t kMmFp32_16DualSharedBytes = kMmFp32_16DualBsOff + kMmFp32_16DualBsBytes;  // 64KB

// As/stagingWh/stagingWr share this [2][BK][BM] shape.
__device__ __forceinline__ int mm_fp32_16_dual_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16DualBK + kk) * kMmFp32_16DualBM + i;
}
// stagingB: [2][BN][BK], K fast -- matches B's own global layout.
__device__ __forceinline__ int mm_fp32_16_dual_stagingB_idx(int buf, int j, int kk) {
    return (buf * kMmFp32_16DualBN + j) * kMmFp32_16DualBK + kk;
}
// Bs: [2][BK][BN], N fast -- the compute-friendly layout, same as every
// other kernel's Bs.
__device__ __forceinline__ int mm_fp32_16_dual_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16DualBK + kk) * kMmFp32_16DualBN + j;
}
}  // namespace

// __launch_bounds__(256, 2) matters here: without it, this kernel's extra
// staging/transpose state pushes ptxas to 129 registers/thread -- just
// enough to drop occupancy from 2 resident blocks/SM (16 warps) to 1 (8
// warps), the same occupancy cliff that hurt gemm_fp32_tiled_db_kernel and
// mm_fp32_16_tiled_cpasync_vec4_kernel earlier. Forcing the 2-block budget
// keeps this kernel in the same occupancy class as warptile2/3.
__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_dualbuf_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualAsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualStagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16DualBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16DualBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16DualWarpsN;
    const int warp_col = warp_id % kMmFp32_16DualWarpsN;
    const int lane_row = lane_id / kMmFp32_16DualLanesN;
    const int lane_col = lane_id % kMmFp32_16DualLanesN;
    const int row_off =
        warp_row * (kMmFp32_16DualBM / kMmFp32_16DualWarpsM) + lane_row * kMmFp32_16DualTM;
    const int col_off =
        warp_col * (kMmFp32_16DualBN / kMmFp32_16DualWarpsN) + lane_col * kMmFp32_16DualTN;

    const int a_i0 = (tid % (kMmFp32_16DualBM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16DualBM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16DualBK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16DualBK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    // Turns this tile's staged raw bytes into the real compute buffers --
    // bit-decode for A (same as every other kernel's decode_A), a plain
    // shared-to-shared layout transpose for B (no decode needed, B is
    // already plain float). Re-derives the same validity conditions
    // load_tile_async used so it only touches groups that were actually
    // staged, leaving that function's direct zero-fills untouched.
    //
    // TRIED AND REVERTED: swapping this decode to fp32_16_combine_
    // branchless (on the theory that fp32_16_combine's round_flag-
    // correction branch, added when mant_hi rounding landed, might cost
    // real cycles here) measured ~4-7% SLOWER across N=1024..32768, not
    // faster -- the branchless version computes every path (normal/
    // extended/degraded, plus the round_flag correction) unconditionally
    // and selects via masks, which only pays off when the corresponding
    // branches are genuinely divergent within a warp. The round_flag/
    // is_carry branch is rare by construction (only fires when mant_hi_
    // pre was exactly 0x1FF and rounded up, ~1-in-1000 elements), so a
    // real branch predictor handles it almost for free; this kernel's
    // test data (uniform floats in [-1,1]) likely also lands in
    // fp32_16_combine's control=0 branch almost universally, so there
    // may be little to no genuine divergence for the branchless approach
    // to even be trading against. Kept as a documented negative result.
    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16DualTM][kMmFp32_16DualTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16DualBK) {
        size_t next_k0 = k0 + kMmFp32_16DualBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16DualBK; ++kk) {
            float a_reg[kMmFp32_16DualTM];
            float b_reg[kMmFp32_16DualTN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_dual_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf(TransposeType transA, TransposeType transB, double alpha,
                                      dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                      size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                      double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16DualSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16DualNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16DualBN - 1) / kMmFp32_16DualBN,
               (m + kMmFp32_16DualBM - 1) / kMmFp32_16DualBM);
    mm_fp32_16_tiled_cpasync_dualbuf_kernel<<<blocks, threads, kMmFp32_16DualSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// "TOMOS FP32/FP16 (fast)": UNCONDITIONAL fast_normal decode sibling of
// mm_fp32_16_tiled_cpasync_dualbuf_kernel -- byte-for-byte identical in
// every respect (same tile constants, same index functions, same
// shared-memory layout, same dual-buffered cp.async pipeline for both
// operands) EXCEPT A's decode in transform_tile calls fp32_16_combine_
// fast_normal instead of fp32_16_combine, skipping the exponent-mode
// (normal/extended/degraded) dispatch entirely -- no per-tile validity
// check either, unlike mm_fp32_16_tiled_cpasync_dualbuf_adaptive_kernel
// (which measured ~1.3-2.1% SLOWER than the plain kernel because the
// block-wide check itself cost more than the dispatch it let threads
// skip). This kernel is the untried, unconditional complement to that
// result: same idea already used unconditionally by this codebase's own
// GEVM "TOMOS FP32/FP16 (fast)" series (mv_fp32_16_accurate_ready_
// atomiconly_scaled_kblock_fast_normal), applied here to the GEMM
// dualbuf kernel instead.
//
// CORRECTNESS CONTRACT (UNSAFE ON ARBITRARY DATA): every element of A
// must have control bit (bit0 of wh) == 0, i.e. every |A[i,j]| must fall
// within fp16's own normal representable range (magnitude roughly
// [6.1e-5, 65504] per fp32_16_split's own encoding) -- see fp32_16_
// combine_fast_normal's own contract in fp32_16_pack.hpp. This kernel
// never checks that; the caller must guarantee it independently (e.g.
// via a known-safe magnitude sweep range), or silently get a wrong
// result on any out-of-range element instead of a graceful degrade.
__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_dualbuf_fast_normal_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualAsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualStagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16DualBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16DualBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16DualWarpsN;
    const int warp_col = warp_id % kMmFp32_16DualWarpsN;
    const int lane_row = lane_id / kMmFp32_16DualLanesN;
    const int lane_col = lane_id % kMmFp32_16DualLanesN;
    const int row_off =
        warp_row * (kMmFp32_16DualBM / kMmFp32_16DualWarpsM) + lane_row * kMmFp32_16DualTM;
    const int col_off =
        warp_col * (kMmFp32_16DualBN / kMmFp32_16DualWarpsN) + lane_col * kMmFp32_16DualTN;

    const int a_i0 = (tid % (kMmFp32_16DualBM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16DualBM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16DualBK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16DualBK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    // Same staged-bytes-to-compute-buffers turn as mm_fp32_16_tiled_
    // cpasync_dualbuf_kernel's own transform_tile, except A's decode
    // below is fp32_16_combine_fast_normal (unconditional, no control-
    // bit check) instead of fp32_16_combine.
    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine_fast_normal(wh4.x, wr4.x);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine_fast_normal(wh4.y, wr4.y);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine_fast_normal(wh4.z, wr4.z);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine_fast_normal(wh4.w, wr4.w);
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16DualTM][kMmFp32_16DualTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16DualBK) {
        size_t next_k0 = k0 + kMmFp32_16DualBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16DualBK; ++kk) {
            float a_reg[kMmFp32_16DualTM];
            float b_reg[kMmFp32_16DualTN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_dual_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf_fast_normal(TransposeType transA, TransposeType transB, double alpha,
                                      dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                      size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                      double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf_fast_normal_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16DualSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16DualNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16DualBN - 1) / kMmFp32_16DualBN,
               (m + kMmFp32_16DualBM - 1) / kMmFp32_16DualBM);
    mm_fp32_16_tiled_cpasync_dualbuf_fast_normal_kernel<<<blocks, threads, kMmFp32_16DualSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Byte-for-byte identical to mm_fp32_16_tiled_cpasync_dualbuf_kernel --
// same tile constants, same index functions, same shared-memory layout,
// same priming/main-loop/epilogue -- except decode_A calls fp32_16_
// combine_truncated instead of fp32_16_combine. Exists specifically to
// A/B the "always-rounded, round_flag-aware decode" kernel above against
// the "never-rounded, no-correction-at-all" decode this file used before
// mant_hi rounding was added to the packed format. CORRECTNESS CONTRACT:
// wh/wr fed to this kernel MUST come from fp32_16_split_truncated, never
// fp32_16_split/fp32_16_split_clamped -- see fp32_16_combine_truncated's
// own comment in fp32_16_pack.hpp for what silently breaks otherwise.
__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_dualbuf_truncated_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualAsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualStagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16DualBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16DualBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16DualWarpsN;
    const int warp_col = warp_id % kMmFp32_16DualWarpsN;
    const int lane_row = lane_id / kMmFp32_16DualLanesN;
    const int lane_col = lane_id % kMmFp32_16DualLanesN;
    const int row_off =
        warp_row * (kMmFp32_16DualBM / kMmFp32_16DualWarpsM) + lane_row * kMmFp32_16DualTM;
    const int col_off =
        warp_col * (kMmFp32_16DualBN / kMmFp32_16DualWarpsN) + lane_col * kMmFp32_16DualTN;

    const int a_i0 = (tid % (kMmFp32_16DualBM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16DualBM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16DualBK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16DualBK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
