            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine_truncated(wh4.x, wr4.x);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine_truncated(wh4.y, wr4.y);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine_truncated(wh4.z, wr4.z);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine_truncated(wh4.w, wr4.w);
            }
