        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16DualTM][kMmFp32_16DualTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16DualBK) {
        size_t next_k0 = k0 + kMmFp32_16DualBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16DualBK; ++kk) {
            float a_reg[kMmFp32_16DualTM];
            float b_reg[kMmFp32_16DualTN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_dual_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf_truncated(TransposeType transA, TransposeType transB, double alpha,
                                                dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                                size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                                double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf_truncated_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16DualSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16DualNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16DualBN - 1) / kMmFp32_16DualBN,
               (m + kMmFp32_16DualBM - 1) / kMmFp32_16DualBM);
    mm_fp32_16_tiled_cpasync_dualbuf_truncated_kernel<<<blocks, threads, kMmFp32_16DualSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Same tile constants, same index functions, same shared-memory layout,
// same priming/main-loop/epilogue as mm_fp32_16_tiled_cpasync_dualbuf_
// kernel -- except transform_tile first checks, once per tile via a
// block-wide __syncthreads_or reduction over the just-staged A elements'
// control bits, whether the ENTIRE tile is control=0 ("normal" exponent
// range, the common case for input data whose magnitude stays within
// fp16's own normal range). When it is, every thread in the block
// decodes that tile's A elements with fp32_16_combine_fast_normal
// (skips the offset/direction/degraded dispatch entirely); otherwise it
// falls back to the full fp32_16_combine, exactly as the plain dualbuf
// kernel always does. Exists to measure whether paying one extra block-
// wide barrier per tile (the reduction itself) is worth it in exchange
// for skipping fp32_16_combine's dispatch on tiles that never need it
// -- see fp32_16_vs_fp32_bf16_decode_investigation.tex (repo root) for
// the SASS/measurement background that motivated this. CORRECTNESS:
// this kernel is expected to be BIT-IDENTICAL to mm_fp32_16_tiled_
// cpasync_dualbuf on the same (wh,wr) input -- fp32_16_combine_fast_
// normal's own body is exactly fp32_16_combine's !control branch, so
// the two paths only ever disagree if the reduction itself picks the
// wrong branch, never because of a precision difference between them.
__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_dualbuf_adaptive_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualAsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualStagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16DualBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16DualBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16DualWarpsN;
    const int warp_col = warp_id % kMmFp32_16DualWarpsN;
    const int lane_row = lane_id / kMmFp32_16DualLanesN;
    const int lane_col = lane_id % kMmFp32_16DualLanesN;
    const int row_off =
        warp_row * (kMmFp32_16DualBM / kMmFp32_16DualWarpsM) + lane_row * kMmFp32_16DualTM;
    const int col_off =
        warp_col * (kMmFp32_16DualBN / kMmFp32_16DualWarpsN) + lane_col * kMmFp32_16DualTN;

    const int a_i0 = (tid % (kMmFp32_16DualBM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16DualBM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16DualBK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16DualBK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
        // Block-wide "does this tile need the full decode" check: every
        // thread inspects the control bit (bit0) of the (up to 8) A
        // elements it just staged -- only the ones load_tile_async
        // actually wrote (same a_row0/a_kg validity condition), since
        // stagingWh otherwise still holds a stale previous tile's bytes
        // there. __syncthreads_or combines all 256 threads' local flags
        // into one block-uniform answer, so every thread takes the
        // identical branch below -- this is a real extra block barrier
        // per tile (on top of the __syncthreads() the main loop already
        // does once per tile-step), traded against skipping fp32_16_
        // combine's dispatch when it isn't needed.
        bool local_needs_full = false;
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                local_needs_full = local_needs_full || ((wh4.x & 0x1u) != 0u) ||
                                   ((wh4.y & 0x1u) != 0u) || ((wh4.z & 0x1u) != 0u) ||
                                   ((wh4.w & 0x1u) != 0u);
            }
        }
        bool tile_needs_full = __syncthreads_or(local_needs_full);

#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                if (tile_needs_full) {
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
                } else {
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 0)] =
                        fp32_16_combine_fast_normal(wh4.x, wr4.x);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 1)] =
                        fp32_16_combine_fast_normal(wh4.y, wr4.y);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 2)] =
                        fp32_16_combine_fast_normal(wh4.z, wr4.z);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 3)] =
                        fp32_16_combine_fast_normal(wh4.w, wr4.w);
                }
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16DualTM][kMmFp32_16DualTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16DualBK) {
        size_t next_k0 = k0 + kMmFp32_16DualBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16DualBK; ++kk) {
            float a_reg[kMmFp32_16DualTM];
            float b_reg[kMmFp32_16DualTN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_dual_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf_adaptive(TransposeType transA, TransposeType transB, double alpha,
                                               dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                               size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                               double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf_adaptive_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16DualSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16DualNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16DualBN - 1) / kMmFp32_16DualBN,
               (m + kMmFp32_16DualBM - 1) / kMmFp32_16DualBM);
    mm_fp32_16_tiled_cpasync_dualbuf_adaptive_kernel<<<blocks, threads, kMmFp32_16DualSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Same idea as mm_fp32_16_tiled_cpasync_dualbuf_adaptive_kernel (skip
// fp32_16_combine's dispatch on tiles that provably don't need it), but
// the "does this need the full decode" decision is made per-WARP via
// __any_sync instead of per-BLOCK via __syncthreads_or. This is possible
// because a_kk_base (= tid/32 = warp_id) makes a_kk -- and therefore
// which 2 rows of A a given warp decodes -- warp-uniform: each warp
// owns a fixed, disjoint pair of A rows (a_kk = warp_id, warp_id+8), and
// no OTHER warp's decode work depends on this warp's fast/full choice
// (the compute phase reads As[] via a completely different thread
// mapping -- row_off/col_off, based on warp_row/lane_row -- and the
// main loop's existing __syncthreads() already makes every warp's
// writes visible before that phase runs, regardless of this kernel's
// existence). So unlike the block-wide version, this needs no shared-
// memory round trip and no wait on the other 7 warps -- __any_sync only
// reconverges the calling warp's own 32 lanes, typically a single cheap
// instruction. All lanes reach the vote reconverged (no early exits
// anywhere in this kernel), so a full 0xffffffff mask is always valid.
// Exists to test whether this measurably beats the block-wide adaptive
// kernel's own measured regression -- see mm_fp32_16_tiled_cpasync_
// dualbuf_adaptive_kernel's comment for that result.
__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_dualbuf_adaptive_warp_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16DualStagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualAsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualStagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16DualBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16DualBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16DualBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16DualWarpsN;
    const int warp_col = warp_id % kMmFp32_16DualWarpsN;
    const int lane_row = lane_id / kMmFp32_16DualLanesN;
    const int lane_col = lane_id % kMmFp32_16DualLanesN;
    const int row_off =
        warp_row * (kMmFp32_16DualBM / kMmFp32_16DualWarpsM) + lane_row * kMmFp32_16DualTM;
    const int col_off =
        warp_col * (kMmFp32_16DualBN / kMmFp32_16DualWarpsN) + lane_col * kMmFp32_16DualTN;

    const int a_i0 = (tid % (kMmFp32_16DualBM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16DualBM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16DualBK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16DualBK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
        // Warp-level "does this warp's 2 A-rows need the full decode"
        // check -- see this kernel's own top-of-file comment for why a
        // per-warp __any_sync is correct here (a_kk is warp-uniform, no
        // other warp depends on this warp's choice).
        bool local_needs_full = false;
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                local_needs_full = local_needs_full || ((wh4.x & 0x1u) != 0u) ||
                                   ((wh4.y & 0x1u) != 0u) || ((wh4.z & 0x1u) != 0u) ||
                                   ((wh4.w & 0x1u) != 0u);
            }
        }
        bool warp_needs_full = __any_sync(0xffffffffu, local_needs_full);

#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                if (warp_needs_full) {
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
                } else {
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 0)] =
                        fp32_16_combine_fast_normal(wh4.x, wr4.x);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 1)] =
                        fp32_16_combine_fast_normal(wh4.y, wr4.y);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 2)] =
                        fp32_16_combine_fast_normal(wh4.z, wr4.z);
                    As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 3)] =
                        fp32_16_combine_fast_normal(wh4.w, wr4.w);
                }
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16DualTM][kMmFp32_16DualTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16DualBK) {
        size_t next_k0 = k0 + kMmFp32_16DualBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16DualBK; ++kk) {
            float a_reg[kMmFp32_16DualTM];
            float b_reg[kMmFp32_16DualTN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_dual_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16DualTN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf_adaptive_warp(TransposeType transA, TransposeType transB, double alpha,
                                                     dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                                     size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                                     double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf_adaptive_warp_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16DualSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16DualNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16DualBN - 1) / kMmFp32_16DualBN,
               (m + kMmFp32_16DualBM - 1) / kMmFp32_16DualBM);
    mm_fp32_16_tiled_cpasync_dualbuf_adaptive_warp_kernel<<<blocks, threads, kMmFp32_16DualSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

namespace {
// Reuses kMmFp32_16Dual{BM,BK,TM,TN,WarpsM,WarpsN,LanesM,LanesN,NumThreads}
// and the mm_fp32_16_dual_{a,stagingB,bs}_idx index functions unchanged --
// only the shared-memory layout differs (B's staging/Bs buffers exist in
// TWO copies, one per N-group, since both groups' B tiles must be
// resident simultaneously across the whole K-loop; A's layout is a
// single copy, shared by both groups).
constexpr size_t kMmFp32_16MultiNStagingWhOff = 0;
constexpr size_t kMmFp32_16MultiNStagingWrOff =
    kMmFp32_16MultiNStagingWhOff + kMmFp32_16DualStagingWhBytes;
constexpr size_t kMmFp32_16MultiNAsOff = kMmFp32_16MultiNStagingWrOff + kMmFp32_16DualStagingWrBytes;
constexpr size_t kMmFp32_16MultiNStagingB0Off = kMmFp32_16MultiNAsOff + kMmFp32_16DualAsBytes;
constexpr size_t kMmFp32_16MultiNBs0Off = kMmFp32_16MultiNStagingB0Off + kMmFp32_16DualStagingBBytes;
constexpr size_t kMmFp32_16MultiNStagingB1Off = kMmFp32_16MultiNBs0Off + kMmFp32_16DualBsBytes;
constexpr size_t kMmFp32_16MultiNBs1Off = kMmFp32_16MultiNStagingB1Off + kMmFp32_16DualStagingBBytes;
constexpr size_t kMmFp32_16MultiNSharedBytes = kMmFp32_16MultiNBs1Off + kMmFp32_16DualBsBytes;  // ~96KB
}  // namespace

// A different strategy from mm_fp32_16_tiled_cpasync_dualbuf_adaptive[_
// warp]: instead of making each block's own decode cheaper, this
// eliminates the REDUNDANT decode entirely. In the plain dualbuf kernel,
// every block redundantly re-decodes the same A data -- N/BN different
// blocks share the same M-row range (block_row), and each independently
// runs fp32_16_combine on the identical (wh,wr) bytes into its own
// private shared-memory As, since shared memory isn't visible across
// blocks (see fp32_16_vs_fp32_bf16_decode_investigation.tex, repo root,
// for the SASS/measurement background on why that decode is expensive
// in the first place). This kernel instead has each block cover TWO
// adjacent BN-wide N-tiles instead of one, decoding A into shared
// memory ONCE per K-step and reusing that same As for BOTH N-groups'
// accumulation before moving to the next K-step -- halving the number
// of blocks (and therefore the redundant-decode factor) that cover a
// given M-row range, with zero extra global memory traffic and no
// change to A's own decode logic at all (plain fp32_16_combine, same as
// the original dualbuf kernel -- this is orthogonal to, and could later
// be combined with, the adaptive/truncated decode ideas).
//
// Cost: each thread now holds TWO acc[TM][TN] accumulator arrays (one
// per N-group) live simultaneously across the whole K-loop, instead of
// one -- roughly doubling this kernel's accumulator register footprint
// versus mm_fp32_16_tiled_cpasync_dualbuf_kernel. That blows well past
// the 128-register ceiling that lets the plain kernel fit 2 blocks/SM
// under __launch_bounds__(256,2), so this kernel targets only 1
// block/SM (__launch_bounds__(256,1)) instead -- see the ptxas
// register count from the build for the actual figure. Trading
// occupancy (half as many resident warps/SM) for a halved decode-
// redundancy factor; which one wins is exactly what this comparison is
// for.
__global__ __launch_bounds__(256, 1) void mm_fp32_16_tiled_cpasync_dualbuf_multin_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16MultiNStagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16MultiNStagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16MultiNAsOff);
    float* stagingB0 = reinterpret_cast<float*>(smem_raw + kMmFp32_16MultiNStagingB0Off);
    float* Bs0 = reinterpret_cast<float*>(smem_raw + kMmFp32_16MultiNBs0Off);
    float* stagingB1 = reinterpret_cast<float*>(smem_raw + kMmFp32_16MultiNStagingB1Off);
    float* Bs1 = reinterpret_cast<float*>(smem_raw + kMmFp32_16MultiNBs1Off);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16DualBM;
    const size_t block_col0 = static_cast<size_t>(blockIdx.x) * (2 * kMmFp32_16DualBN);
    const size_t block_col1 = block_col0 + kMmFp32_16DualBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16DualWarpsN;
    const int warp_col = warp_id % kMmFp32_16DualWarpsN;
    const int lane_row = lane_id / kMmFp32_16DualLanesN;
    const int lane_col = lane_id % kMmFp32_16DualLanesN;
    const int row_off =
        warp_row * (kMmFp32_16DualBM / kMmFp32_16DualWarpsM) + lane_row * kMmFp32_16DualTM;
    const int col_off =
        warp_col * (kMmFp32_16DualBN / kMmFp32_16DualWarpsN) + lane_col * kMmFp32_16DualTN;

    const int a_i0 = (tid % (kMmFp32_16DualBM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16DualBM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16DualBK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16DualBK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_kg0 = k0 + b_kk0_base;
            size_t b_col0v = block_col0 + b_j;
            if (b_col0v < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB0[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col0v * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs0[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
            size_t b_col1v = block_col1 + b_j;
            if (b_col1v < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB1[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col1v * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs1[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16DualBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                As[mm_fp32_16_dual_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16DualNumThreads / (kMmFp32_16DualBK / 4));
            size_t b_kg0 = k0 + b_kk0_base;
            size_t b_col0v = block_col0 + b_j;
            if (b_col0v < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB0[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs0[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs0[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs0[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs0[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
            size_t b_col1v = block_col1 + b_j;
            if (b_col1v < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB1[mm_fp32_16_dual_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs1[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs1[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs1[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs1[mm_fp32_16_dual_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc0[kMmFp32_16DualTM][kMmFp32_16DualTN];
    float acc1[kMmFp32_16DualTM][kMmFp32_16DualTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) {
            acc0[i][j] = 0.0f;
            acc1[i][j] = 0.0f;
        }

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16DualBK) {
        size_t next_k0 = k0 + kMmFp32_16DualBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16DualBK; ++kk) {
            float a_reg[kMmFp32_16DualTM];
            float b_reg0[kMmFp32_16DualTN];
            float b_reg1[kMmFp32_16DualTN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16DualTN / 4; ++v) {
                float4 t0 = *reinterpret_cast<const float4*>(
                    &Bs0[mm_fp32_16_dual_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg0[v * 4 + 0] = t0.x;
                b_reg0[v * 4 + 1] = t0.y;
                b_reg0[v * 4 + 2] = t0.z;
                b_reg0[v * 4 + 3] = t0.w;
                float4 t1 = *reinterpret_cast<const float4*>(
                    &Bs1[mm_fp32_16_dual_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg1[v * 4 + 0] = t1.x;
                b_reg1[v * 4 + 1] = t1.y;
                b_reg1[v * 4 + 2] = t1.z;
                b_reg1[v * 4 + 3] = t1.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16DualTM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16DualTN; ++j) {
                    acc0[i][j] += a_reg[i] * b_reg0[j];
                    acc1[i][j] += a_reg[i] * b_reg1[j];
                }
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16DualTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16DualTN; ++j) {
            size_t col0v = block_col0 + col_off + j;
            if (col0v < n) {
                size_t idx0 = row + col0v * ld_c;
                C[idx0] = static_cast<float>(alpha * static_cast<double>(acc0[i][j]) +
                                             beta * static_cast<double>(C[idx0]));
            }
            size_t col1v = block_col1 + col_off + j;
            if (col1v < n) {
                size_t idx1 = row + col1v * ld_c;
                C[idx1] = static_cast<float>(alpha * static_cast<double>(acc1[i][j]) +
                                             beta * static_cast<double>(C[idx1]));
            }
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf_multin(TransposeType transA, TransposeType transB, double alpha,
                                             dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                             size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                             double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf_multin_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16MultiNSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16DualNumThreads);  // 256, 1D
    dim3 blocks((n + 2 * kMmFp32_16DualBN - 1) / (2 * kMmFp32_16DualBN),
               (m + kMmFp32_16DualBM - 1) / kMmFp32_16DualBM);
    mm_fp32_16_tiled_cpasync_dualbuf_multin_kernel<<<blocks, threads, kMmFp32_16MultiNSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Second strategy for the same redundant-decode problem described above
// mm_fp32_16_tiled_cpasync_dualbuf_multin_kernel, this time attacking it
// from the opposite direction: instead of keeping decode fused into the
// GEMM kernel and reusing it on-chip across a couple of N-tiles, this
// decodes A into a plain fp32 GLOBAL-memory buffer up front -- exactly
// ONCE per element, independent of N entirely -- then hands that buffer
// to gemm_fp32_tiled_cpasync_dualbuf (this codebase's fastest plain fp32
// GEMM, see mm_cuda_kernels.cu), which needs no decode logic of its own
// at all. Materializing the FULL M x K matrix at once would need an
// extra M*K*4-byte allocation on top of wh/wr's own M*K*4 bytes combined
// (2 bytes each) -- a serious risk at the largest sizes this codebase
// tests (e.g. M=K=49152 already has wh+wr+B+C at ~29GB combined on a
// 40GB A100 before adding a full extra copy of A). Instead this
// processes M in kMmFp32_16MaterializeChunkRows-row strips: decode one
// strip into a small, REUSED scratch buffer (kMmFp32_16MaterializeChunk
// Rows * K * 4 bytes, independent of M), immediately run the native
// GEMM against that strip across the FULL n range (exactly where the
// N/BN redundancy would otherwise occur), then move to the next strip.
// Total decode work is O(M*K) regardless of chunk size -- chunk size
// only trades scratch memory against the number of separate native-GEMM
// launches (each of which re-reads the FULL B matrix, so fewer/bigger
// chunks means fewer redundant B re-reads, at the cost of a bigger
// scratch allocation).
//
// COMPARISON-ONLY env-var toggle: set
// TOMOS_FP32_16_WORKSPACE_CHUNK_ROWS=N to override the default below
// at runtime (no rebuild needed) -- exists to A/B this exact trade-off
// (scratch memory / launch+redundant-B-traffic count) without touching
// the default any shipped benchmark relies on.
size_t mm_fp32_16_materialize_chunk_rows() {
    static const size_t value = []() -> size_t {
        if (const char* env = std::getenv("TOMOS_FP32_16_WORKSPACE_CHUNK_ROWS")) {
            size_t parsed = std::strtoul(env, nullptr, 10);
            if (parsed > 0) return parsed;
        }
        return 2048;
    }();
    return value;
}

__global__ void mm_fp32_16_materialize_chunk_kernel(size_t chunk_rows, size_t row_offset, size_t k,
                                                     const uint16_t* __restrict__ wh,
                                                     const uint16_t* __restrict__ wr, size_t ld_a,
                                                     float* __restrict__ out, size_t ld_out) {
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    size_t total = chunk_rows * k;
    if (idx >= total) return;
    size_t local_row = idx % chunk_rows;
    size_t col = idx / chunk_rows;
    size_t src_idx = (row_offset + local_row) + col * ld_a;
    size_t dst_idx = local_row + col * ld_out;
    out[dst_idx] = fp32_16_combine(wh[src_idx], wr[src_idx]);
}

void mm_fp32_16_gemm_materialize(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    size_t scratch_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m);
    float* scratch = nullptr;
    if (cudaMalloc(&scratch, scratch_rows * k * sizeof(float)) != cudaSuccess) {
        // Scratch chunk itself doesn't fit (pathologically large K) --
        // fall back to the fused-decode kernel rather than fail outright.
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    for (size_t row0 = 0; row0 < m; row0 += mm_fp32_16_materialize_chunk_rows()) {
        size_t chunk_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m - row0);
        size_t total = chunk_rows * k;
        int threads = 256;
        int blocks = static_cast<int>((total + static_cast<size_t>(threads) - 1) / threads);
        mm_fp32_16_materialize_chunk_kernel<<<blocks, threads>>>(chunk_rows, row0, k, wh, wr, ld_a,
                                                                  scratch, chunk_rows);
        gemm_fp32_tiled_cpasync_dualbuf(TransposeType::NO_TRANSPOSE, TransposeType::NO_TRANSPOSE, alpha,
                                        chunk_rows, k, n, scratch, chunk_rows, const_cast<float*>(B), ld_b,
                                        beta, C + row0, ld_c);
    }

    cudaFree(scratch);
}

// Identical structure to mm_fp32_16_gemm_materialize above (same
// materialize_chunk_kernel decode pass, same kMmFp32_16MaterializeChunk
// Rows chunking, same scratch-buffer allocation/fallback) EXCEPT the
// second-stage native GEMM call is gemm_fp32_tiled_syncpipe4_bk8_
// warptile_nostride_snake_midpoint_exact instead of gemm_fp32_tiled_
// cpasync_dualbuf. Since materialize's decode pass is a wholly separate
// global-memory prepass (not fused into any tiled GEMM pipeline), the
// native GEMM stage is a genuine black box here -- no new __global__
// kernel logic is needed, just this new host wrapper. midpoint_exact
// has its own internal alignment/exact-multiple-of-tile-size dispatch
// guards (falls back to a bounds-checked sibling automatically for
// chunk_rows that don't divide evenly, e.g. a ragged final chunk when m
// isn't a multiple of kMmFp32_16MaterializeChunkRows=4096), so no extra
// fallback logic is needed here either -- same as the original wrapper
// relying on gemm_fp32_tiled_cpasync_dualbuf's own internal guards.
void mm_fp32_16_gemm_materialize_midpoint_exact(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    size_t scratch_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m);
    float* scratch = nullptr;
    if (cudaMalloc(&scratch, scratch_rows * k * sizeof(float)) != cudaSuccess) {
        // Scratch chunk itself doesn't fit (pathologically large K) --
        // fall back to the fused-decode kernel rather than fail outright.
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    for (size_t row0 = 0; row0 < m; row0 += mm_fp32_16_materialize_chunk_rows()) {
        size_t chunk_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m - row0);
        size_t total = chunk_rows * k;
        int threads = 256;
        int blocks = static_cast<int>((total + static_cast<size_t>(threads) - 1) / threads);
        mm_fp32_16_materialize_chunk_kernel<<<blocks, threads>>>(chunk_rows, row0, k, wh, wr, ld_a,
                                                                  scratch, chunk_rows);
        gemm_fp32_tiled_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact(TransposeType::NO_TRANSPOSE, TransposeType::NO_TRANSPOSE, alpha,
                                        chunk_rows, k, n, scratch, chunk_rows, const_cast<float*>(B), ld_b,
                                        beta, C + row0, ld_c);
    }

    cudaFree(scratch);
}

// "TOMOS FP32/FP16 (workspace, fast)": UNCONDITIONAL fast_normal decode
// sibling of mm_fp32_16_materialize_chunk_kernel -- identical in every
// respect (same one-thread-per-element grid, same chunked decode-into-
// global-scratch strategy) except it calls fp32_16_combine_fast_normal
// instead of fp32_16_combine, skipping the exponent-mode (normal/
// extended/degraded) dispatch entirely, no per-element validity check.
// CORRECTNESS CONTRACT (UNSAFE ON ARBITRARY DATA): every element of A
// must have control bit (bit0 of wh) == 0 -- see fp32_16_combine_fast_
// normal's own contract in fp32_16_pack.hpp. Never checked here; the
// caller must guarantee it independently.
__global__ void mm_fp32_16_materialize_chunk_fast_normal_kernel(size_t chunk_rows, size_t row_offset, size_t k,
                                                                  const uint16_t* __restrict__ wh,
                                                                  const uint16_t* __restrict__ wr, size_t ld_a,
                                                                  float* __restrict__ out, size_t ld_out) {
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    size_t total = chunk_rows * k;
    if (idx >= total) return;
    size_t local_row = idx % chunk_rows;
    size_t col = idx / chunk_rows;
    size_t src_idx = (row_offset + local_row) + col * ld_a;
    size_t dst_idx = local_row + col * ld_out;
    out[dst_idx] = fp32_16_combine_fast_normal(wh[src_idx], wr[src_idx]);
}

// "TOMOS FP32/FP16 (workspace, fast)": UNCONDITIONAL fast_normal sibling
// of mm_fp32_16_gemm_materialize_midpoint_exact above -- identical
// two-phase materialize-then-native-GEMM structure (same chunking, same
// gemm_fp32_tiled_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact
// compute stage, unmodified), except the chunk-decode pass calls
// mm_fp32_16_materialize_chunk_fast_normal_kernel instead of mm_fp32_16_
// materialize_chunk_kernel. Same UNSAFE-on-arbitrary-data contract as
// that kernel: every element of A must have control bit (bit0 of wh)
// == 0, never checked here.
void mm_fp32_16_gemm_materialize_midpoint_exact_fast_normal(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    size_t scratch_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m);
    float* scratch = nullptr;
    if (cudaMalloc(&scratch, scratch_rows * k * sizeof(float)) != cudaSuccess) {
        // Scratch chunk itself doesn't fit (pathologically large K) --
        // fall back to the fused-decode kernel rather than fail outright.
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    for (size_t row0 = 0; row0 < m; row0 += mm_fp32_16_materialize_chunk_rows()) {
        size_t chunk_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m - row0);
        size_t total = chunk_rows * k;
        int threads = 256;
        int blocks = static_cast<int>((total + static_cast<size_t>(threads) - 1) / threads);
        mm_fp32_16_materialize_chunk_fast_normal_kernel<<<blocks, threads>>>(chunk_rows, row0, k, wh, wr, ld_a,
                                                                              scratch, chunk_rows);
        gemm_fp32_tiled_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact(TransposeType::NO_TRANSPOSE, TransposeType::NO_TRANSPOSE, alpha,
                                        chunk_rows, k, n, scratch, chunk_rows, const_cast<float*>(B), ld_b,
                                        beta, C + row0, ld_c);
    }

    cudaFree(scratch);
}

// EXPERIMENT: vectorized decode for mm_fp32_16_gemm_materialize_
// midpoint_exact's own chunk-decode pass. mm_fp32_16_materialize_chunk_
// kernel above is a pure memory-bandwidth-bound kernel (one thread, one
// scalar wh/wr load, one scalar fp32_16_combine, one scalar store per
// element) -- this decode pass is the ENTIRE extra cost materialize
// pays over plain native fp32 (the GEMM stage itself is already this
// codebase's best native kernel either way), so speeding it up flows
// straight into materialize's total time. This kernel groups 4
// consecutive rows per thread (rows are the fastest-varying/leading
// dimension in this column-major layout, so 4 consecutive rows ARE 4
// consecutive elements in memory) and reads/writes them via ushort4/
// float4 in one shot instead of 4 separate scalar accesses, with a
// scalar fallback for a chunk's final partial group of <4 rows (needed
// whenever chunk_rows isn't itself a multiple of 4 -- e.g. any ragged
// last chunk).
//
// ALIGNMENT CONTRACT (host wrapper enforces both):
//   - ld_a must be a multiple of 4: row_offset (always a multiple of
//     kMmFp32_16MaterializeChunkRows=4096, hence of 4) and each group's
//     local_row0 (always a multiple of 4 by construction) already keep
//     the row-offset component of src_idx0 aligned; ld_a%4==0 is what
//     keeps col*ld_a from breaking that alignment as col varies.
//   - ld_out must be a multiple of 4: the host wrapper pads the
//     scratch buffer's own leading dimension up to the next multiple
//     of 4 (a few extra bytes at most) specifically so this holds for
//     every column, not just column 0.
// Both were verified against a host-side simulation (27 shapes,
// including ragged/single-row/multi-chunk cases) before this was ever
// compiled -- exact match against the scalar kernel's own indexing,
// zero out-of-bounds writes.
__global__ void mm_fp32_16_materialize_chunk_vec_kernel(size_t chunk_rows, size_t row_offset, size_t k,
                                                         const uint16_t* __restrict__ wh,
                                                         const uint16_t* __restrict__ wr, size_t ld_a,
                                                         float* __restrict__ out, size_t ld_out) {
    size_t row_groups = (chunk_rows + 3) / 4;
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    size_t total_groups = row_groups * k;
    if (idx >= total_groups) return;
    size_t group = idx % row_groups;
    size_t col = idx / row_groups;
    size_t local_row0 = group * 4;
    size_t src_idx0 = (row_offset + local_row0) + col * ld_a;
    size_t dst_idx0 = local_row0 + col * ld_out;
    if (local_row0 + 4 <= chunk_rows) {
        ushort4 wh4 = *reinterpret_cast<const ushort4*>(&wh[src_idx0]);
        ushort4 wr4 = *reinterpret_cast<const ushort4*>(&wr[src_idx0]);
        float4 out4;
        out4.x = fp32_16_combine(wh4.x, wr4.x);
        out4.y = fp32_16_combine(wh4.y, wr4.y);
        out4.z = fp32_16_combine(wh4.z, wr4.z);
        out4.w = fp32_16_combine(wh4.w, wr4.w);
        *reinterpret_cast<float4*>(&out[dst_idx0]) = out4;
    } else {
        for (size_t r = local_row0; r < chunk_rows; ++r) {
            size_t src_idx = (row_offset + r) + col * ld_a;
            size_t dst_idx = r + col * ld_out;
            out[dst_idx] = fp32_16_combine(wh[src_idx], wr[src_idx]);
        }
    }
}

// Host wrapper: identical structure/fallback contract to mm_fp32_16_
// gemm_materialize_midpoint_exact above, EXCEPT it calls the vectorized
// decode kernel and pads the scratch buffer's leading dimension to a
// multiple of 4 (see that kernel's own comment for why). Falls back to
// the plain scalar-decode materialize kernel when ld_a isn't a multiple
// of 4 (can't safely issue aligned ushort4 reads of wh/wr in that case)
// -- same "misaligned -> fall back to the always-safe sibling" pattern
// used throughout this codebase (e.g. mm_fp32_16_tiled_cpasync_vec2/
// vec3's own alignment guards).
void mm_fp32_16_gemm_materialize_midpoint_exact_vec(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    if (ld_a % 4 != 0) {
        mm_fp32_16_gemm_materialize_midpoint_exact(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                                    beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    size_t scratch_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m);
    size_t scratch_rows_padded = (scratch_rows + 3) / 4 * 4;
    float* scratch = nullptr;
    if (cudaMalloc(&scratch, scratch_rows_padded * k * sizeof(float)) != cudaSuccess) {
        // Scratch chunk itself doesn't fit (pathologically large K) --
        // fall back to the fused-decode kernel rather than fail outright.
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    for (size_t row0 = 0; row0 < m; row0 += mm_fp32_16_materialize_chunk_rows()) {
        size_t chunk_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m - row0);
        size_t row_groups = (chunk_rows + 3) / 4;
        size_t total = row_groups * k;
        int threads = 256;
        int blocks = static_cast<int>((total + static_cast<size_t>(threads) - 1) / threads);
        mm_fp32_16_materialize_chunk_vec_kernel<<<blocks, threads>>>(chunk_rows, row0, k, wh, wr, ld_a,
                                                                      scratch, scratch_rows_padded);
        gemm_fp32_tiled_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact(TransposeType::NO_TRANSPOSE, TransposeType::NO_TRANSPOSE, alpha,
                                        chunk_rows, k, n, scratch, scratch_rows_padded, const_cast<float*>(B), ld_b,
                                        beta, C + row0, ld_c);
    }

    cudaFree(scratch);
}

// Naive, always-correct-for-any-shape fallback for the ROUNDED fp32_bf16
// format -- mirrors mm_fp32_bf16_accurate_kernel (fp32_bf16_cuda_
// kernels.cu) exactly (one thread per output element C(i,j), scalar
// per-element loads so alignment never matters, transpose handled via
// the same conditional index swap) EXCEPT the decode call is fp32_bf16_
// combine_rounded instead of fp32_bf16_combine. This closes a real
// correctness gap: unlike fp32_16 (where fp32_16_combine safely decodes
// BOTH its own rounded output AND fp32_16_split_truncated's output,
// since round_flag=0 makes its correction a no-op), fp32_bf16's two
// formats are mutually incompatible in both directions -- fp32_bf16_
// combine (plain) silently produces wrong results on rounded-encoded
// data whenever round_flag=1, so mm_fp32_bf16_accurate (plain-decode)
// is NOT a safe transpose/misaligned fallback for anything downstream
// of fp32_bf16_split_rounded, even though the analogous plain fallback
// IS safe for fp32_16's truncated kernel. This kernel is the correctly-
// decoding replacement, used as the transpose/misaligned/malloc-failure
// fallback for both mm_fp32_bf16_gemm_materialize_rounded and mm_fp32_
// bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded
// below.
namespace {
__global__ void mm_fp32_bf16_accurate_rounded_kernel(
    TransposeType transA, TransposeType transB, double alpha, size_t m,
    size_t k, size_t n, const uint16_t* wh, const uint16_t* wr, size_t ld_a,
    const float* B, size_t ld_b, double beta, float* C, size_t ld_c) {
    size_t i = blockIdx.y * blockDim.y + threadIdx.y;
    size_t j = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= m || j >= n) return;

    double acc = 0.0;
    for (size_t l = 0; l < k; ++l) {
        size_t a_row = (transA == TransposeType::NO_TRANSPOSE) ? i : l;
        size_t a_col = (transA == TransposeType::NO_TRANSPOSE) ? l : i;
        size_t idx = a_row + a_col * ld_a;
        double a_val = static_cast<double>(fp32_bf16_combine_rounded(wh[idx], wr[idx]));
        double b_val = (transB == TransposeType::NO_TRANSPOSE)
                          ? static_cast<double>(B[l + j * ld_b])
                          : static_cast<double>(B[j + l * ld_b]);
        acc += a_val * b_val;
    }
    C[i + j * ld_c] = (beta != 0.0)
                          ? static_cast<float>(alpha * acc + beta * static_cast<double>(
                                                                 C[i + j * ld_c]))
                          : static_cast<float>(alpha * acc);
}
}  // namespace

void mm_fp32_bf16_accurate_rounded(TransposeType transA, TransposeType transB,
                           double alpha, dim<2> size_A, const uint16_t* wh,
                           const uint16_t* wr, size_t ld_a, dim<2> size_B,
                           const float* B, size_t ld_b, double beta, float* C,
                           size_t ld_c) {
    size_t m = (transA == TransposeType::NO_TRANSPOSE) ? size_A[0] : size_A[1];
    size_t k = (transA == TransposeType::NO_TRANSPOSE) ? size_A[1] : size_A[0];
    size_t n = (transB == TransposeType::NO_TRANSPOSE) ? size_B[1] : size_B[0];

    dim3 threads(32, 8);
    dim3 blocks((n + threads.x - 1) / threads.x, (m + threads.y - 1) / threads.y);
    mm_fp32_bf16_accurate_rounded_kernel<<<blocks, threads>>>(
        transA, transB, alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
    cudaDeviceSynchronize();
}

// Rounded-encoding counterpart to mm_fp32_16_gemm_materialize_midpoint_
// exact above -- identical materialize structure (same kMmFp32_16
// MaterializeChunkRows chunking, same scratch-buffer allocation) EXCEPT
// the decode kernel calls fp32_bf16_combine_rounded and the transpose/
// malloc-failure fallback is mm_fp32_bf16_accurate_rounded (NOT mm_
// fp32_bf16_accurate -- see that function's own comment for why the
// plain decoder is unsafe here). Since materialize's own decode pass is
// a simple per-element kernel (no vectorized loads, no GEMM tiling
// register pressure), it sidesteps mm_fp32_bf16_syncpipe4_bk8_warptile_
// nostride_snake_midpoint_exact_rounded_kernel's real spill entirely --
// same "decode once, then hand off to the already-proven 0-spill native
// GEMM" strategy that made materialize_midpoint_exact win outright for
// fp32_16.
__global__ void mm_fp32_bf16_materialize_rounded_chunk_kernel(size_t chunk_rows, size_t row_offset, size_t k,
                                                     const uint16_t* __restrict__ wh,
                                                     const uint16_t* __restrict__ wr, size_t ld_a,
                                                     float* __restrict__ out, size_t ld_out) {
    size_t idx = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    size_t total = chunk_rows * k;
    if (idx >= total) return;
    size_t local_row = idx % chunk_rows;
    size_t col = idx / chunk_rows;
    size_t src_idx = (row_offset + local_row) + col * ld_a;
    size_t dst_idx = local_row + col * ld_out;
    out[dst_idx] = fp32_bf16_combine_rounded(wh[src_idx], wr[src_idx]);
}

void mm_fp32_bf16_gemm_materialize_rounded(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_bf16_accurate_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                              beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    size_t scratch_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m);
    float* scratch = nullptr;
    if (cudaMalloc(&scratch, scratch_rows * k * sizeof(float)) != cudaSuccess) {
        // Scratch chunk itself doesn't fit (pathologically large K) --
        // fall back to the naive rounded-decode kernel (correct for any
        // size, just slow) rather than a wrong-decode kernel or failing
        // outright.
        mm_fp32_bf16_accurate_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }

    for (size_t row0 = 0; row0 < m; row0 += mm_fp32_16_materialize_chunk_rows()) {
        size_t chunk_rows = std::min(mm_fp32_16_materialize_chunk_rows(), m - row0);
        size_t total = chunk_rows * k;
        int threads = 256;
        int blocks = static_cast<int>((total + static_cast<size_t>(threads) - 1) / threads);
        mm_fp32_bf16_materialize_rounded_chunk_kernel<<<blocks, threads>>>(chunk_rows, row0, k, wh, wr, ld_a,
                                                                  scratch, chunk_rows);
        gemm_fp32_tiled_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact(TransposeType::NO_TRANSPOSE, TransposeType::NO_TRANSPOSE, alpha,
                                        chunk_rows, k, n, scratch, chunk_rows, const_cast<float*>(B), ld_b,
                                        beta, C + row0, ld_c);
    }

    cudaFree(scratch);
}

// A genuinely fused counterpart to mm_fp32_16_gemm_materialize_midpoint_
// exact above: instead of decoding A to a separate global-memory scratch
// buffer and calling the native fp32 GEMM as a black box, this ports
// gemm_fp32_tiled_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact's
// ENTIRE tiling structure into this file and decodes wh/wr straight into
// the tile pipeline's shared-memory A buffer -- the same "decode once
// per BK-tile into shared memory" placement mm_fp32_16_tiled_cpasync_
// dualbuf_kernel's own transform_tile already uses (see that kernel's
// comment), just retargeted at midpoint_exact's newer tile/warp/
// pipeline/traversal shape instead of dualbuf's BK=16/2-stage/plain-
// row-major one. Concretely, every one of midpoint_exact's headline
// techniques is carried over unchanged: BK=8 (matching CUTLASS's real
// ThreadblockShape<128,128,8>, vs this file's own BK=16), the CUTLASS
// RowMajorInterleaved<2> warp/lane geometry (vs plain row-major here),
// the 4-stage rotating shared-memory pipeline (vs 2-stage), rolling-
// pointer ("nostride") addressing, the snake (boustrophedon) FFMA
// accumulate traversal, the interleaved i==4 prefetch checkpoint, and
// the bounds-check-free "exact" fast path -- the ONLY change from
// midpoint_exact's own kernel is that load_global_advance's A-side load
// becomes two ushort4 reads (wh, wr) plus a 4-wide fp32_16_combine
// decode (exactly mirroring transform_tile's A-side idiom) in place of
// a single float4 read, with everything downstream of that decode (B
// loading, shared-memory layout, register loads, the FFMA nest, the
// epilogue) untouched. See the file-level "exact" fast-path guard on
// midpoint_exact's own host wrapper (mm_cuda_kernels.cu) for why no
// bounds check is needed once the host-side exact-multiple dispatch
// guard below holds.
namespace {
constexpr int kMmFp32_16MidExactBM = 128;
constexpr int kMmFp32_16MidExactBN = 128;
constexpr int kMmFp32_16MidExactBK = 8;
constexpr int kMmFp32_16MidExactTM = 8;
constexpr int kMmFp32_16MidExactTN = 8;
constexpr int kMmFp32_16MidExactWarpsM = 4;
constexpr int kMmFp32_16MidExactWarpsN = 2;
constexpr int kMmFp32_16MidExactNumThreads =
    (kMmFp32_16MidExactBM / kMmFp32_16MidExactTM) * (kMmFp32_16MidExactBN / kMmFp32_16MidExactTN);  // 256

__device__ __forceinline__ int mm_fp32_16_mid_exact_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16MidExactBK + kk) * kMmFp32_16MidExactBM + i;
}
__device__ __forceinline__ int mm_fp32_16_mid_exact_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16MidExactBK + kk) * kMmFp32_16MidExactBN + j;
}

constexpr size_t kMmFp32_16MidExactAsBytes =
    4UL * kMmFp32_16MidExactBK * kMmFp32_16MidExactBM * sizeof(float);
constexpr size_t kMmFp32_16MidExactBsBytes =
    4UL * kMmFp32_16MidExactBK * kMmFp32_16MidExactBN * sizeof(float);
constexpr size_t kMmFp32_16MidExactAsOff = 0;
constexpr size_t kMmFp32_16MidExactBsOff = kMmFp32_16MidExactAsOff + kMmFp32_16MidExactAsBytes;
constexpr size_t kMmFp32_16MidExactSharedBytes = kMmFp32_16MidExactBsOff + kMmFp32_16MidExactBsBytes;
}  // namespace

__global__ __launch_bounds__(256, 2) void mm_fp32_16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactAsOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16MidExactBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16MidExactBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16MidExactWarpsN;
    const int warp_col = warp_id % kMmFp32_16MidExactWarpsN;
    // CUTLASS's actual RowMajorInterleaved<2> lane mapping -- see
    // gemm_fp32_tiled_syncpipe4_bk8_warptile_kernel's own comment
    // (mm_cuda_kernels.cu) for the derivation from its real source.
    const int lane_row = 2 * (lane_id / 16) + (lane_id % 2);
    const int lane_col = (lane_id % 16) / 2;
    const int row_off =
        warp_row * (kMmFp32_16MidExactBM / kMmFp32_16MidExactWarpsM) + lane_row * kMmFp32_16MidExactTM;
    const int col_off =
        warp_col * (kMmFp32_16MidExactBN / kMmFp32_16MidExactWarpsN) + lane_col * kMmFp32_16MidExactTN;

    const int a_i0 = (tid % (kMmFp32_16MidExactBM / 4)) * 4;
    const int a_kk = tid / (kMmFp32_16MidExactBM / 4);
    const int b_kk0 = (tid % (kMmFp32_16MidExactBK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16MidExactBK / 4);

    const size_t a_row0 = block_row + a_i0;
    const size_t b_col = block_col + b_j;

    const uint16_t* wh_ptr0 = &wh[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const uint16_t* wr_ptr0 = &wr[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const float* b_ptr0 = &B[b_kk0 + b_col * ld_b];

    // No bounds check: the host wrapper only dispatches here when m/n
    // are exact multiples of the 128 tile and k is an exact multiple of
    // BK=8, so every tile fetched by every thread is always in-bounds.
    // A-side decode: same 4-wide fp32_16_combine idiom as mm_fp32_16_
    // tiled_cpasync_dualbuf_kernel's transform_tile, just applied
    // directly to a freshly-loaded ushort4 pair instead of a staged one
    // (this kernel has no separate cp.async staging step -- like
    // midpoint_exact, loads go straight from global memory into
    // registers, then into shared memory via store_to_smem below).
    auto load_global_advance = [&](float4& tb_a, float4& tb_b) {
        ushort4 wh4 = *reinterpret_cast<const ushort4*>(wh_ptr0);
        ushort4 wr4 = *reinterpret_cast<const ushort4*>(wr_ptr0);
        tb_a.x = fp32_16_combine(wh4.x, wr4.x);
        tb_a.y = fp32_16_combine(wh4.y, wr4.y);
        tb_a.z = fp32_16_combine(wh4.z, wr4.z);
        tb_a.w = fp32_16_combine(wh4.w, wr4.w);
        tb_b = *reinterpret_cast<const float4*>(b_ptr0);

        wh_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        wr_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        b_ptr0 += kMmFp32_16MidExactBK;
    };

    auto store_to_smem = [&](int buf, const float4& tb_a, const float4& tb_b) {
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 0)] = tb_a.x;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 1)] = tb_a.y;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 2)] = tb_a.z;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 3)] = tb_a.w;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 0, b_j)] = tb_b.x;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 1, b_j)] = tb_b.y;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 2, b_j)] = tb_b.z;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 3, b_j)] = tb_b.w;
    };

    auto load_compute_regs = [&](int buf, int kk, float (&a_reg)[kMmFp32_16MidExactTM],
                                 float (&b_reg)[kMmFp32_16MidExactTN]) {
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTM / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &As[mm_fp32_16_mid_exact_a_idx(buf, kk, row_off + v * 4)]);
            a_reg[v * 4 + 0] = t.x;
            a_reg[v * 4 + 1] = t.y;
            a_reg[v * 4 + 2] = t.z;
            a_reg[v * 4 + 3] = t.w;
        }
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTN / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &Bs[mm_fp32_16_mid_exact_bs_idx(buf, kk, col_off + v * 4)]);
            b_reg[v * 4 + 0] = t.x;
            b_reg[v * 4 + 1] = t.y;
            b_reg[v * 4 + 2] = t.z;
            b_reg[v * 4 + 3] = t.w;
        }
    };

    float acc[kMmFp32_16MidExactTM][kMmFp32_16MidExactTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) acc[i][j] = 0.0f;

    // Prologue: prime stages 0, 1, and 2 (kStages-1 = 3 tiles) before
    // the mainloop.
    float4 tb_a, tb_b;
    load_global_advance(tb_a, tb_b);
    store_to_smem(0, tb_a, tb_b);
    if (kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(1, tb_a, tb_b);
    }
    if (2 * kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(2, tb_a, tb_b);
    }
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16MidExactBK) {
        size_t next3_k0 = k0 + 3 * kMmFp32_16MidExactBK;
        int fetch_buf = (cur + 3) % 4;

        float a_reg[2][kMmFp32_16MidExactTM];
        float b_reg[2][kMmFp32_16MidExactTN];
        load_compute_regs(cur, 0, a_reg[0], b_reg[0]);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16MidExactBK; ++kk) {
            int slot = kk & 1;
            int next_slot = slot ^ 1;
            bool has_next_kk = (kk + 1 < kMmFp32_16MidExactBK);
            bool has_next_tile = (kk == 0 && next3_k0 < k);

#pragma unroll
            for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
                if (i == 4) {
                    if (has_next_kk) {
                        load_compute_regs(cur, kk + 1, a_reg[next_slot], b_reg[next_slot]);
                    }
                    if (has_next_tile) {
                        load_global_advance(tb_a, tb_b);
                    }
                }
#pragma unroll
                for (int jj = 0; jj < kMmFp32_16MidExactTN; ++jj) {
                    int j = (i & 1) ? (kMmFp32_16MidExactTN - 1 - jj) : jj;
                    acc[i][j] += a_reg[slot][i] * b_reg[slot][j];
                }
            }
        }

        if (next3_k0 < k) {
            store_to_smem(fetch_buf, tb_a, tb_b);
            __syncthreads();
        }
        cur = (cur + 1) % 4;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

// Host wrapper follows the same guard order as every other kernel in
// this file: transpose -> fall back to mm_fp32_16_accurate; misaligned
// -> fall back to mm_fp32_16_tiled_cpasync_vec2 (same fallback
// mm_fp32_16_tiled_cpasync_dualbuf itself uses); not an exact multiple
// of the 128 tile / BK=8 -- fall back to mm_fp32_16_gemm_materialize_
// midpoint_exact, which handles every size correctly (including a
// ragged final chunk) via its own chunked materialize-then-native-GEMM
// path, rather than building a second, bounds-checked fused sibling
// that wasn't asked for.
void mm_fp32_16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }
    if (m % kMmFp32_16MidExactBM != 0 || n % kMmFp32_16MidExactBN != 0 || k % kMmFp32_16MidExactBK != 0) {
        mm_fp32_16_gemm_materialize_midpoint_exact(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                                    beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16MidExactSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16MidExactNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16MidExactBN - 1) / kMmFp32_16MidExactBN,
               (m + kMmFp32_16MidExactBM - 1) / kMmFp32_16MidExactBM);
    mm_fp32_16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_kernel<<<blocks, threads, kMmFp32_16MidExactSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Byte-for-byte identical to mm_fp32_16_syncpipe4_bk8_warptile_nostride_
// snake_midpoint_exact_kernel -- same tile constants (kMmFp32_16MidExact*
// and the mm_fp32_16_mid_exact_a_idx/bs_idx index functions, reused
// unchanged, not redefined), same shared-memory layout, same 4-stage
// pipeline/rolling-pointer/snake traversal/interleaved checkpoint --
// EXCEPT load_global_advance's decode calls fp32_16_combine_truncated
// instead of fp32_16_combine. Exists for the same reason mm_fp32_16_
// tiled_cpasync_dualbuf_truncated exists relative to plain dualbuf: A/B
// the "always-rounded, round_flag-aware decode" against the "never-
// rounded, no-correction-at-all" decode this file used before mant_hi
// rounding was added. CORRECTNESS CONTRACT: wh/wr fed to this kernel
// MUST come from fp32_16_split_truncated, never fp32_16_split/fp32_16_
// split_clamped -- see fp32_16_combine_truncated's own comment in
// fp32_16_pack.hpp for what silently breaks otherwise.
__global__ __launch_bounds__(256, 2) void mm_fp32_16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_truncated_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactAsOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16MidExactBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16MidExactBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16MidExactWarpsN;
    const int warp_col = warp_id % kMmFp32_16MidExactWarpsN;
    const int lane_row = 2 * (lane_id / 16) + (lane_id % 2);
    const int lane_col = (lane_id % 16) / 2;
    const int row_off =
        warp_row * (kMmFp32_16MidExactBM / kMmFp32_16MidExactWarpsM) + lane_row * kMmFp32_16MidExactTM;
    const int col_off =
        warp_col * (kMmFp32_16MidExactBN / kMmFp32_16MidExactWarpsN) + lane_col * kMmFp32_16MidExactTN;

    const int a_i0 = (tid % (kMmFp32_16MidExactBM / 4)) * 4;
    const int a_kk = tid / (kMmFp32_16MidExactBM / 4);
    const int b_kk0 = (tid % (kMmFp32_16MidExactBK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16MidExactBK / 4);

    const size_t a_row0 = block_row + a_i0;
    const size_t b_col = block_col + b_j;

    const uint16_t* wh_ptr0 = &wh[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const uint16_t* wr_ptr0 = &wr[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const float* b_ptr0 = &B[b_kk0 + b_col * ld_b];

    // No bounds check: the host wrapper only dispatches here when m/n
    // are exact multiples of the 128 tile and k is an exact multiple of
    // BK=8, so every tile fetched by every thread is always in-bounds.
    auto load_global_advance = [&](float4& tb_a, float4& tb_b) {
        ushort4 wh4 = *reinterpret_cast<const ushort4*>(wh_ptr0);
        ushort4 wr4 = *reinterpret_cast<const ushort4*>(wr_ptr0);
        tb_a.x = fp32_16_combine_truncated(wh4.x, wr4.x);
        tb_a.y = fp32_16_combine_truncated(wh4.y, wr4.y);
        tb_a.z = fp32_16_combine_truncated(wh4.z, wr4.z);
        tb_a.w = fp32_16_combine_truncated(wh4.w, wr4.w);
        tb_b = *reinterpret_cast<const float4*>(b_ptr0);

        wh_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        wr_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        b_ptr0 += kMmFp32_16MidExactBK;
    };

    auto store_to_smem = [&](int buf, const float4& tb_a, const float4& tb_b) {
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 0)] = tb_a.x;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 1)] = tb_a.y;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 2)] = tb_a.z;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 3)] = tb_a.w;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 0, b_j)] = tb_b.x;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 1, b_j)] = tb_b.y;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 2, b_j)] = tb_b.z;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 3, b_j)] = tb_b.w;
    };

    auto load_compute_regs = [&](int buf, int kk, float (&a_reg)[kMmFp32_16MidExactTM],
                                 float (&b_reg)[kMmFp32_16MidExactTN]) {
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTM / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &As[mm_fp32_16_mid_exact_a_idx(buf, kk, row_off + v * 4)]);
            a_reg[v * 4 + 0] = t.x;
            a_reg[v * 4 + 1] = t.y;
            a_reg[v * 4 + 2] = t.z;
            a_reg[v * 4 + 3] = t.w;
        }
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTN / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &Bs[mm_fp32_16_mid_exact_bs_idx(buf, kk, col_off + v * 4)]);
            b_reg[v * 4 + 0] = t.x;
            b_reg[v * 4 + 1] = t.y;
            b_reg[v * 4 + 2] = t.z;
            b_reg[v * 4 + 3] = t.w;
        }
    };

    float acc[kMmFp32_16MidExactTM][kMmFp32_16MidExactTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) acc[i][j] = 0.0f;

    // Prologue: prime stages 0, 1, and 2 (kStages-1 = 3 tiles) before
    // the mainloop.
    float4 tb_a, tb_b;
    load_global_advance(tb_a, tb_b);
    store_to_smem(0, tb_a, tb_b);
    if (kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(1, tb_a, tb_b);
    }
    if (2 * kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(2, tb_a, tb_b);
    }
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16MidExactBK) {
        size_t next3_k0 = k0 + 3 * kMmFp32_16MidExactBK;
        int fetch_buf = (cur + 3) % 4;

        float a_reg[2][kMmFp32_16MidExactTM];
        float b_reg[2][kMmFp32_16MidExactTN];
        load_compute_regs(cur, 0, a_reg[0], b_reg[0]);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16MidExactBK; ++kk) {
            int slot = kk & 1;
            int next_slot = slot ^ 1;
            bool has_next_kk = (kk + 1 < kMmFp32_16MidExactBK);
            bool has_next_tile = (kk == 0 && next3_k0 < k);

#pragma unroll
            for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
                if (i == 4) {
                    if (has_next_kk) {
                        load_compute_regs(cur, kk + 1, a_reg[next_slot], b_reg[next_slot]);
                    }
                    if (has_next_tile) {
                        load_global_advance(tb_a, tb_b);
                    }
                }
#pragma unroll
                for (int jj = 0; jj < kMmFp32_16MidExactTN; ++jj) {
                    int j = (i & 1) ? (kMmFp32_16MidExactTN - 1 - jj) : jj;
                    acc[i][j] += a_reg[slot][i] * b_reg[slot][j];
                }
            }
        }

        if (next3_k0 < k) {
            store_to_smem(fetch_buf, tb_a, tb_b);
            __syncthreads();
        }
        cur = (cur + 1) % 4;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

// Host wrapper follows the same guard order as every other kernel in
// this file: transpose -> fall back to mm_fp32_16_accurate (same
// fallback the plain mm_fp32_16_tiled_cpasync_dualbuf_truncated itself
// uses); misaligned -> fall back to mm_fp32_16_tiled_cpasync_vec2 (same
// fallback both mm_fp32_16_tiled_cpasync_dualbuf_truncated and the
// non-truncated midpoint_exact kernel use). For a non-exact-multiple
// problem size, this CANNOT fall back to mm_fp32_16_gemm_materialize_
// midpoint_exact the way the non-truncated kernel does -- that fallback
// internally decodes via plain fp32_16_combine, which would silently
// produce wrong results on truncated-split wh/wr. Falls back to plain
// mm_fp32_16_tiled_cpasync_dualbuf_truncated instead: already bounds-
// checked for any size, and already uses the correct truncated decode
// contract.
void mm_fp32_16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_truncated(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_vec2(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                      beta, C, ld_c);
        return;
    }
    if (m % kMmFp32_16MidExactBM != 0 || n % kMmFp32_16MidExactBN != 0 || k % kMmFp32_16MidExactBK != 0) {
        mm_fp32_16_tiled_cpasync_dualbuf_truncated(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                                    beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_truncated_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16MidExactSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16MidExactNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16MidExactBN - 1) / kMmFp32_16MidExactBN,
               (m + kMmFp32_16MidExactBM - 1) / kMmFp32_16MidExactBM);
    mm_fp32_16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_truncated_kernel<<<blocks, threads, kMmFp32_16MidExactSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// FP32/BF16 counterpart to mm_fp32_16_syncpipe4_bk8_warptile_nostride_
// snake_midpoint_exact_kernel above -- byte-for-byte identical (same
// kMmFp32_16MidExact* tile constants and index functions, reused
// unchanged, not redefined; same 4-stage pipeline/rolling-pointer/
// snake traversal/interleaved checkpoint/bounds-check-free "exact" fast
// path) EXCEPT load_global_advance's decode calls fp32_bf16_combine
// instead of fp32_16_combine. fp32_bf16's own packed format uses the
// SAME two-uint16_t wh/wr split as fp32_16 (see fp32_bf16_pack.hpp) --
// wh is bits 31-16 of the float32 pattern (already a valid bf16 bit
// pattern via plain truncation, no rounding, no branching), wr is the
// remaining 16 mantissa bits; fp32_bf16_combine's reconstruction is
// unconditional and exact for every input (unlike fp32_16_combine,
// there's no degraded/approximate fallback branch, since bf16's 8-bit
// exponent already matches fp32's own width/bias exactly). Deliberately
// placed in this file (fp32_16_cuda_kernels.cu) alongside its fp32_16
// sibling rather than in fp32_bf16_cuda_kernels.cu, at the user's
// request, since the only difference between the two kernels is which
// combine function they call.
__global__ __launch_bounds__(256, 2) void mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactAsOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16MidExactBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16MidExactBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16MidExactWarpsN;
    const int warp_col = warp_id % kMmFp32_16MidExactWarpsN;
    const int lane_row = 2 * (lane_id / 16) + (lane_id % 2);
    const int lane_col = (lane_id % 16) / 2;
    const int row_off =
        warp_row * (kMmFp32_16MidExactBM / kMmFp32_16MidExactWarpsM) + lane_row * kMmFp32_16MidExactTM;
    const int col_off =
        warp_col * (kMmFp32_16MidExactBN / kMmFp32_16MidExactWarpsN) + lane_col * kMmFp32_16MidExactTN;

    const int a_i0 = (tid % (kMmFp32_16MidExactBM / 4)) * 4;
    const int a_kk = tid / (kMmFp32_16MidExactBM / 4);
    const int b_kk0 = (tid % (kMmFp32_16MidExactBK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16MidExactBK / 4);

    const size_t a_row0 = block_row + a_i0;
    const size_t b_col = block_col + b_j;

    const uint16_t* wh_ptr0 = &wh[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const uint16_t* wr_ptr0 = &wr[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const float* b_ptr0 = &B[b_kk0 + b_col * ld_b];

    // No bounds check: the host wrapper only dispatches here when m/n
    // are exact multiples of the 128 tile and k is an exact multiple of
    // BK=8, so every tile fetched by every thread is always in-bounds.
    auto load_global_advance = [&](float4& tb_a, float4& tb_b) {
        ushort4 wh4 = *reinterpret_cast<const ushort4*>(wh_ptr0);
        ushort4 wr4 = *reinterpret_cast<const ushort4*>(wr_ptr0);
        tb_a.x = fp32_bf16_combine(wh4.x, wr4.x);
        tb_a.y = fp32_bf16_combine(wh4.y, wr4.y);
        tb_a.z = fp32_bf16_combine(wh4.z, wr4.z);
        tb_a.w = fp32_bf16_combine(wh4.w, wr4.w);
        tb_b = *reinterpret_cast<const float4*>(b_ptr0);

        wh_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        wr_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        b_ptr0 += kMmFp32_16MidExactBK;
    };

    auto store_to_smem = [&](int buf, const float4& tb_a, const float4& tb_b) {
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 0)] = tb_a.x;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 1)] = tb_a.y;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 2)] = tb_a.z;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 3)] = tb_a.w;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 0, b_j)] = tb_b.x;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 1, b_j)] = tb_b.y;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 2, b_j)] = tb_b.z;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 3, b_j)] = tb_b.w;
    };

    auto load_compute_regs = [&](int buf, int kk, float (&a_reg)[kMmFp32_16MidExactTM],
                                 float (&b_reg)[kMmFp32_16MidExactTN]) {
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTM / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &As[mm_fp32_16_mid_exact_a_idx(buf, kk, row_off + v * 4)]);
            a_reg[v * 4 + 0] = t.x;
            a_reg[v * 4 + 1] = t.y;
            a_reg[v * 4 + 2] = t.z;
            a_reg[v * 4 + 3] = t.w;
        }
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTN / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &Bs[mm_fp32_16_mid_exact_bs_idx(buf, kk, col_off + v * 4)]);
            b_reg[v * 4 + 0] = t.x;
            b_reg[v * 4 + 1] = t.y;
            b_reg[v * 4 + 2] = t.z;
            b_reg[v * 4 + 3] = t.w;
        }
    };

    float acc[kMmFp32_16MidExactTM][kMmFp32_16MidExactTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) acc[i][j] = 0.0f;

    // Prologue: prime stages 0, 1, and 2 (kStages-1 = 3 tiles) before
    // the mainloop.
    float4 tb_a, tb_b;
    load_global_advance(tb_a, tb_b);
    store_to_smem(0, tb_a, tb_b);
    if (kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(1, tb_a, tb_b);
    }
    if (2 * kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(2, tb_a, tb_b);
    }
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16MidExactBK) {
        size_t next3_k0 = k0 + 3 * kMmFp32_16MidExactBK;
        int fetch_buf = (cur + 3) % 4;

        float a_reg[2][kMmFp32_16MidExactTM];
        float b_reg[2][kMmFp32_16MidExactTN];
        load_compute_regs(cur, 0, a_reg[0], b_reg[0]);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16MidExactBK; ++kk) {
            int slot = kk & 1;
            int next_slot = slot ^ 1;
            bool has_next_kk = (kk + 1 < kMmFp32_16MidExactBK);
            bool has_next_tile = (kk == 0 && next3_k0 < k);

#pragma unroll
            for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
                if (i == 4) {
                    if (has_next_kk) {
                        load_compute_regs(cur, kk + 1, a_reg[next_slot], b_reg[next_slot]);
                    }
                    if (has_next_tile) {
                        load_global_advance(tb_a, tb_b);
                    }
                }
#pragma unroll
                for (int jj = 0; jj < kMmFp32_16MidExactTN; ++jj) {
                    int j = (i & 1) ? (kMmFp32_16MidExactTN - 1 - jj) : jj;
                    acc[i][j] += a_reg[slot][i] * b_reg[slot][j];
                }
            }
        }

        if (next3_k0 < k) {
            store_to_smem(fetch_buf, tb_a, tb_b);
            __syncthreads();
        }
        cur = (cur + 1) % 4;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

// Host wrapper follows the same guard order as every other kernel in
// this file: transpose -> fall back to mm_fp32_bf16_accurate; misaligned
// -> fall back to mm_fp32_bf16_tiled (fp32_bf16 has no "vec2"-equivalent
// intermediate tier the way fp32_16 does, so this goes straight to the
// plain shared-memory-tiled kernel); not an exact multiple of the 128
// tile / BK=8 -- fall back to mm_fp32_bf16_tiled_cpasync_dualbuf, the
// existing bounds-checked bf16 kernel that handles any size correctly
// (there's no bf16 "materialize_midpoint_exact" equivalent to fall back
// to instead -- building one wasn't asked for).
void mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_bf16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                              beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_bf16_tiled(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                           beta, C, ld_c);
        return;
    }
    if (m % kMmFp32_16MidExactBM != 0 || n % kMmFp32_16MidExactBN != 0 || k % kMmFp32_16MidExactBK != 0) {
        mm_fp32_bf16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                           beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16MidExactSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16MidExactNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16MidExactBN - 1) / kMmFp32_16MidExactBN,
               (m + kMmFp32_16MidExactBM - 1) / kMmFp32_16MidExactBM);
    mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_kernel<<<blocks, threads, kMmFp32_16MidExactSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Rounded-encoding counterpart to mm_fp32_bf16_syncpipe4_bk8_warptile_
// nostride_snake_midpoint_exact_kernel above -- byte-for-byte identical
// (same kMmFp32_16MidExact* tile constants/index functions, same 4-stage
// pipeline/rolling-pointer/snake traversal/interleaved checkpoint/
// bounds-check-free "exact" fast path) EXCEPT load_global_advance's
// decode calls fp32_bf16_combine_rounded instead of fp32_bf16_combine.
// CORRECTNESS CONTRACT: wh/wr fed to this kernel MUST come from fp32_
// bf16_split_rounded, never fp32_bf16_split -- see fp32_bf16_pack.hpp's
// own comment on fp32_bf16_split_rounded for the round_flag encoding
// (wr's bit0) this decode depends on, and why full reconstruction here
// is no longer bit-exact (unlike the plain kernel above), only accurate
// to within one ULP of the full 23-bit fp32 mantissa.
//
// Measured (cuobjdump -res-usage / --dump-sass on libtomos_cuda.so):
// REG:128 STACK:56, 23 STL + 11 LDL -- a real spill, unlike the plain
// kernel above's clean 0-spill compile. fp32_bf16_combine_rounded's
// round_flag subtract-and-mask logic apparently has a meaningfully
// larger register footprint than fp32_bf16_combine's unconditional OR --
// the same pattern fp32_16_combine_truncated vs fp32_16_combine showed.
// Investigated at length and NOT resolved: three bit-identical all-
// scalar reformulations (see fp32_bf16_combine_rounded's own TRIED AND
// REVERTED comment in fp32_bf16_pack.hpp) all compiled to this same
// spill -- ptxas normalizes them to equivalent code. A fourth attempt,
// batching two lanes' round_flag correction into one __vsub2 call
// (packed 16-bit subtract, no cross-lane borrow -- a genuinely
// different instruction-level primitive, not just a reformulation) ALSO
// produced the identical spill -- because, as isolating __vsub2 alone
// into a standalone kernel and inspecting its SASS revealed, sm_80 has
// no native packed-16-bit SIMD subtract instruction: nvcc SOFTWARE-
// EMULATES __vsub2 via a scalar xor/sub/xor/and/add sequence (the
// classic SWAR borrow-isolation trick) on this architecture, so it was
// never actually a different primitive at the SASS level here, just a
// longer way of writing an equivalent scalar sequence ptxas normalizes
// the same way. Relaxing __launch_bounds__ from (256,2) to (256) alone
// (diagnostic only, immediately reverted) let ptxas use 138 registers
// with 0 spill, confirming this is a genuine ~10-register shortfall
// against the 128-register 2-blocks/SM ceiling, not fixable by any
// arithmetic reformulation tried -- see git log for the __vsub2 attempt
// if revisiting this with a genuinely different approach (e.g. a
// different encoding that avoids needing a conditional correction at
// decode time at all).
__global__ __launch_bounds__(256, 2) void mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactAsOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16MidExactBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16MidExactBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16MidExactWarpsN;
    const int warp_col = warp_id % kMmFp32_16MidExactWarpsN;
    const int lane_row = 2 * (lane_id / 16) + (lane_id % 2);
    const int lane_col = (lane_id % 16) / 2;
    const int row_off =
        warp_row * (kMmFp32_16MidExactBM / kMmFp32_16MidExactWarpsM) + lane_row * kMmFp32_16MidExactTM;
    const int col_off =
        warp_col * (kMmFp32_16MidExactBN / kMmFp32_16MidExactWarpsN) + lane_col * kMmFp32_16MidExactTN;

    const int a_i0 = (tid % (kMmFp32_16MidExactBM / 4)) * 4;
    const int a_kk = tid / (kMmFp32_16MidExactBM / 4);
    const int b_kk0 = (tid % (kMmFp32_16MidExactBK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16MidExactBK / 4);

    const size_t a_row0 = block_row + a_i0;
    const size_t b_col = block_col + b_j;

    const uint16_t* wh_ptr0 = &wh[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const uint16_t* wr_ptr0 = &wr[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const float* b_ptr0 = &B[b_kk0 + b_col * ld_b];

    // No bounds check: the host wrapper only dispatches here when m/n
    // are exact multiples of the 128 tile and k is an exact multiple of
    // BK=8, so every tile fetched by every thread is always in-bounds.
    auto load_global_advance = [&](float4& tb_a, float4& tb_b) {
        ushort4 wh4 = *reinterpret_cast<const ushort4*>(wh_ptr0);
        ushort4 wr4 = *reinterpret_cast<const ushort4*>(wr_ptr0);
        tb_a.x = fp32_bf16_combine_rounded(wh4.x, wr4.x);
        tb_a.y = fp32_bf16_combine_rounded(wh4.y, wr4.y);
        tb_a.z = fp32_bf16_combine_rounded(wh4.z, wr4.z);
        tb_a.w = fp32_bf16_combine_rounded(wh4.w, wr4.w);
        tb_b = *reinterpret_cast<const float4*>(b_ptr0);

        wh_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        wr_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        b_ptr0 += kMmFp32_16MidExactBK;
    };

    auto store_to_smem = [&](int buf, const float4& tb_a, const float4& tb_b) {
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 0)] = tb_a.x;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 1)] = tb_a.y;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 2)] = tb_a.z;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 3)] = tb_a.w;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 0, b_j)] = tb_b.x;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 1, b_j)] = tb_b.y;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 2, b_j)] = tb_b.z;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 3, b_j)] = tb_b.w;
    };

    auto load_compute_regs = [&](int buf, int kk, float (&a_reg)[kMmFp32_16MidExactTM],
                                 float (&b_reg)[kMmFp32_16MidExactTN]) {
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTM / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &As[mm_fp32_16_mid_exact_a_idx(buf, kk, row_off + v * 4)]);
            a_reg[v * 4 + 0] = t.x;
            a_reg[v * 4 + 1] = t.y;
            a_reg[v * 4 + 2] = t.z;
            a_reg[v * 4 + 3] = t.w;
        }
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTN / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &Bs[mm_fp32_16_mid_exact_bs_idx(buf, kk, col_off + v * 4)]);
            b_reg[v * 4 + 0] = t.x;
            b_reg[v * 4 + 1] = t.y;
            b_reg[v * 4 + 2] = t.z;
            b_reg[v * 4 + 3] = t.w;
        }
    };

    float acc[kMmFp32_16MidExactTM][kMmFp32_16MidExactTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) acc[i][j] = 0.0f;

    // Prologue: prime stages 0, 1, and 2 (kStages-1 = 3 tiles) before
    // the mainloop.
    float4 tb_a, tb_b;
    load_global_advance(tb_a, tb_b);
    store_to_smem(0, tb_a, tb_b);
    if (kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(1, tb_a, tb_b);
    }
    if (2 * kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(2, tb_a, tb_b);
    }
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16MidExactBK) {
        size_t next3_k0 = k0 + 3 * kMmFp32_16MidExactBK;
        int fetch_buf = (cur + 3) % 4;

        float a_reg[2][kMmFp32_16MidExactTM];
        float b_reg[2][kMmFp32_16MidExactTN];
        load_compute_regs(cur, 0, a_reg[0], b_reg[0]);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16MidExactBK; ++kk) {
            int slot = kk & 1;
            int next_slot = slot ^ 1;
            bool has_next_kk = (kk + 1 < kMmFp32_16MidExactBK);
            bool has_next_tile = (kk == 0 && next3_k0 < k);

#pragma unroll
            for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
                if (i == 4) {
                    if (has_next_kk) {
                        load_compute_regs(cur, kk + 1, a_reg[next_slot], b_reg[next_slot]);
                    }
                    if (has_next_tile) {
                        load_global_advance(tb_a, tb_b);
                    }
                }
#pragma unroll
                for (int jj = 0; jj < kMmFp32_16MidExactTN; ++jj) {
                    int j = (i & 1) ? (kMmFp32_16MidExactTN - 1 - jj) : jj;
                    acc[i][j] += a_reg[slot][i] * b_reg[slot][j];
                }
            }
        }

        if (next3_k0 < k) {
            store_to_smem(fetch_buf, tb_a, tb_b);
            __syncthreads();
        }
        cur = (cur + 1) % 4;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

// Host wrapper: same guard order as mm_fp32_bf16_syncpipe4_bk8_warptile_
// nostride_snake_midpoint_exact's own wrapper above, but EVERY fallback
// tier here must decode via the rounded contract, never plain fp32_
// bf16_combine (unlike fp32_16's truncated kernel, whose plain-decode
// fallback happens to be safe -- see mm_fp32_bf16_accurate_rounded's own
// comment for why that safety property does NOT carry over to fp32_
// bf16). transpose/misaligned -> mm_fp32_bf16_accurate_rounded (the
// naive kernel handles both: no vectorized loads means alignment never
// matters, and it has its own transpose-aware indexing); non-exact-
// multiple-of-128/BK=8 -> mm_fp32_bf16_gemm_materialize_rounded (handles
// any NO_TRANSPOSE size via its own chunking + midpoint_exact's own
// internal dispatch). CORRECTNESS CONTRACT: callers MUST pass wh/wr
// produced by fp32_bf16_split_rounded.
void mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_bf16_accurate_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                              beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_bf16_accurate_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                           beta, C, ld_c);
        return;
    }
    if (m % kMmFp32_16MidExactBM != 0 || n % kMmFp32_16MidExactBN != 0 || k % kMmFp32_16MidExactBK != 0) {
        mm_fp32_bf16_gemm_materialize_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                           beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16MidExactSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16MidExactNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16MidExactBN - 1) / kMmFp32_16MidExactBN,
               (m + kMmFp32_16MidExactBM - 1) / kMmFp32_16MidExactBM);
    mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_kernel<<<blocks, threads, kMmFp32_16MidExactSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// EXPERIMENT: same structure as mm_fp32_bf16_syncpipe4_bk8_warptile_
// nostride_snake_midpoint_exact_rounded_kernel above, but load_global_
// advance first checks -- once per BK=8 tile, via a block-wide
// __syncthreads_or reduction over all 256 threads' just-loaded wr
// bytes' round_flag bits (bit0) -- whether the ENTIRE tile has any
// rounded element at all. When it doesn't (round_flag=0 for every
// element, common when input data rarely needs rounding), decode
// collapses to the plain fp32_bf16_combine (verified host-side: exact
// substitute for fp32_bf16_combine_rounded whenever round_flag=0 --
// wr's bit0 is unconditionally forced to 0 by fp32_bf16_split_rounded
// either way, so the correction becomes a no-op), needing none of the
// corrected path's extra live values; otherwise it falls back to
// fp32_bf16_combine_rounded exactly as the kernel above always does.
// Same "skip the expensive decode when a whole tile doesn't need it"
// idea as mm_fp32_16_tiled_cpasync_dualbuf_adaptive_kernel, adapted
// from that kernel's cp.async-staged tile structure to this one's
// register-to-register load_global_advance.
//
// UNLIKE the bounds-check removal that produced the exact-fast-path
// family of kernels, this is NOT a compile-time-provable elimination --
// whether a tile needs correction depends on the actual data, not a
// host-supplied size guarantee -- so this trades REAL extra block-wide
// barriers against sometimes skipping the corrected decode's extra live
// values. Measured (cuobjdump --dump-sass): REG:128 STACK:16, 3 STL + 2
// LDL -- a real reduction from the plain kernel's REG:128 STACK:56, 23
// STL + 11 LDL -- but this adds 4 genuinely NEW BAR.RED.OR instructions
// (the reduction-barrier __syncthreads_or compiles to, one per
// load_global_advance call site: 3 in the prologue, 1 in the mainloop)
// on top of the 2 plain BAR.SYNC both kernels already have from their
// shared __syncthreads() calls -- a real, nontrivial synchronization
// cost, not just "the same barriers, more work per barrier". See mm_
// fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_
// rounded_adaptive_warp_kernel below for a lower-synchronization-risk
// alternative (per-warp __any_sync instead of per-block
// __syncthreads_or) that trades a smaller spill reduction (STACK:32)
// for adding ZERO new barrier-class instructions (only cheap VOTE.ANY).
// Whether either trade is worth it for real runtime performance is
// exactly what building both measures -- only a real GPU run can say.
__global__ __launch_bounds__(256, 2) void mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_adaptive_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactAsOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16MidExactBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16MidExactBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16MidExactWarpsN;
    const int warp_col = warp_id % kMmFp32_16MidExactWarpsN;
    const int lane_row = 2 * (lane_id / 16) + (lane_id % 2);
    const int lane_col = (lane_id % 16) / 2;
    const int row_off =
        warp_row * (kMmFp32_16MidExactBM / kMmFp32_16MidExactWarpsM) + lane_row * kMmFp32_16MidExactTM;
    const int col_off =
        warp_col * (kMmFp32_16MidExactBN / kMmFp32_16MidExactWarpsN) + lane_col * kMmFp32_16MidExactTN;

    const int a_i0 = (tid % (kMmFp32_16MidExactBM / 4)) * 4;
    const int a_kk = tid / (kMmFp32_16MidExactBM / 4);
    const int b_kk0 = (tid % (kMmFp32_16MidExactBK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16MidExactBK / 4);

    const size_t a_row0 = block_row + a_i0;
    const size_t b_col = block_col + b_j;

    const uint16_t* wh_ptr0 = &wh[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const uint16_t* wr_ptr0 = &wr[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const float* b_ptr0 = &B[b_kk0 + b_col * ld_b];

    // No bounds check: the host wrapper only dispatches here when m/n
    // are exact multiples of the 128 tile and k is an exact multiple of
    // BK=8, so every tile fetched by every thread is always in-bounds.
    // has_next_tile (the mainloop's own guard for whether this gets
    // called at all in a given kk-iteration) is uniform across all 256
    // threads, so the __syncthreads_or below never sees divergent
    // participation regardless of which call site invokes this lambda.
    auto load_global_advance = [&](float4& tb_a, float4& tb_b) {
        ushort4 wh4 = *reinterpret_cast<const ushort4*>(wh_ptr0);
        ushort4 wr4 = *reinterpret_cast<const ushort4*>(wr_ptr0);
        bool local_needs_correction = ((wr4.x & 0x1u) != 0u) || ((wr4.y & 0x1u) != 0u) ||
                                      ((wr4.z & 0x1u) != 0u) || ((wr4.w & 0x1u) != 0u);
        bool tile_needs_correction = __syncthreads_or(local_needs_correction);
        if (tile_needs_correction) {
            tb_a.x = fp32_bf16_combine_rounded(wh4.x, wr4.x);
            tb_a.y = fp32_bf16_combine_rounded(wh4.y, wr4.y);
            tb_a.z = fp32_bf16_combine_rounded(wh4.z, wr4.z);
            tb_a.w = fp32_bf16_combine_rounded(wh4.w, wr4.w);
        } else {
            tb_a.x = fp32_bf16_combine(wh4.x, wr4.x);
            tb_a.y = fp32_bf16_combine(wh4.y, wr4.y);
            tb_a.z = fp32_bf16_combine(wh4.z, wr4.z);
            tb_a.w = fp32_bf16_combine(wh4.w, wr4.w);
        }
        tb_b = *reinterpret_cast<const float4*>(b_ptr0);

        wh_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        wr_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        b_ptr0 += kMmFp32_16MidExactBK;
    };

    auto store_to_smem = [&](int buf, const float4& tb_a, const float4& tb_b) {
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 0)] = tb_a.x;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 1)] = tb_a.y;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 2)] = tb_a.z;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 3)] = tb_a.w;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 0, b_j)] = tb_b.x;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 1, b_j)] = tb_b.y;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 2, b_j)] = tb_b.z;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 3, b_j)] = tb_b.w;
    };

    auto load_compute_regs = [&](int buf, int kk, float (&a_reg)[kMmFp32_16MidExactTM],
                                 float (&b_reg)[kMmFp32_16MidExactTN]) {
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTM / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &As[mm_fp32_16_mid_exact_a_idx(buf, kk, row_off + v * 4)]);
            a_reg[v * 4 + 0] = t.x;
            a_reg[v * 4 + 1] = t.y;
            a_reg[v * 4 + 2] = t.z;
            a_reg[v * 4 + 3] = t.w;
        }
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTN / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &Bs[mm_fp32_16_mid_exact_bs_idx(buf, kk, col_off + v * 4)]);
            b_reg[v * 4 + 0] = t.x;
            b_reg[v * 4 + 1] = t.y;
            b_reg[v * 4 + 2] = t.z;
            b_reg[v * 4 + 3] = t.w;
        }
    };

    float acc[kMmFp32_16MidExactTM][kMmFp32_16MidExactTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) acc[i][j] = 0.0f;

    // Prologue: prime stages 0, 1, and 2 (kStages-1 = 3 tiles) before
    // the mainloop.
    float4 tb_a, tb_b;
    load_global_advance(tb_a, tb_b);
    store_to_smem(0, tb_a, tb_b);
    if (kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(1, tb_a, tb_b);
    }
    if (2 * kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(2, tb_a, tb_b);
    }
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16MidExactBK) {
        size_t next3_k0 = k0 + 3 * kMmFp32_16MidExactBK;
        int fetch_buf = (cur + 3) % 4;

        float a_reg[2][kMmFp32_16MidExactTM];
        float b_reg[2][kMmFp32_16MidExactTN];
        load_compute_regs(cur, 0, a_reg[0], b_reg[0]);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16MidExactBK; ++kk) {
            int slot = kk & 1;
            int next_slot = slot ^ 1;
            bool has_next_kk = (kk + 1 < kMmFp32_16MidExactBK);
            bool has_next_tile = (kk == 0 && next3_k0 < k);

#pragma unroll
            for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
                if (i == 4) {
                    if (has_next_kk) {
                        load_compute_regs(cur, kk + 1, a_reg[next_slot], b_reg[next_slot]);
                    }
                    if (has_next_tile) {
                        load_global_advance(tb_a, tb_b);
                    }
                }
#pragma unroll
                for (int jj = 0; jj < kMmFp32_16MidExactTN; ++jj) {
                    int j = (i & 1) ? (kMmFp32_16MidExactTN - 1 - jj) : jj;
                    acc[i][j] += a_reg[slot][i] * b_reg[slot][j];
                }
            }
        }

        if (next3_k0 < k) {
            store_to_smem(fetch_buf, tb_a, tb_b);
            __syncthreads();
        }
        cur = (cur + 1) % 4;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

// Host wrapper: same guard order/fallback contract as mm_fp32_bf16_
// syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded's own
// wrapper above (transpose/misaligned -> mm_fp32_bf16_accurate_rounded;
// non-exact-multiple -> mm_fp32_bf16_gemm_materialize_rounded) --
// CORRECTNESS CONTRACT: callers MUST pass wh/wr produced by fp32_bf16_
// split_rounded, same as the non-adaptive kernel.
void mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_adaptive(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_bf16_accurate_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                              beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_bf16_accurate_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                           beta, C, ld_c);
        return;
    }
    if (m % kMmFp32_16MidExactBM != 0 || n % kMmFp32_16MidExactBN != 0 || k % kMmFp32_16MidExactBK != 0) {
        mm_fp32_bf16_gemm_materialize_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                           beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_adaptive_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16MidExactSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16MidExactNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16MidExactBN - 1) / kMmFp32_16MidExactBN,
               (m + kMmFp32_16MidExactBM - 1) / kMmFp32_16MidExactBM);
    mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_adaptive_kernel<<<blocks, threads, kMmFp32_16MidExactSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Same idea as mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_
// midpoint_exact_rounded_adaptive_kernel above (skip the corrected
// decode on tiles that provably don't need it), but the "does this
// need the corrected decode" decision is made per-WARP via __any_sync
// instead of per-BLOCK via __syncthreads_or -- same technique as
// mm_fp32_16_tiled_cpasync_dualbuf_adaptive_warp_kernel, and valid here
// for the identical reason: a_kk = tid / (kMmFp32_16MidExactBM / 4) =
// tid / 32 = warp_id (kMmFp32_16MidExactBM is 128, same as that
// kernel's own BM), so a_kk -- and therefore which A row a given warp
// decodes -- is warp-uniform: each warp owns a fixed, disjoint row, and
// no OTHER warp's decode work depends on this warp's fast/corrected
// choice (the compute phase reads As[] via a completely different
// thread mapping, row_off/col_off based on warp_row/lane_row, and the
// main loop's existing __syncthreads() already makes every warp's
// writes visible before that phase runs). __any_sync only reconverges
// the calling warp's own 32 lanes -- no shared-memory round trip, no
// wait on the other 7 warps -- so this should be meaningfully cheaper
// than the block-wide version's real extra barrier, while still
// providing the same register-pressure benefit whenever it applies.
__global__ __launch_bounds__(256, 2) void mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_adaptive_warp_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactAsOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16MidExactBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16MidExactBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16MidExactBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16MidExactWarpsN;
    const int warp_col = warp_id % kMmFp32_16MidExactWarpsN;
    const int lane_row = 2 * (lane_id / 16) + (lane_id % 2);
    const int lane_col = (lane_id % 16) / 2;
    const int row_off =
        warp_row * (kMmFp32_16MidExactBM / kMmFp32_16MidExactWarpsM) + lane_row * kMmFp32_16MidExactTM;
    const int col_off =
        warp_col * (kMmFp32_16MidExactBN / kMmFp32_16MidExactWarpsN) + lane_col * kMmFp32_16MidExactTN;

    const int a_i0 = (tid % (kMmFp32_16MidExactBM / 4)) * 4;
    const int a_kk = tid / (kMmFp32_16MidExactBM / 4);
    const int b_kk0 = (tid % (kMmFp32_16MidExactBK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16MidExactBK / 4);

    const size_t a_row0 = block_row + a_i0;
    const size_t b_col = block_col + b_j;

    const uint16_t* wh_ptr0 = &wh[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const uint16_t* wr_ptr0 = &wr[a_row0 + static_cast<size_t>(a_kk) * ld_a];
    const float* b_ptr0 = &B[b_kk0 + b_col * ld_b];

    // No bounds check: the host wrapper only dispatches here when m/n
    // are exact multiples of the 128 tile and k is an exact multiple of
    // BK=8, so every tile fetched by every thread is always in-bounds.
    // All lanes reach the vote reconverged (no early exits anywhere in
    // this kernel), so a full 0xffffffff mask is always valid.
    auto load_global_advance = [&](float4& tb_a, float4& tb_b) {
        ushort4 wh4 = *reinterpret_cast<const ushort4*>(wh_ptr0);
        ushort4 wr4 = *reinterpret_cast<const ushort4*>(wr_ptr0);
        bool local_needs_correction = ((wr4.x & 0x1u) != 0u) || ((wr4.y & 0x1u) != 0u) ||
                                      ((wr4.z & 0x1u) != 0u) || ((wr4.w & 0x1u) != 0u);
        bool warp_needs_correction = __any_sync(0xffffffffu, local_needs_correction);
        if (warp_needs_correction) {
            tb_a.x = fp32_bf16_combine_rounded(wh4.x, wr4.x);
            tb_a.y = fp32_bf16_combine_rounded(wh4.y, wr4.y);
            tb_a.z = fp32_bf16_combine_rounded(wh4.z, wr4.z);
            tb_a.w = fp32_bf16_combine_rounded(wh4.w, wr4.w);
        } else {
            tb_a.x = fp32_bf16_combine(wh4.x, wr4.x);
            tb_a.y = fp32_bf16_combine(wh4.y, wr4.y);
            tb_a.z = fp32_bf16_combine(wh4.z, wr4.z);
            tb_a.w = fp32_bf16_combine(wh4.w, wr4.w);
        }
        tb_b = *reinterpret_cast<const float4*>(b_ptr0);

        wh_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        wr_ptr0 += static_cast<size_t>(kMmFp32_16MidExactBK) * ld_a;
        b_ptr0 += kMmFp32_16MidExactBK;
    };

    auto store_to_smem = [&](int buf, const float4& tb_a, const float4& tb_b) {
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 0)] = tb_a.x;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 1)] = tb_a.y;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 2)] = tb_a.z;
        As[mm_fp32_16_mid_exact_a_idx(buf, a_kk, a_i0 + 3)] = tb_a.w;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 0, b_j)] = tb_b.x;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 1, b_j)] = tb_b.y;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 2, b_j)] = tb_b.z;
        Bs[mm_fp32_16_mid_exact_bs_idx(buf, b_kk0 + 3, b_j)] = tb_b.w;
    };

    auto load_compute_regs = [&](int buf, int kk, float (&a_reg)[kMmFp32_16MidExactTM],
                                 float (&b_reg)[kMmFp32_16MidExactTN]) {
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTM / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &As[mm_fp32_16_mid_exact_a_idx(buf, kk, row_off + v * 4)]);
            a_reg[v * 4 + 0] = t.x;
            a_reg[v * 4 + 1] = t.y;
            a_reg[v * 4 + 2] = t.z;
            a_reg[v * 4 + 3] = t.w;
        }
#pragma unroll
        for (int v = 0; v < kMmFp32_16MidExactTN / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &Bs[mm_fp32_16_mid_exact_bs_idx(buf, kk, col_off + v * 4)]);
            b_reg[v * 4 + 0] = t.x;
            b_reg[v * 4 + 1] = t.y;
            b_reg[v * 4 + 2] = t.z;
            b_reg[v * 4 + 3] = t.w;
        }
    };

    float acc[kMmFp32_16MidExactTM][kMmFp32_16MidExactTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) acc[i][j] = 0.0f;

    // Prologue: prime stages 0, 1, and 2 (kStages-1 = 3 tiles) before
    // the mainloop.
    float4 tb_a, tb_b;
    load_global_advance(tb_a, tb_b);
    store_to_smem(0, tb_a, tb_b);
    if (kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(1, tb_a, tb_b);
    }
    if (2 * kMmFp32_16MidExactBK < k) {
        load_global_advance(tb_a, tb_b);
        store_to_smem(2, tb_a, tb_b);
    }
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16MidExactBK) {
        size_t next3_k0 = k0 + 3 * kMmFp32_16MidExactBK;
        int fetch_buf = (cur + 3) % 4;

        float a_reg[2][kMmFp32_16MidExactTM];
        float b_reg[2][kMmFp32_16MidExactTN];
        load_compute_regs(cur, 0, a_reg[0], b_reg[0]);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16MidExactBK; ++kk) {
            int slot = kk & 1;
            int next_slot = slot ^ 1;
            bool has_next_kk = (kk + 1 < kMmFp32_16MidExactBK);
            bool has_next_tile = (kk == 0 && next3_k0 < k);

#pragma unroll
            for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
                if (i == 4) {
                    if (has_next_kk) {
                        load_compute_regs(cur, kk + 1, a_reg[next_slot], b_reg[next_slot]);
                    }
                    if (has_next_tile) {
                        load_global_advance(tb_a, tb_b);
                    }
                }
#pragma unroll
                for (int jj = 0; jj < kMmFp32_16MidExactTN; ++jj) {
                    int j = (i & 1) ? (kMmFp32_16MidExactTN - 1 - jj) : jj;
                    acc[i][j] += a_reg[slot][i] * b_reg[slot][j];
                }
            }
        }

        if (next3_k0 < k) {
            store_to_smem(fetch_buf, tb_a, tb_b);
            __syncthreads();
        }
        cur = (cur + 1) % 4;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16MidExactTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16MidExactTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

// Host wrapper: same guard order/fallback contract as mm_fp32_bf16_
// syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_adaptive
// above -- CORRECTNESS CONTRACT: callers MUST pass wh/wr produced by
// fp32_bf16_split_rounded, same as the non-adaptive kernel.
void mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_adaptive_warp(TransposeType transA, TransposeType transB, double alpha,
                                 dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                 size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                 double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_bf16_accurate_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                              beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_bf16_accurate_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                           beta, C, ld_c);
        return;
    }
    if (m % kMmFp32_16MidExactBM != 0 || n % kMmFp32_16MidExactBN != 0 || k % kMmFp32_16MidExactBK != 0) {
        mm_fp32_bf16_gemm_materialize_rounded(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                           beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_adaptive_warp_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16MidExactSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16MidExactNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16MidExactBN - 1) / kMmFp32_16MidExactBN,
               (m + kMmFp32_16MidExactBM - 1) / kMmFp32_16MidExactBM);
    mm_fp32_bf16_syncpipe4_bk8_warptile_nostride_snake_midpoint_exact_rounded_adaptive_warp_kernel<<<blocks, threads, kMmFp32_16MidExactSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Same dual-cp.async structure as mm_fp32_16_tiled_cpasync_dualbuf_kernel,
// with BK doubled from 16 to 32 -- the same "wider B coalescing" lever
// that helped going 8->16 (see mm_cuda_kernels.cu's gemm_fp32_tiled_
// cpasync_vec3_kernel and mm_fp32_16_tiled_cpasync_vec2_kernel), tried
// again on top of dualbuf's already-working double-cp.async pipeline.
//
// The predicted risk: doubling BK roughly doubles every shared-memory
// region here (staging + As + stagingB + Bs all scale with BK), landing
// at 128KB/block. A100 has 164KB/SM available, so only ONE such block
// fits per SM regardless of register count -- the same occupancy cliff
// that hurt gemm_fp32_tiled_db_kernel and mm_fp32_16_tiled_cpasync_vec4_
// kernel, just triggered by shared memory instead of registers this time
// (so __launch_bounds__ can't fix it the way it fixed those). Kept and
// measured anyway rather than assumed, on the same principle as every
// other experiment in this file: the harness exists to find out, not to
// guess.
namespace {
constexpr int kMmFp32_16Dual2BM = 128;
constexpr int kMmFp32_16Dual2BN = 128;
constexpr int kMmFp32_16Dual2BK = 32;
constexpr int kMmFp32_16Dual2TM = 8;
constexpr int kMmFp32_16Dual2TN = 8;
constexpr int kMmFp32_16Dual2WarpsM = 2;
constexpr int kMmFp32_16Dual2WarpsN = 4;
constexpr int kMmFp32_16Dual2LanesM = 8;
constexpr int kMmFp32_16Dual2LanesN = 4;
constexpr int kMmFp32_16Dual2NumThreads =
    (kMmFp32_16Dual2BM / kMmFp32_16Dual2TM) * (kMmFp32_16Dual2BN / kMmFp32_16Dual2TN);  // 256

constexpr size_t kMmFp32_16Dual2StagingWhBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual2BK) * kMmFp32_16Dual2BM * sizeof(uint16_t);
constexpr size_t kMmFp32_16Dual2StagingWrBytes = kMmFp32_16Dual2StagingWhBytes;
constexpr size_t kMmFp32_16Dual2AsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual2BK) * kMmFp32_16Dual2BM * sizeof(float);
constexpr size_t kMmFp32_16Dual2StagingBBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual2BN) * kMmFp32_16Dual2BK * sizeof(float);
constexpr size_t kMmFp32_16Dual2BsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual2BK) * kMmFp32_16Dual2BN * sizeof(float);

constexpr size_t kMmFp32_16Dual2StagingWhOff = 0;
constexpr size_t kMmFp32_16Dual2StagingWrOff =
    kMmFp32_16Dual2StagingWhOff + kMmFp32_16Dual2StagingWhBytes;
constexpr size_t kMmFp32_16Dual2AsOff = kMmFp32_16Dual2StagingWrOff + kMmFp32_16Dual2StagingWrBytes;
constexpr size_t kMmFp32_16Dual2StagingBOff = kMmFp32_16Dual2AsOff + kMmFp32_16Dual2AsBytes;
constexpr size_t kMmFp32_16Dual2BsOff = kMmFp32_16Dual2StagingBOff + kMmFp32_16Dual2StagingBBytes;
constexpr size_t kMmFp32_16Dual2SharedBytes = kMmFp32_16Dual2BsOff + kMmFp32_16Dual2BsBytes;  // 128KB

__device__ __forceinline__ int mm_fp32_16_dual2_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16Dual2BK + kk) * kMmFp32_16Dual2BM + i;
}
__device__ __forceinline__ int mm_fp32_16_dual2_stagingB_idx(int buf, int j, int kk) {
    return (buf * kMmFp32_16Dual2BN + j) * kMmFp32_16Dual2BK + kk;
}
__device__ __forceinline__ int mm_fp32_16_dual2_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16Dual2BK + kk) * kMmFp32_16Dual2BN + j;
}
}  // namespace

__global__ __launch_bounds__(256, 1) void mm_fp32_16_tiled_cpasync_dualbuf2_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual2StagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual2StagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual2AsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual2StagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual2BsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16Dual2BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16Dual2BN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16Dual2WarpsN;
    const int warp_col = warp_id % kMmFp32_16Dual2WarpsN;
    const int lane_row = lane_id / kMmFp32_16Dual2LanesN;
    const int lane_col = lane_id % kMmFp32_16Dual2LanesN;
    const int row_off =
        warp_row * (kMmFp32_16Dual2BM / kMmFp32_16Dual2WarpsM) + lane_row * kMmFp32_16Dual2TM;
    const int col_off =
        warp_col * (kMmFp32_16Dual2BN / kMmFp32_16Dual2WarpsN) + lane_col * kMmFp32_16Dual2TN;

    // A: (BM/4)*BK = 32*32 = 1024 groups -- 4 per thread (BK range 0..31
    // covered via a_kk_base + v*8 for v in 0..3).
    const int a_i0 = (tid % (kMmFp32_16Dual2BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16Dual2BM / 4);

    // B: BN*(BK/4) = 128*8 = 1024 groups -- 4 per thread (BN range 0..127
    // covered via b_j_base + v*32 for v in 0..3; kk0 covers the full
    // 0..31 range directly since BK/4=8 matches this mapping's divisor).
    const int b_kk0_base = (tid % (kMmFp32_16Dual2BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16Dual2BK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual2NumThreads / (kMmFp32_16Dual2BM / 4));
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual2_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual2_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual2_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16Dual2NumThreads / (kMmFp32_16Dual2BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(
                    &stagingB[mm_fp32_16_dual2_stagingB_idx(buf, b_j, b_kk0_base)],
                    &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_dual2_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual2NumThreads / (kMmFp32_16Dual2BM / 4));
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 = *reinterpret_cast<const ushort4*>(
                    &stagingWh[mm_fp32_16_dual2_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 = *reinterpret_cast<const ushort4*>(
                    &stagingWr[mm_fp32_16_dual2_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_dual2_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                As[mm_fp32_16_dual2_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                As[mm_fp32_16_dual2_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                As[mm_fp32_16_dual2_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16Dual2NumThreads / (kMmFp32_16Dual2BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_dual2_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_dual2_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual2_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual2_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual2_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16Dual2TM][kMmFp32_16Dual2TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual2TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual2TN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16Dual2BK) {
        size_t next_k0 = k0 + kMmFp32_16Dual2BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16Dual2BK; ++kk) {
            float a_reg[kMmFp32_16Dual2TM];
            float b_reg[kMmFp32_16Dual2TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual2TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual2_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual2TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_dual2_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16Dual2TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16Dual2TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual2TM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual2TN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf2(TransposeType transA, TransposeType transB, double alpha,
                                       dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                       size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                       double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf2_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16Dual2SharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16Dual2NumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16Dual2BN - 1) / kMmFp32_16Dual2BN,
               (m + kMmFp32_16Dual2BM - 1) / kMmFp32_16Dual2BM);
    mm_fp32_16_tiled_cpasync_dualbuf2_kernel<<<blocks, threads, kMmFp32_16Dual2SharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// A genuine 3-stage software pipeline: tile i+2's cp.async is issued while
// tile i+1 is mid-transform and tile i is being computed, so all THREE
// tiles' worth of buffers (staging AND transformed, for both A and B)
// must stay valid simultaneously -- unlike dualbuf's 2-stage design, one
// buffer set isn't enough. Tripling every buffer at dualbuf's BM=128 would
// land at ~96KB/block (the same occupancy wall that sank dualbuf2 at
// BK=32), so this halves BM to 64 instead: A-side buffers (which scale
// with BM) shrink accordingly, while BN/BK stay at dualbuf's 128/16 (B's
// coalescing, already tuned, is untouched). Net: ~72KB/block, fitting 2
// blocks/SM (144KB <= A100's 164KB/SM) -- but note this measures "smaller
// tile + deeper pipeline" together, not pipelining in isolation, since
// BM=64 also means less arithmetic intensity per tile load and a
// different grid shape (more, shorter blocks along M).
//
// Pipelining mechanics: __pipeline_commit() is called once per load_tile_
// async call (one "stage" per tile, matching every other kernel here).
// __pipeline_wait_prior(STAGES-2) -- i.e. wait_prior(1) for STAGES=3 --
// is the standard steady-state call for an N-stage pipeline: called once
// per newly issued stage, it drains outstanding commits back down to "at
// most 1 remaining" every time, maintaining exactly two tiles' worth of
// prefetch in flight (the one just issued, and the one before it) at all
// times once primed.
namespace {
constexpr int kMmFp32_16TriBM = 64;
constexpr int kMmFp32_16TriBN = 128;
constexpr int kMmFp32_16TriBK = 16;
constexpr int kMmFp32_16TriTM = 8;
constexpr int kMmFp32_16TriTN = 8;
constexpr int kMmFp32_16TriWarpsM = 1;
constexpr int kMmFp32_16TriWarpsN = 4;
constexpr int kMmFp32_16TriLanesM = 8;
constexpr int kMmFp32_16TriLanesN = 4;
constexpr int kMmFp32_16TriStages = 3;
constexpr int kMmFp32_16TriNumThreads =
    (kMmFp32_16TriBM / kMmFp32_16TriTM) * (kMmFp32_16TriBN / kMmFp32_16TriTN);  // 128

constexpr size_t kMmFp32_16TriStagingWhBytes = static_cast<size_t>(kMmFp32_16TriStages) *
    kMmFp32_16TriBK * kMmFp32_16TriBM * sizeof(uint16_t);
constexpr size_t kMmFp32_16TriStagingWrBytes = kMmFp32_16TriStagingWhBytes;
constexpr size_t kMmFp32_16TriAsBytes = static_cast<size_t>(kMmFp32_16TriStages) *
    kMmFp32_16TriBK * kMmFp32_16TriBM * sizeof(float);
constexpr size_t kMmFp32_16TriStagingBBytes = static_cast<size_t>(kMmFp32_16TriStages) *
    kMmFp32_16TriBN * kMmFp32_16TriBK * sizeof(float);
constexpr size_t kMmFp32_16TriBsBytes = static_cast<size_t>(kMmFp32_16TriStages) *
    kMmFp32_16TriBK * kMmFp32_16TriBN * sizeof(float);

constexpr size_t kMmFp32_16TriStagingWhOff = 0;
constexpr size_t kMmFp32_16TriStagingWrOff =
    kMmFp32_16TriStagingWhOff + kMmFp32_16TriStagingWhBytes;
constexpr size_t kMmFp32_16TriAsOff = kMmFp32_16TriStagingWrOff + kMmFp32_16TriStagingWrBytes;
constexpr size_t kMmFp32_16TriStagingBOff = kMmFp32_16TriAsOff + kMmFp32_16TriAsBytes;
constexpr size_t kMmFp32_16TriBsOff = kMmFp32_16TriStagingBOff + kMmFp32_16TriStagingBBytes;
constexpr size_t kMmFp32_16TriSharedBytes = kMmFp32_16TriBsOff + kMmFp32_16TriBsBytes;  // ~72KB

__device__ __forceinline__ int mm_fp32_16_tri_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16TriBK + kk) * kMmFp32_16TriBM + i;
}
__device__ __forceinline__ int mm_fp32_16_tri_stagingB_idx(int buf, int j, int kk) {
    return (buf * kMmFp32_16TriBN + j) * kMmFp32_16TriBK + kk;
}
__device__ __forceinline__ int mm_fp32_16_tri_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16TriBK + kk) * kMmFp32_16TriBN + j;
}
}  // namespace

__global__ __launch_bounds__(128, 2) void mm_fp32_16_tiled_cpasync_tripipe_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16TriStagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16TriStagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16TriAsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16TriStagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16TriBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16TriBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16TriBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16TriWarpsN;
    const int warp_col = warp_id % kMmFp32_16TriWarpsN;
    const int lane_row = lane_id / kMmFp32_16TriLanesN;
    const int lane_col = lane_id % kMmFp32_16TriLanesN;
    const int row_off =
        warp_row * (kMmFp32_16TriBM / kMmFp32_16TriWarpsM) + lane_row * kMmFp32_16TriTM;
    const int col_off =
        warp_col * (kMmFp32_16TriBN / kMmFp32_16TriWarpsN) + lane_col * kMmFp32_16TriTN;

    // A: (BM/4)*BK = 16*16 = 256 groups -- 2 per thread.
    const int a_i0 = (tid % (kMmFp32_16TriBM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16TriBM / 4);
    // B: BN*(BK/4) = 128*4 = 512 groups -- 4 per thread.
    const int b_kk0_base = (tid % (kMmFp32_16TriBK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16TriBK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16TriNumThreads / (kMmFp32_16TriBM / 4));
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_tri_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_tri_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_tri_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16TriNumThreads / (kMmFp32_16TriBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_tri_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_tri_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16TriNumThreads / (kMmFp32_16TriBM / 4));
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 = *reinterpret_cast<const ushort4*>(
                    &stagingWh[mm_fp32_16_tri_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 = *reinterpret_cast<const ushort4*>(
                    &stagingWr[mm_fp32_16_tri_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_tri_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                As[mm_fp32_16_tri_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                As[mm_fp32_16_tri_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                As[mm_fp32_16_tri_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16TriNumThreads / (kMmFp32_16TriBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_tri_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_tri_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_tri_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_tri_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_tri_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16TriTM][kMmFp32_16TriTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16TriTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16TriTN; ++j) acc[i][j] = 0.0f;

    // Pipeline bookkeeping: __pipeline_commit() gives each tile a
    // monotonically increasing sequence number (0, 1, 2, ... in issue
    // order, one per load_tile_async call, never skipped or reordered).
    // To guarantee tile t's copy has landed, the correct wait_prior
    // argument is (commits_issued_so_far - 1 - t) -- "wait until nothing
    // older than t remains pending" -- NOT a hardcoded STAGES-2: that
    // shortcut is only right when a *new* commit was just issued this
    // same step. Near the tail of the K-loop (fewer than STAGES-1 tiles
    // left), no new commit gets issued, so a stale hardcoded value would
    // silently skip waiting for the tile about to be read -- a real race,
    // not just a style issue. commits_issued tracks the true count so
    // every wait_prior call is correct regardless of where in the loop
    // (including priming and the tail) it's called from.
    int commits_issued = 1;
    load_tile_async(0, 0);
    if (kMmFp32_16TriBK < k) {
        load_tile_async(1, kMmFp32_16TriBK);
        commits_issued = 2;
    }
    __pipeline_wait_prior(commits_issued - 1 - 0);
    transform_tile(0, 0);
    __syncthreads();

    int tile_idx = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16TriBK, ++tile_idx) {
        int cur = tile_idx % kMmFp32_16TriStages;
        size_t issue_k0 = k0 + (kMmFp32_16TriStages - 1) * kMmFp32_16TriBK;
        int issue_tile = tile_idx + kMmFp32_16TriStages - 1;
        if (issue_k0 < k) {
            load_tile_async(issue_tile % kMmFp32_16TriStages, issue_k0);
            commits_issued = issue_tile + 1;
        }

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16TriBK; ++kk) {
            float a_reg[kMmFp32_16TriTM];
            float b_reg[kMmFp32_16TriTN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16TriTM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_tri_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16TriTN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_tri_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16TriTM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16TriTN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        size_t next_k0 = k0 + kMmFp32_16TriBK;
        int next_tile = tile_idx + 1;
        if (next_k0 < k) {
            __pipeline_wait_prior(commits_issued - 1 - next_tile);
            transform_tile(next_tile % kMmFp32_16TriStages, next_k0);
        }
        __syncthreads();
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16TriTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16TriTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_tripipe(TransposeType transA, TransposeType transB, double alpha,
                                      dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                      size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                      double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_tripipe_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16TriSharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16TriNumThreads);  // 128, 1D
    dim3 blocks((n + kMmFp32_16TriBN - 1) / kMmFp32_16TriBN,
               (m + kMmFp32_16TriBM - 1) / kMmFp32_16TriBM);
    mm_fp32_16_tiled_cpasync_tripipe_kernel<<<blocks, threads, kMmFp32_16TriSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// The inverse of dualbuf2: instead of growing BK (which cost occupancy --
// see that kernel's comment), this SHRINKS it back to 8 (from dualbuf's
// 16), at the SAME BM=BN=128 tile dualbuf uses (unlike tripipe, which
// confounded a smaller tile with a deeper pipeline; this isolates BK
// alone). Every buffer scales down with BK, landing at ~32KB/block --
// comfortably inside the *static* 48KB limit, so no dynamic shared memory
// or cudaFuncSetAttribute dance is needed here at all. The question this
// answers: is occupancy headroom beyond dualbuf's 2-blocks/SM worth more
// than the wider B-coalescing BK=16 bought (see mm_fp32_16_tiled_cpasync_
// vec2_kernel's comment for that coalescing argument)?
//
// A structural side effect of BK=8: (BM/4)*BK = 32*8 = 256 = kNumThreads
// and BN*(BK/4) = 128*2 = 256 = kNumThreads both divide evenly into ONE
// group per thread -- unlike dualbuf's two-pass A and B loads, both are
// single-pass here, same simplicity cpasync_vec2 (the pre-dualbuf,
// B-still-synchronous kernel) had at this BK.
namespace {
constexpr int kMmFp32_16Dual3BM = 128;
constexpr int kMmFp32_16Dual3BN = 128;
constexpr int kMmFp32_16Dual3BK = 8;
constexpr int kMmFp32_16Dual3TM = 8;
constexpr int kMmFp32_16Dual3TN = 8;
constexpr int kMmFp32_16Dual3WarpsM = 2;
constexpr int kMmFp32_16Dual3WarpsN = 4;
constexpr int kMmFp32_16Dual3LanesM = 8;
constexpr int kMmFp32_16Dual3LanesN = 4;
constexpr int kMmFp32_16Dual3NumThreads =
    (kMmFp32_16Dual3BM / kMmFp32_16Dual3TM) * (kMmFp32_16Dual3BN / kMmFp32_16Dual3TN);  // 256
}  // namespace

__global__ void mm_fp32_16_tiled_cpasync_dualbuf3_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __align__(16) uint16_t stagingWh[2][kMmFp32_16Dual3BK][kMmFp32_16Dual3BM];
    __shared__ __align__(16) uint16_t stagingWr[2][kMmFp32_16Dual3BK][kMmFp32_16Dual3BM];
    __shared__ __align__(16) float As[2][kMmFp32_16Dual3BK][kMmFp32_16Dual3BM];
    __shared__ __align__(16) float stagingB[2][kMmFp32_16Dual3BN][kMmFp32_16Dual3BK];
    __shared__ __align__(16) float Bs[2][kMmFp32_16Dual3BK][kMmFp32_16Dual3BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16Dual3BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16Dual3BN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16Dual3WarpsN;
    const int warp_col = warp_id % kMmFp32_16Dual3WarpsN;
    const int lane_row = lane_id / kMmFp32_16Dual3LanesN;
    const int lane_col = lane_id % kMmFp32_16Dual3LanesN;
    const int row_off =
        warp_row * (kMmFp32_16Dual3BM / kMmFp32_16Dual3WarpsM) + lane_row * kMmFp32_16Dual3TM;
    const int col_off =
        warp_col * (kMmFp32_16Dual3BN / kMmFp32_16Dual3WarpsN) + lane_col * kMmFp32_16Dual3TN;

    // A: (BM/4)*BK = 32*8 = 256 = kNumThreads -- single pass.
    const int a_i0 = (tid % (kMmFp32_16Dual3BM / 4)) * 4;
    const int a_kk = tid / (kMmFp32_16Dual3BM / 4);
    // B: BN*(BK/4) = 128*2 = 256 = kNumThreads -- single pass.
    const int b_kk0 = (tid % (kMmFp32_16Dual3BK / 4)) * 4;
    const int b_j = tid / (kMmFp32_16Dual3BK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
        size_t a_row0 = block_row + a_i0;
        size_t a_kg = k0 + a_kk;
        if (a_row0 < m && a_kg < k) {
            size_t a_idx = a_row0 + a_kg * ld_a;
            __pipeline_memcpy_async(&stagingWh[buf][a_kk][a_i0], &wh[a_idx], sizeof(ushort4));
            __pipeline_memcpy_async(&stagingWr[buf][a_kk][a_i0], &wr[a_idx], sizeof(ushort4));
        } else {
#pragma unroll
            for (int e = 0; e < 4; ++e) As[buf][a_kk][a_i0 + e] = 0.0f;
        }

        size_t b_col = block_col + b_j;
        size_t b_kg0 = k0 + b_kk0;
        if (b_col < n && b_kg0 < k) {
            __pipeline_memcpy_async(&stagingB[buf][b_j][b_kk0], &B[b_kg0 + b_col * ld_b],
                                    sizeof(float4));
        } else {
#pragma unroll
            for (int e = 0; e < 4; ++e) Bs[buf][b_kk0 + e][b_j] = 0.0f;
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
        size_t a_row0 = block_row + a_i0;
        size_t a_kg = k0 + a_kk;
        if (a_row0 < m && a_kg < k) {
            ushort4 wh4 = *reinterpret_cast<const ushort4*>(&stagingWh[buf][a_kk][a_i0]);
            ushort4 wr4 = *reinterpret_cast<const ushort4*>(&stagingWr[buf][a_kk][a_i0]);
            As[buf][a_kk][a_i0 + 0] = fp32_16_combine(wh4.x, wr4.x);
            As[buf][a_kk][a_i0 + 1] = fp32_16_combine(wh4.y, wr4.y);
            As[buf][a_kk][a_i0 + 2] = fp32_16_combine(wh4.z, wr4.z);
            As[buf][a_kk][a_i0 + 3] = fp32_16_combine(wh4.w, wr4.w);
        }

        size_t b_col = block_col + b_j;
        size_t b_kg0 = k0 + b_kk0;
        if (b_col < n && b_kg0 < k) {
            float4 t = *reinterpret_cast<const float4*>(&stagingB[buf][b_j][b_kk0]);
            Bs[buf][b_kk0 + 0][b_j] = t.x;
            Bs[buf][b_kk0 + 1][b_j] = t.y;
            Bs[buf][b_kk0 + 2][b_j] = t.z;
            Bs[buf][b_kk0 + 3][b_j] = t.w;
        }
    };

    float acc[kMmFp32_16Dual3TM][kMmFp32_16Dual3TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual3TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual3TN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16Dual3BK) {
        size_t next_k0 = k0 + kMmFp32_16Dual3BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16Dual3BK; ++kk) {
            float a_reg[kMmFp32_16Dual3TM];
            float b_reg[kMmFp32_16Dual3TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual3TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&As[cur][kk][row_off + v * 4]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual3TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(&Bs[cur][kk][col_off + v * 4]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16Dual3TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16Dual3TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual3TM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual3TN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf3(TransposeType transA, TransposeType transB, double alpha,
                                       dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                       size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                       double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    dim3 threads(kMmFp32_16Dual3NumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16Dual3BN - 1) / kMmFp32_16Dual3BN,
               (m + kMmFp32_16Dual3BM - 1) / kMmFp32_16Dual3BM);
    mm_fp32_16_tiled_cpasync_dualbuf3_kernel<<<blocks, threads>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// dualbuf's efficiency vs cuBLAS climbs steadily with N (45% at N=1024 up
// to ~90% at N=32768) -- the classic signature of grid-size/wave-
// quantization loss, not per-block inefficiency: dualbuf's 128x128 tile
// produces only an 8x8=64-block grid at N=1024, well under a 108-SM GPU's
// SM count, leaving many SMs with zero work. This kernel keeps dualbuf's
// exact machinery (real cp.async prefetch for BOTH A and B, same BN=128/
// BK=16, same decode/transpose logic) and shrinks ONLY BM, from 128 to
// 64 -- doubling the row-tile count (16x8=128 blocks at N=1024) without
// touching the tile-shape/BK/pipeline-depth axes already tried (dualbuf2,
// dualbuf3, tripipe). This isolates the grid-fill hypothesis that
// tripipe's BM=64 experiment confounded with a 3-stage pipeline.
//
// The predicted cost: BM=64 halves threads/block to 128 (4 warps instead
// of 8), so once N is large enough that grid size stops being the
// bottleneck, this kernel has fewer warps resident per SM than dualbuf
// even if more blocks fit -- expected to cost a few percent at steady
// state in exchange for the small-N win.
//
// On one dev GPU, dualbuf4 winning only at N=1024 and losing steadily
// from N=2048 up matched a simple threshold on (grid blocks at dualbuf's
// 128x128 tiling) vs (SM count) -- a real dispatcher was briefly built on
// that basis. It was dropped after measuring an actual A100: there,
// dualbuf4 LOSES at N=1024 but WINS at N=2048/4096 before losing again at
// N=8192+ -- a non-monotonic crossover the single-variable heuristic
// can't express, and gets backwards on that hardware. No dispatcher
// exists here; dualbuf and dualbuf4 are both kept as directly-callable
// options, since which one wins is GPU- and size-dependent in a way not
// yet explained by grid/SM-count alone.
namespace {
constexpr int kMmFp32_16Dual4BM = 64;
constexpr int kMmFp32_16Dual4BN = 128;
constexpr int kMmFp32_16Dual4BK = 16;
constexpr int kMmFp32_16Dual4TM = 8;
constexpr int kMmFp32_16Dual4TN = 8;
constexpr int kMmFp32_16Dual4WarpsM = 1;
constexpr int kMmFp32_16Dual4WarpsN = 4;
constexpr int kMmFp32_16Dual4LanesM = 8;
constexpr int kMmFp32_16Dual4LanesN = 4;
constexpr int kMmFp32_16Dual4NumThreads =
    (kMmFp32_16Dual4BM / kMmFp32_16Dual4TM) * (kMmFp32_16Dual4BN / kMmFp32_16Dual4TN);  // 128

constexpr size_t kMmFp32_16Dual4StagingWhBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual4BK) * kMmFp32_16Dual4BM * sizeof(uint16_t);
constexpr size_t kMmFp32_16Dual4StagingWrBytes = kMmFp32_16Dual4StagingWhBytes;
constexpr size_t kMmFp32_16Dual4AsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual4BK) * kMmFp32_16Dual4BM * sizeof(float);
constexpr size_t kMmFp32_16Dual4StagingBBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual4BN) * kMmFp32_16Dual4BK * sizeof(float);
constexpr size_t kMmFp32_16Dual4BsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual4BK) * kMmFp32_16Dual4BN * sizeof(float);

constexpr size_t kMmFp32_16Dual4StagingWhOff = 0;
constexpr size_t kMmFp32_16Dual4StagingWrOff =
    kMmFp32_16Dual4StagingWhOff + kMmFp32_16Dual4StagingWhBytes;
constexpr size_t kMmFp32_16Dual4AsOff = kMmFp32_16Dual4StagingWrOff + kMmFp32_16Dual4StagingWrBytes;
constexpr size_t kMmFp32_16Dual4StagingBOff = kMmFp32_16Dual4AsOff + kMmFp32_16Dual4AsBytes;
constexpr size_t kMmFp32_16Dual4BsOff = kMmFp32_16Dual4StagingBOff + kMmFp32_16Dual4StagingBBytes;
constexpr size_t kMmFp32_16Dual4SharedBytes = kMmFp32_16Dual4BsOff + kMmFp32_16Dual4BsBytes;  // 48KB

__device__ __forceinline__ int mm_fp32_16_dual4_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16Dual4BK + kk) * kMmFp32_16Dual4BM + i;
}
__device__ __forceinline__ int mm_fp32_16_dual4_stagingB_idx(int buf, int j, int kk) {
    return (buf * kMmFp32_16Dual4BN + j) * kMmFp32_16Dual4BK + kk;
}
__device__ __forceinline__ int mm_fp32_16_dual4_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16Dual4BK + kk) * kMmFp32_16Dual4BN + j;
}
}  // namespace

__global__ __launch_bounds__(128, 3) void mm_fp32_16_tiled_cpasync_dualbuf4_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual4StagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual4StagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual4AsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual4StagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual4BsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16Dual4BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16Dual4BN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16Dual4WarpsN;
    const int warp_col = warp_id % kMmFp32_16Dual4WarpsN;
    const int lane_row = lane_id / kMmFp32_16Dual4LanesN;
    const int lane_col = lane_id % kMmFp32_16Dual4LanesN;
    const int row_off =
        warp_row * (kMmFp32_16Dual4BM / kMmFp32_16Dual4WarpsM) + lane_row * kMmFp32_16Dual4TM;
    const int col_off =
        warp_col * (kMmFp32_16Dual4BN / kMmFp32_16Dual4WarpsN) + lane_col * kMmFp32_16Dual4TN;

    // A: (BM/4)*BK / NumThreads = (64/4)*16 / 128 = 2 passes.
    const int a_i0 = (tid % (kMmFp32_16Dual4BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16Dual4BM / 4);
    // B: BN*(BK/4) / NumThreads = 128*4 / 128 = 4 passes.
    const int b_kk0_base = (tid % (kMmFp32_16Dual4BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16Dual4BK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual4BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual4_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual4_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual4_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16Dual4NumThreads / (kMmFp32_16Dual4BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_dual4_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_dual4_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual4BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual4_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual4_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_dual4_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                As[mm_fp32_16_dual4_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                As[mm_fp32_16_dual4_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                As[mm_fp32_16_dual4_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16Dual4NumThreads / (kMmFp32_16Dual4BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_dual4_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_dual4_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual4_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual4_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual4_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16Dual4TM][kMmFp32_16Dual4TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual4TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual4TN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16Dual4BK) {
        size_t next_k0 = k0 + kMmFp32_16Dual4BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16Dual4BK; ++kk) {
            float a_reg[kMmFp32_16Dual4TM];
            float b_reg[kMmFp32_16Dual4TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual4TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual4_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual4TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_dual4_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16Dual4TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16Dual4TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual4TM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual4TN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf4(TransposeType transA, TransposeType transB, double alpha,
                                       dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                       size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                       double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf4_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16Dual4SharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16Dual4NumThreads);  // 128, 1D
    dim3 blocks((n + kMmFp32_16Dual4BN - 1) / kMmFp32_16Dual4BN,
               (m + kMmFp32_16Dual4BM - 1) / kMmFp32_16Dual4BM);
    mm_fp32_16_tiled_cpasync_dualbuf4_kernel<<<blocks, threads, kMmFp32_16Dual4SharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// The mirror of dualbuf4: shrinks BN (128->64) instead of BM, keeping
// BM=128/BK=16 and the same real dual-cp.async machinery for both A and
// B. Built to test whether dualbuf4's win over dualbuf specifically at
// mid-range N (N=2048/4096 on an A100, not just small N as first
// measured on a different dev GPU) is a general small-tile effect that
// should show up symmetrically on the N-axis too, or specific to the
// M-axis shrink -- e.g. because B already carries the extra staging+
// transpose step dualbuf added for it, which A doesn't have, so shrinking
// the dimension that drives B's tile (BN) could behave differently than
// shrinking the one that drives A's tile (BM). Same alignment/boundary
// requirements as vec2; falls back to dualbuf otherwise.
namespace {
constexpr int kMmFp32_16Dual5BM = 128;
constexpr int kMmFp32_16Dual5BN = 64;
constexpr int kMmFp32_16Dual5BK = 16;
constexpr int kMmFp32_16Dual5TM = 8;
constexpr int kMmFp32_16Dual5TN = 8;
constexpr int kMmFp32_16Dual5WarpsM = 4;
constexpr int kMmFp32_16Dual5WarpsN = 1;
constexpr int kMmFp32_16Dual5LanesM = 4;
constexpr int kMmFp32_16Dual5LanesN = 8;
constexpr int kMmFp32_16Dual5NumThreads =
    (kMmFp32_16Dual5BM / kMmFp32_16Dual5TM) * (kMmFp32_16Dual5BN / kMmFp32_16Dual5TN);  // 128

constexpr size_t kMmFp32_16Dual5StagingWhBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual5BK) * kMmFp32_16Dual5BM * sizeof(uint16_t);
constexpr size_t kMmFp32_16Dual5StagingWrBytes = kMmFp32_16Dual5StagingWhBytes;
constexpr size_t kMmFp32_16Dual5AsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual5BK) * kMmFp32_16Dual5BM * sizeof(float);
constexpr size_t kMmFp32_16Dual5StagingBBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual5BN) * kMmFp32_16Dual5BK * sizeof(float);
constexpr size_t kMmFp32_16Dual5BsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual5BK) * kMmFp32_16Dual5BN * sizeof(float);

constexpr size_t kMmFp32_16Dual5StagingWhOff = 0;
constexpr size_t kMmFp32_16Dual5StagingWrOff =
    kMmFp32_16Dual5StagingWhOff + kMmFp32_16Dual5StagingWhBytes;
constexpr size_t kMmFp32_16Dual5AsOff = kMmFp32_16Dual5StagingWrOff + kMmFp32_16Dual5StagingWrBytes;
constexpr size_t kMmFp32_16Dual5StagingBOff = kMmFp32_16Dual5AsOff + kMmFp32_16Dual5AsBytes;
constexpr size_t kMmFp32_16Dual5BsOff = kMmFp32_16Dual5StagingBOff + kMmFp32_16Dual5StagingBBytes;
constexpr size_t kMmFp32_16Dual5SharedBytes = kMmFp32_16Dual5BsOff + kMmFp32_16Dual5BsBytes;  // 48KB

__device__ __forceinline__ int mm_fp32_16_dual5_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16Dual5BK + kk) * kMmFp32_16Dual5BM + i;
}
__device__ __forceinline__ int mm_fp32_16_dual5_stagingB_idx(int buf, int j, int kk) {
    return (buf * kMmFp32_16Dual5BN + j) * kMmFp32_16Dual5BK + kk;
}
__device__ __forceinline__ int mm_fp32_16_dual5_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16Dual5BK + kk) * kMmFp32_16Dual5BN + j;
}
}  // namespace

__global__ __launch_bounds__(128, 3) void mm_fp32_16_tiled_cpasync_dualbuf5_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual5StagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual5StagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual5AsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual5StagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual5BsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16Dual5BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16Dual5BN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16Dual5WarpsN;
    const int warp_col = warp_id % kMmFp32_16Dual5WarpsN;
    const int lane_row = lane_id / kMmFp32_16Dual5LanesN;
    const int lane_col = lane_id % kMmFp32_16Dual5LanesN;
    const int row_off =
        warp_row * (kMmFp32_16Dual5BM / kMmFp32_16Dual5WarpsM) + lane_row * kMmFp32_16Dual5TM;
    const int col_off =
        warp_col * (kMmFp32_16Dual5BN / kMmFp32_16Dual5WarpsN) + lane_col * kMmFp32_16Dual5TN;

    // A: (BM/4)*BK / NumThreads = (128/4)*16 / 128 = 4 passes.
    const int a_i0 = (tid % (kMmFp32_16Dual5BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16Dual5BM / 4);
    // B: BN*(BK/4) / NumThreads = 64*4 / 128 = 2 passes.
    const int b_kk0_base = (tid % (kMmFp32_16Dual5BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16Dual5BK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual5BK / 4);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual5_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual5_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual5_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16Dual5NumThreads / (kMmFp32_16Dual5BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_dual5_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_dual5_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 4; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual5BK / 4);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual5_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual5_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_dual5_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                As[mm_fp32_16_dual5_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                As[mm_fp32_16_dual5_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                As[mm_fp32_16_dual5_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16Dual5NumThreads / (kMmFp32_16Dual5BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_dual5_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_dual5_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual5_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual5_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual5_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16Dual5TM][kMmFp32_16Dual5TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual5TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual5TN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16Dual5BK) {
        size_t next_k0 = k0 + kMmFp32_16Dual5BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16Dual5BK; ++kk) {
            float a_reg[kMmFp32_16Dual5TM];
            float b_reg[kMmFp32_16Dual5TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual5TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual5_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual5TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_dual5_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16Dual5TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16Dual5TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual5TM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual5TN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf5(TransposeType transA, TransposeType transB, double alpha,
                                       dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                       size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                       double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf5_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16Dual5SharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16Dual5NumThreads);  // 128, 1D
    dim3 blocks((n + kMmFp32_16Dual5BN - 1) / kMmFp32_16Dual5BN,
               (m + kMmFp32_16Dual5BM - 1) / kMmFp32_16Dual5BM);
    mm_fp32_16_tiled_cpasync_dualbuf5_kernel<<<blocks, threads, kMmFp32_16Dual5SharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Same tile shape and shared-memory double-buffering as dualbuf (BM=BN=
// 128, BK=16, same real dual-cp.async for A and B) -- the only change is
// INSIDE the inner k-loop. Every kernel so far loads a_reg/b_reg from
// shared memory for tile kk and immediately consumes them; the compiler
// can reorder within the fully-unrolled BK=16 loop, but never tested
// whether explicitly software-pipelining that load (prefetch kk+1's
// registers while computing on kk's) does any better than relying on
// ptxas's own scheduling. Doubles a_reg/b_reg's register footprint (16
// registers -> 32) to hold both the in-flight and in-use sets, which may
// or may not push past dualbuf's occupancy budget -- measured, not
// assumed, same as every other change in this file.
namespace {
constexpr int kMmFp32_16Dual6BM = 128;
constexpr int kMmFp32_16Dual6BN = 128;
constexpr int kMmFp32_16Dual6BK = 16;
constexpr int kMmFp32_16Dual6TM = 8;
constexpr int kMmFp32_16Dual6TN = 8;
constexpr int kMmFp32_16Dual6WarpsM = 2;
constexpr int kMmFp32_16Dual6WarpsN = 4;
constexpr int kMmFp32_16Dual6LanesM = 8;
constexpr int kMmFp32_16Dual6LanesN = 4;
constexpr int kMmFp32_16Dual6NumThreads =
    (kMmFp32_16Dual6BM / kMmFp32_16Dual6TM) * (kMmFp32_16Dual6BN / kMmFp32_16Dual6TN);  // 256

constexpr size_t kMmFp32_16Dual6StagingWhBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual6BK) * kMmFp32_16Dual6BM * sizeof(uint16_t);
constexpr size_t kMmFp32_16Dual6StagingWrBytes = kMmFp32_16Dual6StagingWhBytes;
constexpr size_t kMmFp32_16Dual6AsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual6BK) * kMmFp32_16Dual6BM * sizeof(float);
constexpr size_t kMmFp32_16Dual6StagingBBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual6BN) * kMmFp32_16Dual6BK * sizeof(float);
constexpr size_t kMmFp32_16Dual6BsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual6BK) * kMmFp32_16Dual6BN * sizeof(float);

constexpr size_t kMmFp32_16Dual6StagingWhOff = 0;
constexpr size_t kMmFp32_16Dual6StagingWrOff =
    kMmFp32_16Dual6StagingWhOff + kMmFp32_16Dual6StagingWhBytes;
constexpr size_t kMmFp32_16Dual6AsOff = kMmFp32_16Dual6StagingWrOff + kMmFp32_16Dual6StagingWrBytes;
constexpr size_t kMmFp32_16Dual6StagingBOff = kMmFp32_16Dual6AsOff + kMmFp32_16Dual6AsBytes;
constexpr size_t kMmFp32_16Dual6BsOff = kMmFp32_16Dual6StagingBOff + kMmFp32_16Dual6StagingBBytes;
constexpr size_t kMmFp32_16Dual6SharedBytes = kMmFp32_16Dual6BsOff + kMmFp32_16Dual6BsBytes;  // 64KB

__device__ __forceinline__ int mm_fp32_16_dual6_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16Dual6BK + kk) * kMmFp32_16Dual6BM + i;
}
__device__ __forceinline__ int mm_fp32_16_dual6_stagingB_idx(int buf, int j, int kk) {
    return (buf * kMmFp32_16Dual6BN + j) * kMmFp32_16Dual6BK + kk;
}
__device__ __forceinline__ int mm_fp32_16_dual6_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16Dual6BK + kk) * kMmFp32_16Dual6BN + j;
}
}  // namespace

__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_dualbuf6_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual6StagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual6StagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual6AsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual6StagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual6BsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16Dual6BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16Dual6BN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16Dual6WarpsN;
    const int warp_col = warp_id % kMmFp32_16Dual6WarpsN;
    const int lane_row = lane_id / kMmFp32_16Dual6LanesN;
    const int lane_col = lane_id % kMmFp32_16Dual6LanesN;
    const int row_off =
        warp_row * (kMmFp32_16Dual6BM / kMmFp32_16Dual6WarpsM) + lane_row * kMmFp32_16Dual6TM;
    const int col_off =
        warp_col * (kMmFp32_16Dual6BN / kMmFp32_16Dual6WarpsN) + lane_col * kMmFp32_16Dual6TN;

    const int a_i0 = (tid % (kMmFp32_16Dual6BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16Dual6BM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16Dual6BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16Dual6BK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual6BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual6_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual6_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual6_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16Dual6NumThreads / (kMmFp32_16Dual6BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_dual6_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_dual6_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual6BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual6_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual6_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_dual6_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                As[mm_fp32_16_dual6_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                As[mm_fp32_16_dual6_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                As[mm_fp32_16_dual6_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16Dual6NumThreads / (kMmFp32_16Dual6BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_dual6_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_dual6_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual6_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual6_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual6_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16Dual6TM][kMmFp32_16Dual6TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual6TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual6TN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    // Software-pipelined register loads: a_reg[buf][slot]/b_reg[buf][slot]
    // hold the register-double-buffered values for tile buffer `buf`.
    // Only "cur"'s slot pair is read from shared memory going in; from
    // then on each kk loads the NEXT kk's registers before consuming the
    // CURRENT kk's, so the load for kk+1 overlaps with the FMA chain for
    // kk instead of the two happening back-to-back.
    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16Dual6BK) {
        size_t next_k0 = k0 + kMmFp32_16Dual6BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

        float a_reg[2][kMmFp32_16Dual6TM];
        float b_reg[2][kMmFp32_16Dual6TN];
#pragma unroll
        for (int v = 0; v < kMmFp32_16Dual6TM / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &As[mm_fp32_16_dual6_a_idx(cur, 0, row_off + v * 4)]);
            a_reg[0][v * 4 + 0] = t.x;
            a_reg[0][v * 4 + 1] = t.y;
            a_reg[0][v * 4 + 2] = t.z;
            a_reg[0][v * 4 + 3] = t.w;
        }
#pragma unroll
        for (int v = 0; v < kMmFp32_16Dual6TN / 4; ++v) {
            float4 t = *reinterpret_cast<const float4*>(
                &Bs[mm_fp32_16_dual6_bs_idx(cur, 0, col_off + v * 4)]);
            b_reg[0][v * 4 + 0] = t.x;
            b_reg[0][v * 4 + 1] = t.y;
            b_reg[0][v * 4 + 2] = t.z;
            b_reg[0][v * 4 + 3] = t.w;
        }

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16Dual6BK; ++kk) {
            int slot = kk % 2;
            int next_slot = slot ^ 1;
            if (kk + 1 < kMmFp32_16Dual6BK) {
#pragma unroll
                for (int v = 0; v < kMmFp32_16Dual6TM / 4; ++v) {
                    float4 t = *reinterpret_cast<const float4*>(
                        &As[mm_fp32_16_dual6_a_idx(cur, kk + 1, row_off + v * 4)]);
                    a_reg[next_slot][v * 4 + 0] = t.x;
                    a_reg[next_slot][v * 4 + 1] = t.y;
                    a_reg[next_slot][v * 4 + 2] = t.z;
                    a_reg[next_slot][v * 4 + 3] = t.w;
                }
#pragma unroll
                for (int v = 0; v < kMmFp32_16Dual6TN / 4; ++v) {
                    float4 t = *reinterpret_cast<const float4*>(
                        &Bs[mm_fp32_16_dual6_bs_idx(cur, kk + 1, col_off + v * 4)]);
                    b_reg[next_slot][v * 4 + 0] = t.x;
                    b_reg[next_slot][v * 4 + 1] = t.y;
                    b_reg[next_slot][v * 4 + 2] = t.z;
                    b_reg[next_slot][v * 4 + 3] = t.w;
                }
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16Dual6TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16Dual6TN; ++j)
                    acc[i][j] += a_reg[slot][i] * b_reg[slot][j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual6TM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual6TN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf6(TransposeType transA, TransposeType transB, double alpha,
                                       dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                       size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                       double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf6_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16Dual6SharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16Dual6NumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16Dual6BN - 1) / kMmFp32_16Dual6BN,
               (m + kMmFp32_16Dual6BM - 1) / kMmFp32_16Dual6BM);
    mm_fp32_16_tiled_cpasync_dualbuf6_kernel<<<blocks, threads, kMmFp32_16Dual6SharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

// Split-K: dualbuf's exact 128x128/BK=16 tile and warp/lane shape (the
// most efficient shape measured in this series), but instead of one
// block reducing the FULL K range per output tile, P blocks each reduce
// a K/P slice and atomicAdd their partial contribution into C. This is
// the standard technique for the actual problem dualbuf4/5 were fighting
// (too few *output* tiles to fill the GPU when M/N are small relative to
// K) -- unlike shrinking the output tile (which trades away per-block
// efficiency), split-K keeps the efficient tile and multiplies the block
// count by dividing K instead. A grid-stride/persistent kernel was
// considered first but rejected: it only amortizes launch overhead when
// there are MORE tiles than the GPU can hold at once (the already-fine
// large-N case) -- it can't invent parallelism when there are too FEW
// tiles, which is exactly the small/mid-N regime this targets.
//
// Correctness requires beta*C to be applied exactly once, before any
// slice's atomicAdd -- done by a separate prescale kernel that runs first
// (same default stream, so its writes are guaranteed complete before the
// split-K kernel's grid launches). Each slice's boundary checks use the
// LOCAL k_end (its slice's end), not the global k, so slices don't
// double-count any K range.
namespace {
constexpr int kMmFp32_16SplitBM = 128;
constexpr int kMmFp32_16SplitBN = 128;
constexpr int kMmFp32_16SplitBK = 16;
constexpr int kMmFp32_16SplitTM = 8;
constexpr int kMmFp32_16SplitTN = 8;
constexpr int kMmFp32_16SplitWarpsM = 2;
constexpr int kMmFp32_16SplitWarpsN = 4;
constexpr int kMmFp32_16SplitLanesM = 8;
constexpr int kMmFp32_16SplitLanesN = 4;
constexpr int kMmFp32_16SplitNumThreads =
    (kMmFp32_16SplitBM / kMmFp32_16SplitTM) * (kMmFp32_16SplitBN / kMmFp32_16SplitTN);  // 256

constexpr size_t kMmFp32_16SplitStagingWhBytes =
    2 * static_cast<size_t>(kMmFp32_16SplitBK) * kMmFp32_16SplitBM * sizeof(uint16_t);
constexpr size_t kMmFp32_16SplitStagingWrBytes = kMmFp32_16SplitStagingWhBytes;
constexpr size_t kMmFp32_16SplitAsBytes =
    2 * static_cast<size_t>(kMmFp32_16SplitBK) * kMmFp32_16SplitBM * sizeof(float);
constexpr size_t kMmFp32_16SplitStagingBBytes =
    2 * static_cast<size_t>(kMmFp32_16SplitBN) * kMmFp32_16SplitBK * sizeof(float);
constexpr size_t kMmFp32_16SplitBsBytes =
    2 * static_cast<size_t>(kMmFp32_16SplitBK) * kMmFp32_16SplitBN * sizeof(float);

constexpr size_t kMmFp32_16SplitStagingWhOff = 0;
constexpr size_t kMmFp32_16SplitStagingWrOff =
    kMmFp32_16SplitStagingWhOff + kMmFp32_16SplitStagingWhBytes;
constexpr size_t kMmFp32_16SplitAsOff = kMmFp32_16SplitStagingWrOff + kMmFp32_16SplitStagingWrBytes;
constexpr size_t kMmFp32_16SplitStagingBOff = kMmFp32_16SplitAsOff + kMmFp32_16SplitAsBytes;
constexpr size_t kMmFp32_16SplitBsOff = kMmFp32_16SplitStagingBOff + kMmFp32_16SplitStagingBBytes;
constexpr size_t kMmFp32_16SplitSharedBytes = kMmFp32_16SplitBsOff + kMmFp32_16SplitBsBytes;  // 64KB

__device__ __forceinline__ int mm_fp32_16_split_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16SplitBK + kk) * kMmFp32_16SplitBM + i;
}
__device__ __forceinline__ int mm_fp32_16_split_stagingB_idx(int buf, int j, int kk) {
    return (buf * kMmFp32_16SplitBN + j) * kMmFp32_16SplitBK + kk;
}
__device__ __forceinline__ int mm_fp32_16_split_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16SplitBK + kk) * kMmFp32_16SplitBN + j;
}
}  // namespace

__global__ void mm_fp32_16_splitk_prescale_kernel(size_t m, size_t n, double beta,
                                                   float* __restrict__ C, size_t ld_c) {
    size_t row = static_cast<size_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    size_t col = static_cast<size_t>(blockIdx.y) * blockDim.y + threadIdx.y;
    if (row >= m || col >= n) return;
    size_t idx = row + col * ld_c;
    C[idx] = static_cast<float>(beta * static_cast<double>(C[idx]));
}

__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_splitk_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    float* __restrict__ C, size_t ld_c, size_t k_slice) {
    size_t k_start = static_cast<size_t>(blockIdx.z) * k_slice;
    if (k_start >= k) return;
    size_t k_end = k_start + k_slice < k ? k_start + k_slice : k;

    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16SplitStagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16SplitStagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16SplitAsOff);
    float* stagingB = reinterpret_cast<float*>(smem_raw + kMmFp32_16SplitStagingBOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16SplitBsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16SplitBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16SplitBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16SplitWarpsN;
    const int warp_col = warp_id % kMmFp32_16SplitWarpsN;
    const int lane_row = lane_id / kMmFp32_16SplitLanesN;
    const int lane_col = lane_id % kMmFp32_16SplitLanesN;
    const int row_off =
        warp_row * (kMmFp32_16SplitBM / kMmFp32_16SplitWarpsM) + lane_row * kMmFp32_16SplitTM;
    const int col_off =
        warp_col * (kMmFp32_16SplitBN / kMmFp32_16SplitWarpsN) + lane_col * kMmFp32_16SplitTN;

    const int a_i0 = (tid % (kMmFp32_16SplitBM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16SplitBM / 4);
    const int b_kk0_base = (tid % (kMmFp32_16SplitBK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16SplitBK / 4);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16SplitBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k_end) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_split_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_split_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_split_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16SplitNumThreads / (kMmFp32_16SplitBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k_end) {
                __pipeline_memcpy_async(&stagingB[mm_fp32_16_split_stagingB_idx(buf, b_j, b_kk0_base)],
                                        &B[b_kg0 + b_col * ld_b], sizeof(float4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_split_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16SplitBK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k_end) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_split_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_split_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_split_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                As[mm_fp32_16_split_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                As[mm_fp32_16_split_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                As[mm_fp32_16_split_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16SplitNumThreads / (kMmFp32_16SplitBK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k_end) {
                float4 t = *reinterpret_cast<const float4*>(
                    &stagingB[mm_fp32_16_split_stagingB_idx(buf, b_j, b_kk0_base)]);
                Bs[mm_fp32_16_split_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_split_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_split_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_split_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            }
        }
    };

    float acc[kMmFp32_16SplitTM][kMmFp32_16SplitTN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16SplitTM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16SplitTN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, k_start);
    __pipeline_wait_prior(0);
    transform_tile(0, k_start);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = k_start; k0 < k_end; k0 += kMmFp32_16SplitBK) {
        size_t next_k0 = k0 + kMmFp32_16SplitBK;
        int nxt = cur ^ 1;
        if (next_k0 < k_end) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16SplitBK; ++kk) {
            float a_reg[kMmFp32_16SplitTM];
            float b_reg[kMmFp32_16SplitTN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16SplitTM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_split_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16SplitTN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_split_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16SplitTM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16SplitTN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k_end) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16SplitTM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16SplitTN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            atomicAdd(&C[idx], static_cast<float>(alpha * static_cast<double>(acc[i][j])));
        }
    }
}

void mm_fp32_16_tiled_cpasync_splitk(TransposeType transA, TransposeType transB, double alpha,
                                     dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                     size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                     double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_splitk_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16SplitSharedBytes));
        attr_set = true;
    }

    size_t total_tiles = ((n + kMmFp32_16SplitBN - 1) / kMmFp32_16SplitBN) *
                         ((m + kMmFp32_16SplitBM - 1) / kMmFp32_16SplitBM);

    static int sm_count = -1;
    if (sm_count < 0) {
        int device = 0;
        cudaGetDevice(&device);
        cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
    }
    size_t target_blocks = static_cast<size_t>(sm_count) * 2;

    // P: a blanket "always aim for 3x target_blocks" margin was tried and
    // measured WORSE than the original "just enough to clear
    // target_blocks" rule even in the case that rule already won (N=1024
    // on an A100: P went from 4 -> 11, and throughput dropped from 6774
    // to 5755 GFlop/s -- extra splits past the sweet spot cost more in
    // atomicAdd/sync overhead than they gain). So: keep the original
    // "just enough" rule for the clearly-underfilled case (this is what
    // produced the one real win), and add a narrow, separate case for the
    // specific failure this was missing -- total_tiles landing only
    // slightly ABOVE target_blocks (e.g. 256 vs 216 at N=2048), which
    // still wastes a mostly-empty tail wave. A modest fixed P=2 there
    // smooths that tail without the runaway-split cost the 3x rule paid.
    // Not so many splits that each slice covers less than 4 BK-tiles
    // (keeps per-block K-work from getting too thin) or beyond a fixed
    // ceiling (bounds atomicAdd contention at every output element).
    size_t p;
    if (total_tiles == 0) {
        p = 1;
    } else if (total_tiles < target_blocks) {
        p = (target_blocks + total_tiles - 1) / total_tiles;
    } else if (total_tiles < target_blocks + target_blocks / 2) {
        p = 2;
    } else {
        p = 1;
    }
    size_t max_p_by_k = k / (4 * kMmFp32_16SplitBK);
    if (max_p_by_k < 1) max_p_by_k = 1;
    if (p > max_p_by_k) p = max_p_by_k;
    if (p > 32) p = 32;
    if (p < 1) p = 1;
    // k_start = blockIdx.z * k_slice must stay a multiple of 4: B's
    // cp.async float4 load address is offset directly by k_start (b_kg0),
    // not scaled by any stride guaranteed a multiple of 4 the way A's
    // ld_a-scaled offset is -- an unrounded k_slice landed k_start on a
    // misaligned address, corrupting the cp.async transfer (confirmed via
    // compute-sanitizer: "Invalid __global__ read ... is misaligned").
    // Rounding up to a full BK tile keeps every slice boundary aligned.
    size_t k_slice = (((k + p - 1) / p + kMmFp32_16SplitBK - 1) / kMmFp32_16SplitBK) *
                     kMmFp32_16SplitBK;

    dim3 prescale_threads(32, 8);
    dim3 prescale_blocks((m + prescale_threads.x - 1) / prescale_threads.x,
                         (n + prescale_threads.y - 1) / prescale_threads.y);
    mm_fp32_16_splitk_prescale_kernel<<<prescale_blocks, prescale_threads>>>(m, n, beta, C, ld_c);

    dim3 threads(kMmFp32_16SplitNumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16SplitBN - 1) / kMmFp32_16SplitBN,
               (m + kMmFp32_16SplitBM - 1) / kMmFp32_16SplitBM,
               static_cast<unsigned int>(p));
    mm_fp32_16_tiled_cpasync_splitk_kernel<<<blocks, threads, kMmFp32_16SplitSharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, C, ld_c, k_slice);
}

// Same tile/warp shape as dualbuf, same real cp.async + decode for A --
// but B goes back to a SYNCHRONOUS one-step global-read-then-transpose
// write into Bs (matching gemm_fp32_tiled_cpasync_vec3_kernel's B path in
// mm_cuda_kernels.cu exactly), instead of dualbuf's two-step cp.async-
// into-a-staging-buffer-then-transform. dualbuf's B staging was added to
// hide B's global memory latency; profiling dualbuf directly (ncu, A100)
// showed it's compute-bound (86% SM/FMA throughput, only 20% DRAM
// throughput) with no meaningful memory latency left to hide, and vec3
// (plain FP32, no decode step at all, and ALSO synchronous-B) still beats
// dualbuf's relative-to-cuBLAS efficiency despite dualbuf's async B and
// extra warp-tiling. This tests directly whether B's staging round-trip
// is now pure overhead in dualbuf's compute-bound regime: same A path,
// same warp shape, only B's load strategy changes.
namespace {
constexpr int kMmFp32_16Dual7BM = 128;
constexpr int kMmFp32_16Dual7BN = 128;
constexpr int kMmFp32_16Dual7BK = 16;
constexpr int kMmFp32_16Dual7TM = 8;
constexpr int kMmFp32_16Dual7TN = 8;
constexpr int kMmFp32_16Dual7WarpsM = 2;
constexpr int kMmFp32_16Dual7WarpsN = 4;
constexpr int kMmFp32_16Dual7LanesM = 8;
constexpr int kMmFp32_16Dual7LanesN = 4;
constexpr int kMmFp32_16Dual7NumThreads =
    (kMmFp32_16Dual7BM / kMmFp32_16Dual7TM) * (kMmFp32_16Dual7BN / kMmFp32_16Dual7TN);  // 256

constexpr size_t kMmFp32_16Dual7StagingWhBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual7BK) * kMmFp32_16Dual7BM * sizeof(uint16_t);
constexpr size_t kMmFp32_16Dual7StagingWrBytes = kMmFp32_16Dual7StagingWhBytes;
constexpr size_t kMmFp32_16Dual7AsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual7BK) * kMmFp32_16Dual7BM * sizeof(float);
constexpr size_t kMmFp32_16Dual7BsBytes =
    2 * static_cast<size_t>(kMmFp32_16Dual7BK) * kMmFp32_16Dual7BN * sizeof(float);

constexpr size_t kMmFp32_16Dual7StagingWhOff = 0;
constexpr size_t kMmFp32_16Dual7StagingWrOff =
    kMmFp32_16Dual7StagingWhOff + kMmFp32_16Dual7StagingWhBytes;
constexpr size_t kMmFp32_16Dual7AsOff = kMmFp32_16Dual7StagingWrOff + kMmFp32_16Dual7StagingWrBytes;
constexpr size_t kMmFp32_16Dual7BsOff = kMmFp32_16Dual7AsOff + kMmFp32_16Dual7AsBytes;
constexpr size_t kMmFp32_16Dual7SharedBytes = kMmFp32_16Dual7BsOff + kMmFp32_16Dual7BsBytes;  // 48KB

__device__ __forceinline__ int mm_fp32_16_dual7_a_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16Dual7BK + kk) * kMmFp32_16Dual7BM + i;
}
__device__ __forceinline__ int mm_fp32_16_dual7_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16Dual7BK + kk) * kMmFp32_16Dual7BN + j;
}
}  // namespace

__global__ __launch_bounds__(256, 2) void mm_fp32_16_tiled_cpasync_dualbuf7_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, const uint16_t* __restrict__ wr, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    uint16_t* stagingWh = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual7StagingWhOff);
    uint16_t* stagingWr = reinterpret_cast<uint16_t*>(smem_raw + kMmFp32_16Dual7StagingWrOff);
    float* As = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual7AsOff);
    float* Bs = reinterpret_cast<float*>(smem_raw + kMmFp32_16Dual7BsOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16Dual7BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16Dual7BN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane_id = tid % 32;
    const int warp_row = warp_id / kMmFp32_16Dual7WarpsN;
    const int warp_col = warp_id % kMmFp32_16Dual7WarpsN;
    const int lane_row = lane_id / kMmFp32_16Dual7LanesN;
    const int lane_col = lane_id % kMmFp32_16Dual7LanesN;
    const int row_off =
        warp_row * (kMmFp32_16Dual7BM / kMmFp32_16Dual7WarpsM) + lane_row * kMmFp32_16Dual7TM;
    const int col_off =
        warp_col * (kMmFp32_16Dual7BN / kMmFp32_16Dual7WarpsN) + lane_col * kMmFp32_16Dual7TN;

    // A: (BM/4)*BK / NumThreads = 2 passes -- same mapping as dualbuf.
    const int a_i0 = (tid % (kMmFp32_16Dual7BM / 4)) * 4;
    const int a_kk_base = tid / (kMmFp32_16Dual7BM / 4);
    // B: BN*(BK/4) / NumThreads = 2 passes -- same mapping vec3 uses for
    // its (synchronous) B load.
    const int b_kk0_base = (tid % (kMmFp32_16Dual7BK / 4)) * 4;
    const int b_j_base = tid / (kMmFp32_16Dual7BK / 4);

    // Issues A's cp.async for tile k0 into buf, and does B's SYNCHRONOUS
    // global read + transpose write into Bs[buf] in the same call -- B's
    // load happens right here (not deferred to a separate transform
    // step), same structural position vec3 uses, so its latency has the
    // entire upcoming compute loop over the CURRENT tile to be hidden in.
    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual7BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                size_t a_idx = a_row0 + a_kg * ld_a;
                __pipeline_memcpy_async(&stagingWh[mm_fp32_16_dual7_a_idx(buf, a_kk, a_i0)],
                                        &wh[a_idx], sizeof(ushort4));
                __pipeline_memcpy_async(&stagingWr[mm_fp32_16_dual7_a_idx(buf, a_kk, a_i0)],
                                        &wr[a_idx], sizeof(ushort4));
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) As[mm_fp32_16_dual7_a_idx(buf, a_kk, a_i0 + e)] = 0.0f;
            }
        }
        __pipeline_commit();

#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int b_j = b_j_base + v * (kMmFp32_16Dual7NumThreads / (kMmFp32_16Dual7BK / 4));
            size_t b_col = block_col + b_j;
            size_t b_kg0 = k0 + b_kk0_base;
            if (b_col < n && b_kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[b_kg0 + b_col * ld_b]);
                Bs[mm_fp32_16_dual7_bs_idx(buf, b_kk0_base + 0, b_j)] = t.x;
                Bs[mm_fp32_16_dual7_bs_idx(buf, b_kk0_base + 1, b_j)] = t.y;
                Bs[mm_fp32_16_dual7_bs_idx(buf, b_kk0_base + 2, b_j)] = t.z;
                Bs[mm_fp32_16_dual7_bs_idx(buf, b_kk0_base + 3, b_j)] = t.w;
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e)
                    Bs[mm_fp32_16_dual7_bs_idx(buf, b_kk0_base + e, b_j)] = 0.0f;
            }
        }
    };

    // Decodes A's staged raw bytes into As -- B needs no transform step
    // anymore, it's already fully written by load_tile_async above.
    auto transform_tile = [&](int buf, size_t k0) {
#pragma unroll
        for (int v = 0; v < 2; ++v) {
            int a_kk = a_kk_base + v * (kMmFp32_16Dual7BK / 2);
            size_t a_row0 = block_row + a_i0;
            size_t a_kg = k0 + a_kk;
            if (a_row0 < m && a_kg < k) {
                ushort4 wh4 =
                    *reinterpret_cast<const ushort4*>(&stagingWh[mm_fp32_16_dual7_a_idx(buf, a_kk, a_i0)]);
                ushort4 wr4 =
                    *reinterpret_cast<const ushort4*>(&stagingWr[mm_fp32_16_dual7_a_idx(buf, a_kk, a_i0)]);
                As[mm_fp32_16_dual7_a_idx(buf, a_kk, a_i0 + 0)] = fp32_16_combine(wh4.x, wr4.x);
                As[mm_fp32_16_dual7_a_idx(buf, a_kk, a_i0 + 1)] = fp32_16_combine(wh4.y, wr4.y);
                As[mm_fp32_16_dual7_a_idx(buf, a_kk, a_i0 + 2)] = fp32_16_combine(wh4.z, wr4.z);
                As[mm_fp32_16_dual7_a_idx(buf, a_kk, a_i0 + 3)] = fp32_16_combine(wh4.w, wr4.w);
            }
        }
    };

    float acc[kMmFp32_16Dual7TM][kMmFp32_16Dual7TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual7TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual7TN; ++j) acc[i][j] = 0.0f;

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0, 0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16Dual7BK) {
        size_t next_k0 = k0 + kMmFp32_16Dual7BK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16Dual7BK; ++kk) {
            float a_reg[kMmFp32_16Dual7TM];
            float b_reg[kMmFp32_16Dual7TN];
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual7TM / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &As[mm_fp32_16_dual7_a_idx(cur, kk, row_off + v * 4)]);
                a_reg[v * 4 + 0] = t.x;
                a_reg[v * 4 + 1] = t.y;
                a_reg[v * 4 + 2] = t.z;
                a_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int v = 0; v < kMmFp32_16Dual7TN / 4; ++v) {
                float4 t = *reinterpret_cast<const float4*>(
                    &Bs[mm_fp32_16_dual7_bs_idx(cur, kk, col_off + v * 4)]);
                b_reg[v * 4 + 0] = t.x;
                b_reg[v * 4 + 1] = t.y;
                b_reg[v * 4 + 2] = t.z;
                b_reg[v * 4 + 3] = t.w;
            }
#pragma unroll
            for (int i = 0; i < kMmFp32_16Dual7TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16Dual7TN; ++j) acc[i][j] += a_reg[i] * b_reg[j];
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt, next_k0);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16Dual7TM; ++i) {
        size_t row = block_row + row_off + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16Dual7TN; ++j) {
            size_t col = block_col + col_off + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            C[idx] = static_cast<float>(alpha * static_cast<double>(acc[i][j]) +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_tiled_cpasync_dualbuf7(TransposeType transA, TransposeType transB, double alpha,
                                       dim<2> size_A, const uint16_t* wh, const uint16_t* wr,
                                       size_t ld_a, dim<2> size_B, const float* B, size_t ld_b,
                                       double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_accurate(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                            beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    if (ld_a % 4 != 0 || m % 4 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_tiled_cpasync_dualbuf(transA, transB, alpha, size_A, wh, wr, ld_a, size_B, B, ld_b,
                                         beta, C, ld_c);
        return;
    }

    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_tiled_cpasync_dualbuf7_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16Dual7SharedBytes));
        attr_set = true;
    }

    dim3 threads(kMmFp32_16Dual7NumThreads);  // 256, 1D
    dim3 blocks((n + kMmFp32_16Dual7BN - 1) / kMmFp32_16Dual7BN,
               (m + kMmFp32_16Dual7BM - 1) / kMmFp32_16Dual7BM);
    mm_fp32_16_tiled_cpasync_dualbuf7_kernel<<<blocks, threads, kMmFp32_16Dual7SharedBytes>>>(
        alpha, m, k, n, wh, wr, ld_a, B, ld_b, beta, C, ld_c);
}

}  // namespace experimental

// Thin forwarding wrappers -- see the matching banner comment above.
// Same signatures as before this reorganization; no caller (plotted
