    }

    if (i >= rows_op) return;
    double acc_d = static_cast<double>(static_cast<float>(acc));
    y[i] = (beta != 0.0)
              ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
              : static_cast<float>(alpha * acc_d);
}

// Fast-decode sibling of mv_fp32_16_pure_half_tiled_kernel above -- added as a new, separate
// function, original untouched. Identical except its decode calls use
// fp32_16_half_only_fast instead of fp32_16_half_only (saturates
// underflowed control=1 values to signed zero instead of recovering a
// genuine fp16 subnormal -- see fp32_16_half_only_fast's own comment in
// fp32_16_pack.hpp for the accuracy-for-speed trade this makes).
__global__ void mv_fp32_16_pure_half_fast_tiled_kernel(TransposeType trans,
                                                   double alpha, size_t m,
                                                   size_t n,
                                                   const uint16_t* wh,
                                                   size_t ld_a, const float* x,
                                                   double beta, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    __shared__ __half x_tile[kMvTileSize];
    __half acc = static_cast<__half>(0.0f);
    for (size_t tile_start = 0; tile_start < cols_op;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              cols_op - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_fast(wh[idx]);
                acc = acc + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i >= rows_op) return;
    double acc_d = static_cast<double>(static_cast<float>(acc));
    y[i] = (beta != 0.0)
              ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
              : static_cast<float>(alpha * acc_d);
}

// Used for NARROW matrices once cols_op reaches kMvNarrowVecColThreshold --
// see that constant's comment for the crossover this was benchmarked
// against. Each thread handles kMvRowsPerThread output rows instead of 1
// (see that constant's comment for why). For NO_TRANSPOSE, those rows are
// contiguous in memory (idx = i + j*ld_a, column-major), so they're read
// with a single 64-bit ushort4 load instead of 4 separate 16-bit loads --
// a real reduction in memory-instruction count, unlike an earlier version
// of this kernel that only vectorized the FMA (__half2) without reducing
// load count, which left a substantial gap against cuBLAS's own vectorized
// path (cublasHgemm(n=1)) at cols_op past ~256 (measured ~0.7-0.8x there).
// x is read directly (relying on the read-only cache, not staged through
// shared memory): a plain-vs-shared-mem-tiled A/B test found tiling's
// __syncthreads() overhead wasn't paying for itself once cols_op is large
// enough to matter (a wash to slightly negative), so this drops that
// machinery entirely for a simpler kernel. For TRANSPOSE, the rows are NOT
// contiguous (idx = j + i*ld_a, so consecutive rows are ld_a apart), so the
// vectorized load isn't available there -- the "vectorized" flag below
// picks a per-element scalar fallback in that case, and also for a
// thread's trailing partial row group at the end of rows_op.
__global__ void mv_fp32_16_pure_half_narrow_vec_kernel(TransposeType trans,
                                                        double alpha,
                                                        size_t m, size_t n,
                                                        const uint16_t* wh,
                                                        size_t ld_a,
                                                        const float* __restrict__ x,
                                                        double beta,
                                                        float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    // The vectorized load also requires ld_a to be a multiple of
    // kMvRowsPerThread: base = i0 + j*ld_a must stay 8-byte-aligned for
    // every j, and i0 alone (a multiple of kMvRowsPerThread by
    // construction) only guarantees that for j==0 unless ld_a is too.
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t j = 0; j < cols_op; ++j) {
        __half x_val = static_cast<__half>(__ldg(&x[j]));
        if (vectorized) {
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 = acc0 + fp32_16_half_only_branchless_no_overflow_nomask(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only_branchless_no_overflow_nomask(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only_branchless_no_overflow_nomask(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only_branchless_no_overflow_nomask(raw.w) * x_val;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        double acc_d = static_cast<double>(static_cast<float>(acc[k]));
        y[i] = (beta != 0.0)
                  ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                  : static_cast<float>(alpha * acc_d);
    }
}

// Fast2-decode sibling of mv_fp32_16_pure_half_narrow_vec_kernel above -- added as a new,
// separate function, original untouched. Identical except its
