// cp.async sibling of mv_fp32_16_pure_half_fast2_narrow_vec_kernel above
// -- mechanical duplicate, added as a new, separate function, original
// untouched. fp32_16_half_only_fast2 (bit-exact, branch-reduced decode)
// alone was confirmed, via a real per-call LSQR timing breakdown
// (TOMOS_LSQR_TIMING=1) on the real LSQR matrix (M=1,000,000, K=1000,
// where this kernel is what mv_fp32_16_pure_half_no_transpose_fast2
// actually dispatches to), to make NO measurable difference over the
// safe decode -- two independent, reproducible runs, not noise (see
// this session's own investigation). That result means this kernel
// isn't ALU/decode-bound; it's the OTHER proven lever (cp.async
// prefetch, which this kernel -- unlike cpasync_warpuniform's own wide/
// col-split tier -- has never had) that's actually untested here.
// Doubles-buffers each thread's own next-column wh ushort4 read (8
// bytes, 4 rows) into a private (not cross-thread-shared -- every
// thread owns its own disjoint i0..i0+3 row group) shared-memory
// staging slot while decoding the current column, same technique as
// mv_fp32_16_accurate_narrow_vec_cpasync_kernel's own (this file, much
// earlier) -- only applied to the "vectorized" (aligned, NO_TRANSPOSE)
// path; the scalar fallback (TRANSPOSE, or a trailing partial row
// group) is untouched, same reasoning as every other cp.async kernel in
// this file.
__global__ void mv_fp32_16_pure_half_fast2_narrow_vec_cpasync_kernel(TransposeType trans,
                                                        double alpha,
                                                        size_t m, size_t n,
                                                        const uint16_t* wh,
                                                        size_t ld_a,
                                                        const float* __restrict__ x,
                                                        double beta,
                                                        float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);

    if (!vectorized) {
        for (size_t j = 0; j < cols_op; ++j) {
            __half x_val = static_cast<__half>(__ldg(&x[j]));
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    } else {
        __shared__ ushort4 stageWh[2][kMvTileSize];
        const int tid = threadIdx.x;

        if (cols_op > 0) {
            __pipeline_memcpy_async(&stageWh[0][tid], &wh[i0], sizeof(ushort4));
            __pipeline_commit();
            __pipeline_wait_prior(0);
        }

        int cur = 0;
        for (size_t j = 0; j < cols_op; ++j) {
            size_t next_j = j + 1;
            int nxt = cur ^ 1;
            if (next_j < cols_op) {
                size_t base = i0 + next_j * ld_a;
                __pipeline_memcpy_async(&stageWh[nxt][tid], &wh[base], sizeof(ushort4));
                __pipeline_commit();
            }

            __half x_val = static_cast<__half>(__ldg(&x[j]));
            ushort4 raw = stageWh[cur][tid];
            acc0 = acc0 + fp32_16_half_only_branchless_no_overflow_nomask(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only_branchless_no_overflow_nomask(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only_branchless_no_overflow_nomask(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only_branchless_no_overflow_nomask(raw.w) * x_val;

            if (next_j < cols_op) __pipeline_wait_prior(0);
            cur = nxt;
        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        double acc_d = static_cast<double>(static_cast<float>(acc[k]));
        y[i] = (beta != 0.0)
                  ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                  : static_cast<float>(alpha * acc_d);
    }
}

// Host wrapper for the cp.async kernel above -- mirrors mv_fp32_16_pure_
// half_fast2_wide_ilp_shared_half2_atomic_wide4x's own final "else"
// branch exactly (same grid/block calc), just launching the cp.async
// kernel instead of the plain fast2_narrow_vec_kernel.
void mv_fp32_16_pure_half_fast2_narrow_vec_cpasync(TransposeType trans, double alpha, size_t m, size_t n,
                                                     const uint16_t* wh, size_t ld_a, const float* x, double beta,
                                                     float* y) {
    int threads = kMvTileSize;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
    int blocks = static_cast<int>((row_groups + threads - 1) / threads);
    mv_fp32_16_pure_half_fast2_narrow_vec_cpasync_kernel<<<blocks, threads>>>(trans, alpha, m, n, wh, ld_a, x, beta,
                                                                               y);
}

// Fast-decode sibling of mv_fp32_16_pure_half_narrow_vec_kernel above -- added as a new, separate
// function, original untouched. Identical except its decode calls use
// fp32_16_half_only_fast instead of fp32_16_half_only (saturates
// underflowed control=1 values to signed zero instead of recovering a
// genuine fp16 subnormal -- see fp32_16_half_only_fast's own comment in
// fp32_16_pack.hpp for the accuracy-for-speed trade this makes).
__global__ void mv_fp32_16_pure_half_fast_narrow_vec_kernel(TransposeType trans,
                                                        double alpha,
                                                        size_t m, size_t n,
                                                        const uint16_t* wh,
                                                        size_t ld_a,
                                                        const float* __restrict__ x,
                                                        double beta,
                                                        float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    // The vectorized load also requires ld_a to be a multiple of
    // kMvRowsPerThread: base = i0 + j*ld_a must stay 8-byte-aligned for
    // every j, and i0 alone (a multiple of kMvRowsPerThread by
    // construction) only guarantees that for j==0 unless ld_a is too.
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t j = 0; j < cols_op; ++j) {
        __half x_val = static_cast<__half>(__ldg(&x[j]));
        if (vectorized) {
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 = acc0 + fp32_16_half_only_fast(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only_fast(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only_fast(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only_fast(raw.w) * x_val;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_fast(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        double acc_d = static_cast<double>(static_cast<float>(acc[k]));
        y[i] = (beta != 0.0)
                  ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                  : static_cast<float>(alpha * acc_d);
    }
}

// For WIDE matrices (few rows, many columns) only -- see mv_fp32_16_accurate_
// wide_kernel: same coalesced row-tile / column-split layout. Each split's
// own reduction still happens entirely in __half (genuine fp16-only
// compute, matching mv_fp32_16_pure_half_tiled_kernel) -- only once that
// split's column range is fully reduced is the result widened to double
// for the partial buffer, same as the non-wide kernel's final store.
__global__ void mv_fp32_16_pure_half_wide_kernel(TransposeType trans,
                                                    size_t m, size_t n,
                                                    const uint16_t* wh,
                                                    size_t ld_a,
                                                    const float* x,
                                                    size_t col_splits,
                                                    double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __half acc = static_cast<__half>(0.0f);
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                acc = acc + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i < rows_op)
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
}

void mv_fp32_16_pure_half(TransposeType trans, double alpha, dim<2> size,
                          const uint16_t* wh, size_t ld_a, const float* x,
                          size_t ld_x, double beta, float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        // rows_op alone can't reach kMvTargetTotalThreads threads here --
        // whether because the matrix is genuinely wide (few rows) or just
        // moderately sized (e.g. a square matrix well under that target) --
        // so split-K.
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        // Narrow matrix, few columns (see kMvNarrowVecColThreshold's comment).
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        // Narrow matrix with enough columns for the register-blocked
        // variant (see kMvNarrowVecColThreshold): kMvRowsPerThread output
        // rows/thread, so the thread/block count is divided accordingly.
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel's wide-matrix
// path -- see mv_fp32_16_accurate_wide_regblock_kernel for the full design
// rationale and the earlier attempt's regression this is meant to avoid
// (col_splits here is deliberately NOT recomputed from the register-blocked
// thread count). Same register-blocked (kMvRowsPerThread rows/thread,
// vectorized ushort4 load when eligible) row layout as
// mv_fp32_16_pure_half_narrow_vec_kernel; each row's reduction happens
// entirely in __half, widened to double only for the partial buffer.
__global__ void mv_fp32_16_pure_half_wide_regblock_kernel(TransposeType trans,
                                                          size_t m, size_t n,
                                                          const uint16_t* wh,
                                                          size_t ld_a,
                                                          const float* __restrict__ x,
                                                          size_t col_splits,
                                                          double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t j = col_start; j < col_end; ++j) {
        __half x_val = static_cast<__half>(__ldg(&x[j]));
        if (vectorized) {
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 = acc0 + fp32_16_half_only_branchless_no_overflow_nomask(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only_branchless_no_overflow_nomask(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only_branchless_no_overflow_nomask(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only_branchless_no_overflow_nomask(raw.w) * x_val;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc[k]));
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_accurate_wide_regblock's comment (identical structure,
// applied to the pure_half tier). Narrow/tiled branches unchanged from
// mv_fp32_16_pure_half.
void mv_fp32_16_pure_half_wide_regblock(TransposeType trans, double alpha,
                                        dim<2> size, const uint16_t* wh,
                                        size_t ld_a, const float* x,
                                        size_t ld_x, double beta, float* y,
                                        size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int row_blocks = static_cast<int>((row_groups + kMvTileSize - 1) / kMvTileSize);
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_regblock_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// DIAGNOSTIC, not a performance variant: identical to mv_fp32_16_pure_half's
// wide-matrix branch -- same kernels (mv_fp32_16_pure_half_wide_kernel,
// mv_fp32_16_wide_reduce_kernel), same col_splits/row_blocks -- but with a
// cudaEvent_t placed between the two kernel launches so their costs can be
// measured separately instead of only as one combined mv_fp32_16_pure_half
// call. Exists to answer a question raised by mv_fp32_16_pure_half_wide_
// regblock's two failed attempts: independent of any register-blocking
// change, how much of the *already-shipping* ~70%-of-cuBLAS wide-matrix
// path's time is the main split-K kernel vs. the reduce kernel's serial,
// rows_op-strided summation over col_splits partials? If the reduce step
// turns out to be a large fraction, that -- not register-blocking the main
// kernel -- would be the more promising thing to optimize next. Only valid
// for rows_op < kMvWideRowThreshold (the wide-matrix branch); for other
// shapes this just calls mv_fp32_16_pure_half and reports zeroed timings,
// so it's still safe to call unconditionally from a benchmark sweep.
void mv_fp32_16_pure_half_wide_diag(TransposeType trans, double alpha,
                                    dim<2> size, const uint16_t* wh,
                                    size_t ld_a, const float* x, size_t ld_x,
                                    double beta, float* y, size_t ld_y,
                                    float* main_kernel_ms,
                                    float* reduce_kernel_ms) {
    *main_kernel_ms = 0.0f;
    *reduce_kernel_ms = 0.0f;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op >= kMvWideRowThreshold) {
        mv_fp32_16_pure_half(trans, alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
        return;
    }

    int col_splits = choose_col_splits(rows_op, cols_op);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    double* partial = nullptr;
    cudaError_t err = cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
    if (err != cudaSuccess) {
        cudaGetLastError();
        return;
    }

    cudaEvent_t e_start, e_mid, e_end;
    cudaEventCreate(&e_start);
    cudaEventCreate(&e_mid);
    cudaEventCreate(&e_end);

    dim3 grid(row_blocks, col_splits);
    cudaEventRecord(e_start);
    mv_fp32_16_pure_half_wide_kernel<<<grid, kMvTileSize>>>(
        trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
    cudaEventRecord(e_mid);
    int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
        alpha, beta, rows_op, col_splits, partial, y);
    cudaEventRecord(e_end);
    cudaEventSynchronize(e_end);
    cudaEventElapsedTime(main_kernel_ms, e_start, e_mid);
    cudaEventElapsedTime(reduce_kernel_ms, e_mid, e_end);

    cudaEventDestroy(e_start);
    cudaEventDestroy(e_mid);
    cudaEventDestroy(e_end);
    cudaFree(partial);
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel, informed by
// ncu profiling of the WORKING baseline at 32768x32768 (Warp State
// Statistics: ~71.5% of stall cycles are "stalled waiting for a scoreboard
// dependency on an L1TEX operation" -- each thread issues a load for
// wh[idx], then immediately blocks on it with no independent work to
// overlap the wait; DRAM throughput was only 59.5% of peak and achieved
// occupancy 53%, so this is a latency problem, not primarily a bandwidth or
// occupancy one). Unlike mv_fp32_16_pure_half_wide_regblock (which changed
// the grid/block configuration and regressed for reasons distinct from
// this), this kernel keeps the EXACT same one-thread-per-row grid as the
// baseline -- only the column loop is unrolled 4-wide with 4 independent
// __half accumulators, each following its own column j, so their wh[idx]
// loads can be in flight simultaneously instead of one at a time (x is
// read directly via __ldg rather than shared-memory-tiled, matching
// mv_fp32_16_pure_half_narrow_vec_kernel's approach, to keep the loop body
// simple).
__global__ void mv_fp32_16_pure_half_wide_ilp_kernel(TransposeType trans,
                                                     size_t m, size_t n,
                                                     const uint16_t* wh,
                                                     size_t ld_a,
                                                     const float* __restrict__ x,
                                                     size_t col_splits,
                                                     double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    if (i < rows_op) {
        size_t j = col_start;
        for (; j + 4 <= col_end; j += 4) {
            size_t j0 = j, j1 = j + 1, j2 = j + 2, j3 = j + 3;
            size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
            size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
            size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
            size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
            size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
            size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
            size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
            size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
            size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
            size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
            __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
            __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
            __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
            __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
            __half x0 = static_cast<__half>(__ldg(&x[j0]));
            __half x1 = static_cast<__half>(__ldg(&x[j1]));
            __half x2 = static_cast<__half>(__ldg(&x[j2]));
            __half x3 = static_cast<__half>(__ldg(&x[j3]));
            acc0 = acc0 + a0 * x0;
            acc1 = acc1 + a1 * x1;
            acc2 = acc2 + a2 * x2;
            acc3 = acc3 + a3 * x3;
        }
        for (; j < col_end; ++j) {
            size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
            size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
            size_t idx = a_row + a_col * ld_a;
            __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
            __half x_val = static_cast<__half>(__ldg(&x[j]));
            acc0 = acc0 + a_val * x_val;
        }
    }

    if (i < rows_op) {
        __half acc = (acc0 + acc1) + (acc2 + acc3);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_ilp_kernel's comment. Unlike
// mv_fp32_16_pure_half_wide_regblock, this keeps the EXACT same grid/block
// configuration as mv_fp32_16_pure_half's wide-matrix branch (same
// choose_col_splits(rows_op, cols_op) call, same row_blocks formula) --
// only the main kernel's column-loop unrolling differs. Narrow/tiled
// branches are unchanged from mv_fp32_16_pure_half.
void mv_fp32_16_pure_half_wide_ilp(TransposeType trans, double alpha,
                                   dim<2> size, const uint16_t* wh,
                                   size_t ld_a, const float* x, size_t ld_x,
                                   double beta, float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel: IDENTICAL
// body (same shared-memory x tiling, same single __half accumulator, same
// grid/block configuration) -- the only difference is the
// __launch_bounds__(kMvTileSize, 8) attribute, which asks the compiler to
// keep register usage low enough for 8 resident blocks/SM instead of
// whatever it naturally settles on.
//
// Motivated directly by ncu profiling of the baseline at 32768x32768:
// "Block Limit Registers: 6" was the *tightest* of the occupancy
// constraints there (tighter than the shared-memory or warp-count limits),
// at 38 registers/thread -- and the profiler's own note flagged this
// explicitly ("theoretical occupancy (75.0%) is limited by the number of
// required registers... Est. Speedup: 25%"). mv_fp32_16_pure_half_wide_ilp
// tried to fix the *other* diagnosed problem (L1TEX load-latency stalls)
// by adding more independent accumulators, but that almost certainly
// increased register pressure further and made the already-binding
// register constraint worse, netting out slower despite better ILP. This
// variant tests the opposite direction directly: force lower register
// usage (accepting local-memory spilling if the compiler can't otherwise
// get there) to raise occupancy, with no other change to the kernel at
// all, to see if occupancy -- not ILP -- is the more effective lever here.
__global__ void __launch_bounds__(kMvTileSize, 8)
mv_fp32_16_pure_half_wide_launchbounds_kernel(TransposeType trans, size_t m,
                                              size_t n, const uint16_t* wh,
                                              size_t ld_a, const float* x,
                                              size_t col_splits,
                                              double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __half acc = static_cast<__half>(0.0f);
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                acc = acc + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i < rows_op)
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
}

