// EXPERIMENTAL alternative wide-matrix kernel, structurally different from
// every earlier attempt here rather than a re-tuned variant of the same
// split-K design. Assigns one full WARP (32 lanes) to each group of
// kMvRowsPerThread consecutive rows, instead of one thread per row
// (baseline) or one thread per row-group (mv_fp32_16_pure_half_wide_
// regblock, which regressed). Each lane strides across a slice of cols_op
// (lane l takes columns l, l+32, l+64, ...), using the same vectorized
// ushort4 load across the row-group at each column when eligible (wider
// memory transactions, targeting the ~60%-vs-~94%-of-peak-DRAM-bandwidth
// gap ncu measured between the baseline and cuBLAS at 32768x32768), then a
// __shfl_down_sync warp reduction combines the 32 lanes' partial sums per
// row directly in registers.
//
// Deliberately has NO col_splits, no partial buffer, and no separate
// reduce kernel at all -- every earlier split-K-based variant here
// (mv_fp32_16_pure_half_wide_regblock, _ilp, _launchbounds) paid for that
// machinery's overhead or grid-sizing side effects in some form and none
// of them beat the baseline. Parallelism instead comes from spreading each
// row-group's reduction across a full warp (32-wide) rather than from
// column-splitting across the grid, and the reduction is a handful of
// register-to-register shuffles instead of a global-memory round trip.
__global__ void mv_fp32_16_pure_half_wide_warpgroup_kernel(
    TransposeType trans, double alpha, size_t m, size_t n,
    const uint16_t* wh, size_t ld_a, const float* __restrict__ x,
    double beta, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;

    size_t warp_id = (blockIdx.x * blockDim.x + threadIdx.x) / 32;
    int lane = threadIdx.x % 32;
    size_t i0 = warp_id * static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    if (vectorized) {
        for (size_t j = lane; j < cols_op; j += 32) {
            __half x_val = static_cast<__half>(__ldg(&x[j]));
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 = acc0 + fp32_16_half_only_branchless_no_overflow_nomask(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only_branchless_no_overflow_nomask(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only_branchless_no_overflow_nomask(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only_branchless_no_overflow_nomask(raw.w) * x_val;
        }
    } else {
        for (size_t j = lane; j < cols_op; j += 32) {
            __half x_val = static_cast<__half>(__ldg(&x[j]));
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    }

    // Warp-level reduction, one accumulator at a time, via bit
    // reinterpretation (__half_as_ushort/__ushort_as_half, not a
    // memcpy-based reinterpretation -- see mv_fp32_16_pure_half_narrow_
    // vec_kernel's comment on why that specific pattern is required for
    // correctness on sm_80).
#pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        unsigned b0 = __shfl_down_sync(
            0xFFFFFFFF, static_cast<unsigned>(__half_as_ushort(acc0)), offset);
        unsigned b1 = __shfl_down_sync(
            0xFFFFFFFF, static_cast<unsigned>(__half_as_ushort(acc1)), offset);
        unsigned b2 = __shfl_down_sync(
            0xFFFFFFFF, static_cast<unsigned>(__half_as_ushort(acc2)), offset);
        unsigned b3 = __shfl_down_sync(
            0xFFFFFFFF, static_cast<unsigned>(__half_as_ushort(acc3)), offset);
        acc0 = acc0 + __ushort_as_half(static_cast<unsigned short>(b0));
        acc1 = acc1 + __ushort_as_half(static_cast<unsigned short>(b1));
        acc2 = acc2 + __ushort_as_half(static_cast<unsigned short>(b2));
        acc3 = acc3 + __ushort_as_half(static_cast<unsigned short>(b3));
    }

    if (lane == 0) {
        __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
        for (int k = 0; k < kMvRowsPerThread; ++k) {
            size_t i = i0 + static_cast<size_t>(k);
            if (i >= rows_op) break;
            double acc_d = static_cast<double>(static_cast<float>(acc[k]));
            y[i] = (beta != 0.0)
                      ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                      : static_cast<float>(alpha * acc_d);
        }
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_warpgroup_kernel's comment. Only the
// wide-matrix branch differs (a single self-contained kernel launch, no
// col_splits/partial buffer/reduce kernel); narrow/tiled branches are
// unchanged from mv_fp32_16_pure_half.
void mv_fp32_16_pure_half_wide_warpgroup(TransposeType trans, double alpha,
                                         dim<2> size, const uint16_t* wh,
                                         size_t ld_a, const float* x,
                                         size_t ld_x, double beta, float* y,
                                         size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int threads = kMvTileSize;
        int warps_per_block = threads / 32;
        int blocks =
            static_cast<int>((row_groups + warps_per_block - 1) / warps_per_block);
        mv_fp32_16_pure_half_wide_warpgroup_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel: narrowly
// isolates one variable that mv_fp32_16_pure_half_wide_ilp changed
// alongside its 4-way column unrolling -- x's shared-memory tiling.
// mv_fp32_16_pure_half_wide_ilp dropped the baseline's shared-memory x
// tile in favor of direct __ldg reads (matching mv_fp32_16_pure_half_
// narrow_vec_kernel's approach) while ALSO adding 4 independent
// accumulators; it measured worse than the baseline (0.55 vs 0.71 of
// cuBLAS at 32768x32768) despite the added ILP, which is a hint that
// removing the shared-memory tiling cost more than the unrolling gained.
// This kernel is otherwise IDENTICAL to mv_fp32_16_pure_half_wide_ilp_
// kernel (same grid/col_splits, same 4 independent accumulators, same
// column-loop unrolling) but keeps the baseline's cooperative shared-
// memory x_tile instead of direct __ldg reads, to test that hint in
// isolation rather than as a confounded combination of two changes at
// once.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh,
    size_t ld_a, const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                acc0 = acc0 + a0 * x_tile[jj];
                acc1 = acc1 + a1 * x_tile[jj + 1];
                acc2 = acc2 + a2 * x_tile[jj + 2];
                acc3 = acc3 + a3 * x_tile[jj + 3];
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                acc0 = acc0 + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half acc = (acc0 + acc1) + (acc2 + acc3);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_ilp_shared_kernel's comment. IDENTICAL grid/
// col_splits to the baseline (and to mv_fp32_16_pure_half_wide_ilp); only
// the main kernel differs. Narrow/tiled branches unchanged.
void mv_fp32_16_pure_half_wide_ilp_shared(TransposeType trans, double alpha,
                                          dim<2> size, const uint16_t* wh,
                                          size_t ld_a, const float* x,
                                          size_t ld_x, double beta, float* y,
                                          size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel: IDENTICAL to
// mv_fp32_16_pure_half_wide_ilp_shared_kernel (same grid/col_splits, same
// 4-way unroll with 4 named accumulators, same shared-memory x_tile) except
// wh and x are marked __restrict__ and every wh load goes through __ldg(),
// routing it through the read-only data cache explicitly instead of relying
// on the compiler to infer no-aliasing on its own. None of the earlier
// variants tried this: mv_fp32_16_pure_half_wide_ilp used __ldg only for x
// (while dropping x's shared-memory tiling, which is what actually cost it
// the regression -- see its comment), never for wh, and ilp_shared/ilp8_
// shared/ilp2_shared all read wh via plain indexing throughout. Since ncu
// profiling of this whole kernel family's bottleneck is consistently a
// scoreboard stall waiting on an L1TEX result for wh's read (not x's), this
// isolates whether routing that specific read through the read-only cache
// closes any more of the remaining gap to cuBLAS, on top of the already-
// proven 4-way-unroll-plus-shared-tiling win (0.71 -> 0.83 of cuBLAS at
// 32768x32768).
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_ldg_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* __restrict__ wh,
    size_t ld_a, const float* __restrict__ x, size_t col_splits,
    double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(__ldg(&wh[idx0]));
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(__ldg(&wh[idx1]));
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(__ldg(&wh[idx2]));
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(__ldg(&wh[idx3]));
                acc0 = acc0 + a0 * x_tile[jj];
                acc1 = acc1 + a1 * x_tile[jj + 1];
                acc2 = acc2 + a2 * x_tile[jj + 2];
                acc3 = acc3 + a3 * x_tile[jj + 3];
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(__ldg(&wh[idx]));
                acc0 = acc0 + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half acc = (acc0 + acc1) + (acc2 + acc3);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_ilp_shared_ldg_kernel's comment. IDENTICAL
// grid/col_splits to mv_fp32_16_pure_half_wide_ilp_shared; only the main
// kernel differs (wh/x marked __restrict__, wh read via __ldg()). Narrow/
// tiled branches unchanged.
void mv_fp32_16_pure_half_wide_ilp_shared_ldg(TransposeType trans,
                                              double alpha, dim<2> size,
                                              const uint16_t* wh, size_t ld_a,
                                              const float* x, size_t ld_x,
                                              double beta, float* y,
                                              size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_ldg_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel: a different
// lever than any of the unroll-width variants above. mv_fp32_16_pure_half_
// wide_ilp_shared_kernel's 4-way unroll already lets the 4 wh loads within
// ONE group overlap each other (that's the source of its 0.71 -> 0.83 win);
// 8-way unrolling then regressed to 0.74, most likely because doubling the
// accumulator count (acc0..acc7, each its own independent dependency chain)
// raised register pressure without deepening the memory-level-parallelism
// window enough to pay for it. This kernel instead keeps exactly 4 named
// accumulators (the proven-best width) but software-pipelines the loads:
// each iteration issues the loads for the NEXT group of 4 columns before
// consuming the CURRENT group's already-loaded values in the accumulation.
// This deepens the number of outstanding wh loads from 4 to up to 8 without
// widening any accumulator chain, targeting the same L1TEX-scoreboard stall
// ncu profiling identified as the dominant cost throughout this
// investigation, via a mechanism distinct from unroll width, occupancy
// tuning, or the (regressive) __ldg/read-only-cache attempt in mv_fp32_16_
// pure_half_wide_ilp_shared_ldg_kernel above.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_prefetch_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            bool have_cur = (jj + 4 <= tile_len);
            __half a0 = static_cast<__half>(0.0f), a1 = static_cast<__half>(0.0f);
            __half a2 = static_cast<__half>(0.0f), a3 = static_cast<__half>(0.0f);
            if (have_cur) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
            }
            while (have_cur) {
                size_t cur_jj = jj;
                size_t next_jj = jj + 4;
                bool have_next = (next_jj + 4 <= tile_len);
                __half b0 = static_cast<__half>(0.0f), b1 = static_cast<__half>(0.0f);
                __half b2 = static_cast<__half>(0.0f), b3 = static_cast<__half>(0.0f);
                if (have_next) {
                    size_t j0 = tile_start + next_jj, j1 = j0 + 1, j2 = j0 + 2,
                          j3 = j0 + 3;
                    size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                    size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                    size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                    size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                    size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                    size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                    size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                    size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                    size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                    size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                    b0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                    b1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                    b2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                    b3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                }

                acc0 = acc0 + a0 * x_tile[cur_jj];
                acc1 = acc1 + a1 * x_tile[cur_jj + 1];
                acc2 = acc2 + a2 * x_tile[cur_jj + 2];
                acc3 = acc3 + a3 * x_tile[cur_jj + 3];

                a0 = b0; a1 = b1; a2 = b2; a3 = b3;
                have_cur = have_next;
                jj = next_jj;
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                acc0 = acc0 + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half acc = (acc0 + acc1) + (acc2 + acc3);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_ilp_shared_prefetch_kernel's comment.
// IDENTICAL grid/col_splits to mv_fp32_16_pure_half_wide_ilp_shared; only
// the main kernel differs (software-pipelined loads). Narrow/tiled branches
