}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel: tests
// whether fp32_16_half_only's branch instruction itself (not the logic it
// guards) was the cost mv_fp32_16_pure_half_wide_ilp_shared_fasthalf
// measured a speedup from -- unlike that kernel (which is CONFIRMED unsafe
// and fails correctness checks, since fp32_16_fast_half skips the control=1
// saturation logic entirely), this kernel computes the EXACT same result
// as fp32_16_half_only for every input via fp32_16_half_only_branchless
// (see its comment above, near the top of this file), which does the same
// work through unconditional bitwise masks instead of an if/else chain.
// IDENTICAL to mv_fp32_16_pure_half_wide_ilp_shared_kernel (same grid/
// col_splits, same 4-way unroll, same shared-memory x_tile) except every
// fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]) call is replaced with
// fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]). Expected to be fully correct
// (bit-exact match to fp32_16_half_only, not merely "safe for this
// benchmark's data" the way fasthalf was wrongly assumed to be); the open
// question is whether it recovers any of fasthalf's measured 0.83 -> 0.88
// gain now that the correctness-losing shortcut has been removed.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_branchless_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                acc0 = acc0 + a0 * x_tile[jj];
                acc1 = acc1 + a1 * x_tile[jj + 1];
                acc2 = acc2 + a2 * x_tile[jj + 2];
                acc3 = acc3 + a3 * x_tile[jj + 3];
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                acc0 = acc0 + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half acc = (acc0 + acc1) + (acc2 + acc3);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_ilp_shared_branchless_kernel's comment.
// IDENTICAL grid/col_splits to mv_fp32_16_pure_half_wide_ilp_shared; only
// the main kernel's decode call differs. Narrow/tiled branches unchanged
// (still use fp32_16_half_only via the pre-existing kernels).
void mv_fp32_16_pure_half_wide_ilp_shared_branchless(TransposeType trans,
                                                     double alpha, dim<2> size,
                                                     const uint16_t* wh,
                                                     size_t ld_a,
                                                     const float* x,
                                                     size_t ld_x, double beta,
                                                     float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_branchless_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// Returns the number of doubles mv_fp32_16_pure_half_wide_ilp_shared_
// branchless_workspace's wide (split-K) path needs -- same formula/
// contract as mv_fp32_16_pure_half_wide_ilp_shared_fasthalf_workspace_
// size above (0 for shapes that don't dispatch to the wide path).
size_t mv_fp32_16_pure_half_wide_ilp_shared_branchless_workspace_size(TransposeType trans, dim<2> size) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op >= kMvWideRowThreshold) return 0;
    int col_splits = choose_col_splits(rows_op, cols_op);
    return rows_op * static_cast<size_t>(col_splits);
}

// Workspace-buffered sibling of mv_fp32_16_pure_half_wide_ilp_shared_
// branchless above -- same "caller-owned scratch buffer instead of
// per-call cudaMalloc/cudaFree" fix as mv_fp32_16_pure_half_wide_ilp_
// shared_fasthalf_workspace (see that function's own comment for the full
// rationale). Built to answer the "test" question mv_fp32_16_pure_half_
// wide_ilp_shared_branchless_kernel's own comment poses (whether removing
// fp32_16_half_only's branch, while keeping its exact semantics via
// fp32_16_half_only_branchless, recovers any of fasthalf's own measured
// gain) on a fair, malloc/free-overhead-free footing -- the plain
// function above would otherwise confound "branchless vs branching
// decode" with the SAME per-call allocator overhead mv_fp32_16_pure_
// half_wide_ilp_shared_fasthalf_workspace's own comment diagnoses.
// Contract: workspace must be a device buffer of at least mv_fp32_16_
// pure_half_wide_ilp_shared_branchless_workspace_size(trans, size)
// doubles; may be nullptr for shapes that don't reach the wide path.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_pure_half_wide_ilp_shared_branchless_workspace(TransposeType trans,
                                                                double alpha, dim<2> size,
                                                                const uint16_t* wh,
                                                                size_t ld_a, const float* x,
                                                                size_t ld_x, double beta,
                                                                float* y, size_t ld_y,
                                                                double* workspace) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_branchless_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, workspace);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, workspace, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel: uses
// Ampere's cp.async (via __pipeline_memcpy_async) to stage wh into shared
// memory, bypassing the register file entirely for the copy -- a
// fundamentally different mechanism from every _wide_* variant above
// (including ilp_shared_prefetch, which reordered ORDINARY register-
// mediated loads but still had every value pass through a register).
// cp.async lets the async-copy engine move bytes directly from global to
// shared memory, freeing the SM to do other work while the copy is in
// flight and issuing many outstanding requests without register pressure
// -- a different way of overlapping compute with the same L1TEX latency
// ncu identified as the dominant stall reason throughout this
// investigation.
//
// cp.async requires a CONTIGUOUS global source range per call (>=4 bytes),
// which rules out staging the column-unrolled access pattern directly (4
// different columns for one row are ld_a elements apart, not contiguous --
// the same reason a "vectorized ushort4 load" couldn't apply there
// either). The one axis that IS contiguous in this column-major layout
// (idx = row + col*ld_a) is ROWS for a fixed column -- exactly what
// mv_fp32_16_pure_half_wide_regblock's register-blocking used, but that
// approach failed for an unrelated reason (col_splits/occupancy mismatch
// from reducing thread count). This kernel avoids that pitfall entirely:
// blockDim.x stays kMvTileSize (256, matching every baseline/experimental
// grid), and instead of each thread owning multiple rows, the WHOLE BLOCK
// cooperatively async-copies a 2D [kMvCpAsyncStageWidth columns x
// kMvTileSize rows] tile of wh into shared memory per stage (each block's
// kMvTileSize consecutive rows are one contiguous global run per column),
// using 4-byte (2-row) cp.async transfers issued by half the block's
// threads (threadIdx.x % 2 == 0) to keep every transfer's source range
// contiguous and correctly sized. Only NO_TRANSPOSE is implemented this
// way (matching every benchmarked shape); TRANSPOSE falls back to the
// already-proven mv_fp32_16_pure_half_wide_ilp_shared. Single-buffered
// (stage a chunk, wait for it, compute, then stage the next) rather than
// double-buffered/pipelined -- this tests whether cp.async's register-
// bypassing copy mechanism helps at all before adding pipelining depth on
// top of it.
//
// ALIGNMENT CAVEAT: each cp.async transfer moves 4 bytes (kMvCpAsyncRowChunk
// = 2 uint16_t), which requires the global source address (row_start +
// threadIdx.x + col*ld_a, in elements) to be EVEN -- true whenever ld_a is
// even, since row_start (a multiple of kMvTileSize=256) and threadIdx.x
// (even, by construction: only threadIdx.x % 2 == 0 threads issue) are
// always even regardless of col. Every shape this investigation has
// benchmarked uses ld_a = a power-of-two dimension (e.g. 32768), so this
// holds here, but it is NOT a general-purpose guarantee for arbitrary
// odd ld_a -- unlike mv_fp32_16_pure_half_wide_ilp_shared_fasthalf's
// caveat (a silent wrong-answer risk), a misaligned cp.async source here
// would be a hardware/PTX-level violation, not merely an accuracy issue.
static constexpr int kMvCpAsyncStageWidth = 64;
static constexpr int kMvCpAsyncRowChunk = 2;

__global__ void mv_fp32_16_pure_half_wide_ilp_shared_cpasync_kernel(
    size_t m, size_t n, const uint16_t* wh, size_t ld_a, const float* x,
    size_t col_splits, double* partial) {
    size_t rows_op = m;
    size_t cols_op = n;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    size_t row_start = static_cast<size_t>(blockIdx.x) * blockDim.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __shared__ uint16_t wh_tile[kMvCpAsyncStageWidth][kMvTileSize];
    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);

    bool full_row_chunk =
        (row_start + static_cast<size_t>(threadIdx.x) +
             static_cast<size_t>(kMvCpAsyncRowChunk) <=
         rows_op);

    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        for (size_t stage_start = 0; stage_start < tile_len;
             stage_start += kMvCpAsyncStageWidth) {
            size_t stage_len = min(static_cast<size_t>(kMvCpAsyncStageWidth),
                                   tile_len - stage_start);

            if (threadIdx.x % kMvCpAsyncRowChunk == 0) {
                if (full_row_chunk) {
                    for (size_t c = 0; c < stage_len; ++c) {
                        size_t col = tile_start + stage_start + c;
                        const uint16_t* src =
                            &wh[(row_start + threadIdx.x) + col * ld_a];
                        uint16_t* dst = &wh_tile[c][threadIdx.x];
                        __pipeline_memcpy_async(
                            dst, src, sizeof(uint16_t) * kMvCpAsyncRowChunk);
                    }
                } else {
                    for (size_t c = 0; c < stage_len; ++c) {
                        size_t col = tile_start + stage_start + c;
#pragma unroll
                        for (int r = 0; r < kMvCpAsyncRowChunk; ++r) {
                            size_t grow = row_start + threadIdx.x +
                                        static_cast<size_t>(r);
                            if (grow < rows_op)
                                wh_tile[c][threadIdx.x + r] =
                                    wh[grow + col * ld_a];
                        }
                    }
                }
            }
            __pipeline_commit();
            __pipeline_wait_prior(0);
            __syncthreads();

            if (i < rows_op) {
                size_t jj = 0;
                for (; jj + 4 <= stage_len; jj += 4) {
                    size_t xoff = stage_start + jj;
                    __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[jj][threadIdx.x]);
                    __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[jj + 1][threadIdx.x]);
                    __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[jj + 2][threadIdx.x]);
                    __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[jj + 3][threadIdx.x]);
                    acc0 = acc0 + a0 * x_tile[xoff];
                    acc1 = acc1 + a1 * x_tile[xoff + 1];
                    acc2 = acc2 + a2 * x_tile[xoff + 2];
                    acc3 = acc3 + a3 * x_tile[xoff + 3];
                }
                for (; jj < stage_len; ++jj) {
                    __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[jj][threadIdx.x]);
                    acc0 = acc0 + a_val * x_tile[stage_start + jj];
                }
            }
            __syncthreads();
        }
    }

    if (i < rows_op) {
        __half acc = (acc0 + acc1) + (acc2 + acc3);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_ilp_shared_cpasync_kernel's comment. Only
// reaches the cp.async kernel for TransposeType::NO_TRANSPOSE and
// rows_op < kMvWideRowThreshold (matching every benchmarked shape in this
// investigation); falls back to the already-proven mv_fp32_16_pure_half_
// wide_ilp_shared for TRANSPOSE, and to the plain mv_fp32_16_pure_half for
// shapes outside the wide-path range. Same grid/col_splits/blockDim.x as
// the baseline dispatch.
void mv_fp32_16_pure_half_wide_ilp_shared_cpasync(TransposeType trans,
                                                  double alpha, dim<2> size,
                                                  const uint16_t* wh,
                                                  size_t ld_a, const float* x,
                                                  size_t ld_x, double beta,
                                                  float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (trans != TransposeType::NO_TRANSPOSE) {
        mv_fp32_16_pure_half_wide_ilp_shared(trans, alpha, size, wh, ld_a, x,
                                             ld_x, beta, y, ld_y);
        return;
    }
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_cpasync_kernel<<<grid, kMvTileSize>>>(
            size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else {
        mv_fp32_16_pure_half(trans, alpha, size, wh, ld_a, x, ld_x, beta, y,
                             ld_y);
    }
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel:
// mv_fp32_16_pure_half_wide_ilp_shared_cpasync measured 0.62 of cuBLAS,
// below the 0.83 baseline -- but that kernel was deliberately single-
// buffered (stage a chunk, wait for ALL of it, THEN compute), so cp.async
// never actually overlapped anything; it just routed the same synchronous
// work through a different instruction path with extra small-transfer
// issue overhead on top. This kernel tests cp.async the way it is meant to
// be used: while computing on the CURRENT stage (already-completed
// buffer), the copies for the NEXT stage are issued into the OTHER
// buffer, so the async engine has real work to do concurrently with
// compute instead of being waited on immediately. Uses the standard
// double-buffered pipeline idiom (issue next, wait_prior(1) to confirm only
// the OLDER/current group finished, sync, compute, sync, swap buffers) --
// the same pattern CUTLASS-style multi-stage GEMM kernels use. Two
// kMvCpAsyncDoubleStageWidth-wide buffers must both fit in shared memory
// at once, so the stage width is narrower here (32 vs the single-buffered
// kernel's 64) to stay within the 48KB static shared-memory budget. Same
// NO_TRANSPOSE-only scope, same ld_a-must-be-even alignment caveat, and
// same row-chunk cp.async transfer scheme as mv_fp32_16_pure_half_wide_
// ilp_shared_cpasync -- see its comment for the full mechanism this
// shares.
static constexpr int kMvCpAsyncDoubleStageWidth = 32;

__global__ void mv_fp32_16_pure_half_wide_ilp_shared_cpasync2_kernel(
    size_t m, size_t n, const uint16_t* wh, size_t ld_a, const float* x,
    size_t col_splits, double* partial) {
    size_t rows_op = m;
    size_t cols_op = n;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    size_t row_start = static_cast<size_t>(blockIdx.x) * blockDim.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __shared__ uint16_t
        wh_tile[2][kMvCpAsyncDoubleStageWidth][kMvTileSize];
    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);

    bool full_row_chunk =
        (row_start + static_cast<size_t>(threadIdx.x) +
             static_cast<size_t>(kMvCpAsyncRowChunk) <=
         rows_op);
    bool issuer = (threadIdx.x % kMvCpAsyncRowChunk == 0);

    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        // Prologue: issue the first stage into buffer 0.
        {
            size_t stage_len0 =
                min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth), tile_len);
            if (issuer) {
                if (full_row_chunk) {
                    for (size_t c = 0; c < stage_len0; ++c) {
                        size_t col = tile_start + c;
                        const uint16_t* src =
                            &wh[(row_start + threadIdx.x) + col * ld_a];
                        uint16_t* dst = &wh_tile[0][c][threadIdx.x];
                        __pipeline_memcpy_async(
                            dst, src, sizeof(uint16_t) * kMvCpAsyncRowChunk);
                    }
                } else {
                    for (size_t c = 0; c < stage_len0; ++c) {
                        size_t col = tile_start + c;
#pragma unroll
                        for (int r = 0; r < kMvCpAsyncRowChunk; ++r) {
                            size_t grow = row_start + threadIdx.x +
                                        static_cast<size_t>(r);
                            if (grow < rows_op)
                                wh_tile[0][c][threadIdx.x + r] =
                                    wh[grow + col * ld_a];
                        }
                    }
                }
            }
            __pipeline_commit();
        }

        int cur_buf = 0;
        for (size_t stage_start = 0; stage_start < tile_len;
             stage_start += kMvCpAsyncDoubleStageWidth) {
            size_t stage_len = min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth),
                                   tile_len - stage_start);
            size_t next_stage_start = stage_start + kMvCpAsyncDoubleStageWidth;
            bool has_next = next_stage_start < tile_len;
            int next_buf = 1 - cur_buf;

            if (has_next) {
                size_t next_stage_len =
                    min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth),
                        tile_len - next_stage_start);
                if (issuer) {
                    if (full_row_chunk) {
                        for (size_t c = 0; c < next_stage_len; ++c) {
                            size_t col = tile_start + next_stage_start + c;
                            const uint16_t* src =
                                &wh[(row_start + threadIdx.x) + col * ld_a];
                            uint16_t* dst = &wh_tile[next_buf][c][threadIdx.x];
                            __pipeline_memcpy_async(
                                dst, src, sizeof(uint16_t) * kMvCpAsyncRowChunk);
                        }
                    } else {
                        for (size_t c = 0; c < next_stage_len; ++c) {
                            size_t col = tile_start + next_stage_start + c;
#pragma unroll
                            for (int r = 0; r < kMvCpAsyncRowChunk; ++r) {
                                size_t grow = row_start + threadIdx.x +
                                            static_cast<size_t>(r);
                                if (grow < rows_op)
                                    wh_tile[next_buf][c][threadIdx.x + r] =
                                        wh[grow + col * ld_a];
                            }
                        }
                    }
                }
                __pipeline_commit();
                __pipeline_wait_prior(1);
            } else {
                __pipeline_wait_prior(0);
            }
            __syncthreads();

            if (i < rows_op) {
                size_t jj = 0;
                for (; jj + 4 <= stage_len; jj += 4) {
                    size_t xoff = stage_start + jj;
                    __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj][threadIdx.x]);
                    __half a1 =
                        fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj + 1][threadIdx.x]);
                    __half a2 =
                        fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj + 2][threadIdx.x]);
                    __half a3 =
                        fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj + 3][threadIdx.x]);
                    acc0 = acc0 + a0 * x_tile[xoff];
                    acc1 = acc1 + a1 * x_tile[xoff + 1];
                    acc2 = acc2 + a2 * x_tile[xoff + 2];
                    acc3 = acc3 + a3 * x_tile[xoff + 3];
                }
                for (; jj < stage_len; ++jj) {
                    __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj][threadIdx.x]);
                    acc0 = acc0 + a_val * x_tile[stage_start + jj];
                }
            }
            __syncthreads();
            cur_buf = next_buf;
        }
    }

    if (i < rows_op) {
        __half acc = (acc0 + acc1) + (acc2 + acc3);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_ilp_shared_cpasync2_kernel's comment. Same
// TRANSPOSE fallback, wide-path-only scope, and grid/col_splits/blockDim.x
// as mv_fp32_16_pure_half_wide_ilp_shared_cpasync.
void mv_fp32_16_pure_half_wide_ilp_shared_cpasync2(TransposeType trans,
                                                   double alpha, dim<2> size,
                                                   const uint16_t* wh,
                                                   size_t ld_a, const float* x,
                                                   size_t ld_x, double beta,
                                                   float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (trans != TransposeType::NO_TRANSPOSE) {
        mv_fp32_16_pure_half_wide_ilp_shared(trans, alpha, size, wh, ld_a, x,
                                             ld_x, beta, y, ld_y);
        return;
    }
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_cpasync2_kernel<<<grid, kMvTileSize>>>(
            size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else {
        mv_fp32_16_pure_half(trans, alpha, size, wh, ld_a, x, ld_x, beta, y,
                             ld_y);
    }
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel: tests
// whether the split-K design's SECOND kernel launch (mv_fp32_16_wide_
// reduce_kernel, which every _wide_* variant above uses to combine
// col_splits blocks' partial sums, and which enforces its own inter-block
// synchronization via the kernel-launch boundary -- all col_splits blocks
// for a row must finish writing partial[] before the reduce kernel can
// safely read it) is itself a real cost, distinct from every __syncthreads
// ()-focused question this investigation has asked so far. This kernel
// eliminates that second launch and the intermediate "partial" double
// buffer entirely: each col_splits block instead combines its 4-way-
// unrolled column-chunk sum directly into y via atomicAdd(float*, float),
// so different blocks' contributions to the same output row can land in
// any order without needing a separate combining pass.
//
// Correctness requires beta's scaling to happen exactly ONCE per row
// before any block's atomicAdd, not once per col_splits block -- handled
// by a cheap prescale step run before the main kernel: cudaMemset(y, 0,
// ...) when beta == 0 (the case every performance benchmark in this file
// actually exercises), or a small mv_fp32_16_wide_atomic_prescale_kernel
// launch when beta != 0 (only exercised by run_correctness_case, not by
// bench_one's timed comparisons). Note a cudaMemset/prescale launch is
// itself a separate operation on the stream -- this doesn't eliminate ALL
// synchronization, only the col_splits-combining reduce kernel and its
// partial buffer specifically. Same 4-way unroll and shared-memory x_tile
// as mv_fp32_16_pure_half_wide_ilp_shared; only the combining step differs.
__global__ void mv_fp32_16_wide_atomic_prescale_kernel(size_t rows_op,
                                                       double beta,
                                                       float* y) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < rows_op)
        y[i] = static_cast<float>(beta * static_cast<double>(y[i]));
}

__global__ void mv_fp32_16_pure_half_wide_ilp_shared_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                acc0 = acc0 + a0 * x_tile[jj];
                acc1 = acc1 + a1 * x_tile[jj + 1];
                acc2 = acc2 + a2 * x_tile[jj + 2];
                acc3 = acc3 + a3 * x_tile[jj + 3];
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                acc0 = acc0 + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half acc = (acc0 + acc1) + (acc2 + acc3);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_ilp_shared_atomic_kernel's comment.
// IDENTICAL grid/col_splits to mv_fp32_16_pure_half_wide_ilp_shared; no
// partial buffer or second (reduce) kernel launch -- replaced by a
// cudaMemset (beta == 0) or a small prescale kernel (beta != 0) plus
// atomicAdd inside the main kernel. Narrow/tiled branches unchanged.
void mv_fp32_16_pure_half_wide_ilp_shared_atomic(TransposeType trans,
                                                 double alpha, dim<2> size,
                                                 const uint16_t* wh,
                                                 size_t ld_a, const float* x,
                                                 size_t ld_x, double beta,
                                                 float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        if (beta == 0.0) {
            cudaMemset(y, 0, rows_op * sizeof(float));
        } else {
            int threads = kMvTileSize;
            int blocks = (rows_op + threads - 1) / threads;
            mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_atomic_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// checked temp-dependencies/randls2.0's own gemv_fp16_cm_pair_ktiled_
// atomic (dense_kernels.cu:6698) after the split-K family (bigtile_half2,
// half2_wide4x, half2_best) plateaued: that kernel combines K-tiling with
// a direct atomicAdd into y, no separate reduce kernel or partial buffer
// at all -- independently arriving at the SAME combine strategy
// mv_fp32_16_pure_half_wide_ilp_shared_atomic above already tried in this
// codebase, cross-validating it as architecturally sound. But that
// existing kernel has the SAME "tested on the older scalar body, not
// half2-packed" gap that already cost mv_fp32_16_pure_half_wide_ilp_
// shared_branchless and _half2_vecrow real regressions when finally
// paired with packing (or in vecrow's case, when compared against the
// ALREADY-packed baseline). This kernel is the fair version: IDENTICAL
// to mv_fp32_16_pure_half_wide_ilp_shared_atomic_kernel above (same
// grid/col_splits, same atomicAdd combine, same cudaMemset/prescale-
// kernel beta handling, so no malloc/free of any kind either -- a
// genuinely different combine axis from every split+reduce sibling in
// this family) except the 4-way unroll packs into two __half2
// accumulators via __hfma2, exactly like mv_fp32_16_pure_half_wide_ilp_
// shared_half2_kernel's own arithmetic. No workspace parameter needed
// (no buffer to own) -- also drops the trailing cudaDeviceSynchronize()
// the original atomic wrapper has, same reasoning as every _workspace
// sibling's own lack of one (a benchmark's own time_call already syncs
// via cudaEventSynchronize).
//
// PROMOTED -- this is now "TOMOS FP16" itself (mv_fp32_16_pure_half_wide_
// ilp_shared_half2, the plain split+reduce kernel, remains available
// unchanged and is still what every other sibling's own comparison in
// this family measures against, but is no longer what "TOMOS FP16" means
// in the benchmark/plot). CONFIRMED on real A100 NO_TRANSPOSE hardware:
// dramatically faster than every split+reduce sibling at small/medium M
// -- eliminating BOTH the malloc/free AND the separate reduce-kernel
// launch pays off far more than either fix alone once launch/combine
// overhead dominates actual kernel work (M=1024: 90.5 -> 188.2 GFlop/s,
// +108%; M=1536: +58%; M=4096: +13%) -- and stays competitive-to-ahead of
// even mv_fp32_16_pure_half_wide_ilp_shared_half2_best (the previous best
// split+reduce choice) at large M too (M=32768: 1213.1 -> 1239.0, +2%;
// M=65536: 1193.8 -> 1214.6, +2%), with one narrow band around
// M=24576-49152 where half2_best's own wide4x choice measured ~4%-5%
// ahead instead (small enough to be within run-to-run noise on a shared
// cluster GPU, not independently reconfirmed).
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// Software-pipelined/prefetch sibling of mv_fp32_16_pure_half_wide_ilp_
// shared_half2_atomic_kernel above -- added as a new, separate function,
// original untouched. IDENTICAL compute and combine (same shared x-tiling,
// same __hfma2 accumulation, same safe fp32_16_half_only decode, same
// atomicAdd-into-y combine); the only change is WHEN the wh loads for the
// inner 4-wide unrolled loop are issued. The original kernel loads
// wh[idx0..idx3] and immediately consumes them in the very next __hfma2 --
// Nsight Compute profiling of that exact kernel found 88.7% of stall cycles
// are L1TEX scoreboard stalls (warps waiting on these global loads) despite
// L2/DRAM being nowhere near saturated (Mem Busy ~12%, Max Bandwidth ~25%,
// L1 hit rate ~0.24% since A is streamed once, no reuse) -- i.e.
// latency-bound, not bandwidth-bound or atomic-contention-bound (ruled out
// separately: mv_fp32_16_pure_half_wide_ilp_shared_half2_split, which
// removes the atomic entirely, measured no faster): too few independent
// memory requests in flight to hide each load's round-trip latency. This
// variant software-pipelines the inner loop (classic prologue + steady-
// state double-buffering): the NEXT 4-wide batch's wh loads are issued at
// the TOP of each loop iteration, before that same iteration's __hfma2
// consumes the CURRENT batch (loaded on the PREVIOUS iteration, or in the
// prologue for the first) -- so every batch's load has a full iteration's
// worth of independent FMA work to overlap with before its result is
// actually needed, instead of being consumed immediately after issue.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_prefetch_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            __half cur0 = static_cast<__half>(0.0f), cur1 = cur0, cur2 = cur0, cur3 = cur0;
            if (jj + 4 <= tile_len) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                cur0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                cur1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                cur2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                cur3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
            }
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t next_jj = jj + 4;
                __half nxt0 = static_cast<__half>(0.0f), nxt1 = nxt0, nxt2 = nxt0, nxt3 = nxt0;
                if (next_jj + 4 <= tile_len) {
                    size_t j0 = tile_start + next_jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                    size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                    size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                    size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                    size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                    size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                    size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                    size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                    size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                    size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                    size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                    nxt0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                    nxt1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                    nxt2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                    nxt3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                }

                __half2 a01 = __halves2half2(cur0, cur1);
                __half2 a23 = __halves2half2(cur2, cur3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);

                cur0 = nxt0; cur1 = nxt1; cur2 = nxt2; cur3 = nxt3;
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// Shared decode-batch helper for mv_fp32_16_pure_half_wide_ilp_shared_half2_
// atomic_prefetch2_kernel below -- loads the 4-wide batch of wh values at
// tile_start+offset (safe fp32_16_half_only decode, same indexing as the
// non-pipelined kernel's own unrolled loop), or zero-fills if that batch is
// past tile_len (matching the original kernel's own tail-loop cutover, but
// needed here as an explicit check since a depth-2 pipeline issues loads up
// to 2 batches beyond the batch actually being consumed).
__device__ __forceinline__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_load_batch(
    TransposeType trans, size_t i, size_t tile_start, size_t offset, size_t tile_len,
    const uint16_t* wh, size_t ld_a,
    __half& a0, __half& a1, __half& a2, __half& a3) {
    if (offset + 4 <= tile_len) {
        size_t j0 = tile_start + offset, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
        size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
        size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
        size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
        size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
        size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
        size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
        size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
        size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
        size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
        size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
        a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
        a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
        a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
        a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
    } else {
        a0 = a1 = a2 = a3 = static_cast<__half>(0.0f);
    }
}

// Depth-2 sibling of mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_
// prefetch_kernel above -- added as a new, separate function, original
// untouched. IDENTICAL compute/combine; only the pipeline depth changes.
// The depth-1 prefetch variant (1 batch/4 elements ahead) measured NO
// FASTER than the non-pipelined kernel, and re-profiling it found the
// L1TEX-scoreboard-stall share barely moved (88.7% -> 85.2%) -- consistent
// with ptxas already scheduling that single independent load about as well
// on its own, regardless of source order. This variant keeps TWO batches
// (8 elements) in flight instead of one: a 3-slot software pipeline (A =
// batch being consumed now, B = batch loaded last iteration for next time,
// C = batch issued THIS iteration for two iterations from now), directly
// doubling the number of independent outstanding wh loads per thread at
// any given moment, rather than relying on the compiler to find that
// overlap from a 1-deep hint.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_prefetch2_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            __half A0, A1, A2, A3, B0, B1, B2, B3;
            mv_fp32_16_pure_half_wide_ilp_shared_half2_load_batch(
                trans, i, tile_start, jj, tile_len, wh, ld_a, A0, A1, A2, A3);
            mv_fp32_16_pure_half_wide_ilp_shared_half2_load_batch(
                trans, i, tile_start, jj + 4, tile_len, wh, ld_a, B0, B1, B2, B3);
            for (; jj + 4 <= tile_len; jj += 4) {
                __half2 a01 = __halves2half2(A0, A1);
                __half2 a23 = __halves2half2(A2, A3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);

                __half C0, C1, C2, C3;
                mv_fp32_16_pure_half_wide_ilp_shared_half2_load_batch(
                    trans, i, tile_start, jj + 8, tile_len, wh, ld_a, C0, C1, C2, C3);

                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);

                A0 = B0; A1 = B1; A2 = B2; A3 = B3;
                B0 = C0; B1 = C1; B2 = C2; B3 = C3;
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// Half2/atomic-combine, wide4x-matched-col_splits sibling of
// mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_prefetch2_kernel above
// -- reuses mv_fp32_16_pure_half_wide_ilp_shared_cpasync2_kernel's own
// double-buffered cp.async staging mechanism (see that kernel's own
// comment, and mv_fp32_16_pure_half_wide_ilp_shared_cpasync_kernel's, for
// the full cp.async/alignment rationale and the kMvCpAsyncRowChunk/
// kMvCpAsyncDoubleStageWidth constants reused here unchanged) instead of
// writing a new staging scheme from scratch. Register-based lookahead
// (prefetch/prefetch2 above) measured no faster and barely moved the
// L1TEX-stall share Nsight Compute identified as the dominant cost --
// consistent with ptxas already scheduling a single independent register
// load about as well on its own. cp.async is a fundamentally different
// mechanism: the async-copy engine moves bytes from global to shared
// memory directly, without ever occupying a register for the pending
// value or blocking the issuing warp until an explicit wait, which
// register-mediated loads (ordinary or manually reordered) cannot do.
//
// Unlike cpasync2 (which uses the OLDER choose_col_splits cost model,
// scalar __half accumulation instead of __hfma2 packing, and a separate
// reduce-kernel + double-precision partial buffer to combine col_splits
// blocks), this kernel matches wide4x/prefetch/prefetch2 exactly on every
// OTHER axis via its host wrapper below (SAME choose_col_splits_target(
// ...,kMvTargetTotalThreads*4) col_splits formula, SAME __half2/__hfma2
// accumulation, SAME atomicAdd-into-y combine and y-prescale pattern) so
// this is a clean, single-variable comparison against "TOMOS FP16
// (implicit)" -- only the wh-loading mechanism differs. NO_TRANSPOSE only
// (cp.async's contiguous-row-chunk staging assumes NO_TRANSPOSE's
// column-major access pattern); the host wrapper falls back to
// mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_best for TRANSPOSE,
// mirroring cpasync/cpasync2's own established fallback precedent.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_kernel(
    size_t m, size_t n, const uint16_t* wh, size_t ld_a, const float* x,
    size_t col_splits, double alpha, float* y) {
    size_t rows_op = m;
    size_t cols_op = n;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    size_t row_start = static_cast<size_t>(blockIdx.x) * blockDim.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __shared__ uint16_t wh_tile[2][kMvCpAsyncDoubleStageWidth][kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));

    bool full_row_chunk =
        (row_start + static_cast<size_t>(threadIdx.x) +
             static_cast<size_t>(kMvCpAsyncRowChunk) <=
         rows_op);
    bool issuer = (threadIdx.x % kMvCpAsyncRowChunk == 0);

    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        // Prologue: issue the first stage into buffer 0.
        {
            size_t stage_len0 =
                min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth), tile_len);
            if (issuer) {
                if (full_row_chunk) {
                    for (size_t c = 0; c < stage_len0; ++c) {
                        size_t col = tile_start + c;
                        const uint16_t* src =
                            &wh[(row_start + threadIdx.x) + col * ld_a];
                        uint16_t* dst = &wh_tile[0][c][threadIdx.x];
                        __pipeline_memcpy_async(
                            dst, src, sizeof(uint16_t) * kMvCpAsyncRowChunk);
                    }
                } else {
                    for (size_t c = 0; c < stage_len0; ++c) {
                        size_t col = tile_start + c;
#pragma unroll
                        for (int r = 0; r < kMvCpAsyncRowChunk; ++r) {
                            size_t grow = row_start + threadIdx.x +
                                        static_cast<size_t>(r);
                            if (grow < rows_op)
                                wh_tile[0][c][threadIdx.x + r] =
                                    wh[grow + col * ld_a];
                        }
                    }
                }
            }
            __pipeline_commit();
        }

        int cur_buf = 0;
        for (size_t stage_start = 0; stage_start < tile_len;
             stage_start += kMvCpAsyncDoubleStageWidth) {
            size_t stage_len = min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth),
                                   tile_len - stage_start);
            size_t next_stage_start = stage_start + kMvCpAsyncDoubleStageWidth;
            bool has_next = next_stage_start < tile_len;
            int next_buf = 1 - cur_buf;

            if (has_next) {
                size_t next_stage_len =
                    min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth),
                        tile_len - next_stage_start);
                if (issuer) {
                    if (full_row_chunk) {
                        for (size_t c = 0; c < next_stage_len; ++c) {
                            size_t col = tile_start + next_stage_start + c;
                            const uint16_t* src =
                                &wh[(row_start + threadIdx.x) + col * ld_a];
                            uint16_t* dst = &wh_tile[next_buf][c][threadIdx.x];
                            __pipeline_memcpy_async(
                                dst, src, sizeof(uint16_t) * kMvCpAsyncRowChunk);
                        }
                    } else {
                        for (size_t c = 0; c < next_stage_len; ++c) {
                            size_t col = tile_start + next_stage_start + c;
#pragma unroll
                            for (int r = 0; r < kMvCpAsyncRowChunk; ++r) {
                                size_t grow = row_start + threadIdx.x +
                                            static_cast<size_t>(r);
                                if (grow < rows_op)
                                    wh_tile[next_buf][c][threadIdx.x + r] =
                                        wh[grow + col * ld_a];
                            }
                        }
                    }
                }
                __pipeline_commit();
                __pipeline_wait_prior(1);
            } else {
                __pipeline_wait_prior(0);
            }
            __syncthreads();

            if (i < rows_op) {
                size_t jj = 0;
                for (; jj + 4 <= stage_len; jj += 4) {
                    size_t xoff = stage_start + jj;
                    __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj][threadIdx.x]);
                    __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj + 1][threadIdx.x]);
                    __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj + 2][threadIdx.x]);
                    __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj + 3][threadIdx.x]);
                    __half2 a01 = __halves2half2(a0, a1);
                    __half2 a23 = __halves2half2(a2, a3);
                    __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[xoff]);
                    __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[xoff + 2]);
                    acc01 = __hfma2(a01, x01, acc01);
                    acc23 = __hfma2(a23, x23, acc23);
                }
                for (; jj < stage_len; ++jj) {
                    __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj][threadIdx.x]);
                    __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                    __half2 x_pad =
                        __halves2half2(x_tile[stage_start + jj], static_cast<__half>(0.0f));
                    acc01 = __hfma2(a_pad, x_pad, acc01);
                }
            }
            __syncthreads();
            cur_buf = next_buf;
        }
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// "test2" -- warp-uniform-issuer sibling of mv_fp32_16_pure_half_wide_ilp_
// shared_half2_atomic_cpasync_kernel above. Re-profiling that kernel
// (Warp State Statistics + Occupancy) found its own biggest flagged
// opportunity (Est. Local Speedup 25.51%) is warp divergence during
// staging, NOT the memory latency cp.async already fixed (warp cycles/
// instruction dropped 59.5->11.8 there): only 24.67 of 32 threads active
// per warp on average. Root cause: that kernel's own `issuer = (threadIdx
// .x % kMvCpAsyncRowChunk == 0)` alternates even/odd WITHIN every 32-
// thread warp (16 issue, 16 idle, every warp, for the whole staging
// loop) -- real intra-warp predication cost, not idle warps the scheduler
// could otherwise hide behind other resident work.
//
// This kernel changes ONLY which 128 of the 256 threads issue (same total
// transfer count, same 4-byte-per-transfer row-pair granularity, same
// wh_tile[buf][col][row_local] shared-memory layout the compute phase
// reads from -- that phase is BYTE-FOR-BYTE unchanged below): instead of
// alternating parity, issuer = (threadIdx.x < kMvTileSize/2) -- the FIRST
// 4 warps (128 = 4*32, warp-uniform: every thread in warps 0-3 takes the
// SAME branch, every thread in warps 4-7 takes the SAME other branch, no
// per-thread divergence within any single warp either way). Issuer thread
// t now covers rows (row_start+2t, row_start+2t+1) instead of the
// original scheme's (row_start+t, row_start+t+1) for even t -- same 256
// rows covered overall, just re-indexed so all 128 issuers are contiguous
// (warp-aligned) rather than interleaved.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform_kernel(
    size_t m, size_t n, const uint16_t* wh, size_t ld_a, const float* x,
    size_t col_splits, double alpha, float* y) {
    size_t rows_op = m;
    size_t cols_op = n;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    size_t row_start = static_cast<size_t>(blockIdx.x) * blockDim.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __shared__ uint16_t wh_tile[2][kMvCpAsyncDoubleStageWidth][kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));

    bool issuer = (threadIdx.x < kMvTileSize / 2);
    size_t row_pair_base = row_start + 2 * static_cast<size_t>(threadIdx.x);
    bool full_row_chunk = (row_pair_base + static_cast<size_t>(kMvCpAsyncRowChunk) <= rows_op);

    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        // Prologue: issue the first stage into buffer 0.
        {
            size_t stage_len0 =
                min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth), tile_len);
            if (issuer) {
                if (full_row_chunk) {
                    for (size_t c = 0; c < stage_len0; ++c) {
                        size_t col = tile_start + c;
                        const uint16_t* src = &wh[row_pair_base + col * ld_a];
                        uint16_t* dst = &wh_tile[0][c][2 * threadIdx.x];
                        __pipeline_memcpy_async(
                            dst, src, sizeof(uint16_t) * kMvCpAsyncRowChunk);
                    }
                } else {
                    for (size_t c = 0; c < stage_len0; ++c) {
                        size_t col = tile_start + c;
#pragma unroll
                        for (int r = 0; r < kMvCpAsyncRowChunk; ++r) {
                            size_t grow = row_pair_base + static_cast<size_t>(r);
                            if (grow < rows_op)
                                wh_tile[0][c][2 * threadIdx.x + r] =
                                    wh[grow + col * ld_a];
                        }
                    }
                }
            }
            __pipeline_commit();
        }

        int cur_buf = 0;
        for (size_t stage_start = 0; stage_start < tile_len;
             stage_start += kMvCpAsyncDoubleStageWidth) {
            size_t stage_len = min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth),
                                   tile_len - stage_start);
            size_t next_stage_start = stage_start + kMvCpAsyncDoubleStageWidth;
            bool has_next = next_stage_start < tile_len;
            int next_buf = 1 - cur_buf;

            if (has_next) {
                size_t next_stage_len =
                    min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth),
                        tile_len - next_stage_start);
                if (issuer) {
                    if (full_row_chunk) {
                        for (size_t c = 0; c < next_stage_len; ++c) {
                            size_t col = tile_start + next_stage_start + c;
                            const uint16_t* src = &wh[row_pair_base + col * ld_a];
                            uint16_t* dst = &wh_tile[next_buf][c][2 * threadIdx.x];
                            __pipeline_memcpy_async(
                                dst, src, sizeof(uint16_t) * kMvCpAsyncRowChunk);
                        }
                    } else {
                        for (size_t c = 0; c < next_stage_len; ++c) {
                            size_t col = tile_start + next_stage_start + c;
#pragma unroll
                            for (int r = 0; r < kMvCpAsyncRowChunk; ++r) {
                                size_t grow = row_pair_base + static_cast<size_t>(r);
                                if (grow < rows_op)
                                    wh_tile[next_buf][c][2 * threadIdx.x + r] =
                                        wh[grow + col * ld_a];
                            }
                        }
                    }
                }
                __pipeline_commit();
                __pipeline_wait_prior(1);
            } else {
                __pipeline_wait_prior(0);
            }
            __syncthreads();

            if (i < rows_op) {
                size_t jj = 0;
                for (; jj + 4 <= stage_len; jj += 4) {
                    size_t xoff = stage_start + jj;
                    __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj][threadIdx.x]);
                    __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj + 1][threadIdx.x]);
                    __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj + 2][threadIdx.x]);
                    __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj + 3][threadIdx.x]);
                    __half2 a01 = __halves2half2(a0, a1);
                    __half2 a23 = __halves2half2(a2, a3);
                    __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[xoff]);
                    __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[xoff + 2]);
                    acc01 = __hfma2(a01, x01, acc01);
                    acc23 = __hfma2(a23, x23, acc23);
                }
                for (; jj < stage_len; ++jj) {
                    __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj][threadIdx.x]);
                    __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                    __half2 x_pad =
                        __halves2half2(x_tile[stage_start + jj], static_cast<__half>(0.0f));
                    acc01 = __hfma2(a_pad, x_pad, acc01);
                }
            }
            __syncthreads();
            cur_buf = next_buf;
        }
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}


// ====================================================================
// No-overflow-guaranteed decode sibling of the cpasync_warpuniform
// kernel above: swaps fp32_16_half_only (safe, two sequential branches:
// control then direction) for fp32_16_half_only_branchless_no_overflow
// (branchless, no direction extraction, drops the cheap_bits select --
// see that function's own comment in fp32_16_pack.hpp) -- same
// technique already proven on the narrow_vec kernel family (real,
// measured wins there). This kernel's own accumulate step was ALREADY
// __half2/__hfma2-packed (unlike narrow_vec's original scalar
// accumulation), so this change isolates JUST the decode-cost lever,
// not a repeat of the half2acc one. Mechanical duplicate, added as a
// new, separate function, original untouched. Test-only for now
// (mv_fp32_16_pure_half_vs_cublas_ref.cu's own "test-new" leg via its
// own shape-aware dispatcher), not yet wired into any production
// dispatch registry.
