// Host wrapper for the no_overflow kernel above -- direct launch (no
// multi-tier shape dispatch), mirroring exactly the small-M branch of
// mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform's
// own composed dispatcher (same col_splits/grid/beta-handling). Test-
// only for now (mv_fp32_16_pure_half_vs_cublas_ref.cu's own "test-new"
// leg), not yet wired into any dispatch registry.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform_no_overflow(
    double alpha, dim<2> size, const uint16_t* wh, size_t ld_a, const float* x, double beta, float* y) {
    size_t rows_op = size[0];
    size_t cols_op = size[1];
    int col_splits = choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads * 4);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    if (beta == 0.0) {
        cudaMemset(y, 0, rows_op * sizeof(float));
    } else {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }
    dim3 grid(row_blocks, col_splits);
    mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform_no_overflow_kernel<<<grid, kMvTileSize>>>(
        size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
}


