// Non-atomic sibling of mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_
// kernel above -- added as a new, separate function, original untouched.
// IDENTICAL compute (same tiling, same shared x-staging, same __hfma2
// accumulation, same safe fp32_16_half_only decode); only the combine
// step at the very end changes: instead of every col_splits block
// atomicAdd-ing straight into the SAME y[i] (real contention once
// col_splits gets large enough -- see this kernel family's own Nsight
// Compute profiling: at col_splits=16, neither DRAM throughput (33%) nor
// SM throughput (20%) come close to saturating even at 85% warp
// occupancy, the signature of time spent waiting on a contended atomic
// rather than doing useful work), each block writes its own UNIQUE slot
// in a per-split partial[] buffer (partial[blockIdx.y*rows_op+i], no two
// blocks ever touch the same address), and a separate reduce kernel
// (mv_fp32_16_pure_half_reduce_kernel, already used unchanged by the
// TRANSPOSE atomiconly family -- reused verbatim here, not duplicated)
// sums the col_splits partials and applies alpha/beta exactly once. Note
// alpha is NOT applied here (unlike the atomic version above) -- it's
// applied once, by the reduce kernel, after summing raw partials, not
// once per split before summing (mathematically equivalent for a plain
// sum, but doing it once instead of col_splits times is cheaper and
// keeps this kernel's own output directly reusable as a plain
// partial-sum buffer).
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_split_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, float* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        partial[blockIdx.y * rows_op + i] = static_cast<float>(acc);
    }
}

// Forward-declared here: defined much later in this file (in the
// TRANSPOSE atomiconly section, where it's already used unchanged) --
// needs a declaration this early since this translation unit is compiled
// top-to-bottom and the wrapper below calls it before that point.
__global__ void mv_fp32_16_pure_half_reduce_kernel(double alpha, double beta, size_t rows_op, size_t col_splits,
                                                    const float* __restrict__ partial, float* __restrict__ y);

// Host wrapper for the split kernel above -- same shape-dispatch
// structure as wide4x (SAME col_splits formula too, kMvTargetTotalThreads
// *4, so this is a clean single-variable comparison against wide4x/
// "_best": identical grid, identical decode, identical per-block compute
// -- the ONLY thing that differs is atomicAdd-into-y vs partial-buffer-
// plus-separate-reduce), falling back to the same tiled/narrow_vec
// kernels (which have no atomic-vs-reduce distinction to make) for the
// narrow/else shape tiers. "test" in the GEVM performance plot until (or
// unless) it's actually measured as a real win over wide4x -- not
// promoted/assumed.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_split(TransposeType trans,
                                                       double alpha, dim<2> size,
                                                       const uint16_t* wh,
                                                       size_t ld_a, const float* x,
                                                       size_t ld_x, double beta,
                                                       float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits =
            choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads * 4);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        float* partial = nullptr;
        cudaError_t err = cudaMalloc(&partial, rows_op * static_cast<size_t>(col_splits) * sizeof(float));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_split_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_pure_half_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

// Workspace sizing for the caller-owned-buffer sibling below -- SAME
// col_splits formula the split kernel itself uses (choose_col_splits_
// target(..., kMvTargetTotalThreads*4), matching wide4x, NOT the plain
// choose_col_splits mv_fp32_16_pure_half_wide_ilp_shared_half2_workspace_
// size above uses -- keeping this a clean, single-variable comparison
// against wide4x/"_best" all the way through, not just in the kernel
// body). Returns 0 (no workspace needed) for the narrow/else shape tiers,
// same convention as that other _workspace_size function.
size_t mv_fp32_16_pure_half_wide_ilp_shared_half2_split_workspace_size(TransposeType trans, dim<2> size) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op >= kMvWideRowThreshold) return 0;
    int col_splits = choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads * 4);
    return rows_op * static_cast<size_t>(col_splits);
}

// Workspace-buffered sibling of mv_fp32_16_pure_half_wide_ilp_shared_
// half2_split above -- same "caller-owned scratch buffer instead of
// per-call cudaMalloc/cudaFree" fix as mv_fp32_16_pure_half_wide_ilp_
// shared_half2_workspace's own comment describes (that function's own
// measured numbers show the fix's benefit converges to ~0 by M=16384-
// 65536 for THAT kernel -- this variant exists to check directly whether
// the same holds here, rather than assume it, since a real A100
// measurement found this kernel underperforming wide4x/"_best" with the
// per-call cudaMalloc/cudaFree version, and that allocation overhead
// needs to be ruled out -- not assumed negligible -- before trusting that
// result as evidence against the atomic-contention hypothesis). No
// trailing cudaDeviceSynchronize(), same reasoning as every other
// _workspace sibling in this file.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_split_workspace(TransposeType trans,
                                                                 double alpha, dim<2> size,
                                                                 const uint16_t* wh,
                                                                 size_t ld_a, const float* x,
                                                                 size_t ld_x, double beta,
                                                                 float* y, size_t ld_y,
                                                                 float* workspace) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits =
            choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads * 4);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_split_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, workspace);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_pure_half_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, workspace, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

// Fast2-decode sibling of mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_kernel above -- added as a new,
// separate function, original untouched. Identical except its
// decode calls use fp32_16_half_only_fast2 instead of
// fp32_16_half_only (single-branch "is this genuine underflow"
// check, real shift-based subnormal reconstruction only in that
// one case, branchless cheap path otherwise -- see that
// function's own comment in fp32_16_pack.hpp).
__global__ void mv_fp32_16_pure_half_fast2_wide_ilp_shared_half2_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// Fast-decode sibling of mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_kernel above -- added as a new, separate
// function, original untouched. Identical except its decode calls use
// fp32_16_half_only_fast instead of fp32_16_half_only (saturates
// underflowed control=1 values to signed zero instead of recovering a
// genuine fp16 subnormal -- see fp32_16_half_only_fast's own comment in
// fp32_16_pack.hpp for the accuracy-for-speed trade this makes).
__global__ void mv_fp32_16_pure_half_fast_wide_ilp_shared_half2_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_fast(wh[idx0]);
                __half a1 = fp32_16_half_only_fast(wh[idx1]);
                __half a2 = fp32_16_half_only_fast(wh[idx2]);
                __half a3 = fp32_16_half_only_fast(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_fast(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// Host wrapper for mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_
// kernel above -- SAME grid/col_splits/beta-handling as mv_fp32_16_pure_
// half_wide_ilp_shared_atomic's own wrapper (cudaMemset when beta==0, a
// small prescale kernel otherwise, no malloc/free of any kind).
//
// PROMOTED -- this is "TOMOS FP16" in the benchmark/plot. See the
// kernel's own comment above for the real A100 measurements.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic(TransposeType trans,
                                                        double alpha, dim<2> size,
                                                        const uint16_t* wh,
                                                        size_t ld_a, const float* x,
                                                        size_t ld_x, double beta,
                                                        float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        if (beta == 0.0) {
            cudaMemset(y, 0, rows_op * sizeof(float));
        } else {
            int threads = kMvTileSize;
            int blocks = (rows_op + threads - 1) / threads;
            mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

// "test" -- checked Nsight Compute profiling data for "TOMOS FP16" itself
// (mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic) at M=4096: the grid
// (row_blocks * col_splits from choose_col_splits, targeting kMvTarget
// TotalThreads=131072 total threads) only fills 0.59 waves across the
// A100's 108 SMs, well short of the 100% theoretical occupancy the launch
// config alone would allow (achieved occupancy measured 46.86%, NOT
// register/shared-mem limited -- Block Limit SM=32 vs only ~4.7 blocks/SM
// actually landing). mv_fp32_16_pure_half_wide_ilp_shared_half2_wide2x/
// wide4x already tried MORE col_splits to address exactly this, but pay
// for it with a malloc'd partial buffer + a second reduce-kernel launch
// per call -- the same fixed cost atomicAdd combine was built to
// eliminate, which is why they lose at this size (confirmed crossover
// only above M=16384-24576). This reuses mv_fp32_16_pure_half_wide_ilp_
// shared_half2_atomic_kernel UNCHANGED, only computing col_splits via
// choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads*2)
// instead of the fixed kMvTargetTotalThreads -- more, smaller column
// chunks, more total blocks, raising wave count toward/past 1.0, but each
// extra split costs one more atomicAdd instead of a whole extra malloc/
// launch/serial-reduce-loop. Grid-math note: at M=1024 the plain atomic
// kernel already runs with col_splits=128 (128-way atomicAdd contention
// per row, confirmed via the same profiling run) with no measured
// problem, so more atomic contention at M=4096 isn't new territory for
// this combine mechanism. No workspace needed (no buffer to own, same as
// half2_atomic itself).
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_wide2x(TransposeType trans,
                                                               double alpha, dim<2> size,
                                                               const uint16_t* wh,
                                                               size_t ld_a, const float* x,
                                                               size_t ld_x, double beta,
                                                               float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits =
            choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads * 2);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        if (beta == 0.0) {
            cudaMemset(y, 0, rows_op * sizeof(float));
        } else {
            int threads = kMvTileSize;
            int blocks = (rows_op + threads - 1) / threads;
            mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

