                                                               size_t ld_x, double beta,
                                                               float* y, size_t ld_y) {
    if (trans != TransposeType::NO_TRANSPOSE) {
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_wide4x(trans, alpha, size, wh, ld_a, x,
                                                                  ld_x, beta, y, ld_y);
        return;
    }
    size_t rows_op = size[0];
    size_t cols_op = size[1];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits =
            choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads * 4);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        if (beta == 0.0) {
            cudaMemset(y, 0, rows_op * sizeof(float));
        } else {
            int threads = kMvTileSize;
            int blocks = (rows_op + threads - 1) / threads;
            mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform_kernel<<<grid, kMvTileSize>>>(
            size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    // Sync after every real launch on this (production, NO_TRANSPOSE) path,
    // matching the same "a BLAS-style call syncs before returning, so the
    // caller can trust the output is fully written" convention
    // mv_fp16_native_mixed_atomic (mv_cuda_kernels.cu, --explicit-
    // duplicates' own per-iteration kernel) already follows -- applied
    // here for consistency, not because LSQR's own single-stream calling
    // pattern strictly required it (stream ordering already guarantees
    // correctness there without this).
    cudaDeviceSynchronize();
}

// EXPERIMENTAL, NEW, additive-only sibling of mv_fp32_16_pure_half_wide_
// ilp_shared_half2_atomic_cpasync_warpuniform_kernel immediately above --
// does not modify that kernel or its host wrapper in any way, every
// existing caller is untouched. Built to test whether the SWAR (SIMD-
// within-a-register) decode lever that measured a real +18% to +31%
// throughput win for mv_fp32_16_pure_half_narrow_vec_flush_swar_kernel
// at large M (this session's own fp32_16_workspace_subnormal_density_
// table.sh-adjacent investigation, comparing flush256 vs flush256,SWAR
// at M=131072..1048576) also pays off here -- this is the ONE kernel
// that determines every SQUARE GEMV throughput number in this codebase
// (square shapes never cross kMvWideRowThreshold into the narrow_vec/
// flush family), and its own exact-vs-fast-decode gap (measured 15-39%
// across the whole square sweep, see mv_fp32_16_pure_half_vs_cublas_
// ref.cu's own "TOMOS FP32 / FP16" vs "(fast)" numbers) suggests decode
// cost is a real, persistent bottleneck here too, not just at large M.
//
// IDENTICAL cp.async double-buffered staging, warp-uniform issuer
// layout (issuer = threadIdx.x < kMvTileSize/2), tiling, and half2
// atomicAdd-combine accumulation as the kernel above -- ONLY the
// compute phase's decode changes, from four scalar fp32_16_half_only_
// branchless_no_overflow_nomask calls to two fp32_16_half2_decode_swar
// calls. Note wh_tile[buf][col][row] is NOT contiguous in shared memory
// between consecutive `col` values at a fixed `row` (stride kMvTileSize),
// unlike narrow_vec_flush_swar_kernel's own contiguous global-memory wh
// array -- so here the two uint16_t halves are packed into one uint32_t
// via shift+or immediately before calling the paired decode, rather than
// loaded as a single uint2/uint32_t memory transaction. fp32_16_half2_
// decode_swar's own comment (defined later in this file, forward-
// declared just below since it's called here before that definition)
// states it is verified bit-exact against fp32_16_half_only_branchless_
// no_overflow_nomask specifically -- the same function this kernel's own
// non-SWAR sibling calls -- so this kernel's output is expected to be
// bit-exact with it too; NOT yet independently re-verified against this
// kernel's own specific packing (w01/w23 built from non-adjacent shared-
// memory reads, not a memory-contiguous pair) -- run this against
// verify_mv_fp32_16_gemv.cu (or a standalone correctness spot-check)
// before trusting it beyond throughput comparison. NOT YET MEASURED on
// real hardware.
__device__ __forceinline__ uint32_t fp32_16_half2_decode_swar(uint32_t w);

__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform_swar_kernel(
    size_t m, size_t n, const uint16_t* wh, size_t ld_a, const float* x,
    size_t col_splits, double alpha, float* y) {
    size_t rows_op = m;
    size_t cols_op = n;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    size_t row_start = static_cast<size_t>(blockIdx.x) * blockDim.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __shared__ uint16_t wh_tile[2][kMvCpAsyncDoubleStageWidth][kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));

    bool issuer = (threadIdx.x < kMvTileSize / 2);
    size_t row_pair_base = row_start + 2 * static_cast<size_t>(threadIdx.x);
    bool full_row_chunk = (row_pair_base + static_cast<size_t>(kMvCpAsyncRowChunk) <= rows_op);

    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        // Prologue: issue the first stage into buffer 0.
        {
            size_t stage_len0 =
                min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth), tile_len);
            if (issuer) {
                if (full_row_chunk) {
                    for (size_t c = 0; c < stage_len0; ++c) {
                        size_t col = tile_start + c;
                        const uint16_t* src = &wh[row_pair_base + col * ld_a];
                        uint16_t* dst = &wh_tile[0][c][2 * threadIdx.x];
                        __pipeline_memcpy_async(
                            dst, src, sizeof(uint16_t) * kMvCpAsyncRowChunk);
                    }
                } else {
                    for (size_t c = 0; c < stage_len0; ++c) {
                        size_t col = tile_start + c;
#pragma unroll
                        for (int r = 0; r < kMvCpAsyncRowChunk; ++r) {
                            size_t grow = row_pair_base + static_cast<size_t>(r);
                            if (grow < rows_op)
                                wh_tile[0][c][2 * threadIdx.x + r] =
                                    wh[grow + col * ld_a];
                        }
                    }
                }
            }
            __pipeline_commit();
        }

        int cur_buf = 0;
        for (size_t stage_start = 0; stage_start < tile_len;
             stage_start += kMvCpAsyncDoubleStageWidth) {
            size_t stage_len = min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth),
                                   tile_len - stage_start);
            size_t next_stage_start = stage_start + kMvCpAsyncDoubleStageWidth;
            bool has_next = next_stage_start < tile_len;
            int next_buf = 1 - cur_buf;

            if (has_next) {
                size_t next_stage_len =
                    min(static_cast<size_t>(kMvCpAsyncDoubleStageWidth),
                        tile_len - next_stage_start);
                if (issuer) {
                    if (full_row_chunk) {
                        for (size_t c = 0; c < next_stage_len; ++c) {
                            size_t col = tile_start + next_stage_start + c;
                            const uint16_t* src = &wh[row_pair_base + col * ld_a];
                            uint16_t* dst = &wh_tile[next_buf][c][2 * threadIdx.x];
                            __pipeline_memcpy_async(
                                dst, src, sizeof(uint16_t) * kMvCpAsyncRowChunk);
                        }
                    } else {
                        for (size_t c = 0; c < next_stage_len; ++c) {
                            size_t col = tile_start + next_stage_start + c;
#pragma unroll
                            for (int r = 0; r < kMvCpAsyncRowChunk; ++r) {
                                size_t grow = row_pair_base + static_cast<size_t>(r);
                                if (grow < rows_op)
                                    wh_tile[next_buf][c][2 * threadIdx.x + r] =
                                        wh[grow + col * ld_a];
                            }
                        }
                    }
                }
                __pipeline_commit();
                __pipeline_wait_prior(1);
            } else {
                __pipeline_wait_prior(0);
            }
            __syncthreads();

            if (i < rows_op) {
                size_t jj = 0;
                for (; jj + 4 <= stage_len; jj += 4) {
                    size_t xoff = stage_start + jj;
                    uint32_t w01 = static_cast<uint32_t>(wh_tile[cur_buf][jj][threadIdx.x]) |
                                   (static_cast<uint32_t>(wh_tile[cur_buf][jj + 1][threadIdx.x]) << 16);
                    uint32_t w23 = static_cast<uint32_t>(wh_tile[cur_buf][jj + 2][threadIdx.x]) |
                                   (static_cast<uint32_t>(wh_tile[cur_buf][jj + 3][threadIdx.x]) << 16);
                    uint32_t d01 = fp32_16_half2_decode_swar(w01);
                    uint32_t d23 = fp32_16_half2_decode_swar(w23);
                    __half2 a01 = *reinterpret_cast<__half2*>(&d01);
                    __half2 a23 = *reinterpret_cast<__half2*>(&d23);
                    __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[xoff]);
                    __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[xoff + 2]);
                    acc01 = __hfma2(a01, x01, acc01);
                    acc23 = __hfma2(a23, x23, acc23);
                }
                for (; jj < stage_len; ++jj) {
                    __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh_tile[cur_buf][jj][threadIdx.x]);
                    __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                    __half2 x_pad =
                        __halves2half2(x_tile[stage_start + jj], static_cast<__half>(0.0f));
                    acc01 = __hfma2(a_pad, x_pad, acc01);
                }
            }
            __syncthreads();
            cur_buf = next_buf;
        }
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// Host wrapper for the SWAR-decode kernel above -- mirrors the wide-tier
// (rows_op < kMvWideRowThreshold) branch of mv_fp32_16_pure_half_wide_
// ilp_shared_half2_atomic_cpasync_warpuniform's own host wrapper exactly
// (same grid/col_splits/prescale logic), since that is the ONLY branch
// this experimental kernel provides a sibling for. Every other case
// (TRANSPOSE, or rows_op >= kMvWideRowThreshold) delegates to the
// EXISTING, unmodified wrapper above -- this function adds a new code
// path, it does not change the dispatch behavior of any existing caller
// (nothing in this codebase calls this new function yet).
void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform_swar(
    TransposeType trans, double alpha, dim<2> size, const uint16_t* wh, size_t ld_a, const float* x,
    size_t ld_x, double beta, float* y, size_t ld_y) {
    size_t rows_op = size[0];
    if (trans != TransposeType::NO_TRANSPOSE || rows_op >= kMvWideRowThreshold) {
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform(trans, alpha, size, wh, ld_a, x,
                                                                               ld_x, beta, y, ld_y);
        return;
    }
    size_t cols_op = size[1];
    int col_splits = choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads * 4);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    if (beta == 0.0) {
        cudaMemset(y, 0, rows_op * sizeof(float));
    } else {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }
    dim3 grid(row_blocks, col_splits);
    mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform_swar_kernel<<<grid, kMvTileSize>>>(
        size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
    cudaDeviceSynchronize();
}

// NO_TRANSPOSE-only composed dispatcher for mv_pure_half_impl's own safe-
// decode default (fp32_16_registries.cpp): a real, per-call LSQR timing
// breakdown (TOMOS_LSQR_TIMING=1, see src/core/solver/lsqr.cpp) found
// --implicit-duplicates' own per-iteration NO_TRANSPOSE matvec (the
// dominant cost -- fires ~63-67 times per solve, vs. ~14 for the FP32
// restart-boundary tier this session already fixed) running ~1.6-1.8x
// slower than --explicit-duplicates' own equivalent at the real LSQR
// matrix's shape (M=1,000,000, K=1000). Root cause, confirmed via `ncu`
// in-situ profiling of the real LSQR solve PLUS a fresh scripts/
// benchmarks_gemv_fp32_16_pure_half_tall_1000cols_vs_cublas_ref.sh sweep
// at exactly this shape: it was NOT the decode (fp32_16_half_only vs.
// _fast2 measured bit-identical timing) and NOT memory latency -- it was
// that this function previously routed rows_op >= kMvWideRowThreshold to
// mv_fp32_16_pure_half_fast2_narrow_vec_cpasync (a 4-rows-per-thread,
// register-blocked kernel family), which `ncu` showed running compute-
// bound at only 57% achieved occupancy / 1.51 waves per SM at this shape
// -- 3.16ms in situ. mv_fp32_16_pure_half_fast2_wide_ilp_shared_half2_
// atomic_best (this file, "_best_fast2" below) was never wired into any
// registry and so was never exercised by that timing breakdown, but the
// GEVM benchmark above measures it running THIS shape at 1.788ms/1118.6
// GFlop/s -- within ~2% of --explicit-duplicates' own native_mixed
// (1.757ms/1138.1 GFlop/s), not 1.8x slower. So the actual fix is a
// routing fix, not a kernel-level one: send every rows_op >=
// kMvWideRowThreshold shape (regardless of cols_op -- _best_fast2's own
// internal kMvHalf2AtomicBestCrossoverThreshold=4096 split already
// selects wide4x correctly here) to _best_fast2 instead of narrow_vec_
// cpasync. narrow_vec/narrow_vec_cpasync are left defined, just no
// longer reachable from this dispatcher -- see their own comments for
// the (now superseded) cp.async investigation that produced them.
//
// fp32_16_half_only_fast2 (fp32_16_pack.hpp) is BIT-EXACT with fp32_16_
// half_only -- verified directly, not just by its own comment: for every
// (control, direction) combination it computes the identical result via
// the identical arithmetic, just collapsing the two sequential branches
// into one combined, branchless is_underflow test. Both branches below
// stay bit-exact-safe on arbitrary data -- this is NOT the same axis as
// mv_pure_half_impl's own TOMOS_FP32_16_PURE_HALF_FAST_DECODE toggle
// (fp32_16_half_only_fast, a genuine accuracy-for-speed tradeoff that
// stalled LSQR convergence on real ill-conditioned data); that toggle's
// own "fast" path is untouched, this only changes the "safe decode"
// default's own internal shape dispatch.
void mv_fp32_16_pure_half_no_transpose_fast2(double alpha, dim<2> size, const uint16_t* wh, size_t ld_a,
                                              const float* x, size_t ld_x, double beta, float* y, size_t ld_y) {
    size_t rows_op = size[0];
    if (rows_op < kMvWideRowThreshold) {
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform(
            TransposeType::NO_TRANSPOSE, alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
    } else {
        // Covers the real LSQR matrix's own shape (rows_op >=
        // kMvWideRowThreshold). Routes to test-new's narrow_vec kernel
        // (no-overflow branchless decode + shift-by numbering +
        // vectorized write-back + grid-stride launch + half2-packed
        // accumulate) -- measured ~90% of --explicit-duplicates' own
        // native_mixed throughput at this shape in isolated GEVM
        // benchmarking. Replaces the previous fast2_wide_ilp_shared_
        // half2_atomic_best routing here: that kernel's "matches
        // native_mixed to within ~2%" comment was measured before this
        // session's realistic-underflow-rate discovery and never
        // re-validated -- a real LSQR run (TOMOS_LSQR_TIMING=1) instead
        // measured a genuine ~40-52% per-call gap at this exact shape,
        // not attributable to decode (branchless decode cost doesn't
        // depend on underflow rate).
        //
        // No ld_x/ld_y stride guard: an earlier version of this branch
        // only routed here when ld_x==1 && ld_y==1 (narrow_vec has no
        // ld_x/ld_y parameters, unlike every other kernel in this
        // dispatcher), falling back to fast2_wide_ilp_shared_half2_
        // atomic_best otherwise. That guard was based on a false
        // premise: NOTHING in this entire pure_half dispatch tree
        // (verified by reading cpasync_warpuniform, fast2_wide_ilp_
        // shared_half2_atomic_best, and fast2_wide_ilp_shared_half2_
        // atomic_wide4x directly) ever actually uses ld_x/ld_y in its
        // kernel launches -- every kernel here has ALWAYS silently
        // assumed unit-stride x/y regardless of what's passed in, so
        // the guard wasn't protecting against anything real. Whatever
        // non-1 ld_x/ld_y value mv_pure_half_impl's as_strided_view
        // happened to pass (LSQR's own vectors, e.g.) made the guard
        // false 100% of the time in practice, silently defeating this
        // entire routing change -- confirmed by a real LSQR run showing
        // near-zero improvement (iter_no_transpose 2.4548ms ->
        // 2.3903ms) despite narrow_vec's own isolated-benchmark
        // advantage. If a genuinely strided caller ever needs this
        // dispatcher, it was already silently broken before this
        // change too; this doesn't make that pre-existing gap worse.
        mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_gridstride_nomask_half2acc(
            TransposeType::NO_TRANSPOSE, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

// Shape-aware composed dispatcher for "test-new"'s own kernel: SAME
// small-M branch as mv_fp32_16_pure_half_no_transpose_fast2 above
// (cpasync_warpuniform -- already fast at this shape, no change needed,
// and it picked up the global shift_by numbering automatically), but
// the large-M branch (rows_op >= kMvWideRowThreshold, the real LSQR
// matrix's own shape) now routes to the current best narrow_vec
// candidate (no-overflow branchless decode + shiftenc numbering +
// vectorized write-back + grid-stride launch + half2-packed
// accumulate), which measured ~90% of --explicit-duplicates' own
// native_mixed throughput there -- vs. narrow_vec's own catastrophic
// under-parallelization at SMALL M (977->98 blocks at M=100,000, most
// of a 108-SM GPU idle) if called unconditionally across all shapes.
// Benchmark-only for now (mv_fp32_16_pure_half_vs_cublas_ref.cu's own
// "test-new" leg), not yet wired into any dispatch registry.
void mv_fp32_16_pure_half_test_new_dispatch(double alpha, dim<2> size, const uint16_t* wh, size_t ld_a,
                                             const float* x, size_t ld_x, double beta, float* y, size_t ld_y) {
    size_t rows_op = size[0];
    if (rows_op < kMvWideRowThreshold) {
        // "nomask" decode sibling of cpasync_warpuniform_no_overflow --
        // drops the provably-redundant `& 0x3FFu` after the subnormal
        // shift (see fp32_16_half_only_branchless_no_overflow_nomask's
        // own comment in fp32_16_pack.hpp). Measuring this before
        // promoting the mask removal to the base decode function.
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform_nomask(
            alpha, size, wh, ld_a, x, beta, y);
    } else {
        mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_gridstride_nomask_half2acc(
            TransposeType::NO_TRANSPOSE, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

