// ====================================================================
// Genuinely branchless decode sibling of the fast2 family above: swaps
// fp32_16_half_only_fast2 (single combined is_underflow branch) for
// fp32_16_half_only_branchless (same math, computed unconditionally,
// blended via bitmask -- see that function's own comment in
// fp32_16_pack.hpp). Motivation: sampling the real LSQR test matrix
// (tall_thin_1000.mtx) found a ~18% underflow rate; at any per-lane
// probability that far from 0 or 1, virtually every 32-lane warp is
// already mixed and already pays for BOTH of fast2's paths serially via
// divergence, so branchless removes that divergence (and the branch's
// own overhead) at the cost of always doing the shift-based work --
// roughly a wash on the old ~0%-underflow synthetic benchmark data, a
// real win on real matrix data. Mechanical duplicate of the ENTIRE fast2
// dispatch tree below (tiled_kernel, narrow_vec_kernel, wide_ilp_
// shared_half2_atomic_kernel, bigtile_half2_atomic_kernel + its host
// wrapper, wide4x, best) -- every piece renamed fast2->branchless,
// nothing else changed, so this new tree's own shape-dispatch behavior
// is byte-for-byte identical to fast2's, isolating decode as the only
// variable. Added as new, separate functions; the whole fast2 tree
// above is untouched. Not yet wired into any dispatch registry --
// benchmark-only for now (mv_fp32_16_pure_half_vs_cublas_ref.cu's own
// "test-new" leg), pending a real A100 measurement.
// ====================================================================

__global__ void mv_fp32_16_pure_half_branchless_tiled_kernel(TransposeType trans,
                                                   double alpha, size_t m,
                                                   size_t n,
                                                   const uint16_t* wh,
                                                   size_t ld_a, const float* x,
                                                   double beta, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    __shared__ __half x_tile[kMvTileSize];
    __half acc = static_cast<__half>(0.0f);
    for (size_t tile_start = 0; tile_start < cols_op;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              cols_op - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                acc = acc + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i >= rows_op) return;
    double acc_d = static_cast<double>(static_cast<float>(acc));
    y[i] = (beta != 0.0)
              ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
              : static_cast<float>(alpha * acc_d);
}

__global__ void mv_fp32_16_pure_half_branchless_narrow_vec_kernel(TransposeType trans,
                                                        double alpha,
                                                        size_t m, size_t n,
                                                        const uint16_t* wh,
                                                        size_t ld_a,
                                                        const float* __restrict__ x,
                                                        double beta,
                                                        float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    // The vectorized load also requires ld_a to be a multiple of
    // kMvRowsPerThread: base = i0 + j*ld_a must stay 8-byte-aligned for
    // every j, and i0 alone (a multiple of kMvRowsPerThread by
    // construction) only guarantees that for j==0 unless ld_a is too.
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t j = 0; j < cols_op; ++j) {
        __half x_val = static_cast<__half>(__ldg(&x[j]));
        if (vectorized) {
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 = acc0 + fp32_16_half_only_branchless_no_overflow_nomask(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only_branchless_no_overflow_nomask(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only_branchless_no_overflow_nomask(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only_branchless_no_overflow_nomask(raw.w) * x_val;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        double acc_d = static_cast<double>(static_cast<float>(acc[k]));
        y[i] = (beta != 0.0)
                  ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                  : static_cast<float>(alpha * acc_d);
    }
}

__global__ void mv_fp32_16_pure_half_branchless_wide_ilp_shared_half2_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

__global__ void mv_fp32_16_pure_half_branchless_wide_ilp_shared_bigtile_half2_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvWideBigTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvWideBigTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvWideBigTileSize),
                              col_end - tile_start);
        for (size_t k = threadIdx.x; k < tile_len; k += blockDim.x)
            x_tile[k] = static_cast<__half>(x[tile_start + k]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

void mv_fp32_16_pure_half_branchless_wide_ilp_shared_bigtile_half2_atomic(TransposeType trans,
                                                                double alpha, dim<2> size,
                                                                const uint16_t* wh,
                                                                size_t ld_a, const float* x,
                                                                size_t ld_x, double beta,
                                                                float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        if (beta == 0.0) {
            cudaMemset(y, 0, rows_op * sizeof(float));
        } else {
            int threads = kMvTileSize;
            int blocks = (rows_op + threads - 1) / threads;
            mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_branchless_wide_ilp_shared_bigtile_half2_atomic_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_branchless_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_branchless_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

void mv_fp32_16_pure_half_branchless_wide_ilp_shared_half2_atomic_wide4x(TransposeType trans,
                                                               double alpha, dim<2> size,
                                                               const uint16_t* wh,
                                                               size_t ld_a, const float* x,
                                                               size_t ld_x, double beta,
                                                               float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits =
            choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads * 4);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        if (beta == 0.0) {
            cudaMemset(y, 0, rows_op * sizeof(float));
        } else {
            int threads = kMvTileSize;
            int blocks = (rows_op + threads - 1) / threads;
            mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_branchless_wide_ilp_shared_half2_atomic_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_branchless_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_branchless_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

void mv_fp32_16_pure_half_branchless_wide_ilp_shared_half2_atomic_best(TransposeType trans,
                                                             double alpha, dim<2> size,
                                                             const uint16_t* wh,
                                                             size_t ld_a, const float* x,
                                                             size_t ld_x, double beta,
                                                             float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    if (rows_op >= kMvHalf2AtomicBestCrossoverThreshold) {
        mv_fp32_16_pure_half_branchless_wide_ilp_shared_half2_atomic_wide4x(trans, alpha, size, wh, ld_a, x,
                                                                  ld_x, beta, y, ld_y);
        return;
    }
    mv_fp32_16_pure_half_branchless_wide_ilp_shared_bigtile_half2_atomic(trans, alpha, size, wh, ld_a, x,
                                                               ld_x, beta, y, ld_y);
}


// ====================================================================
// No-overflow-guaranteed sibling of the branchless family above: swaps
// fp32_16_half_only_branchless for fp32_16_half_only_branchless_no_
// overflow (drops the direction extraction and cheap_bits select
// entirely, under a caller-guaranteed "no wh in this buffer ever
// overflows" contract -- see that function's own comment in fp32_16_
// pack.hpp). Measured directly on the real LSQR test matrix (tall_thin_
// 1000.mtx): 0% overflow, ~18% underflow (two independent 2M-value
// samples) -- this contract genuinely holds for that real data, not
// just synthetic test data built to satisfy it. Mechanical duplicate of
// the ENTIRE branchless dispatch tree above (tiled_kernel, narrow_vec_
// kernel, wide_ilp_shared_half2_atomic_kernel, bigtile_half2_atomic_
// kernel + host wrapper, wide4x, best) -- every piece renamed
// branchless->branchless_no_overflow, nothing else changed. Added as
// new, separate functions; the whole branchless tree above is untouched.
// Not yet wired into any dispatch registry -- benchmark-only for now
// (mv_fp32_16_pure_half_vs_cublas_ref.cu's own "test-new" leg).
// ====================================================================

__global__ void mv_fp32_16_pure_half_branchless_no_overflow_tiled_kernel(TransposeType trans,
                                                   double alpha, size_t m,
                                                   size_t n,
                                                   const uint16_t* wh,
                                                   size_t ld_a, const float* x,
                                                   double beta, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    __shared__ __half x_tile[kMvTileSize];
    __half acc = static_cast<__half>(0.0f);
    for (size_t tile_start = 0; tile_start < cols_op;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              cols_op - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow(wh[idx]);
                acc = acc + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i >= rows_op) return;
    double acc_d = static_cast<double>(static_cast<float>(acc));
    y[i] = (beta != 0.0)
              ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
              : static_cast<float>(alpha * acc_d);
}

__global__ void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_kernel(TransposeType trans,
                                                        double alpha,
                                                        size_t m, size_t n,
                                                        const uint16_t* wh,
                                                        size_t ld_a,
                                                        const float* __restrict__ x,
                                                        double beta,
                                                        float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    // The vectorized load also requires ld_a to be a multiple of
    // kMvRowsPerThread: base = i0 + j*ld_a must stay 8-byte-aligned for
    // every j, and i0 alone (a multiple of kMvRowsPerThread by
    // construction) only guarantees that for j==0 unless ld_a is too.
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t j = 0; j < cols_op; ++j) {
        __half x_val = static_cast<__half>(__ldg(&x[j]));
        if (vectorized) {
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 = acc0 + fp32_16_half_only_branchless_no_overflow(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only_branchless_no_overflow(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only_branchless_no_overflow(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only_branchless_no_overflow(raw.w) * x_val;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        double acc_d = static_cast<double>(static_cast<float>(acc[k]));
        y[i] = (beta != 0.0)
                  ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                  : static_cast<float>(alpha * acc_d);
    }
}

// Vectorized-write sibling of the kernel above -- mechanical duplicate,
// added as a new, separate function, original untouched. Motivation:
// `ncu` profiling of the kernel above (the real LSQR shape, M=1,000,000,
// K=1000) flagged its own write-back loop directly -- "global stores...
// only 8.0 of the 32 bytes transmitted per sector are utilized" (Est.
// Speedup 6.0%) and "each warp spends 6.5 cycles stalled waiting for a
// scoreboard dependency on L1TEX" (Est. Speedup 22.7%) -- pointing at
// the 4 separate scalar y[i]= stores (and, when beta!=0, 4 separate
// y[i] reads first) this kernel's own write-back does per thread,
// completely independent of decode cost (already minimized by the
// no_overflow branchless decode this shares unchanged). i0 is always a
// multiple of kMvRowsPerThread(4) by construction, and y comes from
// cudaMalloc (>=256-byte aligned), so &y[i0] is always 16-byte aligned
// whenever the whole 4-row group is in bounds -- safe for a single
// float4 load/store instead of 4 scalar ones. Reuses `vectorized`'s own
// in-bounds check (kept as a SEPARATE `write_vectorized` condition,
// dropping vectorized's OWN extra ld_a%4==0 requirement, which the
// WRITE side never needed -- only the wh READ side does) so this also
// vectorizes the write on the TRANSPOSE path and on NO_TRANSPOSE calls
// where ld_a isn't a multiple of 4, not just the exact case the read
// side handles.
__global__ void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_kernel(TransposeType trans,
                                                        double alpha,
                                                        size_t m, size_t n,
                                                        const uint16_t* wh,
                                                        size_t ld_a,
                                                        const float* __restrict__ x,
                                                        double beta,
                                                        float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    bool write_vectorized = (i0 + kMvRowsPerThread <= rows_op);
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      write_vectorized &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t j = 0; j < cols_op; ++j) {
        __half x_val = static_cast<__half>(__ldg(&x[j]));
        if (vectorized) {
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 = acc0 + fp32_16_half_only_branchless_no_overflow(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only_branchless_no_overflow(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only_branchless_no_overflow(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only_branchless_no_overflow(raw.w) * x_val;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    if (write_vectorized) {
        float4 result;
        float* r = reinterpret_cast<float*>(&result);
        if (beta != 0.0) {
            float4 y4 = *reinterpret_cast<float4*>(&y[i0]);
            const float* yv = reinterpret_cast<const float*>(&y4);
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                r[k] = static_cast<float>(alpha * acc_d + beta * static_cast<double>(yv[k]));
            }
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                r[k] = static_cast<float>(alpha * acc_d);
            }
        }
        *reinterpret_cast<float4*>(&y[i0]) = result;
    } else {
        for (int k = 0; k < kMvRowsPerThread; ++k) {
            size_t i = i0 + static_cast<size_t>(k);
            if (i >= rows_op) break;
            double acc_d = static_cast<double>(static_cast<float>(acc[k]));
            y[i] = (beta != 0.0)
                      ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                      : static_cast<float>(alpha * acc_d);
        }
    }
}

// Host wrapper for the kernel above -- direct single-kernel launch (no
// multi-tier shape dispatch), mirroring mv_fp32_16_pure_half_fast2_
// narrow_vec_cpasync's own wrapper convention. Benchmark-only for now
// (mv_fp32_16_pure_half_vs_cublas_ref.cu's own "test-new" leg), not yet
// wired into any dispatch registry.
void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store(TransposeType trans, double alpha, size_t m,
                                                                       size_t n, const uint16_t* wh, size_t ld_a,
                                                                       const float* x, double beta, float* y) {
    int threads = kMvTileSize;
