// half2-accumulation sibling of the shiftenc kernel above -- mechanical
// duplicate, added as a new, separate function, original untouched.
// Decode itself stays scalar (each of the 4 rows' wh values needs its
// own independent shift/mask, from 4 different memory locations -- not
// packable), but the ACCUMULATE step, once decoded, has no such
// constraint: this packs a0/a1 and a2/a3 into __half2 pairs and uses
// __hfma2 against a broadcast x_val2 (same technique mv_fp32_16_pure_
// half_wide_ilp_shared_half2_atomic_kernel's own inner loop already
// uses, just never adopted here) -- halves the FMA instruction count
// for the accumulate step (2 packed __hfma2 instead of 4 scalar FMAs)
// without changing decode at all. The `if (vectorized)` check is
// hoisted OUTSIDE the column loop (constant per-thread, computed once
// from i0/rows_op/ld_a, not re-checked every column) so the two
// accumulation strategies (half2-packed vs. scalar fallback) don't
// have to coexist inside the same hot loop.
__global__ void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_gridstride_shiftenc_half2acc_kernel(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* __restrict__ x, double beta, float* y, size_t total_row_groups) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t stride = static_cast<size_t>(gridDim.x) * static_cast<size_t>(blockDim.x);

    for (size_t group = blockIdx.x * blockDim.x + threadIdx.x; group < total_row_groups; group += stride) {
        size_t i0 = group * static_cast<size_t>(kMvRowsPerThread);
        bool write_vectorized = (i0 + kMvRowsPerThread <= rows_op);
        bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                          write_vectorized &&
                          (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

        __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
        __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
        if (vectorized) {
            __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
            __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
            for (size_t j = 0; j < cols_op; ++j) {
                __half x_val = static_cast<__half>(__ldg(&x[j]));
                size_t base = i0 + j * ld_a;
                ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
                __half a0 = fp32_16_half_only_branchless_no_overflow_shiftenc(raw.x);
                __half a1 = fp32_16_half_only_branchless_no_overflow_shiftenc(raw.y);
                __half a2 = fp32_16_half_only_branchless_no_overflow_shiftenc(raw.z);
                __half a3 = fp32_16_half_only_branchless_no_overflow_shiftenc(raw.w);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x_val2 = __half2half2(x_val);
                acc01 = __hfma2(a01, x_val2, acc01);
                acc23 = __hfma2(a23, x_val2, acc23);
            }
            acc0 = __low2half(acc01);
            acc1 = __high2half(acc01);
            acc2 = __low2half(acc23);
            acc3 = __high2half(acc23);
        } else {
            for (size_t j = 0; j < cols_op; ++j) {
                __half x_val = static_cast<__half>(__ldg(&x[j]));
                for (int k = 0; k < kMvRowsPerThread; ++k) {
                    size_t i = i0 + static_cast<size_t>(k);
                    if (i >= rows_op) break;
                    size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                    size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                    size_t idx = a_row + a_col * ld_a;
                    __half a_val = fp32_16_half_only_branchless_no_overflow_shiftenc(wh[idx]);
                    __half term = a_val * x_val;
                    switch (k) {
                        case 0: acc0 = acc0 + term; break;
                        case 1: acc1 = acc1 + term; break;
                        case 2: acc2 = acc2 + term; break;
                        default: acc3 = acc3 + term; break;
                    }
                }
            }
        }

        __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
        if (write_vectorized) {
            float4 result;
            float* r = reinterpret_cast<float*>(&result);
            if (beta != 0.0) {
                float4 y4 = *reinterpret_cast<float4*>(&y[i0]);
                const float* yv = reinterpret_cast<const float*>(&y4);
                for (int k = 0; k < kMvRowsPerThread; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                    r[k] = static_cast<float>(alpha * acc_d + beta * static_cast<double>(yv[k]));
                }
            } else {
                for (int k = 0; k < kMvRowsPerThread; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                    r[k] = static_cast<float>(alpha * acc_d);
                }
            }
            *reinterpret_cast<float4*>(&y[i0]) = result;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                y[i] = (beta != 0.0)
                          ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                          : static_cast<float>(alpha * acc_d);
            }
        }
    }
}

// Host wrapper for the half2-accumulation kernel above -- same grid-
// sizing strategy as the shiftenc kernel's own wrapper.
void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_gridstride_shiftenc_half2acc(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a, const float* x,
    double beta, float* y) {
    int threads = kMvTileSize;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
    size_t natural_blocks = (row_groups + threads - 1) / threads;

    int device = 0;
    cudaGetDevice(&device);
    int sm_count = 0;
    cudaDeviceGetAttribute(&sm_count, cudaDevAttrMultiProcessorCount, device);
    int max_active_blocks_per_sm = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &max_active_blocks_per_sm,
        mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_gridstride_shiftenc_half2acc_kernel, threads,
        0);
    size_t wave_blocks = static_cast<size_t>(max_active_blocks_per_sm) * static_cast<size_t>(sm_count);
    size_t blocks = (wave_blocks > 0) ? std::min(wave_blocks, natural_blocks) : natural_blocks;
    if (blocks < 1) blocks = 1;

    mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_gridstride_shiftenc_half2acc_kernel<<<
        static_cast<int>(blocks), threads>>>(trans, alpha, m, n, wh, ld_a, x, beta, y, row_groups);
}


// ====================================================================
// Redundant-mask-removed decode sibling of the shiftenc_half2acc kernel
// above: swaps fp32_16_half_only_branchless_no_overflow_shiftenc for
// fp32_16_half_only_branchless_no_overflow_nomask (drops the provably-
// redundant `& 0x3FFu` after the subnormal shift -- see that function's
// own comment in fp32_16_pack.hpp; confirmed via cuobjdump that this
// mask compiles to a real, separate LOP3.LUT instruction on the
// shiftenc_half2acc kernel, not eliminated by ptxas on its own).
// Mechanical duplicate, added as a new, separate function, original
// untouched. Test-only for now (mv_fp32_16_pure_half_vs_cublas_ref.cu's
// own "test-new" leg), not yet promoted to the base decode function
// pending real-hardware measurement.
// ====================================================================

__global__ void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_gridstride_nomask_half2acc_kernel(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* __restrict__ x, double beta, float* y, size_t total_row_groups) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t stride = static_cast<size_t>(gridDim.x) * static_cast<size_t>(blockDim.x);

    for (size_t group = blockIdx.x * blockDim.x + threadIdx.x; group < total_row_groups; group += stride) {
        size_t i0 = group * static_cast<size_t>(kMvRowsPerThread);
        bool write_vectorized = (i0 + kMvRowsPerThread <= rows_op);
        bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                          write_vectorized &&
                          (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

        __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
        __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
        if (vectorized) {
            __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
            __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
            for (size_t j = 0; j < cols_op; ++j) {
                __half x_val = static_cast<__half>(__ldg(&x[j]));
                size_t base = i0 + j * ld_a;
                ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(raw.x);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(raw.y);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(raw.z);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(raw.w);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x_val2 = __half2half2(x_val);
                acc01 = __hfma2(a01, x_val2, acc01);
                acc23 = __hfma2(a23, x_val2, acc23);
            }
            acc0 = __low2half(acc01);
            acc1 = __high2half(acc01);
            acc2 = __low2half(acc23);
            acc3 = __high2half(acc23);
        } else {
            for (size_t j = 0; j < cols_op; ++j) {
                __half x_val = static_cast<__half>(__ldg(&x[j]));
                for (int k = 0; k < kMvRowsPerThread; ++k) {
                    size_t i = i0 + static_cast<size_t>(k);
                    if (i >= rows_op) break;
                    size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                    size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                    size_t idx = a_row + a_col * ld_a;
                    __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                    __half term = a_val * x_val;
                    switch (k) {
                        case 0: acc0 = acc0 + term; break;
                        case 1: acc1 = acc1 + term; break;
                        case 2: acc2 = acc2 + term; break;
                        default: acc3 = acc3 + term; break;
                    }
                }
            }
        }

        __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
        if (write_vectorized) {
            float4 result;
            float* r = reinterpret_cast<float*>(&result);
            if (beta != 0.0) {
                float4 y4 = *reinterpret_cast<float4*>(&y[i0]);
                const float* yv = reinterpret_cast<const float*>(&y4);
                for (int k = 0; k < kMvRowsPerThread; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                    r[k] = static_cast<float>(alpha * acc_d + beta * static_cast<double>(yv[k]));
                }
            } else {
                for (int k = 0; k < kMvRowsPerThread; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                    r[k] = static_cast<float>(alpha * acc_d);
                }
            }
            *reinterpret_cast<float4*>(&y[i0]) = result;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                y[i] = (beta != 0.0)
                          ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                          : static_cast<float>(alpha * acc_d);
            }
        }
    }
}

// Host wrapper for the half2-accumulation kernel above -- same grid-
// sizing strategy as the shiftenc kernel's own wrapper.
void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_gridstride_nomask_half2acc(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a, const float* x,
    double beta, float* y) {
    int threads = kMvTileSize;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
    size_t natural_blocks = (row_groups + threads - 1) / threads;

    // Occupancy-capped "one wave, no tail" grid sizing (via cudaGetDevice +
    // cudaDeviceGetAttribute + cudaOccupancyMaxActiveBlocksPerMultiprocessor)
    // was tried here and explicitly recorded as a NEGATIVE result in
    // decode.md -- no measurable improvement over just launching
    // natural_blocks directly, safe to do since this kernel's own internal
    // loop is already grid-stride (correct for any block count >= 1, more
    // blocks just means each does proportionally less work, no correctness
    // dependency on hitting an exact wave count). It was kept bundled into
    // this "best" combined candidate anyway (alongside vec4store/half2acc,
    // which DID help) rather than removed for being merely neutral -- but
    // three CUDA driver round-trips per call are NOT actually free under
    // real LSQR usage (unlike an isolated benchmark's tight repeated-call
    // loop, which apparently masks the cost): LSQR interleaves this call
    // with many others every iteration (dot/axpy/nrm2, the TRANSPOSE
    // matvec, preconditioner apply), so it never gets the same back-to-back
    // repetition that might let a driver-level cache absorb this. Removed
    // entirely rather than just cached, since it was never earning its
    // keep in the first place.
    size_t blocks = natural_blocks;
    if (blocks < 1) blocks = 1;

    mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec_vec4store_gridstride_nomask_half2acc_kernel<<<
        static_cast<int>(blocks), threads>>>(trans, alpha, m, n, wh, ld_a, x, beta, y, row_groups);
    // Sync before returning -- see mv_fp32_16_pure_half_wide_ilp_shared_
    // half2_atomic_cpasync_warpuniform's own comment on this same
    // convention (matches mv_fp16_native_mixed_atomic, --explicit-
    // duplicates' equivalent kernel).
    cudaDeviceSynchronize();
}

// ====================================================================
// Periodic-flush siblings of the narrow_vec kernel above -- the kernel
// LSQR's implicit NO_TRANSPOSE matvec actually runs at M >= kMvWide
// RowThreshold (via mv_fp32_16_pure_half_no_transpose_fast2). The base
// kernel keeps its __half2 accumulators live across ALL cols_op columns, so
// its fp16 rounding error grows with the column count (GEMV error
// benchmark: ~5.6e-4 at K=1024 to ~6.7e-3 at K=65536 for the packed
// kernels, while mv_fp16_native_mixed -- what --explicit-duplicates runs --
// stays lower because it caps every fp16 chain at 256 columns and widens at
// tile boundaries), and LSQR's implicit configuration needs more iterations
// than the explicit one as the column count grows. This is a mechanical
// duplicate of that kernel with ONE change: every FLUSH columns the four
// per-row __half accumulators are added into float accumulators and reset,
// so no fp16 chain is ever longer than FLUSH terms. Everything else -- the
// ushort4 vector loads, the four rows per thread, the grid-stride loop, the
// branchless no-overflow decode, the vectorized write-back -- is unchanged,
// which is why this should keep the base kernel's throughput where the
// earlier full mv_fp16_native_mixed-tree duplicate (mv_fp32_16_pure_half_
// nativeaccum) lost ~20%. The flush costs four half->float conversions and
// four adds per FLUSH columns per thread, i.e. negligible next to FLUSH
// columns of decode.
//
// FLUSH is a template parameter so the interval can be swept (exported
// below at 64 and 256 -- 256 matches mv_fp16_native_mixed's tile size).
// The float flush accumulators (not double, unlike native_mixed) keep the
// per-thread register footprint down: a flush adds at most
// ceil(cols_op/FLUSH) terms of tile-sum magnitude, so float's 24-bit
// mantissa is far below the fp16 error being removed.
// Register note (ptxas): 34 registers, no spills, vs the base kernel's 29.
// Capping it at 32 via __launch_bounds__(kMvTileSize, 8) (which would keep
// full theoretical occupancy) was tried and spills 16 bytes; since this
// kernel is ALU-bound (~82% ALU utilization in the earlier ncu profile) the
// spill instructions looked like the bigger risk than the occupancy
// difference, so the uncapped, spill-free version is kept. Untested either
// way on hardware.
template <int FLUSH>
__global__ void mv_fp32_16_pure_half_narrow_vec_flush_kernel(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* __restrict__ x, double beta, float* y, size_t total_row_groups) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t stride = static_cast<size_t>(gridDim.x) * static_cast<size_t>(blockDim.x);

    for (size_t group = blockIdx.x * blockDim.x + threadIdx.x; group < total_row_groups; group += stride) {
        size_t i0 = group * static_cast<size_t>(kMvRowsPerThread);
        bool write_vectorized = (i0 + kMvRowsPerThread <= rows_op);
        bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                          write_vectorized &&
                          (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

        float f0 = 0.0f, f1 = 0.0f, f2 = 0.0f, f3 = 0.0f;
        if (vectorized) {
            __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
            __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
            for (size_t jb = 0; jb < cols_op; jb += FLUSH) {
                size_t je = min(jb + static_cast<size_t>(FLUSH), cols_op);
                for (size_t j = jb; j < je; ++j) {
                    __half x_val = static_cast<__half>(__ldg(&x[j]));
                    size_t base = i0 + j * ld_a;
                    ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
                    __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(raw.x);
                    __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(raw.y);
                    __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(raw.z);
                    __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(raw.w);
                    __half2 a01 = __halves2half2(a0, a1);
                    __half2 a23 = __halves2half2(a2, a3);
                    __half2 x_val2 = __half2half2(x_val);
                    acc01 = __hfma2(a01, x_val2, acc01);
                    acc23 = __hfma2(a23, x_val2, acc23);
                }
                f0 += __half2float(__low2half(acc01));
                f1 += __half2float(__high2half(acc01));
                f2 += __half2float(__low2half(acc23));
                f3 += __half2float(__high2half(acc23));
                acc01 = __half2half2(static_cast<__half>(0.0f));
                acc23 = __half2half2(static_cast<__half>(0.0f));
            }
        } else {
            __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
            __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
            for (size_t jb = 0; jb < cols_op; jb += FLUSH) {
                size_t je = min(jb + static_cast<size_t>(FLUSH), cols_op);
                for (size_t j = jb; j < je; ++j) {
                    __half x_val = static_cast<__half>(__ldg(&x[j]));
                    for (int k = 0; k < kMvRowsPerThread; ++k) {
                        size_t i = i0 + static_cast<size_t>(k);
                        if (i >= rows_op) break;
                        size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                        size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                        size_t idx = a_row + a_col * ld_a;
                        __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                        __half term = a_val * x_val;
                        switch (k) {
                            case 0: acc0 = acc0 + term; break;
                            case 1: acc1 = acc1 + term; break;
                            case 2: acc2 = acc2 + term; break;
                            default: acc3 = acc3 + term; break;
                        }
                    }
                }
                f0 += __half2float(acc0);
                f1 += __half2float(acc1);
                f2 += __half2float(acc2);
                f3 += __half2float(acc3);
                acc0 = acc1 = acc2 = acc3 = static_cast<__half>(0.0f);
            }
        }

        float acc[kMvRowsPerThread] = {f0, f1, f2, f3};
        if (write_vectorized) {
            float4 result;
            float* r = reinterpret_cast<float*>(&result);
            if (beta != 0.0) {
                float4 y4 = *reinterpret_cast<float4*>(&y[i0]);
                const float* yv = reinterpret_cast<const float*>(&y4);
                for (int k = 0; k < kMvRowsPerThread; ++k)
                    r[k] = static_cast<float>(alpha * static_cast<double>(acc[k]) + beta * static_cast<double>(yv[k]));
            } else {
                for (int k = 0; k < kMvRowsPerThread; ++k)
                    r[k] = static_cast<float>(alpha * static_cast<double>(acc[k]));
            }
            *reinterpret_cast<float4*>(&y[i0]) = result;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                double acc_d = static_cast<double>(acc[k]);
                y[i] = (beta != 0.0)
                           ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                           : static_cast<float>(alpha * acc_d);
            }
        }
    }
}

// Same grid sizing as the base wrapper above (natural block count, no
// occupancy query) and the same trailing cudaDeviceSynchronize.
template <int FLUSH>
static void mv_fp32_16_pure_half_narrow_vec_flush_launch(TransposeType trans, double alpha, size_t m, size_t n,
                                                         const uint16_t* wh, size_t ld_a, const float* x,
                                                         double beta, float* y) {
    int threads = kMvTileSize;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
    size_t blocks = (row_groups + threads - 1) / threads;
    if (blocks < 1) blocks = 1;
    mv_fp32_16_pure_half_narrow_vec_flush_kernel<FLUSH><<<static_cast<int>(blocks), threads>>>(
        trans, alpha, m, n, wh, ld_a, x, beta, y, row_groups);
    cudaDeviceSynchronize();
}

// Kernel-only wrappers (narrow_vec at EVERY M, like the base wrapper) --
// what the GEMV error benchmark calls, since its square shapes stay below
// kMvWideRowThreshold where the dispatchers below route elsewhere.
void mv_fp32_16_pure_half_narrow_vec_flush64(TransposeType trans, double alpha, size_t m, size_t n,
                                             const uint16_t* wh, size_t ld_a, const float* x, double beta,
                                             float* y) {
    mv_fp32_16_pure_half_narrow_vec_flush_launch<64>(trans, alpha, m, n, wh, ld_a, x, beta, y);
}
void mv_fp32_16_pure_half_narrow_vec_flush256(TransposeType trans, double alpha, size_t m, size_t n,
                                              const uint16_t* wh, size_t ld_a, const float* x, double beta,
                                              float* y) {
    mv_fp32_16_pure_half_narrow_vec_flush_launch<256>(trans, alpha, m, n, wh, ld_a, x, beta, y);
}

// Drop-in dispatchers with mv_fp32_16_pure_half_no_transpose_fast2's own
// signature and routing (below kMvWideRowThreshold: the cpasync_warpuniform
// kernel, unchanged; at/above it -- LSQR's M=1e6 -- the flushed narrow_vec).
template <int FLUSH>
static void mv_fp32_16_pure_half_no_transpose_flush_dispatch(double alpha, dim<2> size, const uint16_t* wh,
                                                             size_t ld_a, const float* x, size_t ld_x,
                                                             double beta, float* y, size_t ld_y) {
    if (size[0] < kMvWideRowThreshold) {
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform(
            TransposeType::NO_TRANSPOSE, alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
    } else {
        mv_fp32_16_pure_half_narrow_vec_flush_launch<FLUSH>(TransposeType::NO_TRANSPOSE, alpha, size[0], size[1],
                                                            wh, ld_a, x, beta, y);
    }
}
void mv_fp32_16_pure_half_no_transpose_flush64(double alpha, dim<2> size, const uint16_t* wh, size_t ld_a,
                                               const float* x, size_t ld_x, double beta, float* y, size_t ld_y) {
    mv_fp32_16_pure_half_no_transpose_flush_dispatch<64>(alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
}
void mv_fp32_16_pure_half_no_transpose_flush256(double alpha, dim<2> size, const uint16_t* wh, size_t ld_a,
                                                const float* x, size_t ld_x, double beta, float* y,
                                                size_t ld_y) {
    mv_fp32_16_pure_half_no_transpose_flush_dispatch<256>(alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
}

// ====================================================================
// SWAR (SIMD-within-a-register) decode sibling of the periodic-flush
// narrow_vec kernel above. The base decode (fp32_16_half_only_branchless_
// no_overflow_nomask) runs ~10 ALU instructions PER ELEMENT, and this
// kernel is ALU-bound (~86% ALU utilization in the earlier ncu profile)
// while mv_fp16_native_mixed -- no decode -- is memory-bound; that decode
// cost is the standing ~13% gap to native mixed at M=1e6, and the earlier
// bit-layout analysis showed no field reordering shrinks it. This is a
// different lever: decode TWO wh values per 32-bit register, so the masks,
// shifts and selects that act on each 16-bit field independently run once
// per pair instead of once per element, and the result comes out already
// packed as a __half2 (no per-pair __halves2half2).
//   sig  = ((w >> 1) & 0x01FF01FF) | 0x02000200      both lanes' 0x200|mant_hi
//   s0/s1 = ((w >> 10 / 26) & 0xF) | 16               each lane's shift_by,
//                                                     folded with the +16 that
//                                                     isolates that lane
//   h0 = (sig << 16) >> s0 ; h1 = sig >> s1            per-lane variable shift
//   h  = PRMT(h0, h1, 0x5410)                         pack the two 16-bit lanes
//   u  = (w & 0x80008000) | h                         sign | shifted mantissa
//   m  = (w & 0x00010001) * 0xFFFF                    per-lane control mask
//   out = (u & m) | (w & ~m)                          select
// The variable shift is the one step that cannot be shared between lanes
// (each lane has its own shift_by). Verified BIT-EXACT against the scalar
// decode on all 2^32 (lane0, lane1) input pairs by an exhaustive host check
// (including out-of-contract values), so this changes performance only.
__device__ __forceinline__ uint32_t fp32_16_half2_decode_swar(uint32_t w) {
    uint32_t sig = ((w >> 1) & 0x01FF01FFu) | 0x02000200u;
    uint32_t s0 = ((w >> 10) & 0xFu) | 16u;
    uint32_t s1 = ((w >> 26) & 0xFu) | 16u;
    uint32_t h0 = (sig << 16) >> s0;
    uint32_t h1 = sig >> s1;
    uint32_t h = __byte_perm(h0, h1, 0x5410);
    uint32_t underflow = (w & 0x80008000u) | h;
    uint32_t mask = (w & 0x00010001u) * 0xFFFFu;
    return (underflow & mask) | (w & ~mask);
}

// SWAR pair form of the LOSSY fast decode (fp32_16_half_only_fast): control=1
// lanes saturate to signed Inf (direction=1) or signed zero (direction=0),
// no shift-based subnormal reconstruction -- so ~7 ALU ops per PAIR instead
// of the ~19 of the exact decode above. Same accuracy trade as the scalar
// fast decode (flushes the whole underflow band to zero; stalls LSQR on
// matrices with a large underflow fraction) -- benchmark/plot only.
__device__ __forceinline__ uint32_t fp32_16_half2_decode_fast_swar(uint32_t w) {
    uint32_t sat = (w & 0x80008000u) | (((w >> 14) & 0x00010001u) * 0x7C00u);
    uint32_t mask = (w & 0x00010001u) * 0xFFFFu;
    return (sat & mask) | (w & ~mask);
}

// Identical to mv_fp32_16_pure_half_narrow_vec_flush_kernel<FLUSH> except the
// vectorized path loads the four wh as two 32-bit words and decodes each
// with the SWAR pair decode. The non-vectorized fallback keeps the scalar
// decode (it is the rare path -- unaligned ld_a or a ragged tail).
// FAST=true swaps in the LOSSY fast decode (SWAR pair form above, scalar
// fp32_16_half_only_fast in the fallback) -- the exact decode stays the
// default.
template <int FLUSH, bool FAST = false>
__global__ void mv_fp32_16_pure_half_narrow_vec_flush_swar_kernel(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* __restrict__ x, double beta, float* y, size_t total_row_groups) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t stride = static_cast<size_t>(gridDim.x) * static_cast<size_t>(blockDim.x);

    for (size_t group = blockIdx.x * blockDim.x + threadIdx.x; group < total_row_groups; group += stride) {
        size_t i0 = group * static_cast<size_t>(kMvRowsPerThread);
        bool write_vectorized = (i0 + kMvRowsPerThread <= rows_op);
        bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                          write_vectorized &&
                          (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

        float f0 = 0.0f, f1 = 0.0f, f2 = 0.0f, f3 = 0.0f;
        if (vectorized) {
            __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
            __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
            for (size_t jb = 0; jb < cols_op; jb += FLUSH) {
                size_t je = min(jb + static_cast<size_t>(FLUSH), cols_op);
                for (size_t j = jb; j < je; ++j) {
                    __half x_val = static_cast<__half>(__ldg(&x[j]));
                    size_t base = i0 + j * ld_a;
                    uint2 raw = *reinterpret_cast<const uint2*>(&wh[base]);
                    uint32_t d01 = FAST ? fp32_16_half2_decode_fast_swar(raw.x) : fp32_16_half2_decode_swar(raw.x);
                    uint32_t d23 = FAST ? fp32_16_half2_decode_fast_swar(raw.y) : fp32_16_half2_decode_swar(raw.y);
                    __half2 a01 = *reinterpret_cast<__half2*>(&d01);
                    __half2 a23 = *reinterpret_cast<__half2*>(&d23);
                    __half2 x_val2 = __half2half2(x_val);
                    acc01 = __hfma2(a01, x_val2, acc01);
                    acc23 = __hfma2(a23, x_val2, acc23);
                }
                f0 += __half2float(__low2half(acc01));
                f1 += __half2float(__high2half(acc01));
                f2 += __half2float(__low2half(acc23));
                f3 += __half2float(__high2half(acc23));
                acc01 = __half2half2(static_cast<__half>(0.0f));
                acc23 = __half2half2(static_cast<__half>(0.0f));
            }
        } else {
            __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
            __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
            for (size_t jb = 0; jb < cols_op; jb += FLUSH) {
                size_t je = min(jb + static_cast<size_t>(FLUSH), cols_op);
                for (size_t j = jb; j < je; ++j) {
                    __half x_val = static_cast<__half>(__ldg(&x[j]));
                    for (int k = 0; k < kMvRowsPerThread; ++k) {
                        size_t i = i0 + static_cast<size_t>(k);
                        if (i >= rows_op) break;
                        size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                        size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                        size_t idx = a_row + a_col * ld_a;
                        __half a_val = FAST ? fp32_16_half_only_fast(wh[idx])
                                            : fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                        __half term = a_val * x_val;
                        switch (k) {
                            case 0: acc0 = acc0 + term; break;
                            case 1: acc1 = acc1 + term; break;
                            case 2: acc2 = acc2 + term; break;
                            default: acc3 = acc3 + term; break;
                        }
                    }
                }
                f0 += __half2float(acc0);
                f1 += __half2float(acc1);
                f2 += __half2float(acc2);
                f3 += __half2float(acc3);
                acc0 = acc1 = acc2 = acc3 = static_cast<__half>(0.0f);
            }
        }

        float acc[kMvRowsPerThread] = {f0, f1, f2, f3};
        if (write_vectorized) {
            float4 result;
            float* r = reinterpret_cast<float*>(&result);
            if (beta != 0.0) {
                float4 y4 = *reinterpret_cast<float4*>(&y[i0]);
                const float* yv = reinterpret_cast<const float*>(&y4);
                for (int k = 0; k < kMvRowsPerThread; ++k)
                    r[k] = static_cast<float>(alpha * static_cast<double>(acc[k]) + beta * static_cast<double>(yv[k]));
            } else {
                for (int k = 0; k < kMvRowsPerThread; ++k)
                    r[k] = static_cast<float>(alpha * static_cast<double>(acc[k]));
            }
            *reinterpret_cast<float4*>(&y[i0]) = result;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                double acc_d = static_cast<double>(acc[k]);
                y[i] = (beta != 0.0)
                           ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                           : static_cast<float>(alpha * acc_d);
            }
        }
    }
}

template <int FLUSH, bool FAST = false>
static void mv_fp32_16_pure_half_narrow_vec_flush_swar_launch(TransposeType trans, double alpha, size_t m,
                                                              size_t n, const uint16_t* wh, size_t ld_a,
                                                              const float* x, double beta, float* y) {
    int threads = kMvTileSize;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
    size_t blocks = (row_groups + threads - 1) / threads;
    if (blocks < 1) blocks = 1;
    mv_fp32_16_pure_half_narrow_vec_flush_swar_kernel<FLUSH, FAST><<<static_cast<int>(blocks), threads>>>(
        trans, alpha, m, n, wh, ld_a, x, beta, y, row_groups);
    cudaDeviceSynchronize();
}

// Kernel-only wrapper (every M, for the GEMV error benchmark) and the
// fast2-shaped drop-in dispatcher (below kMvWideRowThreshold: the
// cpasync_warpuniform kernel unchanged; at/above it: this kernel).
void mv_fp32_16_pure_half_narrow_vec_flush256_swar(TransposeType trans, double alpha, size_t m, size_t n,
                                                   const uint16_t* wh, size_t ld_a, const float* x, double beta,
                                                   float* y) {
    mv_fp32_16_pure_half_narrow_vec_flush_swar_launch<256>(trans, alpha, m, n, wh, ld_a, x, beta, y);
}
void mv_fp32_16_pure_half_no_transpose_flush256_swar(double alpha, dim<2> size, const uint16_t* wh, size_t ld_a,
                                                     const float* x, size_t ld_x, double beta, float* y,
                                                     size_t ld_y) {
    if (size[0] < kMvWideRowThreshold) {
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_cpasync_warpuniform(
            TransposeType::NO_TRANSPOSE, alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
    } else {
        mv_fp32_16_pure_half_narrow_vec_flush_swar_launch<256>(TransposeType::NO_TRANSPOSE, alpha, size[0],
                                                               size[1], wh, ld_a, x, beta, y);
    }
}

// LOSSY fast-decode sibling of flush256_swar: same flush-every-256 float
// accumulation and SWAR pair decode structure, but with fp32_16_half_only_fast
// semantics (whole underflow band -> 0). Dispatcher mirrors the fast-decode
// path LSQR takes under TOMOS_FP32_16_PURE_HALF_FAST_DECODE (fast wide-ilp
// kernel below kMvWideRowThreshold). Benchmark/plot only -- NOT wired into
// LSQR.
void mv_fp32_16_pure_half_fast_wide_ilp_shared_half2_atomic_best(TransposeType trans, double alpha, dim<2> size,
                                                                 const uint16_t* wh, size_t ld_a, const float* x,
                                                                 size_t ld_x, double beta, float* y, size_t ld_y);
void mv_fp32_16_pure_half_narrow_vec_flush256_fast_swar(TransposeType trans, double alpha, size_t m, size_t n,
                                                        const uint16_t* wh, size_t ld_a, const float* x,
                                                        double beta, float* y) {
    mv_fp32_16_pure_half_narrow_vec_flush_swar_launch<256, true>(trans, alpha, m, n, wh, ld_a, x, beta, y);
}
void mv_fp32_16_pure_half_no_transpose_flush256_fast_swar(double alpha, dim<2> size, const uint16_t* wh,
                                                          size_t ld_a, const float* x, size_t ld_x, double beta,
                                                          float* y, size_t ld_y) {
    if (size[0] < kMvWideRowThreshold) {
        mv_fp32_16_pure_half_fast_wide_ilp_shared_half2_atomic_best(TransposeType::NO_TRANSPOSE, alpha, size, wh,
                                                                    ld_a, x, ld_x, beta, y, ld_y);
    } else {
        mv_fp32_16_pure_half_narrow_vec_flush_swar_launch<256, true>(TransposeType::NO_TRANSPOSE, alpha, size[0],
                                                                     size[1], wh, ld_a, x, beta, y);
    }
}

// test-new3: rows-per-thread=2 sibling of the kernel above -- mechanical
// duplicate with kMvRowsPerThread (4) replaced by kMvRowsPerThreadTest3
// (2) throughout (ushort2/float2 vectorized load-store instead of
// ushort4/float4, one half2 accumulator instead of two), trading register-
// blocking (fewer, larger-work threads -- 4 rows/thread) for more
// parallelism (more, smaller-work threads -- 2 rows/thread). Exists to
// test whether the base kernel's own low achieved occupancy (65% vs.
// --explicit-duplicates' 95%, both ncu-measured at the real LSQR shape --
// see decode.md) is actually costing real throughput, or whether this
// kernel is ALU-bound enough (per this session's earlier ncu finding,
// ~82% ALU utilization) that more occupancy doesn't help. UNTESTED --
// built purely to measure; register-blocking-vs-occupancy could go either
// way at this shape.
static constexpr int kMvRowsPerThreadTest3 = 2;

__global__ void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec2_vec2store_gridstride_nomask_half2acc_kernel(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* __restrict__ x, double beta, float* y, size_t total_row_groups) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t stride = static_cast<size_t>(gridDim.x) * static_cast<size_t>(blockDim.x);

    for (size_t group = blockIdx.x * blockDim.x + threadIdx.x; group < total_row_groups; group += stride) {
        size_t i0 = group * static_cast<size_t>(kMvRowsPerThreadTest3);
        bool write_vectorized = (i0 + kMvRowsPerThreadTest3 <= rows_op);
        bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                          write_vectorized &&
                          (ld_a % static_cast<size_t>(kMvRowsPerThreadTest3) == 0);

        __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
        if (vectorized) {
            __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
            for (size_t j = 0; j < cols_op; ++j) {
                __half x_val = static_cast<__half>(__ldg(&x[j]));
                size_t base = i0 + j * ld_a;
                ushort2 raw = *reinterpret_cast<const ushort2*>(&wh[base]);
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(raw.x);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(raw.y);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 x_val2 = __half2half2(x_val);
                acc01 = __hfma2(a01, x_val2, acc01);
            }
            acc0 = __low2half(acc01);
            acc1 = __high2half(acc01);
        } else {
            for (size_t j = 0; j < cols_op; ++j) {
                __half x_val = static_cast<__half>(__ldg(&x[j]));
                for (int k = 0; k < kMvRowsPerThreadTest3; ++k) {
                    size_t i = i0 + static_cast<size_t>(k);
                    if (i >= rows_op) break;
                    size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                    size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                    size_t idx = a_row + a_col * ld_a;
                    __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                    __half term = a_val * x_val;
                    switch (k) {
                        case 0: acc0 = acc0 + term; break;
                        default: acc1 = acc1 + term; break;
                    }
                }
            }
        }

        __half acc[kMvRowsPerThreadTest3] = {acc0, acc1};
        if (write_vectorized) {
            float2 result;
            float* r = reinterpret_cast<float*>(&result);
            if (beta != 0.0) {
                float2 y2 = *reinterpret_cast<float2*>(&y[i0]);
                const float* yv = reinterpret_cast<const float*>(&y2);
                for (int k = 0; k < kMvRowsPerThreadTest3; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                    r[k] = static_cast<float>(alpha * acc_d + beta * static_cast<double>(yv[k]));
                }
            } else {
                for (int k = 0; k < kMvRowsPerThreadTest3; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                    r[k] = static_cast<float>(alpha * acc_d);
                }
            }
            *reinterpret_cast<float2*>(&y[i0]) = result;
        } else {
            for (int k = 0; k < kMvRowsPerThreadTest3; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                y[i] = (beta != 0.0)
                          ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                          : static_cast<float>(alpha * acc_d);
            }
        }
    }
}

void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec2_vec2store_gridstride_nomask_half2acc(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a, const float* x,
    double beta, float* y) {
    int threads = kMvTileSize;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t row_groups = (rows_op + kMvRowsPerThreadTest3 - 1) / kMvRowsPerThreadTest3;
    size_t blocks = (row_groups + threads - 1) / threads;
    if (blocks < 1) blocks = 1;

    mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec2_vec2store_gridstride_nomask_half2acc_kernel<<<
        static_cast<int>(blocks), threads>>>(trans, alpha, m, n, wh, ld_a, x, beta, y, row_groups);
    cudaDeviceSynchronize();
}

// test-new4: rows-per-thread=8 sibling -- the OPPOSITE direction from
// test-new3 above. test-new3 (rows/thread=2, more occupancy, less
// register-blocking) measured WORSE than the base kMvRowsPerThread=4
// kernel at the real LSQR shape, confirming this kernel is ALU-bound
// (per this session's earlier ncu finding, ~82% ALU utilization) rather
// than occupancy-limited despite its low 65% achieved occupancy. This
// tests whether the trend continues in the other direction: MORE
// register-blocking (8 rows/thread instead of 4) further amortizing
// per-element loop overhead (fewer group iterations, fewer redundant
// x_val reloads, fewer loop-control instructions per useful FMA).
// UNTESTED -- could plateau or reverse (occupancy is already down to
// 65% at rows/thread=4; going to 8 pushes it lower still, and register
// pressure grows with more live accumulators, risking spills).
static constexpr int kMvRowsPerThreadTest4 = 8;

__global__ void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec4x2_vec4x2store_gridstride_nomask_half2acc_kernel(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* __restrict__ x, double beta, float* y, size_t total_row_groups) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t stride = static_cast<size_t>(gridDim.x) * static_cast<size_t>(blockDim.x);

    for (size_t group = blockIdx.x * blockDim.x + threadIdx.x; group < total_row_groups; group += stride) {
        size_t i0 = group * static_cast<size_t>(kMvRowsPerThreadTest4);
        bool write_vectorized = (i0 + kMvRowsPerThreadTest4 <= rows_op);
        bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                          write_vectorized &&
                          (ld_a % static_cast<size_t>(kMvRowsPerThreadTest4) == 0);

        __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
        __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
        __half acc4 = static_cast<__half>(0.0f), acc5 = static_cast<__half>(0.0f);
        __half acc6 = static_cast<__half>(0.0f), acc7 = static_cast<__half>(0.0f);
        if (vectorized) {
            __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
            __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
            __half2 acc45 = __half2half2(static_cast<__half>(0.0f));
            __half2 acc67 = __half2half2(static_cast<__half>(0.0f));
            for (size_t j = 0; j < cols_op; ++j) {
                __half x_val = static_cast<__half>(__ldg(&x[j]));
                __half2 x_val2 = __half2half2(x_val);
                size_t base = i0 + j * ld_a;
                ushort4 raw_lo = *reinterpret_cast<const ushort4*>(&wh[base]);
                ushort4 raw_hi = *reinterpret_cast<const ushort4*>(&wh[base + 4]);
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(raw_lo.x);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(raw_lo.y);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(raw_lo.z);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(raw_lo.w);
                __half a4 = fp32_16_half_only_branchless_no_overflow_nomask(raw_hi.x);
                __half a5 = fp32_16_half_only_branchless_no_overflow_nomask(raw_hi.y);
                __half a6 = fp32_16_half_only_branchless_no_overflow_nomask(raw_hi.z);
                __half a7 = fp32_16_half_only_branchless_no_overflow_nomask(raw_hi.w);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 a45 = __halves2half2(a4, a5);
                __half2 a67 = __halves2half2(a6, a7);
                acc01 = __hfma2(a01, x_val2, acc01);
                acc23 = __hfma2(a23, x_val2, acc23);
                acc45 = __hfma2(a45, x_val2, acc45);
                acc67 = __hfma2(a67, x_val2, acc67);
            }
            acc0 = __low2half(acc01); acc1 = __high2half(acc01);
            acc2 = __low2half(acc23); acc3 = __high2half(acc23);
            acc4 = __low2half(acc45); acc5 = __high2half(acc45);
            acc6 = __low2half(acc67); acc7 = __high2half(acc67);
        } else {
            for (size_t j = 0; j < cols_op; ++j) {
                __half x_val = static_cast<__half>(__ldg(&x[j]));
                for (int k = 0; k < kMvRowsPerThreadTest4; ++k) {
                    size_t i = i0 + static_cast<size_t>(k);
                    if (i >= rows_op) break;
                    size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                    size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                    size_t idx = a_row + a_col * ld_a;
                    __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                    __half term = a_val * x_val;
                    switch (k) {
                        case 0: acc0 = acc0 + term; break;
                        case 1: acc1 = acc1 + term; break;
                        case 2: acc2 = acc2 + term; break;
                        case 3: acc3 = acc3 + term; break;
                        case 4: acc4 = acc4 + term; break;
                        case 5: acc5 = acc5 + term; break;
                        case 6: acc6 = acc6 + term; break;
                        default: acc7 = acc7 + term; break;
                    }
                }
            }
        }

        __half acc[kMvRowsPerThreadTest4] = {acc0, acc1, acc2, acc3, acc4, acc5, acc6, acc7};
        if (write_vectorized) {
            float4 result_lo, result_hi;
            float* r_lo = reinterpret_cast<float*>(&result_lo);
            float* r_hi = reinterpret_cast<float*>(&result_hi);
            if (beta != 0.0) {
                float4 y4_lo = *reinterpret_cast<float4*>(&y[i0]);
                float4 y4_hi = *reinterpret_cast<float4*>(&y[i0 + 4]);
                const float* yv_lo = reinterpret_cast<const float*>(&y4_lo);
                const float* yv_hi = reinterpret_cast<const float*>(&y4_hi);
                for (int k = 0; k < 4; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                    r_lo[k] = static_cast<float>(alpha * acc_d + beta * static_cast<double>(yv_lo[k]));
                }
                for (int k = 0; k < 4; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k + 4]));
                    r_hi[k] = static_cast<float>(alpha * acc_d + beta * static_cast<double>(yv_hi[k]));
                }
            } else {
                for (int k = 0; k < 4; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                    r_lo[k] = static_cast<float>(alpha * acc_d);
                }
                for (int k = 0; k < 4; ++k) {
                    double acc_d = static_cast<double>(static_cast<float>(acc[k + 4]));
                    r_hi[k] = static_cast<float>(alpha * acc_d);
                }
            }
            *reinterpret_cast<float4*>(&y[i0]) = result_lo;
            *reinterpret_cast<float4*>(&y[i0 + 4]) = result_hi;
        } else {
            for (int k = 0; k < kMvRowsPerThreadTest4; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                double acc_d = static_cast<double>(static_cast<float>(acc[k]));
                y[i] = (beta != 0.0)
                          ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                          : static_cast<float>(alpha * acc_d);
            }
        }
    }
}

void mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec4x2_vec4x2store_gridstride_nomask_half2acc(
    TransposeType trans, double alpha, size_t m, size_t n, const uint16_t* wh, size_t ld_a, const float* x,
    double beta, float* y) {
    int threads = kMvTileSize;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t row_groups = (rows_op + kMvRowsPerThreadTest4 - 1) / kMvRowsPerThreadTest4;
    size_t blocks = (row_groups + threads - 1) / threads;
    if (blocks < 1) blocks = 1;

    mv_fp32_16_pure_half_branchless_no_overflow_narrow_vec4x2_vec4x2store_gridstride_nomask_half2acc_kernel<<<
        static_cast<int>(blocks), threads>>>(trans, alpha, m, n, wh, ld_a, x, beta, y, row_groups);
    cudaDeviceSynchronize();
}

__global__ void mv_fp32_16_pure_half_branchless_no_overflow_wide_ilp_shared_half2_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

