            trans, alpha, size[0], size[1], A, ld_a, x, beta, y);
    }
}

void mv_fp16_native_storage_fastequiv_wide_ilp_shared_half2_atomic_best(TransposeType trans,
                                                             double alpha, dim<2> size,
                                                             const __half* A,
                                                             size_t ld_a, const float* x,
                                                             size_t ld_x, double beta,
                                                             float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    if (rows_op >= kMvHalf2AtomicBestCrossoverThreshold) {
        mv_fp16_native_storage_fastequiv_wide_ilp_shared_half2_atomic_wide4x(trans, alpha, size, A, ld_a, x,
                                                                  ld_x, beta, y, ld_y);
        return;
    }
    mv_fp16_native_storage_fastequiv_wide_ilp_shared_bigtile_half2_atomic(trans, alpha, size, A, ld_a, x,
                                                               ld_x, beta, y, ld_y);
}

// ====================================================================
// TOMOS FP32/FP16 (mixed precision): NEW kernel, ADDITIVE only -- does
// not modify any existing kernel. Based on mv_fp32_16_pure_half_wide_
// ilp_shared_half2_atomic_kernel ("TOMOS FP16", promoted above), but any
// wh entry that needs the special 8-bit-exponent encoding (control=1,
// either "extended" or "degraded" -- see fp32_16_pack.hpp's own header
// comment) is decoded EXACTLY via fp32_16_combine(wh,wr) instead of
// saturating to +-Infinity/0 the way fp32_16_half_only does. That is why
// this kernel takes wr as an extra parameter, unlike every other kernel
// in the pure_half family (deliberately wh-only): recovering the
// degraded branch's value is impossible without it -- its exponent lives
// ONLY in wr (see fp32_16_half_only's own comment for the full
// derivation).
//
// For those control=1 entries specifically: the matching x value is read
// directly from the original float x array (NOT the shared __half
// x_tile every control=0 lane uses, which has already lost precision),
// the multiply happens in float, and only the RESULT is narrowed to
// __half -- the same precision the running accumulator already uses --
// before being added in. So the accumulator itself never widens; only
// that one term's multiply briefly happens at higher precision.
//
// Deliberately scalar (no half2/4-wide-unrolled ILP the base kernel
// uses): the per-element branch this requires (which decode function,
// which x source) doesn't pack cleanly into __hfma2, and this kernel
// targets correctness on the rare special-encoded entries it exists for,
// not raw throughput on the common case -- that is still plain "TOMOS
// FP16" (mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_kernel above,
// unmodified).
//
// Scope: only the small-rows_op ("wide matrix") regime gets this mixed-
// precision treatment (see the host wrapper below) -- narrow-column and
// large-rows_op shapes fall through to the existing, UNCHANGED safe
// pure_half kernels (mv_fp32_16_pure_half_tiled_kernel / mv_fp32_16_
// pure_half_narrow_vec_kernel), same as every other wrapper in this file.
//
// UNTESTED: no correctness or performance measurement has been run yet.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_mixed_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh,
    const uint16_t* wr, size_t ld_a, const float* x, size_t col_splits,
    double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half acc = static_cast<__half>(0.0f);
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                uint16_t raw_wh = wh[idx];
                if ((raw_wh & 0x1u) == 0u) {
                    // control=0: ordinary half, same fast path as plain
                    // "TOMOS FP16" -- decode via wh alone, multiply/
                    // accumulate entirely in half.
                    __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(raw_wh);
                    acc = acc + a_val * x_tile[jj];
                } else {
                    // control=1 (extended or degraded): needs wr too --
                    // exact FP32 decode, FP32 multiply against the
                    // ORIGINAL (not half-narrowed) x value, then narrowed
                    // to the accumulator's own precision before the add.
                    float a_val_f = fp32_16_combine(raw_wh, wr[idx]);
                    float term_f = a_val_f * x[j];
                    acc = acc + static_cast<__half>(term_f);
                }
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// Host wrapper for mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_
// mixed_kernel above -- SAME grid/col_splits/beta-handling as mv_fp32_16_
// pure_half_wide_ilp_shared_half2_atomic's own wrapper (cudaMemset when
// beta==0, a small prescale kernel otherwise, no malloc/free of any
// kind). Only the small-rows_op branch calls the new mixed kernel (and
// needs wr for it); the narrow-column and large-rows_op branches reuse
// the existing, unmodified safe pure_half kernels exactly as every other
// wrapper in this file does, so those two shapes are unaffected by this
// addition.
//
// UNTESTED: no correctness or performance measurement has been run yet.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_mixed(TransposeType trans,
                                                              double alpha, dim<2> size,
                                                              const uint16_t* wh,
                                                              const uint16_t* wr,
                                                              size_t ld_a, const float* x,
                                                              size_t ld_x, double beta,
                                                              float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        if (beta == 0.0) {
            cudaMemset(y, 0, rows_op * sizeof(float));
        } else {
            int threads = kMvTileSize;
            int blocks = (rows_op + threads - 1) / threads;
            mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_mixed_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, wr, ld_a, x, col_splits, alpha, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}
// ====================================================================
// END TOMOS FP32/FP16 (mixed precision).
// ====================================================================

// "TOMOS FP32/FP16 (fast)", new version -- ports the OLD "(fast)"
// relationship (mv_fp32_16_pure_half_wide_ilp_shared_fasthalf: UNSAFE-on-
// arbitrary-data sibling of the OLD plain half2 kernel, decode swapped
// from fp32_16_half_only to fp32_16_fast_half, an unconditional bit-
// reinterpret only correct when every wh value already has control=0) to
// "TOMOS FP16"'s own CURRENT atomicAdd-combine dispatcher instead of that
// older plain kernel. IDENTICAL to mv_fp32_16_pure_half_wide_ilp_shared_
// half2_atomic_kernel above except every fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]) call
// is replaced with fp32_16_fast_half(wh[idx]). SAME CORRECTNESS CAVEAT AS
// THE OLD KERNEL (CONFIRMED there, inherited here unchanged): only valid
// on data PROVABLY never extended/degraded-encoded (control=1) -- must be
// tested against a dedicated safe-range generator (gen_fp32_16_wh_safe's
// own convention), never the plain data every other series in this file
// uses.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_fasthalf_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_fast_half(wh[idx0]);
                __half a1 = fp32_16_fast_half(wh[idx1]);
                __half a2 = fp32_16_fast_half(wh[idx2]);
                __half a3 = fp32_16_fast_half(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_fast_half(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

// Host wrapper for mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_
// fasthalf_kernel above -- same grid/col_splits/beta-handling as mv_
// fp32_16_pure_half_wide_ilp_shared_half2_atomic's own wrapper. No
// trailing cudaDeviceSynchronize, same precedent.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_fasthalf(TransposeType trans,
                                                                 double alpha, dim<2> size,
                                                                 const uint16_t* wh,
                                                                 size_t ld_a, const float* x,
                                                                 size_t ld_x, double beta,
                                                                 float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        if (beta == 0.0) {
            cudaMemset(y, 0, rows_op * sizeof(float));
        } else {
            int threads = kMvTileSize;
            int blocks = (rows_op + threads - 1) / threads;
            mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_fasthalf_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

// "test" -- combines "TOMOS FP32/FP16 (fast)"'s own new atomicAdd combine
// with a 4x-larger shared-memory tile, the fasthalf analog of mv_fp32_16_
// pure_half_wide_ilp_shared_bigtile_half2_atomic. Same CORRECTNESS CAVEAT
// as mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_fasthalf_kernel
// above.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_bigtile_half2_atomic_fasthalf_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvWideBigTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvWideBigTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvWideBigTileSize),
                              col_end - tile_start);
        for (size_t k = threadIdx.x; k < tile_len; k += blockDim.x)
            x_tile[k] = static_cast<__half>(x[tile_start + k]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_fast_half(wh[idx0]);
                __half a1 = fp32_16_fast_half(wh[idx1]);
                __half a2 = fp32_16_fast_half(wh[idx2]);
                __half a3 = fp32_16_fast_half(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_fast_half(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc);
        atomicAdd(&y[i], contribution);
    }
}

