// Dispatch threshold for mv_fp32_16_pure_half_wide_ilp_shared_half2_
// atomic_fasthalf_best below -- a SEPARATE constant from kMvHalf2Atomic
// BestCrossoverThreshold (the safe-decode dispatcher's own), even though
// both currently hold 4096, following this file's own established
// convention of per-family threshold constants: this value is carried
// over unchanged from that dispatcher's own choice, NOT independently
// re-derived for the fasthalf decode.
static constexpr size_t kMvFasthalfAtomicBestCrossoverThreshold = 4096;

// "TOMOS FP32/FP16 (fast), best-of" -- same dispatch-not-merge idea as
// mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_best (the safe-decode
// dispatcher this is based on): below kMvFasthalfAtomicBestCrossover
// Threshold rows, calls mv_fp32_16_pure_half_wide_ilp_shared_bigtile_
// half2_atomic_fasthalf; at/above it, calls mv_fp32_16_pure_half_wide_
// ilp_shared_half2_atomic_fasthalf_wide4x. No workspace needed (neither
// callee owns a buffer). Neither callee has been benchmarked against the
// other, against mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_
// fasthalf alone, or against the OLD mv_fp32_16_pure_half_wide_ilp_
// shared_fasthalf_workspace yet -- and, per the shared correctness
// caveat, only valid on the dedicated safe-range data gen_fp32_16_wh_safe
// generates.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_fasthalf_best(TransposeType trans,
                                                                     double alpha, dim<2> size,
                                                                     const uint16_t* wh,
                                                                     size_t ld_a, const float* x,
                                                                     size_t ld_x, double beta,
                                                                     float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    if (rows_op >= kMvFasthalfAtomicBestCrossoverThreshold) {
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_fasthalf_wide4x(trans, alpha, size, wh, ld_a, x,
                                                                          ld_x, beta, y, ld_y);
        return;
    }
    mv_fp32_16_pure_half_wide_ilp_shared_bigtile_half2_atomic_fasthalf(trans, alpha, size, wh, ld_a, x,
                                                                       ld_x, beta, y, ld_y);
}

// EXPERIMENTAL alternative to mv_fp32_16_pure_half_wide_kernel: every
// _wide_* variant above does scalar __half arithmetic (one multiply-add
// per instruction). This kernel instead packs pairs of the 4-way unroll's
// 4 columns into __half2 registers and uses __hfma2 to do 2 scalar half
// FMAs in a single instruction -- halving the compute instruction count
// for the same 4-column group (2 accumulators, acc01/acc23, each __half2,
// instead of 4 separate __half accumulators), on the hypothesis that fewer
// issued compute instructions per group could let more independent wh
// loads be in flight per cycle of issued work, similar in spirit to how
// the original 4-way unroll won over the 1-way baseline, but at the
// instruction-packing level rather than the loop-unrolling level. wh's
// decode still happens per-element (fp32_16_half_only takes one uint16_t
// at a time, no vectorized decode exists), so this does NOT reduce the
// number of loads -- only the arithmetic instruction count consuming
// them, unlike every prior variant that targeted the load side directly.
// x_tile is read as a packed __half2 (one 32-bit shared-memory load
// instead of two 16-bit ones) via reinterpret_cast, requiring x_tile to be
// 4-byte aligned (explicit __align__(4), since the 2-byte-element default
// alignment of a plain __half array isn't guaranteed sufficient for a
// __half2 reinterpret).
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}

// EXPERIMENTAL counterpart to mv_fp32_16_pure_half for direct comparison --
// see mv_fp32_16_pure_half_wide_ilp_shared_half2_kernel's comment.
// IDENTICAL grid/col_splits to mv_fp32_16_pure_half_wide_ilp_shared; only
// the main kernel's arithmetic differs (packed __half2 FMA instead of
// scalar __half). Narrow/tiled branches unchanged.
void mv_fp32_16_pure_half_wide_ilp_shared_half2(TransposeType trans,
                                                double alpha, dim<2> size,
                                                const uint16_t* wh,
                                                size_t ld_a, const float* x,
                                                size_t ld_x, double beta,
                                                float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// "test" -- mirrors mv_fp16_native_storage's own "_best"-style combine-
// strategy dispatch (see that function's comment in mv_cuda_kernels.cu,
// added after a real-hardware measurement found it dramatically better at
// small/medium M and only slightly worse at large M): reduce-kernel
// combine (mv_fp32_16_pure_half_wide_ilp_shared_half2 above, this whole
// investigation's historically-fastest safe-decode series, 78-90% of
// cuBLAS in CSVs from 2026-08-31) below a crossover row count, atomicAdd
// combine (mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_best above,
// "TOMOS FP16 (implicit)" itself) at/above it. Tests whether the SAME
// atomic-contention-at-small-M mechanism that explained native storage's
// own small-M catastrophe (col_splits blocks all atomicAdd-contending on
// a small number of output rows) also afflicts THIS safe-decode packed-
// storage family -- which uses a DIFFERENT col_splits formula
// (choose_col_splits_target(...,kMvTargetTotalThreads*4) via wide4x/best,
// vs native storage's choose_col_splits_fp32, kMvTargetTotalThreads*1),
// so the severity may differ; not assumed to transfer 1:1. Crossover
// reused from native storage's own measurement (8192) as a starting
// point, not independently re-tuned for THIS family yet -- the whole
// point of plotting this as "test" is to find out whether it should be.
static constexpr size_t kMvPureHalfCombineBestCrossoverThreshold = 8192;

void mv_fp32_16_pure_half_wide_ilp_shared_half2_combine_best(TransposeType trans, double alpha, dim<2> size,
                                                              const uint16_t* wh, size_t ld_a, const float* x,
                                                              size_t ld_x, double beta, float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    if (rows_op < kMvPureHalfCombineBestCrossoverThreshold) {
        mv_fp32_16_pure_half_wide_ilp_shared_half2(trans, alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
    } else {
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_best(trans, alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
    }
}

// "test" -- isolates whether removing fp32_16_half_only's own branch
// instruction (via fp32_16_half_only_branchless, a bit-exact bitwise-mask
// reformulation) helps once it's NOT also confounded with losing __hfma2
// packing. mv_fp32_16_pure_half_wide_ilp_shared_branchless (see its own
// comment) already tested a branchless decode, but on the OLDER, pre-
// half2 scalar-accumulator body (4 independent __half += a*x, not packed
// into __half2) -- MEASURED on real A100 NO_TRANSPOSE hardware to be
// 20%-30% SLOWER than mv_fp32_16_pure_half_wide_ilp_shared_half2 itself
// at every square size (e.g. M=8192: 1011.7 -> 712.7 GFlop/s; M=65536:
// 1104.3 -> 867.1 GFlop/s), the opposite of its own intended purpose --
// diagnosed as the lost __hfma2 packing (2 real half FMAs/instruction)
// costing more than the branch removal saved, not a decode-cost finding
// at all. This kernel is the fair isolation: IDENTICAL to mv_fp32_16_
// pure_half_wide_ilp_shared_half2_kernel above (same __hfma2-packed 4-way
// unroll, same shared x_tile) with ONLY fp32_16_half_only swapped for
// fp32_16_half_only_branchless -- so any measured difference from half2
// itself now isolates the branch/no-branch question alone.
//
// CONFIRMED NEGATIVE RESULT on real A100 NO_TRANSPOSE hardware, even in
// this fair isolation: 10%-23% SLOWER than mv_fp32_16_pure_half_wide_ilp_
// shared_half2 itself at every square size (M=8192: 1057.0 -> 823.1
// GFlop/s; M=16384: 1062.4 -> 819.9; M=65536: 1104.7 -> 987.8) -- better
// than the scalar branchless kernel's own -30% (confirming SOME of that
// gap really was the lost __hfma2 packing), but still a real, consistent
// regression with packing kept intact. This FLIPS the original
// hypothesis: on this workload's data (control=0 vastly dominant in
// practice), fp32_16_half_only's own branch is cheap -- well-predicted,
// nearly free -- while fp32_16_half_only_branchless's unconditional
// bitwise masks pay real ALU cost on EVERY element regardless of which
// path it would have taken. Trading a well-predicted branch for
// guaranteed extra work is a net loss, not a neutral-or-better swap.
// Also explains why mv_fp32_16_pure_half_wide_ilp_shared_fasthalf still
// wins outright: its own gain was never about removing a branch -- it's
// about skipping the control=1 handling's WORK entirely, which only its
// unsafe (every-element-must-be-control=0) contract can do. No decode
// swap that stays correct on arbitrary data has recovered any of that gap
// so far -- closing it further would need reducing total decode work by
// some other means, not branch removal.
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_branchless_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}

// Returns the number of doubles mv_fp32_16_pure_half_wide_ilp_shared_
// half2_branchless_workspace's wide (split-K) path needs -- same formula/
// contract as mv_fp32_16_pure_half_wide_ilp_shared_fasthalf_workspace_
// size above (0 for shapes that don't dispatch to the wide path).
size_t mv_fp32_16_pure_half_wide_ilp_shared_half2_branchless_workspace_size(TransposeType trans, dim<2> size) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op >= kMvWideRowThreshold) return 0;
    int col_splits = choose_col_splits(rows_op, cols_op);
    return rows_op * static_cast<size_t>(col_splits);
}

// Workspace-buffered host wrapper for mv_fp32_16_pure_half_wide_ilp_
// shared_half2_branchless_kernel above -- caller-owned scratch buffer,
// same fix/rationale as mv_fp32_16_pure_half_wide_ilp_shared_fasthalf_
// workspace (built directly as a workspace function, no plain-malloc
// sibling, since every prior kernel in this family was measured with the
// malloc/free overhead removed first -- no reason to reintroduce it here
// just to match an older convention). SAME 3-way dispatch as mv_fp32_16_
// pure_half_wide_ilp_shared_half2's own wrapper -- only the wide path's
// kernel and buffer-ownership differ; tiled/narrow_vec fall back to the
// existing (still-branching) mv_fp32_16_pure_half_tiled_kernel/
// mv_fp32_16_pure_half_narrow_vec_kernel, same as every sibling in this
// family. Contract: workspace must be at least mv_fp32_16_pure_half_
// wide_ilp_shared_half2_branchless_workspace_size(trans, size) doubles;
// may be nullptr for shapes that don't reach the wide path.
//
// CONFIRMED NEGATIVE RESULT -- see mv_fp32_16_pure_half_wide_ilp_shared_
// half2_branchless_kernel's own comment above for the real A100
// measurements (10%-23% slower than mv_fp32_16_pure_half_wide_ilp_
// shared_half2_workspace at every square size).
void mv_fp32_16_pure_half_wide_ilp_shared_half2_branchless_workspace(TransposeType trans,
                                                                      double alpha, dim<2> size,
                                                                      const uint16_t* wh,
                                                                      size_t ld_a, const float* x,
                                                                      size_t ld_x, double beta,
                                                                      float* y, size_t ld_y,
                                                                      double* workspace) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_branchless_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, workspace);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, workspace, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

// Returns the number of doubles mv_fp32_16_pure_half_wide_ilp_shared_
// half2_workspace's wide (split-K) path needs -- same formula/contract as
// mv_fp32_16_pure_half_wide_ilp_shared_fasthalf_workspace_size above.
size_t mv_fp32_16_pure_half_wide_ilp_shared_half2_workspace_size(TransposeType trans, dim<2> size) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op >= kMvWideRowThreshold) return 0;
    int col_splits = choose_col_splits(rows_op, cols_op);
    return rows_op * static_cast<size_t>(col_splits);
}

// Workspace-buffered sibling of mv_fp32_16_pure_half_wide_ilp_shared_
// half2 above -- same "caller-owned scratch buffer instead of per-call
// cudaMalloc/cudaFree" fix as mv_fp32_16_pure_half_wide_ilp_shared_
// fasthalf_workspace above; see that function's own comment for the full
// rationale (same root cause, same fix, applies equally to every
// wide_ilp_shared-family kernel since they all share this exact host-
// wrapper pattern). No trailing cudaDeviceSynchronize() -- same reasoning
// as mv_fp32_16_accurate_workspace's own lack of one.
//
// PROMOTED for square NO_TRANSPOSE shapes -- CONFIRMED on real A100
// hardware (mv_fp32_16_pure_half_vs_cublas_ref.cu, square M=K=1024-65536):
// same predicted small/medium-M win as mv_fp32_16_pure_half_wide_ilp_
// shared_fasthalf_workspace's own comment describes -- M=1024: 67.9 ->
// 91.6 GFlop/s (0.36x -> 0.49x of cuBLAS Hgemm); M=2048: 294.0 -> 400.4
// GFlop/s (0.50x -> 0.69x); M=3072: 526.6 -> 713.9 GFlop/s (0.47x ->
// 0.60x); converging to unchanged numbers by M=16384-65536 (0.92x/0.83x,
// same before and after).
//
// NOT promoted for tall-and-thin, same reason and same MEASURED collapse
// at M>=kMvWideRowThreshold (131072) as mv_fp32_16_pure_half_wide_ilp_
// shared_fasthalf_workspace's own comment documents (this function shares
// the identical 3-way dispatch) -- see kMvWideRowThreshold's own comment
// for the diagnosed root cause.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_workspace(TransposeType trans,
                                                           double alpha, dim<2> size,
                                                           const uint16_t* wh,
                                                           size_t ld_a, const float* x,
                                                           size_t ld_x, double beta,
                                                           float* y, size_t ld_y,
                                                           double* workspace) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, workspace);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, workspace, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}

// Forward declaration -- defined later in this file, alongside its other
// TRANSPOSE-specific callers; reused unchanged by mv_fp32_16_hybrid_wide_
// ilp_shared_kernel below.
__device__ inline void mv_fp32_16_hybrid_process_element(uint16_t whv, __half xval_half,
                                                          __half2& acc_cheap, float& acc_extended);

// NO_TRANSPOSE mirror of mv_fp32_16_hybrid_transpose_atomiconly_scaled_
// mblock_vec4_paired -- same "TOMOS FP32/FP16" wh-only extended-exponent
// reconstruction (mv_fp32_16_hybrid_process_element, reused unchanged)
// and same adjacent-pair __hfma2 packing when both elements are cheap
// (control=0), but built on mv_fp32_16_pure_half_wide_ilp_shared_half2's
// own generic trans-dispatched structure instead of the TRANSPOSE-only
// warp-per-column/ushort4 one. That TRANSPOSE structure doesn't carry
// over: it vectorizes wh loads by pairing ADJACENT ROWS within one
// output column, which only exists because TRANSPOSE's column-major
// storage makes adjacent rows of a fixed column contiguous. For
// NO_TRANSPOSE (one thread per output row, sweeping K across columns),
// the roles invert -- for a FIXED row, adjacent K-columns are ld_a
// apart, not contiguous, so no per-thread vector load of wh is possible
// there either way; the wide_ilp_shared family's own 4-way unroll
// already gets its memory-bandwidth win a different way, from adjacent
// THREADS (adjacent rows i, i+1, i+2...) reading adjacent addresses for
// the SAME column j -- i.e. already-coalesced across the warp, not
// vectorized within a lane. So this kernel keeps that same 4-independent-
// scalar-loads structure unchanged, and only ports the hybrid decode +
// paired-packing arithmetic on top of it.
//
// PROMOTED for square NO_TRANSPOSE shapes -- see mv_fp32_16_hybrid_wide_
// ilp_shared_workspace's own comment below for the real A100 measurements
// (this kernel's caller-owned-workspace sibling is the one actually
// measured/used by the benchmark).
__global__ void mv_fp32_16_hybrid_wide_ilp_shared_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc_cheap = __half2half2(static_cast<__half>(0.0f));
    float acc_extended = 0.f;
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                uint16_t w0 = wh[idx0], w1 = wh[idx1], w2 = wh[idx2], w3 = wh[idx3];

                if (((w0 & 0x1u) == 0u) && ((w1 & 0x1u) == 0u)) {
                    __half a0 = *reinterpret_cast<const __half*>(&w0);
                    __half a1 = *reinterpret_cast<const __half*>(&w1);
                    __half2 a01 = __halves2half2(a0, a1);
                    __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                    acc_cheap = __hfma2(a01, x01, acc_cheap);
                } else {
                    mv_fp32_16_hybrid_process_element(w0, x_tile[jj], acc_cheap, acc_extended);
                    mv_fp32_16_hybrid_process_element(w1, x_tile[jj + 1], acc_cheap, acc_extended);
                }
                if (((w2 & 0x1u) == 0u) && ((w3 & 0x1u) == 0u)) {
                    __half a2 = *reinterpret_cast<const __half*>(&w2);
                    __half a3 = *reinterpret_cast<const __half*>(&w3);
                    __half2 a23 = __halves2half2(a2, a3);
                    __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                    acc_cheap = __hfma2(a23, x23, acc_cheap);
                } else {
                    mv_fp32_16_hybrid_process_element(w2, x_tile[jj + 2], acc_cheap, acc_extended);
                    mv_fp32_16_hybrid_process_element(w3, x_tile[jj + 3], acc_cheap, acc_extended);
                }
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                mv_fp32_16_hybrid_process_element(wh[idx], x_tile[jj], acc_cheap, acc_extended);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        float accum = __half2float(__low2half(acc_cheap)) +
                       __half2float(__high2half(acc_cheap)) + acc_extended;
        partial[blockIdx.y * rows_op + i] = static_cast<double>(accum);
    }
}

// Host wrapper for mv_fp32_16_hybrid_wide_ilp_shared_kernel above --
// SAME grid/col_splits setup as mv_fp32_16_pure_half_wide_ilp_shared_
// half2's own wide-path branch, reused unconditionally (standalone
// comparison kernel -- only the "wide" split-K path is implemented, no
// narrow/tiled fallback, matching every other new comparison kernel in
// this file). Uses only wh (no wr), safe on arbitrary data.
//
// SUPERSEDED for benchmark/measurement purposes by mv_fp32_16_hybrid_
// wide_ilp_shared_workspace below (identical numerics, caller-owned
// workspace instead of a per-call cudaMalloc/cudaFree) -- see that
// function's own comment for the real A100 measurements and rationale.
// Kept as the plain/no-workspace-contract entry point.
void mv_fp32_16_hybrid_wide_ilp_shared(TransposeType trans, double alpha,
                                       dim<2> size, const uint16_t* wh,
                                       size_t ld_a, const float* x,
                                       size_t ld_x, double beta, float* y,
                                       size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    int col_splits = choose_col_splits(rows_op, cols_op);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    double* partial = nullptr;
    cudaError_t err =
        cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
    if (err != cudaSuccess) {
        cudaGetLastError();
        return;
    }
    dim3 grid(row_blocks, col_splits);
    mv_fp32_16_hybrid_wide_ilp_shared_kernel<<<grid, kMvTileSize>>>(
        trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
    int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
        alpha, beta, rows_op, col_splits, partial, y);
    cudaFree(partial);
    cudaDeviceSynchronize();
}

// Returns the number of doubles mv_fp32_16_hybrid_wide_ilp_shared_
// workspace's split-K path needs -- unlike mv_fp32_16_pure_half_wide_ilp_
// shared_half2_workspace_size above, this kernel is standalone (wide path
// only, no tiled/narrow_vec fallback -- see mv_fp32_16_hybrid_wide_ilp_
// shared's own comment), so this always returns the split-K size, never 0.
size_t mv_fp32_16_hybrid_wide_ilp_shared_workspace_size(TransposeType trans, dim<2> size) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    int col_splits = choose_col_splits(rows_op, cols_op);
    return rows_op * static_cast<size_t>(col_splits);
}

// Workspace-buffered sibling of mv_fp32_16_hybrid_wide_ilp_shared above --
// same "caller-owned scratch buffer instead of per-call cudaMalloc/
// cudaFree" fix as mv_fp32_16_pure_half_wide_ilp_shared_fasthalf_
// workspace (see that function's own comment for the full rationale).
// Contract: workspace must be at least mv_fp32_16_hybrid_wide_ilp_shared_
// workspace_size(trans, size) doubles -- always used (this kernel has no
// no-workspace-needed fallback path).
//
// PROMOTED for square NO_TRANSPOSE shapes -- CONFIRMED on real A100
// hardware (mv_fp32_16_pure_half_vs_cublas_ref.cu, square M=K=1024-65536):
// the workspace fix delivers the predicted win at small/medium M (e.g.
// M=1024: 63.9 -> 84.3 GFlop/s, 0.34x -> 0.45x of cuBLAS Hgemm; M=3072:
// 338.8 -> 416.1 GFlop/s, 0.35x -> 0.35x -- gains taper as M grows and
// the malloc/free overhead this fixes becomes proportionally smaller),
// converging to unchanged numbers at large M where that overhead was
// already negligible. This kernel's OWN absolute throughput stays the
// weakest of the four NO_TRANSPOSE "TOMOS" series at every square size
// (0.35x-0.51x of cuBLAS, vs half2/fasthalf/bf16's 0.6-0.9x) -- expected:
// it's the only one of the four paying real per-element branch
// divergence plus an extended-precision float path for ~10% of elements.
// Tall-and-thin (large M, small K) not separately investigated for this
// kernel -- it has no narrow_vec/tiled fallback, so it doesn't hit the
// dispatch-threshold gap diagnosed for mv_fp32_16_pure_half_wide_ilp_
// shared_half2/_fasthalf (see kMvWideRowThreshold's own comment).
void mv_fp32_16_hybrid_wide_ilp_shared_workspace(TransposeType trans, double alpha,
                                                 dim<2> size, const uint16_t* wh,
                                                 size_t ld_a, const float* x,
                                                 size_t ld_x, double beta, float* y,
                                                 size_t ld_y, double* workspace) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    int col_splits = choose_col_splits(rows_op, cols_op);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    dim3 grid(row_blocks, col_splits);
    mv_fp32_16_hybrid_wide_ilp_shared_kernel<<<grid, kMvTileSize>>>(
        trans, size[0], size[1], wh, ld_a, x, col_splits, workspace);
    int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
        alpha, beta, rows_op, col_splits, workspace, y);
}

// "TOMOS FP32/FP16", new version -- ports "TOMOS FP32/FP16 (fast)"'s own
// atomicAdd-combine dispatcher structure (atomic combine, no reduce
// kernel/partial buffer; bigtile/wide4x/best dispatch) to the EXPENSIVE
// decode instead of fasthalf's cheap unconditional one: per element,
// checks the control bit (whv & 0x1) -- control=0 ("normal", fits fp16's
// own 5 exponent bits) takes the cheap __hfma2-packed path unchanged;
// control=1 ("extended"/"degraded", needs the FULL 8 exponent bits fp32
// itself uses) reconstructs an approximate float from wh's own offset/
// direction/mant_hi bits (mv_fp32_16_hybrid_process_element, reused
// UNCHANGED from "TOMOS FP32/FP16"'s existing split+reduce kernel below)
// and performs THAT element's multiply-accumulate in float via fmaf,
// instead of fp32_16_half_only's own +-Infinity placeholder or fasthalf's
// silently-wrong reinterpret. IDENTICAL body to mv_fp32_16_hybrid_wide_
// ilp_shared_kernel below except the final combine is a direct atomicAdd
// into y instead of writing to a partial[] buffer for a separate reduce-
// kernel launch.
//
// SUPERSEDED -- this was "TOMOS FP32/FP16" (via its own bigtile/wide4x/
// best dispatcher below), CONFIRMED on real A100 hardware to beat the
// OLD split+reduce mv_fp32_16_hybrid_wide_ilp_shared kernel at every
// square size (e.g. M=4096: 447.0 GFlop/s vs that kernel's own
// comparable numbers). Nsight Compute found this kernel's own Branch
// Efficiency only 54.09% at M=4096 (this benchmark's own 10% control=1
// rate makes ~97% of warps pay for both code paths serially), which
// motivated mv_fp32_16_hybrid_wide_ilp_shared_half2_atomic_branchless
// below -- CONFIRMED a further +6.5% to +22% win over THIS kernel
// standalone, and (after one failed attempt, _branchless_fastx, which
// CONFIRMED NEGATIVE) that win was carried through to a full bigtile/
// wide4x/best dispatcher too (mv_fp32_16_hybrid_wide_ilp_shared_half2_
// atomic_branchless_best -- CONFIRMED +5.7% to +18.7% over THIS kernel's
// own dispatcher, mv_fp32_16_hybrid_wide_ilp_shared_half2_atomic_best).
// "TOMOS FP32/FP16" now means that branchless dispatcher instead. Kept
// as a documented sibling, not deleted -- still what every OTHER
// series' own ratio line in this file compares against.
__global__ void mv_fp32_16_hybrid_wide_ilp_shared_half2_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc_cheap = __half2half2(static_cast<__half>(0.0f));
    float acc_extended = 0.f;
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                uint16_t w0 = wh[idx0], w1 = wh[idx1], w2 = wh[idx2], w3 = wh[idx3];

                if (((w0 & 0x1u) == 0u) && ((w1 & 0x1u) == 0u)) {
                    __half a0 = *reinterpret_cast<const __half*>(&w0);
                    __half a1 = *reinterpret_cast<const __half*>(&w1);
                    __half2 a01 = __halves2half2(a0, a1);
                    __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                    acc_cheap = __hfma2(a01, x01, acc_cheap);
                } else {
                    mv_fp32_16_hybrid_process_element(w0, x_tile[jj], acc_cheap, acc_extended);
                    mv_fp32_16_hybrid_process_element(w1, x_tile[jj + 1], acc_cheap, acc_extended);
                }
                if (((w2 & 0x1u) == 0u) && ((w3 & 0x1u) == 0u)) {
                    __half a2 = *reinterpret_cast<const __half*>(&w2);
                    __half a3 = *reinterpret_cast<const __half*>(&w3);
                    __half2 a23 = __halves2half2(a2, a3);
                    __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                    acc_cheap = __hfma2(a23, x23, acc_cheap);
                } else {
                    mv_fp32_16_hybrid_process_element(w2, x_tile[jj + 2], acc_cheap, acc_extended);
                    mv_fp32_16_hybrid_process_element(w3, x_tile[jj + 3], acc_cheap, acc_extended);
                }
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                mv_fp32_16_hybrid_process_element(wh[idx], x_tile[jj], acc_cheap, acc_extended);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        float accum = __half2float(__low2half(acc_cheap)) +
                       __half2float(__high2half(acc_cheap)) + acc_extended;
        float contribution = static_cast<float>(alpha) * accum;
        atomicAdd(&y[i], contribution);
    }
}

// Host wrapper for mv_fp32_16_hybrid_wide_ilp_shared_half2_atomic_kernel
// above -- same grid/col_splits/beta-handling as mv_fp32_16_pure_half_
// wide_ilp_shared_half2_atomic's own wrapper. Always split-K (no 3-way
// dispatch), matching the plain hybrid kernel's own scope (no narrow_vec/
// tiled fallback exists for the hybrid decode). No trailing
// cudaDeviceSynchronize, same precedent.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_hybrid_wide_ilp_shared_half2_atomic(TransposeType trans, double alpha,
                                                     dim<2> size, const uint16_t* wh,
                                                     size_t ld_a, const float* x,
                                                     size_t ld_x, double beta, float* y,
                                                     size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    int col_splits = choose_col_splits(rows_op, cols_op);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    if (beta == 0.0) {
        cudaMemset(y, 0, rows_op * sizeof(float));
    } else {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }
    dim3 grid(row_blocks, col_splits);
    mv_fp32_16_hybrid_wide_ilp_shared_half2_atomic_kernel<<<grid, kMvTileSize>>>(
        trans, size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
}

// See mv_fp32_16_hybrid_wide_ilp_shared_half2_atomic_kernel's own comment
// -- the bigtile analog (4x-larger shared-memory x tile, cutting
// __syncthreads() frequency 4x), same as mv_fp32_16_pure_half_wide_ilp_
// shared_bigtile_half2_atomic_kernel is to mv_fp32_16_pure_half_wide_ilp_
// shared_half2_atomic_kernel.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_hybrid_wide_ilp_shared_bigtile_half2_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvWideBigTileSize];
    __half2 acc_cheap = __half2half2(static_cast<__half>(0.0f));
    float acc_extended = 0.f;
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvWideBigTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvWideBigTileSize),
                              col_end - tile_start);
        for (size_t k = threadIdx.x; k < tile_len; k += blockDim.x)
            x_tile[k] = static_cast<__half>(x[tile_start + k]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                uint16_t w0 = wh[idx0], w1 = wh[idx1], w2 = wh[idx2], w3 = wh[idx3];

                if (((w0 & 0x1u) == 0u) && ((w1 & 0x1u) == 0u)) {
                    __half a0 = *reinterpret_cast<const __half*>(&w0);
                    __half a1 = *reinterpret_cast<const __half*>(&w1);
                    __half2 a01 = __halves2half2(a0, a1);
                    __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                    acc_cheap = __hfma2(a01, x01, acc_cheap);
                } else {
                    mv_fp32_16_hybrid_process_element(w0, x_tile[jj], acc_cheap, acc_extended);
                    mv_fp32_16_hybrid_process_element(w1, x_tile[jj + 1], acc_cheap, acc_extended);
                }
                if (((w2 & 0x1u) == 0u) && ((w3 & 0x1u) == 0u)) {
                    __half a2 = *reinterpret_cast<const __half*>(&w2);
                    __half a3 = *reinterpret_cast<const __half*>(&w3);
                    __half2 a23 = __halves2half2(a2, a3);
                    __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                    acc_cheap = __hfma2(a23, x23, acc_cheap);
                } else {
                    mv_fp32_16_hybrid_process_element(w2, x_tile[jj + 2], acc_cheap, acc_extended);
                    mv_fp32_16_hybrid_process_element(w3, x_tile[jj + 3], acc_cheap, acc_extended);
                }
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                mv_fp32_16_hybrid_process_element(wh[idx], x_tile[jj], acc_cheap, acc_extended);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        float accum = __half2float(__low2half(acc_cheap)) +
                       __half2float(__high2half(acc_cheap)) + acc_extended;
        float contribution = static_cast<float>(alpha) * accum;
        atomicAdd(&y[i], contribution);
    }
}

