void mv_fp32_16_hybrid_wide_ilp_shared_half2_atomic_branchless_fastx(TransposeType trans, double alpha,
                                                                      dim<2> size, const uint16_t* wh,
                                                                      size_t ld_a, const float* x,
                                                                      size_t ld_x, double beta, float* y,
