// See mv_fp32_16_hybrid_wide_ilp_shared_half2_atomic_branchless_fastx_
// kernel's own comment -- the bigtile analog (4x-larger shared-memory x
// tile, both the half- and float-typed copies), same as mv_fp32_16_
// hybrid_wide_ilp_shared_bigtile_half2_atomic_kernel is to mv_fp32_16_
// hybrid_wide_ilp_shared_half2_atomic_kernel.
//
// CONFIRMED NEGATIVE RESULT on real A100 hardware -- part of the whole
// branchless_fastx family's own regression (see the per-element
// function's own comment for the real numbers).
__global__ void mv_fp32_16_hybrid_wide_ilp_shared_bigtile_half2_atomic_branchless_fastx_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvWideBigTileSize];
    __shared__ __align__(4) float x_tile_f[kMvWideBigTileSize];
    __half2 acc_cheap = __half2half2(static_cast<__half>(0.0f));
    float acc_extended = 0.f;
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvWideBigTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvWideBigTileSize),
                              col_end - tile_start);
        for (size_t k = threadIdx.x; k < tile_len; k += blockDim.x) {
            float xv = x[tile_start + k];
            x_tile[k] = static_cast<__half>(xv);
            x_tile_f[k] = xv;
        }
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                mv_fp32_16_hybrid_process_element_branchless_fastx(
                    wh[idx0], x_tile[jj], x_tile_f[jj], acc_cheap, acc_extended);
                mv_fp32_16_hybrid_process_element_branchless_fastx(
                    wh[idx1], x_tile[jj + 1], x_tile_f[jj + 1], acc_cheap, acc_extended);
                mv_fp32_16_hybrid_process_element_branchless_fastx(
                    wh[idx2], x_tile[jj + 2], x_tile_f[jj + 2], acc_cheap, acc_extended);
                mv_fp32_16_hybrid_process_element_branchless_fastx(
                    wh[idx3], x_tile[jj + 3], x_tile_f[jj + 3], acc_cheap, acc_extended);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                mv_fp32_16_hybrid_process_element_branchless_fastx(
                    wh[idx], x_tile[jj], x_tile_f[jj], acc_cheap, acc_extended);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        float accum = __half2float(__low2half(acc_cheap)) +
                       __half2float(__high2half(acc_cheap)) + acc_extended;
        float contribution = static_cast<float>(alpha) * accum;
        atomicAdd(&y[i], contribution);
    }
}

