                                                                                  ld_x, beta, y, ld_y);
        return;
    }
    mv_fp32_16_hybrid_wide_ilp_shared_bigtile_half2_atomic_branchless_intmask(trans, alpha, size, wh, ld_a, x,
                                                                               ld_x, beta, y, ld_y);
}

// NO_TRANSPOSE-usable mirror of mv_fp32_bf16_pure_bf16_transpose_
// atomiconly_scaled_mblock_vec4 -- same genuine __nv_bfloat16/
// __nv_bfloat162 compute and fp32_bf16_bf16_only decode (bf16's only
// decode -- no fast/safe split exists for it, see that kernel's own
// comment), but built on mv_fp32_16_pure_half_wide_ilp_shared_half2's
// generic trans-dispatched structure instead of the TRANSPOSE-only
// warp-per-column one, for the same reason mv_fp32_16_hybrid_wide_ilp_
// shared_kernel above is: NO_TRANSPOSE has no row-adjacent vector-load
// opportunity per thread, so the 4-way-unroll/independent-scalar-loads
// structure is what this family already uses generically.
//
// PROMOTED for square NO_TRANSPOSE shapes -- see mv_fp32_bf16_pure_bf16_
// wide_ilp_shared_workspace's own comment below for the real A100
// measurements (this kernel's caller-owned-workspace sibling is the one
// actually measured/used by the benchmark).
__global__ void mv_fp32_bf16_pure_bf16_wide_ilp_shared_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __nv_bfloat16 x_tile[kMvTileSize];
    __nv_bfloat162 acc01 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    __nv_bfloat162 acc23 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = __float2bfloat16(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __nv_bfloat16 a0 = fp32_bf16_bf16_only(wh[idx0]);
                __nv_bfloat16 a1 = fp32_bf16_bf16_only(wh[idx1]);
                __nv_bfloat16 a2 = fp32_bf16_bf16_only(wh[idx2]);
                __nv_bfloat16 a3 = fp32_bf16_bf16_only(wh[idx3]);
                __nv_bfloat162 a01 = __halves2bfloat162(a0, a1);
                __nv_bfloat162 a23 = __halves2bfloat162(a2, a3);
                __nv_bfloat162 x01 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj]);
                __nv_bfloat162 x23 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __nv_bfloat16 a_val = fp32_bf16_bf16_only(wh[idx]);
                __nv_bfloat162 a_pad = __halves2bfloat162(a_val, static_cast<__nv_bfloat16>(0.0f));
                __nv_bfloat162 x_pad =
                    __halves2bfloat162(x_tile[jj], static_cast<__nv_bfloat16>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __nv_bfloat162 acc_sum2 = __hadd2(acc01, acc23);
        float accum = __bfloat162float(__low2bfloat16(acc_sum2)) +
                      __bfloat162float(__high2bfloat16(acc_sum2));
        partial[blockIdx.y * rows_op + i] = static_cast<double>(accum);
    }
}

// Host wrapper for mv_fp32_bf16_pure_bf16_wide_ilp_shared_kernel above --
// same grid/col_splits setup as mv_fp32_16_hybrid_wide_ilp_shared's own
// wrapper (standalone comparison kernel, wide split-K path only).
//
// SUPERSEDED for benchmark/measurement purposes by mv_fp32_bf16_pure_
// bf16_wide_ilp_shared_workspace below (identical numerics, caller-owned
// workspace instead of a per-call cudaMalloc/cudaFree) -- see that
// function's own comment for the real A100 measurements and rationale.
// Kept as the plain/no-workspace-contract entry point.
void mv_fp32_bf16_pure_bf16_wide_ilp_shared(TransposeType trans, double alpha,
                                            dim<2> size, const uint16_t* wh,
                                            size_t ld_a, const float* x,
                                            size_t ld_x, double beta, float* y,
                                            size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    int col_splits = choose_col_splits(rows_op, cols_op);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    double* partial = nullptr;
    cudaError_t err =
        cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
    if (err != cudaSuccess) {
        cudaGetLastError();
        return;
    }
    dim3 grid(row_blocks, col_splits);
    mv_fp32_bf16_pure_bf16_wide_ilp_shared_kernel<<<grid, kMvTileSize>>>(
        trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
    int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
        alpha, beta, rows_op, col_splits, partial, y);
    cudaFree(partial);
    cudaDeviceSynchronize();
}

// Returns the number of doubles mv_fp32_bf16_pure_bf16_wide_ilp_shared_
// workspace's split-K path needs -- same "standalone, always split-K"
// reasoning as mv_fp32_16_hybrid_wide_ilp_shared_workspace_size above.
size_t mv_fp32_bf16_pure_bf16_wide_ilp_shared_workspace_size(TransposeType trans, dim<2> size) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    int col_splits = choose_col_splits(rows_op, cols_op);
    return rows_op * static_cast<size_t>(col_splits);
}

// Workspace-buffered sibling of mv_fp32_bf16_pure_bf16_wide_ilp_shared
// above -- same "caller-owned scratch buffer instead of per-call
// cudaMalloc/cudaFree" fix as mv_fp32_16_pure_half_wide_ilp_shared_
// fasthalf_workspace (see that function's own comment for the full
// rationale). Contract: workspace must be at least mv_fp32_bf16_pure_
// bf16_wide_ilp_shared_workspace_size(trans, size) doubles -- always
// used.
//
// PROMOTED for square NO_TRANSPOSE shapes -- CONFIRMED on real A100
// hardware (mv_fp32_16_pure_half_vs_cublas_ref.cu, square M=K=1024-65536,
// vs cuBLAS BF16 GemmEx): same predicted small/medium-M win as every
// other wide_ilp_shared workspace sibling (e.g. M=1024: 68.4 -> 92.9
// GFlop/s, 0.25x -> 0.35x of cuBLAS BF16; M=2048: 322.8 -> 467.0 GFlop/s,
// 0.56x -> 0.81x), converging to roughly unchanged numbers (0.78x-0.87x)
// at large M. Comparable to mv_fp32_16_pure_half_wide_ilp_shared_
// fasthalf_workspace's own ratios at every size -- both pay one
// unconditional, branch-free decode per element (fp32_bf16_bf16_only /
// fp32_16_fast_half), so similar absolute throughput is expected. Tall-
// and-thin not separately investigated for this kernel -- no narrow_vec/
// tiled fallback to hit the dispatch-threshold gap diagnosed for mv_
// fp32_16_pure_half_wide_ilp_shared_half2/_fasthalf (see kMvWideRow
// Threshold's own comment).
void mv_fp32_bf16_pure_bf16_wide_ilp_shared_workspace(TransposeType trans, double alpha,
                                                       dim<2> size, const uint16_t* wh,
                                                       size_t ld_a, const float* x,
                                                       size_t ld_x, double beta, float* y,
                                                       size_t ld_y, double* workspace) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    int col_splits = choose_col_splits(rows_op, cols_op);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    dim3 grid(row_blocks, col_splits);
    mv_fp32_bf16_pure_bf16_wide_ilp_shared_kernel<<<grid, kMvTileSize>>>(
        trans, size[0], size[1], wh, ld_a, x, col_splits, workspace);
    int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
        alpha, beta, rows_op, col_splits, workspace, y);
}

// "TOMOS BF16" -- ports "TOMOS FP16"'s own atomicAdd-combine promotion
// (mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic) to genuine bf16
// compute: IDENTICAL to mv_fp32_bf16_pure_bf16_wide_ilp_shared_kernel
// above (same __nv_bfloat162/__hfma2 packing, same fp32_bf16_bf16_only
// decode) except the combine step is a direct atomicAdd into y instead of
// writing to a partial[] buffer for a separate reduce-kernel launch --
// eliminates that second kernel dispatch + its own malloc/free entirely,
// same win mechanism that made half2_atomic the biggest single lever
// found for the fp16 family. UNLIKE the fp16 family, this does NOT add a
// 3-way (wide/tiled/narrow_vec) dispatch -- the bf16 kernel this is based
// on is itself always-split-K only (no bf16 tiled/narrow_vec kernels
// exist in this codebase), so this stays in that same scope rather than
// silently growing it.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __nv_bfloat16 x_tile[kMvTileSize];
    __nv_bfloat162 acc01 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    __nv_bfloat162 acc23 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = __float2bfloat16(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __nv_bfloat16 a0 = fp32_bf16_bf16_only(wh[idx0]);
                __nv_bfloat16 a1 = fp32_bf16_bf16_only(wh[idx1]);
                __nv_bfloat16 a2 = fp32_bf16_bf16_only(wh[idx2]);
                __nv_bfloat16 a3 = fp32_bf16_bf16_only(wh[idx3]);
                __nv_bfloat162 a01 = __halves2bfloat162(a0, a1);
                __nv_bfloat162 a23 = __halves2bfloat162(a2, a3);
                __nv_bfloat162 x01 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj]);
                __nv_bfloat162 x23 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __nv_bfloat16 a_val = fp32_bf16_bf16_only(wh[idx]);
                __nv_bfloat162 a_pad = __halves2bfloat162(a_val, static_cast<__nv_bfloat16>(0.0f));
                __nv_bfloat162 x_pad =
                    __halves2bfloat162(x_tile[jj], static_cast<__nv_bfloat16>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __nv_bfloat162 acc_sum2 = __hadd2(acc01, acc23);
        float accum = __bfloat162float(__low2bfloat16(acc_sum2)) +
                      __bfloat162float(__high2bfloat16(acc_sum2));
        float contribution = static_cast<float>(alpha) * accum;
        atomicAdd(&y[i], contribution);
    }
}

// Host wrapper for mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_kernel
// above -- same grid/col_splits/beta-handling as mv_fp32_16_pure_half_
// wide_ilp_shared_half2_atomic's own wrapper (cudaMemset when beta==0, a
// small prescale kernel otherwise, no malloc/free of any kind). Always
// split-K (no 3-way dispatch), matching the plain bf16 kernel's own
// scope. No trailing cudaDeviceSynchronize, matching half2_atomic's own
// no-workspace-but-still-sync-free precedent (a benchmark's own time_call
// already syncs via cudaEventSynchronize).
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic(TransposeType trans, double alpha,
                                                    dim<2> size, const uint16_t* wh,
                                                    size_t ld_a, const float* x,
                                                    size_t ld_x, double beta, float* y,
                                                    size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    int col_splits = choose_col_splits(rows_op, cols_op);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    if (beta == 0.0) {
        cudaMemset(y, 0, rows_op * sizeof(float));
    } else {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }
    dim3 grid(row_blocks, col_splits);
    mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_kernel<<<grid, kMvTileSize>>>(
        trans, size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
}

// "test" -- combines "TOMOS BF16"'s own atomicAdd combine with a 4x-larger
// shared-memory tile (kMvWideBigTileSize instead of kMvTileSize), cutting
// __syncthreads() frequency 4x -- the bf16 analog of mv_fp32_16_pure_
// half_wide_ilp_shared_bigtile_half2_atomic. Same grid/col_splits as
// mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_kernel above, only the
// tile width and its own syncing cadence differ.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_bf16_pure_bf16_wide_ilp_shared_bigtile_atomic_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __nv_bfloat16 x_tile[kMvWideBigTileSize];
    __nv_bfloat162 acc01 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    __nv_bfloat162 acc23 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvWideBigTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvWideBigTileSize),
                              col_end - tile_start);
        for (size_t k = threadIdx.x; k < tile_len; k += blockDim.x)
            x_tile[k] = __float2bfloat16(x[tile_start + k]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __nv_bfloat16 a0 = fp32_bf16_bf16_only(wh[idx0]);
                __nv_bfloat16 a1 = fp32_bf16_bf16_only(wh[idx1]);
                __nv_bfloat16 a2 = fp32_bf16_bf16_only(wh[idx2]);
                __nv_bfloat16 a3 = fp32_bf16_bf16_only(wh[idx3]);
                __nv_bfloat162 a01 = __halves2bfloat162(a0, a1);
                __nv_bfloat162 a23 = __halves2bfloat162(a2, a3);
                __nv_bfloat162 x01 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj]);
                __nv_bfloat162 x23 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __nv_bfloat16 a_val = fp32_bf16_bf16_only(wh[idx]);
                __nv_bfloat162 a_pad = __halves2bfloat162(a_val, static_cast<__nv_bfloat16>(0.0f));
                __nv_bfloat162 x_pad =
                    __halves2bfloat162(x_tile[jj], static_cast<__nv_bfloat16>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __nv_bfloat162 acc_sum2 = __hadd2(acc01, acc23);
        float accum = __bfloat162float(__low2bfloat16(acc_sum2)) +
                      __bfloat162float(__high2bfloat16(acc_sum2));
        float contribution = static_cast<float>(alpha) * accum;
        atomicAdd(&y[i], contribution);
    }
}

// Host wrapper for mv_fp32_bf16_pure_bf16_wide_ilp_shared_bigtile_atomic_
