}

// Dispatch threshold for mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_
// best below -- a SEPARATE constant from kMvHalf2AtomicBestCrossoverThreshold
// (fp16's own analog), even though both currently hold 4096, following
// this file's own established convention of per-family threshold constants
// (see kMvHalf2AdaptiveWideMultiplierThreshold vs kMvHalf2BestSquare
// CrossoverThreshold's own comment for why sharing one constant across
// differently-tuned families is a trap): this value is carried over
// unchanged from the fp16 dispatcher's own choice, NOT independently
// re-derived for bf16, so it may need its own separate retuning later --
// keeping it a distinct symbol makes that possible without touching fp16.
static constexpr size_t kMvBf16AtomicBestCrossoverThreshold = 4096;

// "TOMOS BF16, best-of" -- same dispatch-not-merge idea as mv_fp32_16_
// pure_half_wide_ilp_shared_half2_atomic_best (its own fp16 analog): below
// kMvBf16AtomicBestCrossoverThreshold rows, calls mv_fp32_bf16_pure_bf16_
// wide_ilp_shared_bigtile_atomic; at/above it, calls mv_fp32_bf16_pure_
// bf16_wide_ilp_shared_atomic_wide4x. No workspace needed (neither callee
// owns a buffer). Neither callee has been benchmarked against the other,
// against mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic alone, or against
// the older split+reduce mv_fp32_bf16_pure_bf16_wide_ilp_shared_workspace
// yet.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_best(TransposeType trans, double alpha,
                                                         dim<2> size, const uint16_t* wh,
                                                         size_t ld_a, const float* x,
                                                         size_t ld_x, double beta, float* y,
                                                         size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    if (rows_op >= kMvBf16AtomicBestCrossoverThreshold) {
        mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_wide4x(trans, alpha, size, wh, ld_a, x,
                                                              ld_x, beta, y, ld_y);
        return;
    }
    mv_fp32_bf16_pure_bf16_wide_ilp_shared_bigtile_atomic(trans, alpha, size, wh, ld_a, x,
                                                           ld_x, beta, y, ld_y);
}

// "TOMOS FP32/BF16", new version -- REQUESTED as a separate, distinctly-
// named kernel family for the "TOMOS FP32/BF16" plot slot, explicitly
// confirmed to be IDENTICAL to "TOMOS BF16" above on wh (same
// fp32_bf16_bf16_only decode, same __nv_bfloat162/__hfma2 packing, same
// atomicAdd combine, same bigtile/wide4x/best dispatch structure) -- byte-
// for-byte the same bodies as mv_fp32_bf16_pure_bf16_wide_ilp_shared_
// atomic_kernel/_bigtile_atomic_kernel/_atomic_wide4x/_atomic_best above,
// just under a "_v2" suffix so this slot gets its own independently-
// measured benchmark leg and verify check rather than silently reusing
// "TOMOS BF16"'s own symbols. There is genuinely no decode/compute axis
// left to differentiate these two series on for bf16 (unlike fp16, which
// has a real reconstruction axis for "TOMOS FP32/FP16" and a real fast/
// safe decode axis for "TOMOS FP32/FP16 (fast)") -- bf16 shares fp32's
// own 8-bit exponent, so fp32_bf16_bf16_only is already exact across the
// full range, with no fast/safe split or reconstruction trick possible
// (see fp32_bf16_bf16_only's own comment). If a genuine future difference
// is ever found for this slot, it belongs here, in this "_v2" family, not
// by editing "TOMOS BF16"'s own symbols.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_v2_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __nv_bfloat16 x_tile[kMvTileSize];
    __nv_bfloat162 acc01 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    __nv_bfloat162 acc23 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = __float2bfloat16(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __nv_bfloat16 a0 = fp32_bf16_bf16_only(wh[idx0]);
                __nv_bfloat16 a1 = fp32_bf16_bf16_only(wh[idx1]);
                __nv_bfloat16 a2 = fp32_bf16_bf16_only(wh[idx2]);
                __nv_bfloat16 a3 = fp32_bf16_bf16_only(wh[idx3]);
                __nv_bfloat162 a01 = __halves2bfloat162(a0, a1);
                __nv_bfloat162 a23 = __halves2bfloat162(a2, a3);
                __nv_bfloat162 x01 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj]);
                __nv_bfloat162 x23 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __nv_bfloat16 a_val = fp32_bf16_bf16_only(wh[idx]);
                __nv_bfloat162 a_pad = __halves2bfloat162(a_val, static_cast<__nv_bfloat16>(0.0f));
                __nv_bfloat162 x_pad =
                    __halves2bfloat162(x_tile[jj], static_cast<__nv_bfloat16>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __nv_bfloat162 acc_sum2 = __hadd2(acc01, acc23);
        float accum = __bfloat162float(__low2bfloat16(acc_sum2)) +
                      __bfloat162float(__high2bfloat16(acc_sum2));
        float contribution = static_cast<float>(alpha) * accum;
        atomicAdd(&y[i], contribution);
    }
}

// Host wrapper for mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_v2_kernel
// above -- see its own comment.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_v2(TransposeType trans, double alpha,
                                                       dim<2> size, const uint16_t* wh,
                                                       size_t ld_a, const float* x,
                                                       size_t ld_x, double beta, float* y,
                                                       size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    int col_splits = choose_col_splits(rows_op, cols_op);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    if (beta == 0.0) {
        cudaMemset(y, 0, rows_op * sizeof(float));
    } else {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_wide_atomic_prescale_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }
    dim3 grid(row_blocks, col_splits);
    mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_v2_kernel<<<grid, kMvTileSize>>>(
        trans, size[0], size[1], wh, ld_a, x, col_splits, alpha, y);
}

// See mv_fp32_bf16_pure_bf16_wide_ilp_shared_atomic_v2_kernel's own
// comment -- the "_v2" analog of mv_fp32_bf16_pure_bf16_wide_ilp_shared_
// bigtile_atomic_kernel.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_bf16_pure_bf16_wide_ilp_shared_bigtile_atomic_v2_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double alpha, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __nv_bfloat16 x_tile[kMvWideBigTileSize];
    __nv_bfloat162 acc01 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    __nv_bfloat162 acc23 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvWideBigTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvWideBigTileSize),
                              col_end - tile_start);
        for (size_t k = threadIdx.x; k < tile_len; k += blockDim.x)
            x_tile[k] = __float2bfloat16(x[tile_start + k]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __nv_bfloat16 a0 = fp32_bf16_bf16_only(wh[idx0]);
                __nv_bfloat16 a1 = fp32_bf16_bf16_only(wh[idx1]);
                __nv_bfloat16 a2 = fp32_bf16_bf16_only(wh[idx2]);
                __nv_bfloat16 a3 = fp32_bf16_bf16_only(wh[idx3]);
                __nv_bfloat162 a01 = __halves2bfloat162(a0, a1);
                __nv_bfloat162 a23 = __halves2bfloat162(a2, a3);
                __nv_bfloat162 x01 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj]);
                __nv_bfloat162 x23 = *reinterpret_cast<__nv_bfloat162*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __nv_bfloat16 a_val = fp32_bf16_bf16_only(wh[idx]);
                __nv_bfloat162 a_pad = __halves2bfloat162(a_val, static_cast<__nv_bfloat16>(0.0f));
                __nv_bfloat162 x_pad =
                    __halves2bfloat162(x_tile[jj], static_cast<__nv_bfloat16>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __nv_bfloat162 acc_sum2 = __hadd2(acc01, acc23);
        float accum = __bfloat162float(__low2bfloat16(acc_sum2)) +
                      __bfloat162float(__high2bfloat16(acc_sum2));
        float contribution = static_cast<float>(alpha) * accum;
        atomicAdd(&y[i], contribution);
    }
}

