void mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_fast(TransposeType trans, double alpha,
                                                                        dim<2> size, const uint16_t* wh, size_t ld_a,
                                                                        const float* x, size_t ld_x, double beta,
                                                                        float* y, size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(float));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_fast_kernel<<<grid, block, shmem>>>(
        wh, x, y, m, k, M_BLOCK, static_cast<float>(alpha));
}

// "TOMOS FP32/BF16" -- bf16 counterpart of mv_fp32_16_pure_half_
// transpose_atomiconly_scaled_mblock_vec4_fast_kernel above, built on
// its exact structure (ushort4-vectorized load, __hfma2-family packed
// accumulation, M_BLOCK-scaling target/floor) with __half/__half2
// swapped for __nv_bfloat16/__nv_bfloat162 throughout and fp32_16_
// fast_half swapped for fp32_bf16_bf16_only. UNLIKE the fp16 fast/safe
// split this was based on, though, bf16 has NO unsafe-on-arbitrary-data
// caveat to inherit: fp32_bf16_bf16_only's own comment (fp32_bf16_
// pack.hpp) explains why -- bfloat16 shares fp32's own 8-bit exponent
// field, so unlike fp16 (whose 5-bit exponent can overflow/underflow,
// needing the extended/degraded fallback encoding fp32_16_half_only
// must check for) a bf16 truncation of any fp32 value is ALWAYS a
// valid, correctly-ranged bfloat16 -- there is only ONE decode function
// for bf16, and it was already unconditional. So this kernel is safe on
// arbitrary data despite being built from the "fast" (unsafe) fp16
// lineage -- no dedicated safe-range data generator needed for its own
// correctness/benchmark coverage, unlike every fp16 "_fast"/"fast_
// normal" sibling in this file.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_bf16_pure_bf16_transpose_atomiconly_scaled_mblock_vec4_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ y,
    int m, int k, int M_BLOCK, float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    // BUG FIX (see mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_
    // vec4_split_kernel's own comment for the full derivation): col_valid
    // is deliberately NOT an early return, so every thread in the block
    // reaches __syncthreads() below regardless of whether its own column
    // is in range -- an early return here (when k is not a multiple of
    // warpsPerBlock) would leave sx_bf16 partially unfilled for the
    // surviving warps to read as uninitialized shared memory.
    const int col = blockIdx.y * warpsPerBlock + warpId;
    const bool col_valid = col < k;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;  // safe: block-uniform, depends only on blockIdx.x

    extern __shared__ __nv_bfloat16 sx_bf16[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_bf16[r - mStart] = __float2bfloat16(__ldg(&x[r]));
    }
    __syncthreads();

    if (!col_valid) return;  // safe now: every thread already reached the barrier above

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __nv_bfloat162 acc01 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));
    __nv_bfloat162 acc23 = __bfloat162bfloat162(static_cast<__nv_bfloat16>(0.0f));

    const int vBeg = (mStart + 3) & ~3;
    const int vEnd = mEnd & ~3;

    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __nv_bfloat16 a = fp32_bf16_bf16_only(wh[idx]);
        __nv_bfloat162 a_pad = __halves2bfloat162(a, static_cast<__nv_bfloat16>(0.0f));
        __nv_bfloat162 x_pad = __halves2bfloat162(sx_bf16[r - mStart], static_cast<__nv_bfloat16>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pWh = reinterpret_cast<uintptr_t>(&wh[idxBeg]);
        const uintptr_t pX = reinterpret_cast<uintptr_t>(&sx_bf16[vBeg - mStart]);
        const bool aligned = ((pWh & 0x7) == 0) && ((pX & 0x3) == 0);

        if (aligned) {
            for (int r = vBeg + lane * 4; r + 3 < vEnd; r += 32 * 4) {
                const size_t idx = colBase + static_cast<size_t>(r);
                const ushort4 whv = *reinterpret_cast<const ushort4*>(&wh[idx]);
                __nv_bfloat16 a0 = fp32_bf16_bf16_only(whv.x);
                __nv_bfloat16 a1 = fp32_bf16_bf16_only(whv.y);
                __nv_bfloat16 a2 = fp32_bf16_bf16_only(whv.z);
                __nv_bfloat16 a3 = fp32_bf16_bf16_only(whv.w);
                __nv_bfloat162 a01 = __halves2bfloat162(a0, a1);
                __nv_bfloat162 a23 = __halves2bfloat162(a2, a3);
                __nv_bfloat162 x01 = *reinterpret_cast<__nv_bfloat162*>(&sx_bf16[r - mStart]);
                __nv_bfloat162 x23 = *reinterpret_cast<__nv_bfloat162*>(&sx_bf16[r - mStart + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
        } else {
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                __nv_bfloat16 a = fp32_bf16_bf16_only(wh[idx]);
                __nv_bfloat162 a_pad = __halves2bfloat162(a, static_cast<__nv_bfloat16>(0.0f));
                __nv_bfloat162 x_pad = __halves2bfloat162(sx_bf16[r - mStart], static_cast<__nv_bfloat16>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
    }

    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __nv_bfloat16 a = fp32_bf16_bf16_only(wh[idx]);
        __nv_bfloat162 a_pad = __halves2bfloat162(a, static_cast<__nv_bfloat16>(0.0f));
        __nv_bfloat162 x_pad = __halves2bfloat162(sx_bf16[r - mStart], static_cast<__nv_bfloat16>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    __nv_bfloat162 acc2 = __hadd2(acc01, acc23);
    float accum = __bfloat162float(__low2bfloat16(acc2)) + __bfloat162float(__high2bfloat16(acc2));

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0) atomicAdd(&y[col], alpha * accum);
}

// Host wrapper for mv_fp32_bf16_pure_bf16_transpose_atomiconly_scaled_
// mblock_vec4_kernel above -- SAME M_BLOCK-scaling as mv_fp32_16_pure_
// half_transpose_atomiconly_scaled_mblock_vec4_fast/_retuned_floor
// (target=kMvFp32_16TransposeTargetGridBlocks=2048, floor=kMvFp32_16
// TransposeMinMBlock=256, reused directly -- decode/precision-
// independent, same constants already shared across the fp32_16 and
// fp32_bf16 families elsewhere in this file). Only handles TRANSPOSE +
// ld_a==size[0] -- standalone comparison kernel, safe on arbitrary data
// (see the kernel's own comment).
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_bf16_pure_bf16_transpose_atomiconly_scaled_mblock_vec4(TransposeType trans, double alpha, dim<2> size,
                                                                     const uint16_t* wh, size_t ld_a, const float* x,
                                                                     size_t ld_x, double beta, float* y,
                                                                     size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(float));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__nv_bfloat16);

    mv_fp32_bf16_pure_bf16_transpose_atomiconly_scaled_mblock_vec4_kernel<<<grid, block, shmem>>>(
        wh, x, y, m, k, M_BLOCK, static_cast<float>(alpha));
}

// "test" -- hybrid TRANSPOSE kernel for the "TOMOS FP32/FP16" family:
// uses the expensive decode (fp32_16_half_only's own control-bit check,
// see its comment in fp32_16_pack.hpp) to detect, per element, whether
// wh alone is a directly-valid half (control=0 -- direct bit-
// reinterpret, exact) or whether the true value needed more range than
// fp16's own 5-bit exponent can hold (control=1). fp32_16_half_only's
// own fallback for control=1 just flushes to +-Infinity/+-0/degraded-
// zero -- but wh ALONE (no wr needed) already carries enough to do much
// better for the non-degraded extended case: bits 10-14 hold offset(3)/
// direction(1) instead of a raw exponent, which is fp32_16_split's own
// way of encoding an EXTENDED exponent range beyond fp16's 5 bits
// (effectively reaching toward fp32's full 8-bit exponent field, unlike
// a plain half's own narrower range) -- and bits 1-9 still hold mant_hi,
// the SAME 9 top mantissa bits a control=0 value would use. So this
// kernel reconstructs an approximate fp32 value from wh's own bits
// alone (extended exponent from offset/direction, mant_hi zero-padded
// for the missing 14 lower mantissa bits wr would normally supply) and
// accumulates that element's contribution in float -- far more accurate
// than +-Infinity, at ZERO extra memory traffic (still one uint16_t
// read per element, exactly like every other pure_half sibling). Only
// the genuinely-unrecoverable "degraded" bucket (offset==7 -- wh alone
// carries no exponent/range info there at all, see fp32_16_half_only's
// own comment) falls back to contributing 0, matching fp32_16_half_
// only's own signed-zero fallback for that bucket specifically. Uses
// ONLY wh, like every other pure_half sibling -- no wr, unlike the
// RECONSTRUCTION tier's two-array kernels.
//
// Two separate accumulators (a packed __half2 one for the common/cheap
// control=0 path, a plain float one for the rare/expensive control=1
// path) are combined only at the very end, right before the warp-
// shuffle reduction. Both paths multiply against the SAME shared-
// memory __half-truncated x copy (sx_half) every other kernel in this
// file already stages -- only the WEIGHT gets the extended-precision
// treatment; x stays at __half precision throughout, matching the rest
// of the pure_half family. This keeps the kernel exactly as cheap in
// memory traffic as every other single-array sibling (one uint16_t wh
// read AND one shared-memory x read per element, nothing extra) while
// still recovering the weight's true magnitude for the rare control=1
// case -- a real accuracy win over fp32_16_half_only's own +-Infinity
// fallback, just not a full-precision one.
//
// Deliberately NOT hand-vectorized (plain scalar per-lane loop, no
// ushort4/aligned-load fast path) -- the per-element control-bit branch
// this kernel exists to test would fight any attempt at a uniform
// vectorized load/decode path anyway, and this is a first-cut "test"
// kernel (per the user's own framing), not yet a tuned candidate.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_hybrid_transpose_atomiconly_scaled_mblock_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ y, int m, int k, int M_BLOCK,
    float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    if (col >= k) return;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ __half sx_half[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_half[r - mStart] = __float2half(__ldg(&x[r]));
    }
    __syncthreads();

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __half2 acc_cheap = __half2half2(static_cast<__half>(0.0f));
    float acc_extended = 0.f;

    for (int r = mStart + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        const uint16_t whv = wh[idx];
        if ((whv & 0x1u) == 0u) {
            // Cheap path: control=0, wh alone is already a valid,
            // properly-rounded half -- direct reinterpret is exact.
            __half a = *reinterpret_cast<const __half*>(&whv);
            __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
            __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
            acc_cheap = __hfma2(a_pad, x_pad, acc_cheap);
        } else {
            // Expensive path: control=1 -- decode the extended exponent
            // (offset/direction, bits 10-14) and mant_hi (bits 1-9),
            // BOTH already present in wh alone, into an approximate fp32
            // value (missing mantissa bits zero-padded) -- same bit
            // layout fp32_16_combine's own control=1/non-degraded branch
            // uses, just without wr's mant_lo/round_flag contribution.
            const uint32_t shift_by = (static_cast<uint32_t>(whv) >> 10) & 0xFu;
            if (shift_by != fp32_16_detail::kOffsetSaturateStored) {
                const uint32_t direction = (static_cast<uint32_t>(whv) >> 14) & 0x1u;
                const uint32_t exp32 = direction ? (fp32_16_detail::kFp32ExpMax + 1u + shift_by)
                                                  : (fp32_16_detail::kFp32ExpMin - 1u - shift_by);
                const uint32_t mant_hi = (static_cast<uint32_t>(whv) >> 1) & 0x1FFu;
                const uint32_t mant32 = mant_hi << 14;
                const uint32_t sign = (static_cast<uint32_t>(whv) & 0x8000u) << 16;
                const float a_f = fp32_16_detail::bits_to_float(sign | (exp32 << 23) | mant32);
                acc_extended = fmaf(a_f, __half2float(sx_half[r - mStart]), acc_extended);
            }
            // Degraded bucket (offset==7): wh alone carries no exponent/
            // range info here at all -- contributes 0, matching fp32_
            // 16_half_only's own signed-zero fallback for this bucket.
        }
    }

    float accum =
        __half2float(__low2half(acc_cheap)) + __half2float(__high2half(acc_cheap)) + acc_extended;

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0) atomicAdd(&y[col], alpha * accum);
}

// Host wrapper for mv_fp32_16_hybrid_transpose_atomiconly_scaled_
// mblock_kernel above -- SAME M_BLOCK-scaling as "TOMOS FP32/FP16"
// (_retuned_floor)/"TOMOS FP32/FP16 (fast)" (target=kMvFp32_16
// TransposeTargetGridBlocks=2048, floor=kMvFp32_16TransposeMinMBlock=
// 256), the direct comparison point for this "test" kernel. Only
// handles TRANSPOSE + ld_a==size[0] -- standalone comparison kernel,
// safe on arbitrary data (the whole point of the expensive-decode
// branch is to handle out-of-fp16-range values correctly rather than
// requiring safe-range input).
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_hybrid_transpose_atomiconly_scaled_mblock(TransposeType trans, double alpha, dim<2> size,
                                                           const uint16_t* wh, size_t ld_a, const float* x,
                                                           size_t ld_x, double beta, float* y, size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(float));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_hybrid_transpose_atomiconly_scaled_mblock_kernel<<<grid, block, shmem>>>(
        wh, x, y, m, k, M_BLOCK, static_cast<float>(alpha));
}

// Per-element decode-and-accumulate for mv_fp32_16_hybrid_transpose_
// atomiconly_scaled_mblock_vec4_kernel below -- factored out so it can
// be called 4 times per vectorized ushort4 load (and once per scalar
// prefix/suffix element) without duplicating the branch. Same control-
// bit/offset/degraded logic as the untiled "test" kernel above, unpacked
// into a free function since it needs to mutate both accumulators by
// reference. Both paths multiply against the SAME shared-memory __half-
// truncated x copy (xval_half) -- only the weight gets the extended-
// precision treatment for the rare control=1 case, matching the untiled
// kernel's own design (see its comment above for why: this keeps the
// kernel exactly as cheap in memory traffic as every other single-array
// pure_half sibling -- one wh read, one shared-memory x read, nothing
// extra -- while still recovering the weight's true magnitude instead
// of fp32_16_half_only's own +-Infinity fallback).
__device__ inline void mv_fp32_16_hybrid_process_element(uint16_t whv, __half xval_half, __half2& acc_cheap,
                                                          float& acc_extended) {
    if ((whv & 0x1u) == 0u) {
        __half a = *reinterpret_cast<const __half*>(&whv);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(xval_half, static_cast<__half>(0.0f));
        acc_cheap = __hfma2(a_pad, x_pad, acc_cheap);
    } else {
        const uint32_t shift_by = (static_cast<uint32_t>(whv) >> 10) & 0xFu;
        if (shift_by != fp32_16_detail::kOffsetSaturateStored) {
            const uint32_t direction = (static_cast<uint32_t>(whv) >> 14) & 0x1u;
            const uint32_t exp32 = direction ? (fp32_16_detail::kFp32ExpMax + 1u + shift_by)
                                              : (fp32_16_detail::kFp32ExpMin - 1u - shift_by);
            const uint32_t mant_hi = (static_cast<uint32_t>(whv) >> 1) & 0x1FFu;
            const uint32_t mant32 = mant_hi << 14;
            const uint32_t sign = (static_cast<uint32_t>(whv) & 0x8000u) << 16;
            const float a_f = fp32_16_detail::bits_to_float(sign | (exp32 << 23) | mant32);
            acc_extended = fmaf(a_f, __half2float(xval_half), acc_extended);
        }
    }
}

// Vectorized-load sibling of mv_fp32_16_hybrid_transpose_atomiconly_
// scaled_mblock_kernel above -- built to fix that kernel's own measured
// falloff past M=3072ish: it never vectorized its wh load at all (plain
// scalar reads), unlike every OTHER "TOMOS FP32/FP16" kernel in this
// file (all ushort4, 4 elements/load). Since M_BLOCK-scaling makes each
// block's own row range GROW with M (512 at M=3072 up to the 8192 cap
// by M=16384, same target=2048/floor=256 formula every sibling shares),
// the scalar kernel's own per-thread load-instruction count grows right
// alongside it, paying full scalar rate the whole way -- while a
// vectorized sibling doing the SAME growing amount of work only pays
// 1/4 as many load instructions for it. This kernel keeps the untiled
// kernel's own per-element branch (cheap __half2 path vs the wh-only
// extended-exponent float path) completely unchanged -- only the LOAD
// is vectorized (a ushort4 fetch of 4 wh values at once, mirroring the
// same scalar-prefix/vectorized-middle/scalar-suffix structure every
// vec4 kernel in this file already uses), each of the 4 decoded
// independently via mv_fp32_16_hybrid_process_element above -- the
// divergent branch itself stays exactly as expensive as before, only
// the memory traffic it rides on gets cheaper. Both paths multiply
// against the same shared-memory x copy (see that helper's own comment)
// -- no separate global x re-read anywhere in this kernel.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_hybrid_transpose_atomiconly_scaled_mblock_vec4_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ y, int m, int k, int M_BLOCK,
    float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    if (col >= k) return;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ __half sx_half[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_half[r - mStart] = __float2half(__ldg(&x[r]));
    }
    __syncthreads();

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __half2 acc_cheap = __half2half2(static_cast<__half>(0.0f));
    float acc_extended = 0.f;

    const int vBeg = (mStart + 3) & ~3;
    const int vEnd = mEnd & ~3;

    // Scalar prefix: [mStart, min(vBeg, mEnd))
    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        mv_fp32_16_hybrid_process_element(wh[idx], sx_half[r - mStart], acc_cheap, acc_extended);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pWh = reinterpret_cast<uintptr_t>(&wh[idxBeg]);
        const bool aligned = (pWh & 0x7) == 0;

        if (aligned) {
            for (int r = vBeg + lane * 4; r + 3 < vEnd; r += 32 * 4) {
                const size_t idx = colBase + static_cast<size_t>(r);
                const ushort4 whv = *reinterpret_cast<const ushort4*>(&wh[idx]);
                mv_fp32_16_hybrid_process_element(whv.x, sx_half[r - mStart], acc_cheap, acc_extended);
                mv_fp32_16_hybrid_process_element(whv.y, sx_half[r + 1 - mStart], acc_cheap, acc_extended);
                mv_fp32_16_hybrid_process_element(whv.z, sx_half[r + 2 - mStart], acc_cheap, acc_extended);
                mv_fp32_16_hybrid_process_element(whv.w, sx_half[r + 3 - mStart], acc_cheap, acc_extended);
            }
        } else {
            // Unaligned fallback -- still correct, just not vectorized.
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                mv_fp32_16_hybrid_process_element(wh[idx], sx_half[r - mStart], acc_cheap, acc_extended);
            }
        }
    }

    // Scalar suffix: [vEnd, mEnd)
    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        mv_fp32_16_hybrid_process_element(wh[idx], sx_half[r - mStart], acc_cheap, acc_extended);
    }

    float accum =
        __half2float(__low2half(acc_cheap)) + __half2float(__high2half(acc_cheap)) + acc_extended;

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0) atomicAdd(&y[col], alpha * accum);
}

// Host wrapper for mv_fp32_16_hybrid_transpose_atomiconly_scaled_
// mblock_vec4_kernel above -- SAME M_BLOCK-scaling as the untiled "test"
// kernel (target=2048/floor=256). Only handles TRANSPOSE + ld_a==
// size[0], uses ONLY wh (no wr), safe on arbitrary data -- same
// contract as the untiled kernel, only the load is vectorized.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_hybrid_transpose_atomiconly_scaled_mblock_vec4(TransposeType trans, double alpha, dim<2> size,
                                                                const uint16_t* wh, size_t ld_a, const float* x,
                                                                size_t ld_x, double beta, float* y, size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(float));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_hybrid_transpose_atomiconly_scaled_mblock_vec4_kernel<<<grid, block, shmem>>>(
        wh, x, y, m, k, M_BLOCK, static_cast<float>(alpha));
}

// Paired-packing sibling of mv_fp32_16_hybrid_transpose_atomiconly_
// scaled_mblock_vec4_kernel above -- fixes a real arithmetic-throughput
// gap that kernel still has vs "(atomiconly, retuned_floor)": that
// kernel processes each of the 4 ushort4-loaded elements INDIVIDUALLY
// via mv_fp32_16_hybrid_process_element, each call padding its own
// __half2 with a zero in the unused lane -- so every __hfma2 issued on
// the common (control=0) path does only ONE real multiply-add, not two,
// unlike _retuned_floor's own kernel, which packs two REAL adjacent
// elements into every __hfma2 (true half2 SIMD, 2 elements/instruction).
// This kernel checks each adjacent pair's control bits together: if
// BOTH are cheap (control=0) -- the common case, ~(0.9)^2=81% of pairs
// for this kernel's own ~10%-extended benchmark data -- it packs them
// into one real __hfma2 exactly like _retuned_floor does, reading the
// pair's shared-memory x values as a single __half2 (same alignment
// contract as every other vec4 kernel here: checks pX&0x3==0 up front,
// falling back to the existing per-element helper for the whole
// unaligned case). Only when a pair is mixed (one or both control=1)
// does it fall back to mv_fp32_16_hybrid_process_element per element,
// exactly as before. The extended-precision decode logic itself
// (offset/direction/mant_hi from wh alone, accumulated in acc_extended)
// is completely unchanged -- only the common path's own arithmetic
// packing improves.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_hybrid_transpose_atomiconly_scaled_mblock_vec4_paired_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ y, int m, int k, int M_BLOCK,
    float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    // BUG FIX (see mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_
    // vec4_split_kernel's own comment for the full derivation): col_valid
    // is deliberately NOT an early return, so every thread in the block
    // reaches __syncthreads() below regardless of whether its own column
    // is in range -- an early return here (when k is not a multiple of
    // warpsPerBlock) would leave sx_half partially unfilled for the
    // surviving warps to read as uninitialized shared memory.
    const int col = blockIdx.y * warpsPerBlock + warpId;
    const bool col_valid = col < k;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;  // safe: block-uniform, depends only on blockIdx.x

    extern __shared__ __half sx_half[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_half[r - mStart] = __float2half(__ldg(&x[r]));
    }
    __syncthreads();

    if (!col_valid) return;  // safe now: every thread already reached the barrier above

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __half2 acc_cheap = __half2half2(static_cast<__half>(0.0f));
    float acc_extended = 0.f;

    const int vBeg = (mStart + 3) & ~3;
    const int vEnd = mEnd & ~3;

    // Scalar prefix: [mStart, min(vBeg, mEnd))
    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        mv_fp32_16_hybrid_process_element(wh[idx], sx_half[r - mStart], acc_cheap, acc_extended);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pWh = reinterpret_cast<uintptr_t>(&wh[idxBeg]);
        const uintptr_t pX = reinterpret_cast<uintptr_t>(&sx_half[vBeg - mStart]);
        // wh needs 8-byte alignment for a ushort4 load; sx_half needs
        // 4-byte alignment for a paired __half2 read -- same two-part
        // alignment contract as _retuned_floor's own vec4 kernel.
        const bool aligned = ((pWh & 0x7) == 0) && ((pX & 0x3) == 0);

        if (aligned) {
            for (int r = vBeg + lane * 4; r + 3 < vEnd; r += 32 * 4) {
                const size_t idx = colBase + static_cast<size_t>(r);
                const ushort4 whv = *reinterpret_cast<const ushort4*>(&wh[idx]);

                if (((whv.x & 0x1u) == 0u) && ((whv.y & 0x1u) == 0u)) {
                    __half a0 = *reinterpret_cast<const __half*>(&whv.x);
                    __half a1 = *reinterpret_cast<const __half*>(&whv.y);
                    __half2 a01 = __halves2half2(a0, a1);
                    __half2 x01 = *reinterpret_cast<__half2*>(&sx_half[r - mStart]);
                    acc_cheap = __hfma2(a01, x01, acc_cheap);
                } else {
                    mv_fp32_16_hybrid_process_element(whv.x, sx_half[r - mStart], acc_cheap, acc_extended);
                    mv_fp32_16_hybrid_process_element(whv.y, sx_half[r + 1 - mStart], acc_cheap, acc_extended);
                }

                if (((whv.z & 0x1u) == 0u) && ((whv.w & 0x1u) == 0u)) {
                    __half a2 = *reinterpret_cast<const __half*>(&whv.z);
                    __half a3 = *reinterpret_cast<const __half*>(&whv.w);
                    __half2 a23 = __halves2half2(a2, a3);
                    __half2 x23 = *reinterpret_cast<__half2*>(&sx_half[r + 2 - mStart]);
                    acc_cheap = __hfma2(a23, x23, acc_cheap);
                } else {
                    mv_fp32_16_hybrid_process_element(whv.z, sx_half[r + 2 - mStart], acc_cheap, acc_extended);
                    mv_fp32_16_hybrid_process_element(whv.w, sx_half[r + 3 - mStart], acc_cheap, acc_extended);
                }
            }
        } else {
            // Unaligned fallback -- still correct, just not vectorized.
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                mv_fp32_16_hybrid_process_element(wh[idx], sx_half[r - mStart], acc_cheap, acc_extended);
            }
        }
    }

    // Scalar suffix: [vEnd, mEnd)
    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        mv_fp32_16_hybrid_process_element(wh[idx], sx_half[r - mStart], acc_cheap, acc_extended);
    }

    float accum =
        __half2float(__low2half(acc_cheap)) + __half2float(__high2half(acc_cheap)) + acc_extended;

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0) atomicAdd(&y[col], alpha * accum);
}

// Host wrapper for mv_fp32_16_hybrid_transpose_atomiconly_scaled_
// mblock_vec4_paired_kernel above -- SAME M_BLOCK-scaling as every
// other "TOMOS FP32/FP16" sibling (target=2048/floor=256). Only handles
// TRANSPOSE + ld_a==size[0], uses ONLY wh, safe on arbitrary data.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_hybrid_transpose_atomiconly_scaled_mblock_vec4_paired(TransposeType trans, double alpha,
                                                                       dim<2> size, const uint16_t* wh, size_t ld_a,
                                                                       const float* x, size_t ld_x, double beta,
                                                                       float* y, size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(float));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_hybrid_transpose_atomiconly_scaled_mblock_vec4_paired_kernel<<<grid, block, shmem>>>(
        wh, x, y, m, k, M_BLOCK, static_cast<float>(alpha));
}

// __half-typed counterpart of mv_fp32_16_scale_y_kernel -- needed
// because mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_
// vec4_half_io_kernel below stores y as __half, not float, so the
// existing scale_y_kernel (float* y) cannot be reused directly. Reads
// the current y value as float, scales, converts back -- same
// accumulate-wide/store-narrow convention every other kernel in this
// file already uses, just applied to the beta-prescale step too.
__global__ void mv_fp32_16_scale_y_half_kernel(size_t n, double beta, __half* y) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= n) return;
    y[i] = __float2half(static_cast<float>(beta) * __half2float(y[i]));
}

// __half-I/O counterpart of mv_fp32_16_pure_half_transpose_atomiconly_
// scaled_mblock_vec4_kernel above -- IDENTICAL compute (same
// fp32_16_half_only decode, same ushort4-vectorized wh load packed into
// __half2, same __hfma2 arithmetic, same M_BLOCK-scaling grid math),
// only x and y are now __half* instead of float* -- matching cuBLAS's
// own Hgemm(n=1) semantics exactly (A, x, AND y all __half), unlike
// every other mv_fp32_16_pure_half* kernel in this file (which all keep
// x/y in float, a real semantics mismatch against the cuBLAS baseline
// noted in mv_fp32_16_pure_half_transpose_vs_cublas_ref.cu's own header
// comment). Two concrete effects of this change, both isolated
// deliberately (nothing else differs from the plain-vec4-I/O kernel):
//   1. x staging no longer needs a float->__half convert (x is already
//      __half) -- a plain __ldg copy, one instruction cheaper per
//      element than the float-I/O kernel's own __float2half(__ldg(...)).
//   2. The final combine still accumulates and warp-shuffle-reduces in
//      float internally (accum stays a float register, exactly as in
//      the float-I/O kernel) -- only the LAST step, the atomicAdd
//      itself, narrows to __half (atomicAdd(__half*, __half) is a
//      native hardware built-in on compute capability 7.0+, no emulation
//      needed on this file's own sm_80 target) -- so this does NOT
//      accumulate in half precision end-to-end the way a truly minimal
//      half-I/O kernel might; it isolates the I/O TYPE change from any
//      accumulation-precision change, same "change one variable"
//      discipline as every other A/B sibling in this file.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_half_io_kernel(
    const uint16_t* __restrict__ wh, const __half* __restrict__ x, __half* __restrict__ y,
    int m, int k, int M_BLOCK, float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    if (col >= k) return;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ __half sx_half[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    // Scalar staging -- x is already __half, so this is a plain copy
    // (no __float2half convert needed, unlike the float-I/O kernel's
    // own staging loop). Same "wh's own load dominates total traffic,
    // not this" reasoning as that kernel's own comment.
    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_half[r - mStart] = __ldg(&x[r]);
    }
    __syncthreads();

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));

    const int vBeg = (mStart + 3) & ~3;
    const int vEnd = mEnd & ~3;

    // Scalar prefix: [mStart, min(vBeg, mEnd))
    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pWh = reinterpret_cast<uintptr_t>(&wh[idxBeg]);
        const uintptr_t pX = reinterpret_cast<uintptr_t>(&sx_half[vBeg - mStart]);
        // wh needs 8-byte alignment for a ushort4 (4x uint16_t) load;
        // sx_half needs 4-byte alignment for a __half2 load.
        const bool aligned = ((pWh & 0x7) == 0) && ((pX & 0x3) == 0);

        if (aligned) {
            for (int r = vBeg + lane * 4; r + 3 < vEnd; r += 32 * 4) {
                const size_t idx = colBase + static_cast<size_t>(r);
                const ushort4 whv = *reinterpret_cast<const ushort4*>(&wh[idx]);
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(whv.x);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(whv.y);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(whv.z);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(whv.w);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&sx_half[r - mStart]);
                __half2 x23 = *reinterpret_cast<__half2*>(&sx_half[r - mStart + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
        } else {
            // Unaligned fallback -- still correct, just not vectorized.
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
                __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
    }

    // Scalar suffix: [vEnd, mEnd)
    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    __half2 acc2 = __hadd2(acc01, acc23);
    float accum = __half2float(__low2half(acc2)) + __half2float(__high2half(acc2));

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0) atomicAdd(&y[col], __float2half(alpha * accum));
}

// Host wrapper for mv_fp32_16_pure_half_transpose_atomiconly_scaled_
// mblock_vec4_half_io_kernel above -- SAME M_BLOCK-scaling as mv_fp32_
// 16_pure_half_transpose_atomiconly_scaled_mblock_vec4_retuned_floor
// (target=kMvFp32_16TransposeTargetGridBlocks=2048, floor=
// kMvFp32_16TransposeMinMBlock=256, the sibling this was built to
// compare against directly per the user's own request -- "a version of
// pure, atomiconly, retuned_floor that takes the input/output vector as
// fp16"), reused unchanged since the M_BLOCK-scaling formula is
// independent of x/y's own storage type. Only handles TRANSPOSE +
// ld_a==size[0] -- no fallback to a general dispatch, standalone
// comparison kernel, same convention as every other atomiconly_
// scaled_mblock-family kernel in this file.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_half_io_retuned_floor(
    TransposeType trans, double alpha, dim<2> size, const uint16_t* wh, size_t ld_a, const __half* x, size_t ld_x,
    double beta, __half* y, size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(__half));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_half_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_half_io_kernel<<<grid, block, shmem>>>(
        wh, x, y, m, k, M_BLOCK, static_cast<float>(alpha));
}

// Safe two-uint16_t loader: vectorized even when starting at a
// 2B-misaligned address -- ported from randls2.0's own load_half2_
// unaligned (temp-dependencies/randls2.0/src/kernels/cuda/matrix/
// dense_kernels.cu:7521-7532), generalized from __half to raw uint16_t
// since the caller (mv_fp32_16_pure_half_transpose_warp_owner_kernel
// below) decodes each half itself via fp32_16_half_only rather than
// reinterpreting bits as __half -- packing into a __half2 first would
// just be undone immediately.
__device__ inline void fp32_16_load_pair_unaligned(const uint16_t* __restrict__ ptr, uint16_t& lo, uint16_t& hi) {
    const uintptr_t addr = reinterpret_cast<uintptr_t>(ptr);
    const uintptr_t aligned = addr & ~static_cast<uintptr_t>(0x3);
    const int off = static_cast<int>(addr & 0x3);
    const uint32_t* p32 = reinterpret_cast<const uint32_t*>(aligned);

    uint32_t w0 = __ldg(p32);
    uint32_t pair32;
    if (off == 0) {
        pair32 = w0;  // [lo|hi]
    } else {  // off == 2; pair straddles two words
        uint32_t w1 = __ldg(p32 + 1);
        pair32 = (w0 >> 16) | (w1 << 16);
    }
    lo = static_cast<uint16_t>(pair32 & 0xFFFFu);
    hi = static_cast<uint16_t>(pair32 >> 16);
}

// Standalone TRANSPOSE pure_half sibling exploring an entirely different
// grid/reduction strategy: "warp owner, no atomics" -- ported from
// randls2.0's own gemv_fp16_cm_T_warp_owner (temp-dependencies/randls2.0/
// src/kernels/cuda/matrix/dense_kernels.cu:7533-7581, the pure single-
// __half*-array overload; there's also a wh/wr-pair overload at :7442
// for the reconstruction tier, not used here), NOT a variant of mv_fp32_
// 16_pure_half_transpose_atomiconly_scaled_mblock_vec4 above. One warp
// owns output column k for its ENTIRE lifetime (loops the whole M range
// internally in kMvFp32_16TransposeWarpdotMTile-sized tiles, x staged
// into shared memory once per tile and reused by every lane in the
// block), with exactly ONE warp-shuffle reduction and ONE write per
// column at the very end -- no atomics anywhere, since only one warp
// ever touches a given column by construction (grid.x fixed at 1). This
// is the SAME structural skeleton as the already-existing mv_fp32_16_
// transpose_warpdot_tiled_fast_normal_kernel above, deliberately reusing
// its kMvFp32_16TransposeWarpdotMTile/WarpdotWarpsPerBlock constants and
// grid formula unchanged -- only the decode and the load are different.
//
// IMPORTANT PRIOR ART: this exact structural design (warp-owner, no
// atomics, no M_BLOCK-scaling) was already tried in THIS file for the
// fp32_16 RECONSTRUCTION tier -- mv_fp32_16_transpose_warpdot_tiled_
// fast_normal_kernel above -- and measured a REAL REGRESSION there
// (-18.7% to -25.7% vs the atomicAdd/M_BLOCK-scaled design, M=1024-2048).
// That comment's own diagnosis: randls2.0's near-cuBLAS-parity result
// was on PLAIN fp32 (no decode); once every read also pays fp32_16_
// combine_fast_normal's own two-array decode cost, the fixed serial
// per-warp walk falls behind. This kernel is a materially different
// case, not a rerun of that same experiment, for two concrete reasons:
//   1. fp32_16_half_only's decode (single wh array, cheap reinterpret+
//      control-bit branch) is far cheaper than fp32_16_combine_fast_
//      normal's full two-array reconstruction.
//   2. Unlike that kernel -- which cannot vectorize its load at all,
//      since wh/wr are separate arrays, never adjacent in memory --
//      pure_half's single wh array lets ADJACENT ROWS in the same
//      column be read as a genuinely vectorized pair (exploiting the
//      same column-major row-adjacency this file's atomiconly_scaled_
//      mblock family already exploits via ushort4 loads), via fp32_16_
//      load_pair_unaligned above.
// Whether the cheaper decode and real vectorization are enough to avoid
// the reconstruction tier's regression here is exactly what needs a
// real hardware measurement.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_pure_half_transpose_warp_owner_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ y,
    int m, int k, float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;

    __shared__ float x_sh[kMvFp32_16TransposeWarpdotMTile];

    float accum = 0.f;
    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    for (int r0 = 0; r0 < m; r0 += kMvFp32_16TransposeWarpdotMTile) {
        const int tileLen = min(kMvFp32_16TransposeWarpdotMTile, m - r0);

        for (int t = warpId * 32 + lane; t < tileLen; t += warpsPerBlock * 32) {
            x_sh[t] = __ldg(&x[r0 + t]);
        }
        __syncthreads();

        if (col < k) {
            // Vectorized, alignment-safe pair processing: 2 rows at a
            // time per lane (adjacent rows in the same column-major
            // column are memory-adjacent uint16_t elements).
            for (int t = lane * 2; t + 1 < tileLen; t += 64) {
                const size_t idx = colBase + static_cast<size_t>(r0 + t);
                uint16_t lo, hi;
                fp32_16_load_pair_unaligned(&wh[idx], lo, hi);
                float a0 = __half2float(fp32_16_half_only_branchless_no_overflow_nomask(lo));
                float a1 = __half2float(fp32_16_half_only_branchless_no_overflow_nomask(hi));
                accum = fmaf(a0, x_sh[t], accum);
                accum = fmaf(a1, x_sh[t + 1], accum);
            }
            // Odd tail: handle the last leftover row once.
            if ((tileLen & 1) && lane == 0) {
                const int t1 = tileLen - 1;
                const size_t idx = colBase + static_cast<size_t>(r0 + t1);
                float a = __half2float(fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]));
                accum = fmaf(a, x_sh[t1], accum);
            }
        }
        __syncthreads();
    }

    if (col < k) {
        unsigned mask = 0xffffffffu;
#pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            accum += __shfl_down_sync(mask, accum, off);

        if (lane == 0) y[col] += alpha * accum;
    }
}

// Host wrapper for mv_fp32_16_pure_half_transpose_warp_owner_kernel
// above -- no M_BLOCK-scaling here at all (see the kernel's own comment):
// grid.x is always 1, grid.y is the only grid dimension that varies with
// problem size, same convention mv_fp32_16_transpose_warpdot_tiled_
// fast_normal's own host wrapper already uses. Only handles TRANSPOSE +
// ld_a==size[0] -- no fallback to a general dispatch, standalone
// comparison kernel, same convention as every other pure_half_transpose
// kernel in this file.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_pure_half_transpose_warp_owner(TransposeType trans, double alpha, dim<2> size, const uint16_t* wh,
                                                size_t ld_a, const float* x, size_t ld_x, double beta, float* y,
                                                size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(float));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    dim3 block(32, kMvFp32_16TransposeWarpdotWarpsPerBlock);
    dim3 grid(1, (k + kMvFp32_16TransposeWarpdotWarpsPerBlock - 1) / kMvFp32_16TransposeWarpdotWarpsPerBlock);

    mv_fp32_16_pure_half_transpose_warp_owner_kernel<<<grid, block>>>(wh, x, y, m, k, static_cast<float>(alpha));
}

// Split-then-reduce counterpart of mv_fp32_16_pure_half_transpose_warp_
// owner_kernel above, built to fix the real, measured cause of that
// kernel's own worst-of-everything result on real A100 hardware: its
// grid is fixed at (1, ceil(k/8)) -- NO M-splitting at all -- so for any
// shape where k isn't huge, total blocks launched is far too small to
// fill the GPU (e.g. k=4096 -> only 512 blocks total), the exact same
// under-occupancy failure mode the fp32_16 reconstruction tier's own
// FIRST atomiconly kernel had before ITS OWN M_BLOCK-scaling retune
// fixed it (see kMvFp32_16TransposeTargetGridBlocks's own history). The
// warp-owner design's whole point was avoiding atomics, so this reuses
// the SAME split-then-reduce structure mv_fp32_16_transpose_atomiconly_
// scaled_mblock_fast_normal_wrapborrow_vec4_split_kernel already
// established for a DIFFERENT reason (atomic contention at very large
// gridM) -- here it's repurposed to buy grid-oversubscription instead:
// each block now covers only an M_BLOCK-sized slice (not the whole M
// range), writes its own partial sum to a UNIQUE (split, col) scratch
// slot (no atomics -- still true to the design's own premise, since
// distinct blocks never touch the same slot), and a separate reduce
// pass (mv_fp32_16_wide_reduce_kernel, reused unchanged) combines them
// with alpha/beta applied once. Same fp32_16_load_pair_unaligned-based
// vectorized pair loads and fp32_16_half_only decode as the untiled
// kernel above -- only the grid/reduction structure changes.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_pure_half_transpose_warp_owner_split_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, double* __restrict__ partial,
    int m, int k, int M_BLOCK) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    const int splitIdx = blockIdx.x;

    const int mStart = splitIdx * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ float x_sh[];
    const int tileLen = mEnd - mStart;
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;
    for (int t = tid; t < tileLen; t += nt) x_sh[t] = __ldg(&x[mStart + t]);
    __syncthreads();

    if (col < k) {
        const size_t ld = static_cast<size_t>(m);
        const size_t colBase = static_cast<size_t>(col) * ld;

        float accum = 0.f;
        for (int t = lane * 2; t + 1 < tileLen; t += 64) {
            const size_t idx = colBase + static_cast<size_t>(mStart + t);
            uint16_t lo, hi;
            fp32_16_load_pair_unaligned(&wh[idx], lo, hi);
            float a0 = __half2float(fp32_16_half_only_branchless_no_overflow_nomask(lo));
            float a1 = __half2float(fp32_16_half_only_branchless_no_overflow_nomask(hi));
            accum = fmaf(a0, x_sh[t], accum);
            accum = fmaf(a1, x_sh[t + 1], accum);
        }
        if ((tileLen & 1) && lane == 0) {
            const int t1 = tileLen - 1;
            const size_t idx = colBase + static_cast<size_t>(mStart + t1);
            float a = __half2float(fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]));
            accum = fmaf(a, x_sh[t1], accum);
        }

        unsigned mask = 0xffffffffu;
#pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            accum += __shfl_down_sync(mask, accum, off);

        if (lane == 0)
            partial[static_cast<size_t>(splitIdx) * static_cast<size_t>(k) + static_cast<size_t>(col)] =
                static_cast<double>(accum);
    }
}

// Returns the number of doubles mv_fp32_16_pure_half_transpose_warp_
// owner_split's own scratch buffer needs for the given shape -- gridM *
// k, using the EXACT SAME M_BLOCK-scaling that function's own host
// wrapper computes (target=kMvFp32_16TransposeTargetGridBlocks=2048,
// floor=kMvFp32_16TransposeMinMBlock=256 -- already validated for this
// same pure_half decode tier by _atomiconly_scaled_mblock_vec4_retuned_
// floor). Call once per distinct shape (outside any timed loop) to size
// and allocate the buffer, then reuse it across every call at that
// shape -- same workspace contract as mv_fp32_16_accurate_workspace_
// size/mv_fp32_16_accurate_workspace and mv_fp32_16_transpose_
// atomiconly_scaled_mblock_fast_normal_wrapborrow_vec4_retarget2_split_
// workspace_size (see that pair's own comment for why a fresh
// cudaMalloc+cudaFree on every call was explicitly rejected earlier this
// session). trans/ld_a are NOT checked here (this only computes a
// buffer size, never launches anything) -- an unsupported shape simply
// gets a size that's never used, since the caller's own host wrapper
// returns immediately without touching workspace in that case.
size_t mv_fp32_16_pure_half_transpose_warp_owner_split_workspace_size(dim<2> size) {
    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    return static_cast<size_t>(gridM) * static_cast<size_t>(k);
}

// Host wrapper for mv_fp32_16_pure_half_transpose_warp_owner_split_
// kernel above -- caller-provided workspace (see mv_fp32_16_pure_half_
// transpose_warp_owner_split_workspace_size above), no internal
// cudaMalloc/cudaFree in the timed path (explicit standing requirement
// this session, first established for the fp32_16 reconstruction tier's
// own _retarget2_split). Only handles TRANSPOSE + ld_a==size[0] --
// standalone comparison kernel, same convention as every other
// pure_half_transpose kernel in this file.
//
// MEASURED on real A100 hardware (square M=K, M=1024-65536): confirms
// the diagnosis above -- a real, consistent win over plain warp_owner at
// every size tested (1.10x-1.78x faster), closing most of that kernel's
// gap to cuBLAS Hgemm (0.41x-0.73x -> 0.68x-1.04x) and landing close to
// parity with _atomiconly_scaled_mblock_vec4_retuned_floor (0.83x-1.10x
// of it, even BEATING it at M=8192/12288). Remaining gap to _retuned_
// floor grows at the largest sizes tested (M=16384-65536, 0.83x-0.91x)
// -- plausibly the extra scratch-buffer write+readback traffic (double,
// not float, unlike accum's own float precision) this split design pays
// that atomicAdd never does, worth isolating next.
void mv_fp32_16_pure_half_transpose_warp_owner_split(TransposeType trans, double alpha, dim<2> size,
                                                      const uint16_t* wh, size_t ld_a, const float* x, size_t ld_x,
                                                      double beta, float* y, size_t ld_y, double* workspace) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(float);

    mv_fp32_16_pure_half_transpose_warp_owner_split_kernel<<<grid, block, shmem>>>(wh, x, workspace, m, k, M_BLOCK);

    int reduce_blocks = static_cast<int>((rows_op + kMvTileSize - 1) / kMvTileSize);
    mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(alpha, beta, rows_op, static_cast<size_t>(gridM),
                                                                   workspace, y);
}

// float-partial counterpart of mv_fp32_16_wide_reduce_kernel -- every
// OTHER *_split/*_wide reduce in this file accumulates gridM (or
// col_splits) partials in double, chosen for the fp32_16 RECONSTRUCTION
// tier's own accuracy needs. pure_half kernels already accept a 5.0
// relative tolerance (fp32_16_pure_half_transpose_warp_owner_split's own
// correctness check included) because __half-source rounding error
// already dwarfs anything a double accumulator could preserve here --
// there is no accuracy reason to pay double's extra bytes in a scratch
// buffer that exists ONLY to move data between two kernel launches, not
// for its own precision. Used by warp_owner_split_f32 below to test
// whether that extra write+readback bandwidth explains its own measured
// trailing-off at the largest M tested (see that kernel's own comment).
__global__ void mv_fp32_16_pure_half_reduce_kernel(double alpha, double beta, size_t rows_op, size_t col_splits,
                                                    const float* __restrict__ partial, float* __restrict__ y) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= rows_op) return;
    float acc = 0.f;
    for (size_t s = 0; s < col_splits; ++s) acc += partial[s * rows_op + i];
    y[i] = (beta != 0.0) ? static_cast<float>(alpha * acc + beta * static_cast<double>(y[i]))
                          : static_cast<float>(alpha * acc);
}

// float-partial counterpart of mv_fp32_16_pure_half_transpose_warp_
// owner_split_kernel above -- IDENTICAL compute (same M_BLOCK-scaling
// grid, same shared x-staging, same fp32_16_load_pair_unaligned-based
// vectorized pair loads and fp32_16_half_only decode), only the scratch
// buffer element type changes from double to float, storing accum
// directly rather than casting to double first -- isolates whether the
// extra buffer bandwidth (not accum's own precision, already float
// internally either way) explains _split's own measured trailing-off at
// the largest M tested (M=16384-65536, 0.83x-0.91x of _retuned_floor,
// vs near-parity or a real win at M=8192-12288). See mv_fp32_16_pure_
// half_reduce_kernel's own comment for why float loses nothing here.
//
// UNTESTED: no GEMV performance measurement has been run yet.
__global__ void mv_fp32_16_pure_half_transpose_warp_owner_split_f32_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ partial,
    int m, int k, int M_BLOCK) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    const int splitIdx = blockIdx.x;

    const int mStart = splitIdx * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ float x_sh[];
    const int tileLen = mEnd - mStart;
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;
    for (int t = tid; t < tileLen; t += nt) x_sh[t] = __ldg(&x[mStart + t]);
    __syncthreads();

    if (col < k) {
        const size_t ld = static_cast<size_t>(m);
        const size_t colBase = static_cast<size_t>(col) * ld;

        float accum = 0.f;
        for (int t = lane * 2; t + 1 < tileLen; t += 64) {
            const size_t idx = colBase + static_cast<size_t>(mStart + t);
            uint16_t lo, hi;
            fp32_16_load_pair_unaligned(&wh[idx], lo, hi);
            float a0 = __half2float(fp32_16_half_only_branchless_no_overflow_nomask(lo));
            float a1 = __half2float(fp32_16_half_only_branchless_no_overflow_nomask(hi));
            accum = fmaf(a0, x_sh[t], accum);
            accum = fmaf(a1, x_sh[t + 1], accum);
        }
        if ((tileLen & 1) && lane == 0) {
            const int t1 = tileLen - 1;
            const size_t idx = colBase + static_cast<size_t>(mStart + t1);
            float a = __half2float(fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]));
            accum = fmaf(a, x_sh[t1], accum);
        }

        unsigned mask = 0xffffffffu;
#pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            accum += __shfl_down_sync(mask, accum, off);

        if (lane == 0)
            partial[static_cast<size_t>(splitIdx) * static_cast<size_t>(k) + static_cast<size_t>(col)] = accum;
    }
}

// Returns the number of floats mv_fp32_16_pure_half_transpose_warp_
// owner_split_f32's own scratch buffer needs -- IDENTICAL element count
// to mv_fp32_16_pure_half_transpose_warp_owner_split_workspace_size
// (gridM * k, same M_BLOCK-scaling formula), only the caller multiplies
// by sizeof(float) instead of sizeof(double) when allocating.
size_t mv_fp32_16_pure_half_transpose_warp_owner_split_f32_workspace_size(dim<2> size) {
    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    return static_cast<size_t>(gridM) * static_cast<size_t>(k);
}

// Host wrapper for mv_fp32_16_pure_half_transpose_warp_owner_split_f32_
// kernel above -- caller-provided float workspace (see _workspace_size
// above), no internal cudaMalloc/cudaFree in the timed path. Only
// handles TRANSPOSE + ld_a==size[0], standalone comparison kernel.
//
// UNTESTED: no GEMV performance measurement has been run yet.
void mv_fp32_16_pure_half_transpose_warp_owner_split_f32(TransposeType trans, double alpha, dim<2> size,
                                                          const uint16_t* wh, size_t ld_a, const float* x,
                                                          size_t ld_x, double beta, float* y, size_t ld_y,
                                                          float* workspace) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(float);

    mv_fp32_16_pure_half_transpose_warp_owner_split_f32_kernel<<<grid, block, shmem>>>(wh, x, workspace, m, k,
                                                                                        M_BLOCK);

    int reduce_blocks = static_cast<int>((rows_op + kMvTileSize - 1) / kMvTileSize);
    mv_fp32_16_pure_half_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(alpha, beta, rows_op,
                                                                        static_cast<size_t>(gridM), workspace, y);
