// already uses for its own workspace sizing).
void mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec4_split(TransposeType trans, double alpha,
                                                                                dim<2> size, const uint16_t* wh,
                                                                                size_t ld_a, const float* x,
                                                                                size_t ld_x, double beta, float* y,
                                                                                size_t ld_y, float* workspace) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec4_split_kernel<<<grid, block, shmem>>>(
        wh, x, workspace, m, k, M_BLOCK);

    int reduce_blocks = static_cast<int>((rows_op + kMvTileSize - 1) / kMvTileSize);
    mv_fp32_16_pure_half_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(alpha, beta, rows_op,
                                                                        static_cast<size_t>(gridM), workspace, y);
}

// Register-blocking width sweep for the fast2/vec4_split kernel above --
// same motivation and methodology as this session's NO_TRANSPOSE test-
// new3/test-new4 sweep (kMvRowsPerThreadTest3=2/kMvRowsPerThreadTest4=8
// there): sweep the per-lane vectorization width (vec4_split's own N=4)
// to check whether a narrower or wider register-blocking factor overlaps
// this kernel's ALU-bound decode work with its L1TEX-bound wh loads
// better. ncu profiling this session found this kernel 86% Compute-SM-
// bound (ALU flagged as the over-utilized pipeline) with ~50% of stall
// cycles waiting on L1TEX scoreboard dependencies -- a very different
// bound than the NO_TRANSPOSE sweep's kernel, so N=4 being optimal there
// is not assumed to carry over here. This is the N=2 sibling: mechanical
// duplicate of the kernel above with one ushort2/half2 load+accumulate
// per lane-iteration instead of two ushort4/half2 pairs (single acc01
// accumulator, no acc23). Same decode (branchless, no-overflow), same
// M_BLOCK/grid/workspace-size contract -- shares vec4_split's own
// workspace-size function (decode- and width-independent).
__global__ void mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec2_split_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ partial,
    int m, int k, int M_BLOCK) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    const bool col_valid = col < k;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ __half sx_half[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_half[r - mStart] = __float2half(__ldg(&x[r]));
    }
    __syncthreads();

    if (!col_valid) return;

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));

    const int vBeg = (mStart + 1) & ~1;
    const int vEnd = mEnd & ~1;

    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pWh = reinterpret_cast<uintptr_t>(&wh[idxBeg]);
        const uintptr_t pX = reinterpret_cast<uintptr_t>(&sx_half[vBeg - mStart]);
        const bool aligned = ((pWh & 0x3) == 0) && ((pX & 0x3) == 0);

        if (aligned) {
            for (int r = vBeg + lane * 2; r + 1 < vEnd; r += 32 * 2) {
                const size_t idx = colBase + static_cast<size_t>(r);
                const ushort2 whv = *reinterpret_cast<const ushort2*>(&wh[idx]);
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(whv.x);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(whv.y);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 x01 = *reinterpret_cast<__half2*>(&sx_half[r - mStart]);
                acc01 = __hfma2(a01, x01, acc01);
            }
        } else {
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
                __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
    }

    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    float accum = __half2float(__low2half(acc01)) + __half2float(__high2half(acc01));

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0)
        partial[static_cast<size_t>(blockIdx.x) * static_cast<size_t>(k) + static_cast<size_t>(col)] = accum;
}

void mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec2_split(TransposeType trans, double alpha,
                                                                                dim<2> size, const uint16_t* wh,
                                                                                size_t ld_a, const float* x,
                                                                                size_t ld_x, double beta, float* y,
                                                                                size_t ld_y, float* workspace) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec2_split_kernel<<<grid, block, shmem>>>(
        wh, x, workspace, m, k, M_BLOCK);

    int reduce_blocks = static_cast<int>((rows_op + kMvTileSize - 1) / kMvTileSize);
    mv_fp32_16_pure_half_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(alpha, beta, rows_op,
                                                                        static_cast<size_t>(gridM), workspace, y);
}

// N=8 sibling of the same register-blocking sweep: two ushort4/half2 pairs
// (four half2 accumulators, acc01/acc23/acc45/acc67) per lane-iteration
// instead of vec4_split's one pair. Same decode, M_BLOCK/grid/workspace-
// size contract as vec2_split/vec4_split above.
__global__ void mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec8_split_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ partial,
    int m, int k, int M_BLOCK) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    const bool col_valid = col < k;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ __half sx_half[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_half[r - mStart] = __float2half(__ldg(&x[r]));
    }
    __syncthreads();

    if (!col_valid) return;

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc45 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc67 = __half2half2(static_cast<__half>(0.0f));

    const int vBeg = (mStart + 7) & ~7;
    const int vEnd = mEnd & ~7;

    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pWh = reinterpret_cast<uintptr_t>(&wh[idxBeg]);
        const uintptr_t pX = reinterpret_cast<uintptr_t>(&sx_half[vBeg - mStart]);
        const bool aligned = ((pWh & 0x7) == 0) && ((pX & 0x3) == 0);

        if (aligned) {
            for (int r = vBeg + lane * 8; r + 7 < vEnd; r += 32 * 8) {
                const size_t idx = colBase + static_cast<size_t>(r);
                const ushort4 whv_lo = *reinterpret_cast<const ushort4*>(&wh[idx]);
                const ushort4 whv_hi = *reinterpret_cast<const ushort4*>(&wh[idx + 4]);
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(whv_lo.x);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(whv_lo.y);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(whv_lo.z);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(whv_lo.w);
                __half a4 = fp32_16_half_only_branchless_no_overflow_nomask(whv_hi.x);
                __half a5 = fp32_16_half_only_branchless_no_overflow_nomask(whv_hi.y);
                __half a6 = fp32_16_half_only_branchless_no_overflow_nomask(whv_hi.z);
                __half a7 = fp32_16_half_only_branchless_no_overflow_nomask(whv_hi.w);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 a45 = __halves2half2(a4, a5);
                __half2 a67 = __halves2half2(a6, a7);
                __half2 x01 = *reinterpret_cast<__half2*>(&sx_half[r - mStart]);
                __half2 x23 = *reinterpret_cast<__half2*>(&sx_half[r - mStart + 2]);
                __half2 x45 = *reinterpret_cast<__half2*>(&sx_half[r - mStart + 4]);
                __half2 x67 = *reinterpret_cast<__half2*>(&sx_half[r - mStart + 6]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
                acc45 = __hfma2(a45, x45, acc45);
                acc67 = __hfma2(a67, x67, acc67);
            }
        } else {
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
                __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
    }

    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    __half2 acc_lo = __hadd2(acc01, acc23);
    __half2 acc_hi = __hadd2(acc45, acc67);
    __half2 acc2 = __hadd2(acc_lo, acc_hi);
    float accum = __half2float(__low2half(acc2)) + __half2float(__high2half(acc2));

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0)
        partial[static_cast<size_t>(blockIdx.x) * static_cast<size_t>(k) + static_cast<size_t>(col)] = accum;
}

void mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec8_split(TransposeType trans, double alpha,
                                                                                dim<2> size, const uint16_t* wh,
                                                                                size_t ld_a, const float* x,
                                                                                size_t ld_x, double beta, float* y,
                                                                                size_t ld_y, float* workspace) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec8_split_kernel<<<grid, block, shmem>>>(
        wh, x, workspace, m, k, M_BLOCK);

    int reduce_blocks = static_cast<int>((rows_op + kMvTileSize - 1) / kMvTileSize);
    mv_fp32_16_pure_half_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(alpha, beta, rows_op,
                                                                        static_cast<size_t>(gridM), workspace, y);
}

// ====================================================================
// "Native-accumulation" packed-storage NO_TRANSPOSE GEMV: FP32_16-packed A
// (wh-only, "implicit", same branchless no-overflow decode the production
// implicit path uses -- bit-exact with the safe fp32_16_half_only on
// no-overflow data) but with the ACCUMULATION structure of
// mv_fp16_native_mixed (mv_cuda_kernels.cu), the kernel LSQR's
// --explicit-duplicates runs. A mechanical duplicate of mv_fp16_native_
// mixed's whole NO_TRANSPOSE dispatch tree with every A[idx] read replaced
// by the decode -- nothing else changed:
//   rows_op <  8192            wide half2 kernel: column range split over
//                              col_splits blocks, __half2 accumulation
//                              flushed into a DOUBLE every 256-column tile,
//                              per-split double partials + reduce kernel
//   8192 <= rows_op < 131072   atomic kernel: same tile-flushed __half2
//                              accumulation, float atomicAdd combine
//   rows_op >= 131072          tiled kernel (what LSQR's M=1e6 uses): one
//                              thread per row, SCALAR __half accumulation
//                              over each 256-column tile, flushed into a
//                              double per tile
// Why: the packed implicit kernels (mv_fp32_16_pure_half_wide_ilp_shared_
// half2_atomic_best and, at large M, the narrow_vec kernel) carry one fp16
// accumulator across up to the whole column range, so their GEMV error
// grows with K (measured: 5.6e-4 at K=1024 to 6.7e-3 at K=65536), and
// LSQR's implicit configuration needs measurably more iterations than the
// explicit one as the column count grows. mv_fp16_native_mixed instead
// bounds every fp16 chain to 256 terms and widens at tile boundaries (a fix
// its own comments say was added after a real LSQR run stagnated). This
// keeps the packed storage/decode and swaps in that accumulation, to check
// whether the accuracy can be had without giving up the packed kernels'
// throughput. NO_TRANSPOSE only (mv_fp16_native_mixed's TRANSPOSE path is
// a separate, dedicated kernel). The constants below copy mv_cuda_kernels.
// cu's own (tile 256, wide-row threshold and target threads 131072,
// half2-vs-atomic crossover 8192) so the two dispatch identically.
static constexpr int kNativeAccumTileSize = 256;
static constexpr size_t kNativeAccumTargetTotalThreads = 131072;
static constexpr size_t kNativeAccumWideRowThreshold = 131072;
static constexpr size_t kNativeAccumCrossoverThreshold = 8192;

static int nativeaccum_choose_col_splits(size_t rows_op, size_t cols_op, size_t target_total_threads) {
    size_t row_tiles = (rows_op + kNativeAccumTileSize - 1) / kNativeAccumTileSize;
    size_t total_row_threads = row_tiles * kNativeAccumTileSize;
    size_t splits = target_total_threads / std::max<size_t>(total_row_threads, 1);
    splits = std::max<size_t>(splits, size_t(1));
    return static_cast<int>(std::min(splits, cols_op));
}

__global__ void mv_fp32_16_pure_half_nativeaccum_tiled_kernel(double alpha, size_t m, size_t n,
                                                              const uint16_t* wh, size_t ld_a,
                                                              const float* x, double beta, float* y) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    __shared__ __half x_tile[kNativeAccumTileSize];
    double acc_wide = 0.0;
    for (size_t tile_start = 0; tile_start < n; tile_start += kNativeAccumTileSize) {
        size_t tile_len = min(static_cast<size_t>(kNativeAccumTileSize), n - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < m) {
            __half tile_acc = static_cast<__half>(0.0f);
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t idx = i + (tile_start + jj) * ld_a;
                tile_acc = tile_acc + fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]) * x_tile[jj];
            }
            acc_wide += static_cast<double>(static_cast<float>(tile_acc));
        }
        __syncthreads();
    }

    if (i >= m) return;
    y[i] = (beta != 0.0)
               ? static_cast<float>(alpha * acc_wide + beta * static_cast<double>(y[i]))
               : static_cast<float>(alpha * acc_wide);
}

__global__ void mv_fp32_16_pure_half_nativeaccum_atomic_kernel(size_t m, size_t n, const uint16_t* wh,
                                                               size_t ld_a, const float* x,
                                                               size_t col_splits, double alpha, float* y) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (n + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, n);

    __shared__ __align__(4) __half x_tile[kNativeAccumTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    double acc_wide = 0.0;
    for (size_t tile_start = col_start; tile_start < col_end; tile_start += kNativeAccumTileSize) {
        size_t tile_len = min(static_cast<size_t>(kNativeAccumTileSize), col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < m) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + j0 * ld_a]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + (j0 + 1) * ld_a]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + (j0 + 2) * ld_a]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + (j0 + 3) * ld_a]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + j * ld_a]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad = __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
            __half2 acc_sum2 = __hadd2(acc01, acc23);
            __half tile_acc = __low2half(acc_sum2) + __high2half(acc_sum2);
            acc_wide += static_cast<double>(static_cast<float>(tile_acc));
            acc01 = __half2half2(static_cast<__half>(0.0f));
            acc23 = __half2half2(static_cast<__half>(0.0f));
        }
        __syncthreads();
    }

    if (i < m) {
        float contribution = static_cast<float>(alpha) * static_cast<float>(acc_wide);
        atomicAdd(&y[i], contribution);
    }
}

__global__ void mv_fp32_16_pure_half_nativeaccum_prescale_kernel(size_t m, double beta, float* y) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < m) y[i] = static_cast<float>(beta * static_cast<double>(y[i]));
}

__global__ void mv_fp32_16_pure_half_nativeaccum_wide_half2_kernel(size_t m, size_t n, const uint16_t* wh,
                                                                   size_t ld_a, const float* x,
                                                                   size_t col_splits, double* partial) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (n + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, n);

    __shared__ __align__(4) __half x_tile[kNativeAccumTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    double acc_wide = 0.0;
    for (size_t tile_start = col_start; tile_start < col_end; tile_start += kNativeAccumTileSize) {
        size_t tile_len = min(static_cast<size_t>(kNativeAccumTileSize), col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < m) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj;
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + j0 * ld_a]);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + (j0 + 1) * ld_a]);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + (j0 + 2) * ld_a]);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + (j0 + 3) * ld_a]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[i + j * ld_a]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad = __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
            __half2 acc_sum2 = __hadd2(acc01, acc23);
            __half tile_acc = __low2half(acc_sum2) + __high2half(acc_sum2);
            acc_wide += static_cast<double>(static_cast<float>(tile_acc));
            acc01 = __half2half2(static_cast<__half>(0.0f));
            acc23 = __half2half2(static_cast<__half>(0.0f));
        }
        __syncthreads();
    }

    if (i < m) {
        partial[blockIdx.y * m + i] = acc_wide;
    }
}

__global__ void mv_fp32_16_pure_half_nativeaccum_wide_reduce_kernel(double alpha, double beta, size_t m,
                                                                    size_t col_splits, const double* partial,
                                                                    float* y) {
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= m) return;
    double acc = 0.0;
    for (size_t s = 0; s < col_splits; ++s) acc += partial[s * m + i];
    y[i] = (beta != 0.0) ? static_cast<float>(alpha * acc + beta * static_cast<double>(y[i]))
                         : static_cast<float>(alpha * acc);
}

// Composed dispatcher: same three-tier tree, same thresholds, same
// per-call cudaMalloc of the double partials in the half2 tier (matching
// mv_fp16_native_mixed_half2's own, so the timings stay comparable).
void mv_fp32_16_pure_half_nativeaccum(TransposeType trans, double alpha, dim<2> size, const uint16_t* wh,
                                      size_t ld_a, const float* x, size_t ld_x, double beta, float* y,
                                      size_t ld_y) {
    if (trans != TransposeType::NO_TRANSPOSE) return;
    size_t m = size[0];
    size_t n = size[1];

    if (m < kNativeAccumCrossoverThreshold) {
        int col_splits = nativeaccum_choose_col_splits(m, n, kNativeAccumTargetTotalThreads);
        int row_blocks = static_cast<int>((m + kNativeAccumTileSize - 1) / kNativeAccumTileSize);
        double* partial = nullptr;
        cudaError_t err = cudaMalloc(&partial, m * static_cast<size_t>(col_splits) * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_nativeaccum_wide_half2_kernel<<<grid, kNativeAccumTileSize>>>(
            m, n, wh, ld_a, x, col_splits, partial);
        int reduce_blocks = static_cast<int>((m + kNativeAccumTileSize - 1) / kNativeAccumTileSize);
        mv_fp32_16_pure_half_nativeaccum_wide_reduce_kernel<<<reduce_blocks, kNativeAccumTileSize>>>(
            alpha, beta, m, col_splits, partial, y);
        cudaFree(partial);
    } else if (m < kNativeAccumWideRowThreshold) {
        int col_splits = nativeaccum_choose_col_splits(m, n, kNativeAccumTargetTotalThreads * 4);
        int row_blocks = static_cast<int>((m + kNativeAccumTileSize - 1) / kNativeAccumTileSize);
        if (beta == 0.0) {
            cudaMemset(y, 0, m * sizeof(float));
        } else {
            int blocks = static_cast<int>((m + kNativeAccumTileSize - 1) / kNativeAccumTileSize);
            mv_fp32_16_pure_half_nativeaccum_prescale_kernel<<<blocks, kNativeAccumTileSize>>>(m, beta, y);
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_nativeaccum_atomic_kernel<<<grid, kNativeAccumTileSize>>>(
            m, n, wh, ld_a, x, col_splits, alpha, y);
    } else {
        int blocks = static_cast<int>((m + kNativeAccumTileSize - 1) / kNativeAccumTileSize);
        mv_fp32_16_pure_half_nativeaccum_tiled_kernel<<<blocks, kNativeAccumTileSize>>>(
            alpha, m, n, wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

// cp.async sibling of mv_fp32_16_pure_half_fast2_transpose_atomiconly_
// scaled_mblock_vec4_split_kernel above -- mechanical duplicate, added
// as a new, separate function, original untouched. Same motivation as
// mv_fp32_16_pure_half_fast2_narrow_vec_cpasync_kernel's own (this
// file, much earlier): fp32_16_half_only_fast2 alone made no measurable
// difference in a real per-call LSQR timing breakdown, on either
// direction, meaning neither kernel is ALU/decode-bound -- cp.async,
// not decode cost, is the untested lever. x is already staged into
// shared memory ONCE per block (sx_half, unchanged, direct __ldg loop
// before this loop even starts) -- cp.async has nothing to hide there.
// What's NOT staged is wh: every lane's own ushort4 read (4 consecutive
// m-values at one column) happens as a direct, synchronous global load
// every iteration of the aligned/vectorized loop below, with nothing
// hiding its fetch latency. Double-buffers each (warpId, lane)'s own
// NEXT iteration's ushort4 into a private (not cross-thread-shared --
// every thread's own tid=lane+32*warpId slot is only ever read by that
// same thread) shared-memory staging slot while decoding the CURRENT
// iteration's already-staged bytes. Only applied to the aligned
// vectorized path -- the pre-vBeg/post-vEnd scalar fallback loops are
// untouched, same reasoning as every other cp.async kernel in this
// file (not enough per-lane work there to be worth pipelining).
__global__ void mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec4_split_cpasync_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ partial,
    int m, int k, int M_BLOCK) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    const bool col_valid = col < k;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ __half sx_half[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_half[r - mStart] = __float2half(__ldg(&x[r]));
    }
    __syncthreads();

    if (!col_valid) return;

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));

    const int vBeg = (mStart + 3) & ~3;
    const int vEnd = mEnd & ~3;

    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pWh = reinterpret_cast<uintptr_t>(&wh[idxBeg]);
        const uintptr_t pX = reinterpret_cast<uintptr_t>(&sx_half[vBeg - mStart]);
        const bool aligned = ((pWh & 0x7) == 0) && ((pX & 0x3) == 0);

        if (aligned) {
            __shared__ __align__(8) ushort4 stageWh[2][kMvTransposeWarpsPerBlock * 32];

            int r0 = vBeg + lane * 4;
            if (r0 + 3 < vEnd) {
                const size_t idx0 = colBase + static_cast<size_t>(r0);
                __pipeline_memcpy_async(&stageWh[0][tid], &wh[idx0], sizeof(ushort4));
                __pipeline_commit();
                __pipeline_wait_prior(0);
            }

            int cur = 0;
            for (int r = r0; r + 3 < vEnd; r += 32 * 4) {
                int next_r = r + 32 * 4;
                int nxt = cur ^ 1;
                if (next_r + 3 < vEnd) {
                    const size_t idxN = colBase + static_cast<size_t>(next_r);
                    __pipeline_memcpy_async(&stageWh[nxt][tid], &wh[idxN], sizeof(ushort4));
                    __pipeline_commit();
                }

                const ushort4 whv = stageWh[cur][tid];
                __half a0 = fp32_16_half_only_branchless_no_overflow_nomask(whv.x);
                __half a1 = fp32_16_half_only_branchless_no_overflow_nomask(whv.y);
                __half a2 = fp32_16_half_only_branchless_no_overflow_nomask(whv.z);
                __half a3 = fp32_16_half_only_branchless_no_overflow_nomask(whv.w);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&sx_half[r - mStart]);
                __half2 x23 = *reinterpret_cast<__half2*>(&sx_half[r - mStart + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);

                if (next_r + 3 < vEnd) __pipeline_wait_prior(0);
                cur = nxt;
            }
        } else {
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
                __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
                __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
    }

    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    __half2 acc2 = __hadd2(acc01, acc23);
    float accum = __half2float(__low2half(acc2)) + __half2float(__high2half(acc2));

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0)
        partial[static_cast<size_t>(blockIdx.x) * static_cast<size_t>(k) + static_cast<size_t>(col)] = accum;
}

// Host wrapper for the cp.async kernel above -- byte-for-byte the fast2
// kernel's own host wrapper, same workspace-size function.
void mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec4_split_cpasync(
    TransposeType trans, double alpha, dim<2> size, const uint16_t* wh, size_t ld_a, const float* x, size_t ld_x,
    double beta, float* y, size_t ld_y, float* workspace) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_pure_half_fast2_transpose_atomiconly_scaled_mblock_vec4_split_cpasync_kernel<<<grid, block, shmem>>>(
        wh, x, workspace, m, k, M_BLOCK);

    int reduce_blocks = static_cast<int>((rows_op + kMvTileSize - 1) / kMvTileSize);
    mv_fp32_16_pure_half_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(alpha, beta, rows_op,
                                                                        static_cast<size_t>(gridM), workspace, y);
}

// ====================================================================
// mv_fp16_native_mixed's own TRANSPOSE-tuned kernel: true mechanical
// duplicate of mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_
// vec4_split_kernel/_workspace_size/_split above -- the exact same
// M-block-scaled grid (kMvTransposeWarpsPerBlock/kMvTransposeMBlock/
// kMvFp32_16TransposeTargetGridBlocks/kMvFp32_16TransposeMinMBlock, all
// reused directly, unchanged), same shared-memory x-staging, same warp-
// per-column ownership, same shuffle-reduce + partial-buffer-then-
// mv_fp32_16_pure_half_reduce_kernel combine (that reduce kernel is
// already fully generic over A's own storage -- it only ever touches the
// float partial buffer and y, so it's reused here completely unchanged,
// not duplicated) -- every fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]) decode call became
// a direct A[idx] read (A is already genuine __half here, nothing to
// decode), and the vectorized ushort4-load-plus-4x-decode batch became a
// direct 2x__half2 load (same 8 bytes, same alignment requirement, no
// decode branching needed). Built because mv_fp16_native_mixed's own
// TRANSPOSE matvecs (used by lsqr_precision_runner's --explicit-
// duplicates) were reusing the NO_TRANSPOSE-tuned col-split kernel for
// TRANSPOSE too, paying its uncoalesced idx=j+i*ld_a access pattern (see
// mv_fp16_native_mixed's own comment in mv_cuda_kernels.cu) -- this
// kernel targets that shape directly instead, mirroring the ALREADY-
// PROVEN production design LSQR's --implicit-duplicates uses for its own
// TRANSPOSE matvec, rather than a new, unvalidated design.
__global__ void mv_fp16_native_mixed_transpose_atomiconly_scaled_mblock_vec4_split_kernel(
    const __half* __restrict__ A, const float* __restrict__ x, float* __restrict__ partial,
    int m, int k, int M_BLOCK) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    // Same barrier-safety fix as the source kernel's own col_valid
    // handling -- see that kernel's own comment for the full derivation
    // (a real NaN bug, found and fixed earlier this session, from an
    // early return before __syncthreads() when k is not a multiple of
    // warpsPerBlock).
    const int col = blockIdx.y * warpsPerBlock + warpId;
    const bool col_valid = col < k;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;  // safe: block-uniform (depends only on
                                 // blockIdx.x), no divergence at the
                                 // __syncthreads() below.

    extern __shared__ __half sx_half[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_half[r - mStart] = __float2half(__ldg(&x[r]));
    }
    __syncthreads();

    if (!col_valid) return;  // safe now: every thread already reached the
                             // barrier above regardless of its own column.

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));

    const int vBeg = (mStart + 3) & ~3;
    const int vEnd = mEnd & ~3;

    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = A[idx];
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pA = reinterpret_cast<uintptr_t>(&A[idxBeg]);
        const uintptr_t pX = reinterpret_cast<uintptr_t>(&sx_half[vBeg - mStart]);
        const bool aligned = ((pA & 0x7) == 0) && ((pX & 0x3) == 0);

        if (aligned) {
            for (int r = vBeg + lane * 4; r + 3 < vEnd; r += 32 * 4) {
                const size_t idx = colBase + static_cast<size_t>(r);
                __half2 a01 = *reinterpret_cast<const __half2*>(&A[idx]);
                __half2 a23 = *reinterpret_cast<const __half2*>(&A[idx + 2]);
                __half2 x01 = *reinterpret_cast<__half2*>(&sx_half[r - mStart]);
                __half2 x23 = *reinterpret_cast<__half2*>(&sx_half[r - mStart + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
        } else {
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                __half a = A[idx];
                __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
                __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
    }

    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = A[idx];
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    __half2 acc2 = __hadd2(acc01, acc23);
    float accum = __half2float(__low2half(acc2)) + __half2float(__high2half(acc2));

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0)
        partial[static_cast<size_t>(blockIdx.x) * static_cast<size_t>(k) + static_cast<size_t>(col)] = accum;
}

// Identical M_BLOCK-scaling/gridM formula as the source kernel's own
// _workspace_size -- doesn't touch A/decode at all, so this is a direct,
// unmodified mechanical copy (only renamed).
size_t mv_fp16_native_mixed_transpose_atomiconly_scaled_mblock_vec4_split_workspace_size(dim<2> size) {
    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    return static_cast<size_t>(gridM) * static_cast<size_t>(k);
}

// Host wrapper -- caller-provided float workspace (see _workspace_size
// above), no internal cudaMalloc/cudaFree in the timed path. Only handles
// TRANSPOSE + ld_a==size[0], same contract as the source kernel's own
// host wrapper. Reuses mv_fp32_16_pure_half_reduce_kernel directly
// (already fully generic, no A-type dependency).
void mv_fp16_native_mixed_transpose_atomiconly_scaled_mblock_vec4_split(TransposeType trans, double alpha,
                                                                         dim<2> size, const __half* A,
                                                                         size_t ld_a, const float* x, size_t ld_x,
                                                                         double beta, float* y, size_t ld_y,
                                                                         float* workspace) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp16_native_mixed_transpose_atomiconly_scaled_mblock_vec4_split_kernel<<<grid, block, shmem>>>(
        A, x, workspace, m, k, M_BLOCK);

    int reduce_blocks = static_cast<int>((rows_op + kMvTileSize - 1) / kMvTileSize);
    mv_fp32_16_pure_half_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(alpha, beta, rows_op,
                                                                        static_cast<size_t>(gridM), workspace, y);
    // Sync before returning, matching mv_fp16_native_mixed_atomic's own
    // (this kernel's NO_TRANSPOSE sibling) existing convention -- this
    // TRANSPOSE kernel was missing it despite being described as a
    // mechanical duplicate of mv_fp32_16_pure_half_transpose_atomiconly_
    // scaled_mblock_vec4_split, which now also has it.
    cudaDeviceSynchronize();
}
