// Host wrapper -- caller-provided double workspace (see _workspace_size
// above), no internal cudaMalloc/cudaFree in the timed path. Only handles
// TRANSPOSE + ld_a==size[0], same contract as the source kernel's own
// host wrapper. Combines via mv_fp16_native_storage_wide_reduce_kernel
// (forward-declared above), not mv_fp32_16_pure_half_reduce_kernel --
// see this block's own header comment for why.
void mv_fp16_native_storage_transpose_atomiconly_scaled_mblock_vec4_split(TransposeType trans, double alpha,
                                                                            dim<2> size, const __half* A,
                                                                            size_t ld_a, const __half* x,
                                                                            size_t ld_x, double beta, __half* y,
                                                                            size_t ld_y, double* workspace) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp16_native_storage_transpose_atomiconly_scaled_mblock_vec4_split_kernel<<<grid, block, shmem>>>(
        A, x, workspace, m, k, M_BLOCK);

    int reduce_blocks = static_cast<int>((rows_op + kMvTileSize - 1) / kMvTileSize);
    mv_fp16_native_storage_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(alpha, beta, rows_op,
                                                                               static_cast<size_t>(gridM),
                                                                               workspace, y);
}
