// EXPERIMENTAL alternative to mv_fp32_16_pure_half's wide-matrix path:
// reuses mv_fp32_16_pure_half_wide_ilp_shared_half2_kernel UNCHANGED (same
// proven-correct 4-way unroll + __half2 packing), but doubles col_splits
// via choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads*2)
// instead of the fixed kMvTargetTotalThreads -- more, smaller column
// chunks per block, more total blocks launched, and a 2x-larger temporary
// "partial" global buffer. Tests whether more column-level parallelism
// helps on top of the current best result (0.84) -- see choose_col_splits_
// target's comment for why this is a cleanly isolated variable, unlike
// mv_fp32_16_pure_half_wide_regblock's confounded col_splits change.
void mv_fp32_16_pure_half_wide_ilp_shared_half2_wide2x(
    TransposeType trans, double alpha, dim<2> size, const uint16_t* wh,
    size_t ld_a, const float* x, size_t ld_x, double beta, float* y,
    size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits =
            choose_col_splits_target(rows_op, cols_op, kMvTargetTotalThreads * 2);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}

