namespace experimental {

__global__ void mm_fp32_16_pure_half_kernel(
    TransposeType transA, TransposeType transB, double alpha, size_t m,
    size_t k, size_t n, const uint16_t* wh, size_t ld_a, const float* B,
    size_t ld_b, double beta, float* C, size_t ld_c) {
    size_t i = blockIdx.y * blockDim.y + threadIdx.y;
    size_t j = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= m || j >= n) return;

    __half acc = static_cast<__half>(0.0f);
    for (size_t l = 0; l < k; ++l) {
        size_t a_row = (transA == TransposeType::NO_TRANSPOSE) ? i : l;
        size_t a_col = (transA == TransposeType::NO_TRANSPOSE) ? l : i;
        size_t idx = a_row + a_col * ld_a;
        __half a_val = fp32_16_half_only_branchless_no_overflow_nomask(wh[idx]);
        float b_f = (transB == TransposeType::NO_TRANSPOSE)
                      ? B[l + j * ld_b]
                      : B[j + l * ld_b];
        __half b_val = static_cast<__half>(b_f);
        acc = acc + a_val * b_val;
    }
    double acc_d = static_cast<double>(static_cast<float>(acc));
    C[i + j * ld_c] = static_cast<float>(
        alpha * acc_d + beta * static_cast<double>(C[i + j * ld_c]));
}

void mm_fp32_16_pure_half(TransposeType transA, TransposeType transB,
                          double alpha, dim<2> size_A, const uint16_t* wh,
                          size_t ld_a, dim<2> size_B, const float* B,
                          size_t ld_b, double beta, float* C, size_t ld_c) {
    size_t m = (transA == TransposeType::NO_TRANSPOSE) ? size_A[0] : size_A[1];
    size_t k = (transA == TransposeType::NO_TRANSPOSE) ? size_A[1] : size_A[0];
    size_t n = (transB == TransposeType::NO_TRANSPOSE) ? size_B[1] : size_B[0];

    dim3 threads(32, 8);
    dim3 blocks((n + threads.x - 1) / threads.x, (m + threads.y - 1) / threads.y);
    mm_fp32_16_pure_half_kernel<<<blocks, threads>>>(
        transA, transB, alpha, m, k, n, wh, ld_a, B, ld_b, beta, C, ld_c);
    cudaDeviceSynchronize();
}

// Same 128x128/BK=8, 8x8 register-blocked tiling as mm_fp32_16_tiled_kernel
// (see kMmFp32_16BM/BN/BK/TM/TN above), but As/Bs are cached as __half and
// the accumulation runs entirely in __half arithmetic, matching mm_fp32_16_
// pure_half_kernel's precision tier instead of mm_fp32_16_tiled_kernel's.
__global__ void mm_fp32_16_pure_half_tiled_kernel(
    double alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    double beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __half As[kMmFp32_16BK][kMmFp32_16BM];
    __shared__ __half Bs[kMmFp32_16BK][kMmFp32_16BN];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16BM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16BN;

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int tid = ty * (kMmFp32_16BN / kMmFp32_16TN) + tx;
    constexpr int kNumThreads =
        (kMmFp32_16BM / kMmFp32_16TM) * (kMmFp32_16BN / kMmFp32_16TN);

    const __half h_zero = static_cast<__half>(0.0f);
    __half acc[kMmFp32_16TM][kMmFp32_16TN];
#pragma unroll
    for (int i = 0; i < kMmFp32_16TM; ++i)
#pragma unroll
        for (int j = 0; j < kMmFp32_16TN; ++j) acc[i][j] = h_zero;

    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16BK) {
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16BM * kMmFp32_16BK; idx += kNumThreads) {
            int i = idx % kMmFp32_16BM;
            int kk = idx / kMmFp32_16BM;
            size_t row = block_row + i;
            size_t kg = k0 + kk;
            if (row < m && kg < k) {
                size_t a_idx = row + kg * ld_a;
                As[kk][i] = fp32_16_half_only_branchless_no_overflow_nomask(wh[a_idx]);
            } else {
                As[kk][i] = h_zero;
            }
        }
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16BK * kMmFp32_16BN; idx += kNumThreads) {
            int j = idx % kMmFp32_16BN;
            int kk = idx / kMmFp32_16BN;
            size_t col = block_col + j;
            size_t kg = k0 + kk;
            Bs[kk][j] = (col < n && kg < k) ? static_cast<__half>(B[kg + col * ld_b])
                                            : h_zero;
        }
        __syncthreads();

#pragma unroll
        for (int kk = 0; kk < kMmFp32_16BK; ++kk) {
            __half a_reg[kMmFp32_16TM];
            __half b_reg[kMmFp32_16TN];
#pragma unroll
            for (int i = 0; i < kMmFp32_16TM; ++i) a_reg[i] = As[kk][ty * kMmFp32_16TM + i];
#pragma unroll
            for (int j = 0; j < kMmFp32_16TN; ++j) b_reg[j] = Bs[kk][tx * kMmFp32_16TN + j];
#pragma unroll
            for (int i = 0; i < kMmFp32_16TM; ++i)
#pragma unroll
                for (int j = 0; j < kMmFp32_16TN; ++j)
                    acc[i][j] = acc[i][j] + a_reg[i] * b_reg[j];
        }
        __syncthreads();
    }

#pragma unroll
    for (int i = 0; i < kMmFp32_16TM; ++i) {
        size_t row = block_row + ty * kMmFp32_16TM + i;
        if (row >= m) continue;
#pragma unroll
        for (int j = 0; j < kMmFp32_16TN; ++j) {
            size_t col = block_col + tx * kMmFp32_16TN + j;
            if (col >= n) continue;
            size_t idx = row + col * ld_c;
            double acc_d = static_cast<double>(static_cast<float>(acc[i][j]));
            C[idx] = static_cast<float>(alpha * acc_d +
                                        beta * static_cast<double>(C[idx]));
        }
    }
}

void mm_fp32_16_pure_half_tiled(TransposeType transA, TransposeType transB,
                                double alpha, dim<2> size_A, const uint16_t* wh,
                                size_t ld_a, dim<2> size_B, const float* B,
                                size_t ld_b, double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_pure_half(transA, transB, alpha, size_A, wh, ld_a, size_B, B, ld_b,
                             beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    dim3 threads(kMmFp32_16BN / kMmFp32_16TN, kMmFp32_16BM / kMmFp32_16TM);
    dim3 blocks((n + kMmFp32_16BN - 1) / kMmFp32_16BN, (m + kMmFp32_16BM - 1) / kMmFp32_16BM);
    mm_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
        alpha, m, k, n, wh, ld_a, B, ld_b, beta, C, ld_c);
    cudaDeviceSynchronize();
}

namespace {
constexpr int kMmFp32_16WmmaTile = 16;
// 128x128 output tile. An initial 64x64x32 attempt (4 warps, 2x2
// fragments/warp) measured a flat ~4.6 TFlop/s across every benchmarked N,
// well BELOW mm_fp32_16_pure_half_tiled's ~6.3 TFlop/s scalar-__half
// kernel. Growing BM/BN to 128 while KEEPING 4 warps (2x4 = 8 fragments/
// warp, to cover the bigger tile with the same warp count) measured WORSE
// (~4.2-4.3 TFlop/s) -- ptxas reported 197 registers/thread for that
// version, capping occupancy at 1 block/SM (256 threads = 8 warps/SM,
// nowhere near enough to hide mma.sync/shared-memory latency). The actual
// lever, confirmed by that failed attempt, is register pressure per
// thread, not raw tile size or arithmetic intensity: this version keeps
// the 128x128 tile (same FLOPs-per-shared-memory-load-round-trip) but
// spreads it over 16 warps (4x4) at 2x2 = 4 fragments/warp instead of 8,
// halving the accumulator-fragment register footprint per thread while
// doubling the warp count available to hide latency -- ~7.4 TFlop/s
// combined with the __launch_bounds__ below. BK went 32 -> 64 last (one
// fewer shared-memory round trip per K span, at the cost of As+Bs+warp_c
// landing exactly at the 48KB static shared-memory limit) for a further
// marginal (~1-2%) gain; halving it back to 32 remains a safe fallback if
// a future change needs the shared-memory headroom back.
constexpr int kMmFp32_16WmmaBM = 128;
constexpr int kMmFp32_16WmmaBN = 128;
constexpr int kMmFp32_16WmmaBK = 64;
constexpr int kMmFp32_16WmmaWarpRows = 4;  // warps spanning BM (32 rows each)
constexpr int kMmFp32_16WmmaWarpCols = 4;  // warps spanning BN (32 cols each)
constexpr int kMmFp32_16WmmaWarps =
    kMmFp32_16WmmaWarpRows * kMmFp32_16WmmaWarpCols;
constexpr int kMmFp32_16WmmaThreads = kMmFp32_16WmmaWarps * 32;
// Each warp's 32x32 output region is 2x2 = 4 accumulator fragments of the
// underlying 16x16x16 mma.sync tile.
constexpr int kMmFp32_16WmmaFragM = 2;
constexpr int kMmFp32_16WmmaFragN = 2;
}  // namespace

// See mm_fp32_16_pure_half_wmma's declaration in fp32_16_cuda_kernels.cuh
// for the full design rationale (tile shape, fp32 accumulator choice, why
// this differs from the GEMV wmma experiment's replication trick). Output
// is staged through a small per-warp 16x16 shared buffer (reused
// sequentially across each warp's 4 fragments) rather than one block-wide
// Cs[128][128] -- at 64KB, a block-wide buffer that size would have capped
// occupancy far below what the 128x128 tile's As/Bs (16KB) allow.
// __launch_bounds__ caps ptxas at 64 registers/thread (the naturally-
// generated 4-fragment version uses ~128, capping occupancy at exactly 1
// block/SM on a 65536-register file) so 2 blocks/SM -- 32 resident warps
// instead of 16 -- fit instead, trading a few spilled registers (see this
// kernel's comment history for the register-count/occupancy investigation
// that motivated the 128x128 tile, 16-warp layout, and this bound) for
// more latency-hiding parallelism.
__global__ __launch_bounds__(kMmFp32_16WmmaThreads, 2) void mm_fp32_16_pure_half_wmma_kernel(
    __half alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    __half beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __half As[kMmFp32_16WmmaBK][kMmFp32_16WmmaBM];
    __shared__ __half Bs[kMmFp32_16WmmaBK][kMmFp32_16WmmaBN];
    __shared__ float warp_c[kMmFp32_16WmmaWarps][kMmFp32_16WmmaTile][kMmFp32_16WmmaTile];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16WmmaBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16WmmaBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane = tid % 32;
    const int warp_row = warp_id / kMmFp32_16WmmaWarpCols;
    const int warp_col = warp_id % kMmFp32_16WmmaWarpCols;
    const int warp_row_base = warp_row * (kMmFp32_16WmmaBM / kMmFp32_16WmmaWarpRows);
    const int warp_col_base = warp_col * (kMmFp32_16WmmaBN / kMmFp32_16WmmaWarpCols);

    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, kMmFp32_16WmmaTile,
                           kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, float>
        c_frag[kMmFp32_16WmmaFragM][kMmFp32_16WmmaFragN];
#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
            nvcuda::wmma::fill_fragment(c_frag[wm][wn], 0.0f);

    const __half h_zero = static_cast<__half>(0.0f);
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16WmmaBK) {
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBM * kMmFp32_16WmmaBK;
            idx += kMmFp32_16WmmaThreads) {
            int mm = idx % kMmFp32_16WmmaBM;
            int kk = idx / kMmFp32_16WmmaBM;
            size_t row = block_row + static_cast<size_t>(mm);
            size_t kg = k0 + static_cast<size_t>(kk);
            As[kk][mm] = (row < m && kg < k) ? fp32_16_half_only_branchless_no_overflow_nomask(wh[row + kg * ld_a])
                                             : h_zero;
        }
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBK * kMmFp32_16WmmaBN;
            idx += kMmFp32_16WmmaThreads) {
            int nn = idx % kMmFp32_16WmmaBN;
            int kk = idx / kMmFp32_16WmmaBN;
            size_t col = block_col + static_cast<size_t>(nn);
            size_t kg = k0 + static_cast<size_t>(kk);
            Bs[kk][nn] = (col < n && kg < k)
                            ? static_cast<__half>(B[kg + col * ld_b])
                            : h_zero;
        }
        __syncthreads();

#pragma unroll
        for (int ks = 0; ks < kMmFp32_16WmmaBK; ks += kMmFp32_16WmmaTile) {
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::col_major>
                a_frag[kMmFp32_16WmmaFragM];
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::row_major>
                b_frag[kMmFp32_16WmmaFragN];
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
                nvcuda::wmma::load_matrix_sync(
                    a_frag[wm],
                    &As[ks][warp_row_base + wm * kMmFp32_16WmmaTile],
                    kMmFp32_16WmmaBM);
#pragma unroll
            for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                nvcuda::wmma::load_matrix_sync(
                    b_frag[wn],
                    &Bs[ks][warp_col_base + wn * kMmFp32_16WmmaTile],
                    kMmFp32_16WmmaBN);
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
                for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                    nvcuda::wmma::mma_sync(c_frag[wm][wn], a_frag[wm], b_frag[wn],
                                          c_frag[wm][wn]);
        }
        __syncthreads();
    }

#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm) {
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn) {
            nvcuda::wmma::store_matrix_sync(&warp_c[warp_id][0][0], c_frag[wm][wn],
                                            kMmFp32_16WmmaTile,
                                            nvcuda::wmma::mem_row_major);
            __syncwarp();
            size_t frag_row = block_row + static_cast<size_t>(warp_row_base) +
                              static_cast<size_t>(wm) * kMmFp32_16WmmaTile;
            size_t frag_col = block_col + static_cast<size_t>(warp_col_base) +
                              static_cast<size_t>(wn) * kMmFp32_16WmmaTile;
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                int elem = lane + 32 * e;
                int rr = elem / kMmFp32_16WmmaTile;
                int cc = elem % kMmFp32_16WmmaTile;
                size_t row = frag_row + static_cast<size_t>(rr);
                size_t col = frag_col + static_cast<size_t>(cc);
                if (row >= m || col >= n) continue;
                size_t cidx = row + col * ld_c;
                float acc_f = warp_c[warp_id][rr][cc];
                C[cidx] = static_cast<float>(alpha) * acc_f + static_cast<float>(beta) * C[cidx];
            }
            __syncwarp();
        }
    }
}

void mm_fp32_16_pure_half_wmma(TransposeType transA, TransposeType transB,
                               double alpha, dim<2> size_A, const uint16_t* wh,
                               size_t ld_a, dim<2> size_B, const float* B,
                               size_t ld_b, double beta, float* C, size_t ld_c) {
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE) {
        mm_fp32_16_pure_half_tiled(transA, transB, alpha, size_A, wh, ld_a, size_B, B,
                                   ld_b, beta, C, ld_c);
        return;
    }
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];

    float f_alpha = static_cast<float>(alpha);
    float f_beta = static_cast<float>(beta);
    __half h_alpha = static_cast<__half>(f_alpha);
    __half h_beta = static_cast<__half>(f_beta);
    dim3 threads(kMmFp32_16WmmaThreads);
    dim3 blocks((n + kMmFp32_16WmmaBN - 1) / kMmFp32_16WmmaBN,
               (m + kMmFp32_16WmmaBM - 1) / kMmFp32_16WmmaBM);
    mm_fp32_16_pure_half_wmma_kernel<<<blocks, threads>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
    cudaDeviceSynchronize();
}

namespace {
// Same BM/BN/warp/fragment shape as mm_fp32_16_pure_half_wmma_kernel, BK
// halved from 64 to 32 -- same reasoning as gemm_fp16_wmma_cpasync_kernel
// in mm_cuda_kernels.cu (room for double-buffered As/Bs within the 48KB
// static shared-memory limit).
constexpr int kMmFp32_16WmmaCpBK = 32;
}  // namespace

// cp.async double-buffered version of mm_fp32_16_pure_half_wmma_kernel,
// ported from gemm_fp16_wmma_cpasync_kernel (mm_cuda_kernels.cu) after that
// kernel's cp.async pipelining measured a real ~8-10% win over the
// unpipelined wmma kernel there by hiding the global-load latency every
// outer-BK tile was previously fully exposing behind a __syncthreads().
//
// The one real complication versus the plain-fp16 version: fp32_16_half_
// only's decode needs actual register computation (a control-bit branch),
// which can't run *inside* a cp.async transfer -- cp.async can only move
// raw bytes. mm_fp32_16_tiled_cpasync_dualbuf (the accurate/fast tier's
// cp.async kernel) solves this with a SEPARATE raw-bytes staging buffer,
// because it decodes wh+wr TOGETHER into a wider float (different size,
// can't reuse the same memory). Here, wh alone decodes into a same-sized
// __half, so the raw bytes can be cp.async'd directly into As's own memory
// (reinterpreted as uint16_t for the copy) and decoded in place once the
// transfer lands, with no second buffer needed -- decoding a boundary
// tile's zero-fill (already a real __half 0.0f, not raw wh bits) is even
// safe to do unconditionally: fp32_16_half_only_branchless_no_overflow_nomask(0) hits its control=0
// passthrough branch and returns 0.0f right back (see fp32_16_pack.hpp),
// so transform_tile below doesn't need to special-case which slots were
// really staged versus zero-filled.
//
// B stays a plain synchronous scalar cast-to-half load (same reasoning as
// every other cp.async kernel in this codebase: B's natural K-contiguous
// global layout conflicts with Bs's N-fast compute layout). Requires ld_a
// and m to both be even (the same 2-row/4-byte cp.async batching
// requirement as gemm_fp16_wmma_cpasync); falls back to mm_fp32_16_pure_
// half_wmma otherwise.
__global__ __launch_bounds__(kMmFp32_16WmmaThreads, 2) void mm_fp32_16_pure_half_wmma_cpasync_kernel(
    __half alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    __half beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __half As[2][kMmFp32_16WmmaCpBK][kMmFp32_16WmmaBM];
    __shared__ __half Bs[2][kMmFp32_16WmmaCpBK][kMmFp32_16WmmaBN];
    __shared__ float warp_c[kMmFp32_16WmmaWarps][kMmFp32_16WmmaTile][kMmFp32_16WmmaTile];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16WmmaBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16WmmaBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane = tid % 32;
    const int warp_row = warp_id / kMmFp32_16WmmaWarpCols;
    const int warp_col = warp_id % kMmFp32_16WmmaWarpCols;
    const int warp_row_base = warp_row * (kMmFp32_16WmmaBM / kMmFp32_16WmmaWarpRows);
    const int warp_col_base = warp_col * (kMmFp32_16WmmaBN / kMmFp32_16WmmaWarpCols);

    const __half h_zero = static_cast<__half>(0.0f);

    // wh: cp.async, 2 contiguous rows (4 bytes) per transfer, straight into
    // As's own memory -- decode happens in transform_tile, not here (see
    // kernel comment). Same "row < m alone suffices, given ld_a/m both
    // even" reasoning as gemm_fp16_wmma_cpasync_kernel's A load.
    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int idx = tid; idx < (kMmFp32_16WmmaBM / 2) * kMmFp32_16WmmaCpBK;
            idx += kMmFp32_16WmmaThreads) {
            int pair = idx % (kMmFp32_16WmmaBM / 2);
            int kk = idx / (kMmFp32_16WmmaBM / 2);
            int i = pair * 2;
            size_t row = block_row + static_cast<size_t>(i);
            size_t kg = k0 + static_cast<size_t>(kk);
            if (row < m && kg < k) {
                __pipeline_memcpy_async(
                    reinterpret_cast<uint16_t*>(&As[buf][kk][i]), &wh[row + kg * ld_a],
                    sizeof(uint16_t) * 2);
            } else {
                As[buf][kk][i] = h_zero;
                As[buf][kk][i + 1] = h_zero;
            }
        }
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaCpBK * kMmFp32_16WmmaBN;
            idx += kMmFp32_16WmmaThreads) {
            int nn = idx % kMmFp32_16WmmaBN;
            int kk = idx / kMmFp32_16WmmaBN;
            size_t col = block_col + static_cast<size_t>(nn);
            size_t kg = k0 + static_cast<size_t>(kk);
            Bs[buf][kk][nn] = (col < n && kg < k) ? static_cast<__half>(B[kg + col * ld_b])
                                                  : h_zero;
        }
        __pipeline_commit();
    };

    // Decodes every As[buf] slot in place from raw wh bits to a real
    // __half (see kernel comment for why this is safe for both genuinely
    // staged elements and zero-filled boundary ones alike).
    auto transform_tile = [&](int buf) {
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBM * kMmFp32_16WmmaCpBK;
            idx += kMmFp32_16WmmaThreads) {
            int mm = idx % kMmFp32_16WmmaBM;
            int kk = idx / kMmFp32_16WmmaBM;
            uint16_t bits = *reinterpret_cast<uint16_t*>(&As[buf][kk][mm]);
            As[buf][kk][mm] = fp32_16_half_only_branchless_no_overflow_nomask(bits);
        }
    };

    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, kMmFp32_16WmmaTile,
                           kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, float>
        c_frag[kMmFp32_16WmmaFragM][kMmFp32_16WmmaFragN];
#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
            nvcuda::wmma::fill_fragment(c_frag[wm][wn], 0.0f);

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16WmmaCpBK) {
        size_t next_k0 = k0 + kMmFp32_16WmmaCpBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int ks = 0; ks < kMmFp32_16WmmaCpBK; ks += kMmFp32_16WmmaTile) {
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::col_major>
                a_frag[kMmFp32_16WmmaFragM];
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::row_major>
                b_frag[kMmFp32_16WmmaFragN];
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
                nvcuda::wmma::load_matrix_sync(
                    a_frag[wm], &As[cur][ks][warp_row_base + wm * kMmFp32_16WmmaTile],
                    kMmFp32_16WmmaBM);
#pragma unroll
            for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                nvcuda::wmma::load_matrix_sync(
                    b_frag[wn], &Bs[cur][ks][warp_col_base + wn * kMmFp32_16WmmaTile],
                    kMmFp32_16WmmaBN);
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
                for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                    nvcuda::wmma::mma_sync(c_frag[wm][wn], a_frag[wm], b_frag[wn],
                                          c_frag[wm][wn]);
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm) {
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn) {
            nvcuda::wmma::store_matrix_sync(&warp_c[warp_id][0][0], c_frag[wm][wn],
                                            kMmFp32_16WmmaTile,
                                            nvcuda::wmma::mem_row_major);
            __syncwarp();
            size_t frag_row = block_row + static_cast<size_t>(warp_row_base) +
                              static_cast<size_t>(wm) * kMmFp32_16WmmaTile;
            size_t frag_col = block_col + static_cast<size_t>(warp_col_base) +
                              static_cast<size_t>(wn) * kMmFp32_16WmmaTile;
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                int elem = lane + 32 * e;
                int rr = elem / kMmFp32_16WmmaTile;
                int cc = elem % kMmFp32_16WmmaTile;
                size_t row = frag_row + static_cast<size_t>(rr);
                size_t col = frag_col + static_cast<size_t>(cc);
                if (row >= m || col >= n) continue;
                size_t cidx = row + col * ld_c;
                float acc_f = warp_c[warp_id][rr][cc];
                C[cidx] = static_cast<float>(alpha) * acc_f + static_cast<float>(beta) * C[cidx];
            }
            __syncwarp();
        }
    }
}

void mm_fp32_16_pure_half_wmma_cpasync(TransposeType transA, TransposeType transB,
                                       double alpha, dim<2> size_A, const uint16_t* wh,
                                       size_t ld_a, dim<2> size_B, const float* B,
                                       size_t ld_b, double beta, float* C, size_t ld_c) {
    size_t m = size_A[0];
    size_t k = size_A[1];
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE ||
        ld_a % 2 != 0 || m % 2 != 0) {
        mm_fp32_16_pure_half_wmma(transA, transB, alpha, size_A, wh, ld_a, size_B, B, ld_b,
                                  beta, C, ld_c);
        return;
    }
    size_t n = size_B[1];

    float f_alpha = static_cast<float>(alpha);
    float f_beta = static_cast<float>(beta);
    __half h_alpha = static_cast<__half>(f_alpha);
    __half h_beta = static_cast<__half>(f_beta);
    dim3 threads(kMmFp32_16WmmaThreads);
    dim3 blocks((n + kMmFp32_16WmmaBN - 1) / kMmFp32_16WmmaBN,
               (m + kMmFp32_16WmmaBM - 1) / kMmFp32_16WmmaBM);
    mm_fp32_16_pure_half_wmma_cpasync_kernel<<<blocks, threads>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
    cudaDeviceSynchronize();
}

// Same double-buffered structure as mm_fp32_16_pure_half_wmma_cpasync_
// kernel, but both wh's cp.async transfer and B's synchronous read are
// widened -- the same lever ported from gemm_fp16_wmma_cpasync_vec_kernel
// (mm_cuda_kernels.cu) after THAT kernel's widening measured a ~65% win
// there (B's unvectorized scalar load, not A's decode or the tensor cores
// themselves, was the dominant cost). wh widens from 2 elements (4 bytes)
// to 8 elements (16 bytes) per cp.async transfer, straight into As's own
// memory exactly as mm_fp32_16_pure_half_wmma_cpasync_kernel already does
// (transform_tile's decode loop is unchanged -- it iterates element-by-
// element over the whole buffer regardless of how each element arrived,
// so a wider load groups nothing it needs to know about). B (plain float
// here, not __half) widens to a float4 (4 consecutive K-values, 16 bytes)
// synchronous read per thread, matching gemm_fp32_tiled_cpasync_vec2_
// kernel's own B handling, with a cast to __half added when scattering
// into Bs. Requires ld_a and m to both be multiples of 8 (wh's wider
// group) and ld_b and k to both be multiples of 4 (B's float4); falls
// back to mm_fp32_16_pure_half_wmma_cpasync otherwise.
__global__ __launch_bounds__(kMmFp32_16WmmaThreads, 2) void mm_fp32_16_pure_half_wmma_cpasync_vec_kernel(
    __half alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    __half beta, float* __restrict__ C, size_t ld_c) {
    __shared__ __half As[2][kMmFp32_16WmmaCpBK][kMmFp32_16WmmaBM];
    __shared__ __half Bs[2][kMmFp32_16WmmaCpBK][kMmFp32_16WmmaBN];
    __shared__ float warp_c[kMmFp32_16WmmaWarps][kMmFp32_16WmmaTile][kMmFp32_16WmmaTile];

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16WmmaBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16WmmaBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane = tid % 32;
    const int warp_row = warp_id / kMmFp32_16WmmaWarpCols;
    const int warp_col = warp_id % kMmFp32_16WmmaWarpCols;
    const int warp_row_base = warp_row * (kMmFp32_16WmmaBM / kMmFp32_16WmmaWarpRows);
    const int warp_col_base = warp_col * (kMmFp32_16WmmaBN / kMmFp32_16WmmaWarpCols);

    const __half h_zero = static_cast<__half>(0.0f);

    // wh: cp.async, 8 contiguous rows (16 bytes) per transfer, straight
    // into As's own memory -- decode happens in transform_tile, same as
    // mm_fp32_16_pure_half_wmma_cpasync_kernel. B: a single synchronous
    // 16-byte read (4 consecutive K-values, fixed column) via float4, cast
    // to __half and scattered into Bs.
    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int idx = tid; idx < (kMmFp32_16WmmaBM / 8) * kMmFp32_16WmmaCpBK;
            idx += kMmFp32_16WmmaThreads) {
            int group = idx % (kMmFp32_16WmmaBM / 8);
            int kk = idx / (kMmFp32_16WmmaBM / 8);
            int i = group * 8;
            size_t row = block_row + static_cast<size_t>(i);
            size_t kg = k0 + static_cast<size_t>(kk);
            if (row < m && kg < k) {
                __pipeline_memcpy_async(
                    reinterpret_cast<uint16_t*>(&As[buf][kk][i]), &wh[row + kg * ld_a],
                    sizeof(uint16_t) * 8);
            } else {
#pragma unroll
                for (int e = 0; e < 8; ++e) As[buf][kk][i + e] = h_zero;
            }
        }
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBN * (kMmFp32_16WmmaCpBK / 4);
            idx += kMmFp32_16WmmaThreads) {
            int nn = idx % kMmFp32_16WmmaBN;
            int kk0 = (idx / kMmFp32_16WmmaBN) * 4;
            size_t col = block_col + static_cast<size_t>(nn);
            size_t kg0 = k0 + static_cast<size_t>(kk0);
            if (col < n && kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[kg0 + col * ld_b]);
                Bs[buf][kk0 + 0][nn] = static_cast<__half>(t.x);
                Bs[buf][kk0 + 1][nn] = static_cast<__half>(t.y);
                Bs[buf][kk0 + 2][nn] = static_cast<__half>(t.z);
                Bs[buf][kk0 + 3][nn] = static_cast<__half>(t.w);
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[buf][kk0 + e][nn] = h_zero;
            }
        }
        __pipeline_commit();
    };

    // Decodes every As[buf] slot in place from raw wh bits to a real
    // __half -- identical to mm_fp32_16_pure_half_wmma_cpasync_kernel's
    // transform_tile (see that kernel's comment for why this is safe for
    // both genuinely staged and zero-filled slots alike).
    auto transform_tile = [&](int buf) {
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBM * kMmFp32_16WmmaCpBK;
            idx += kMmFp32_16WmmaThreads) {
            int mm = idx % kMmFp32_16WmmaBM;
            int kk = idx / kMmFp32_16WmmaBM;
            uint16_t bits = *reinterpret_cast<uint16_t*>(&As[buf][kk][mm]);
            As[buf][kk][mm] = fp32_16_half_only_branchless_no_overflow_nomask(bits);
        }
    };

    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, kMmFp32_16WmmaTile,
                           kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, float>
        c_frag[kMmFp32_16WmmaFragM][kMmFp32_16WmmaFragN];
#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
            nvcuda::wmma::fill_fragment(c_frag[wm][wn], 0.0f);

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16WmmaCpBK) {
        size_t next_k0 = k0 + kMmFp32_16WmmaCpBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int ks = 0; ks < kMmFp32_16WmmaCpBK; ks += kMmFp32_16WmmaTile) {
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::col_major>
                a_frag[kMmFp32_16WmmaFragM];
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::row_major>
                b_frag[kMmFp32_16WmmaFragN];
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
                nvcuda::wmma::load_matrix_sync(
                    a_frag[wm], &As[cur][ks][warp_row_base + wm * kMmFp32_16WmmaTile],
                    kMmFp32_16WmmaBM);
#pragma unroll
            for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                nvcuda::wmma::load_matrix_sync(
                    b_frag[wn], &Bs[cur][ks][warp_col_base + wn * kMmFp32_16WmmaTile],
                    kMmFp32_16WmmaBN);
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
                for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                    nvcuda::wmma::mma_sync(c_frag[wm][wn], a_frag[wm], b_frag[wn],
                                          c_frag[wm][wn]);
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm) {
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn) {
            nvcuda::wmma::store_matrix_sync(&warp_c[warp_id][0][0], c_frag[wm][wn],
                                            kMmFp32_16WmmaTile,
                                            nvcuda::wmma::mem_row_major);
            __syncwarp();
            size_t frag_row = block_row + static_cast<size_t>(warp_row_base) +
                              static_cast<size_t>(wm) * kMmFp32_16WmmaTile;
            size_t frag_col = block_col + static_cast<size_t>(warp_col_base) +
                              static_cast<size_t>(wn) * kMmFp32_16WmmaTile;
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                int elem = lane + 32 * e;
                int rr = elem / kMmFp32_16WmmaTile;
                int cc = elem % kMmFp32_16WmmaTile;
                size_t row = frag_row + static_cast<size_t>(rr);
                size_t col = frag_col + static_cast<size_t>(cc);
                if (row >= m || col >= n) continue;
                size_t cidx = row + col * ld_c;
                float acc_f = warp_c[warp_id][rr][cc];
                C[cidx] = static_cast<float>(alpha) * acc_f + static_cast<float>(beta) * C[cidx];
            }
            __syncwarp();
        }
    }
}

void mm_fp32_16_pure_half_wmma_cpasync_vec(TransposeType transA, TransposeType transB,
                                           double alpha, dim<2> size_A, const uint16_t* wh,
                                           size_t ld_a, dim<2> size_B, const float* B,
                                           size_t ld_b, double beta, float* C, size_t ld_c) {
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE ||
        ld_a % 8 != 0 || m % 8 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_pure_half_wmma_cpasync(transA, transB, alpha, size_A, wh, ld_a, size_B, B,
                                          ld_b, beta, C, ld_c);
        return;
    }

    float f_alpha = static_cast<float>(alpha);
    float f_beta = static_cast<float>(beta);
    __half h_alpha = static_cast<__half>(f_alpha);
    __half h_beta = static_cast<__half>(f_beta);
    dim3 threads(kMmFp32_16WmmaThreads);
    dim3 blocks((n + kMmFp32_16WmmaBN - 1) / kMmFp32_16WmmaBN,
               (m + kMmFp32_16WmmaBM - 1) / kMmFp32_16WmmaBM);
    mm_fp32_16_pure_half_wmma_cpasync_vec_kernel<<<blocks, threads>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
    cudaDeviceSynchronize();
}

namespace {
// BK doubled from 32 to 64 versus mm_fp32_16_pure_half_wmma_cpasync_vec_
// kernel -- ported from gemm_fp16_wmma_cpasync_vec_bigbk_kernel (mm_cuda_
// kernels.cu) after THAT kernel measured a consistent ~3.5-6% win by
// halving how often the outer loop pays load_tile_async's issue overhead
// and the two per-tile barriers, for the same total compute. Like that
// kernel (and UNLIKE the mm_fp32_16_pure_half_wmma_cpasync/gemm_fp16_wmma_
// dualbuf attempt at fully-async B, which measured WORSE), B's handling
// here is unchanged from the vec kernel -- a single synchronous
// vectorized read, no staging/transpose -- only BK changes. As+Bs double-
// buffered at BK=64 needs 80KB (2x the vec kernel's 40KB), the same
// dynamic-shared-memory opt-in as gemm_fp16_wmma_cpasync_vec_bigbk.
// Requires ld_a and m to both be multiples of 8, and ld_b and k to both
// be multiples of 4; falls back to mm_fp32_16_pure_half_wmma_cpasync_vec
// otherwise.
constexpr int kMmFp32_16WmmaBigBK = 64;
constexpr size_t kMmFp32_16BigBkAsBytes =
    2 * static_cast<size_t>(kMmFp32_16WmmaBigBK) * kMmFp32_16WmmaBM * sizeof(__half);
constexpr size_t kMmFp32_16BigBkBsBytes =
    2 * static_cast<size_t>(kMmFp32_16WmmaBigBK) * kMmFp32_16WmmaBN * sizeof(__half);
constexpr size_t kMmFp32_16BigBkWarpCBytes =
    static_cast<size_t>(kMmFp32_16WmmaWarps) * kMmFp32_16WmmaTile * kMmFp32_16WmmaTile * sizeof(float);
constexpr size_t kMmFp32_16BigBkAsOff = 0;
constexpr size_t kMmFp32_16BigBkBsOff = kMmFp32_16BigBkAsOff + kMmFp32_16BigBkAsBytes;
constexpr size_t kMmFp32_16BigBkWarpCOff = kMmFp32_16BigBkBsOff + kMmFp32_16BigBkBsBytes;
constexpr size_t kMmFp32_16BigBkSharedBytes = kMmFp32_16BigBkWarpCOff + kMmFp32_16BigBkWarpCBytes;  // 80KB
}  // namespace

__device__ __forceinline__ int mm_fp32_16_bigbk_as_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16WmmaBigBK + kk) * kMmFp32_16WmmaBM + i;
}
__device__ __forceinline__ int mm_fp32_16_bigbk_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16WmmaBigBK + kk) * kMmFp32_16WmmaBN + j;
}

__global__ __launch_bounds__(kMmFp32_16WmmaThreads, 2) void mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk_kernel(
    __half alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    __half beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    __half* As = reinterpret_cast<__half*>(smem_raw + kMmFp32_16BigBkAsOff);
    __half* Bs = reinterpret_cast<__half*>(smem_raw + kMmFp32_16BigBkBsOff);
    float* warp_c = reinterpret_cast<float*>(smem_raw + kMmFp32_16BigBkWarpCOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16WmmaBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16WmmaBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane = tid % 32;
    const int warp_row = warp_id / kMmFp32_16WmmaWarpCols;
    const int warp_col = warp_id % kMmFp32_16WmmaWarpCols;
    const int warp_row_base = warp_row * (kMmFp32_16WmmaBM / kMmFp32_16WmmaWarpRows);
    const int warp_col_base = warp_col * (kMmFp32_16WmmaBN / kMmFp32_16WmmaWarpCols);

    const __half h_zero = static_cast<__half>(0.0f);

    // Same wh 8-wide cp.async (raw bits, decoded in place below) and B
    // float4-per-4-K-values synchronous read as mm_fp32_16_pure_half_wmma_
    // cpasync_vec_kernel, just over BigBK=64 instead of 32.
    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int idx = tid; idx < (kMmFp32_16WmmaBM / 8) * kMmFp32_16WmmaBigBK;
            idx += kMmFp32_16WmmaThreads) {
            int group = idx % (kMmFp32_16WmmaBM / 8);
            int kk = idx / (kMmFp32_16WmmaBM / 8);
            int i = group * 8;
            size_t row = block_row + static_cast<size_t>(i);
            size_t kg = k0 + static_cast<size_t>(kk);
            if (row < m && kg < k) {
                __pipeline_memcpy_async(
                    reinterpret_cast<uint16_t*>(&As[mm_fp32_16_bigbk_as_idx(buf, kk, i)]),
                    &wh[row + kg * ld_a], sizeof(uint16_t) * 8);
            } else {
#pragma unroll
                for (int e = 0; e < 8; ++e) As[mm_fp32_16_bigbk_as_idx(buf, kk, i + e)] = h_zero;
            }
        }
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBN * (kMmFp32_16WmmaBigBK / 4);
            idx += kMmFp32_16WmmaThreads) {
            int nn = idx % kMmFp32_16WmmaBN;
            int kk0 = (idx / kMmFp32_16WmmaBN) * 4;
            size_t col = block_col + static_cast<size_t>(nn);
            size_t kg0 = k0 + static_cast<size_t>(kk0);
            if (col < n && kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[kg0 + col * ld_b]);
                Bs[mm_fp32_16_bigbk_bs_idx(buf, kk0 + 0, nn)] = static_cast<__half>(t.x);
                Bs[mm_fp32_16_bigbk_bs_idx(buf, kk0 + 1, nn)] = static_cast<__half>(t.y);
                Bs[mm_fp32_16_bigbk_bs_idx(buf, kk0 + 2, nn)] = static_cast<__half>(t.z);
                Bs[mm_fp32_16_bigbk_bs_idx(buf, kk0 + 3, nn)] = static_cast<__half>(t.w);
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[mm_fp32_16_bigbk_bs_idx(buf, kk0 + e, nn)] = h_zero;
            }
        }
        __pipeline_commit();
    };

    // Decodes every As[buf] slot in place from raw wh bits to a real
    // __half -- identical to mm_fp32_16_pure_half_wmma_cpasync_kernel's
    // transform_tile.
    auto transform_tile = [&](int buf) {
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBM * kMmFp32_16WmmaBigBK;
            idx += kMmFp32_16WmmaThreads) {
            int mm = idx % kMmFp32_16WmmaBM;
            int kk = idx / kMmFp32_16WmmaBM;
            uint16_t bits = *reinterpret_cast<uint16_t*>(&As[mm_fp32_16_bigbk_as_idx(buf, kk, mm)]);
            As[mm_fp32_16_bigbk_as_idx(buf, kk, mm)] = fp32_16_half_only_branchless_no_overflow_nomask(bits);
        }
    };

    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, kMmFp32_16WmmaTile,
                           kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, float>
        c_frag[kMmFp32_16WmmaFragM][kMmFp32_16WmmaFragN];
#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
            nvcuda::wmma::fill_fragment(c_frag[wm][wn], 0.0f);

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16WmmaBigBK) {
        size_t next_k0 = k0 + kMmFp32_16WmmaBigBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int ks = 0; ks < kMmFp32_16WmmaBigBK; ks += kMmFp32_16WmmaTile) {
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::col_major>
                a_frag[kMmFp32_16WmmaFragM];
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::row_major>
                b_frag[kMmFp32_16WmmaFragN];
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
                nvcuda::wmma::load_matrix_sync(
                    a_frag[wm], &As[mm_fp32_16_bigbk_as_idx(cur, ks, warp_row_base + wm * kMmFp32_16WmmaTile)],
                    kMmFp32_16WmmaBM);
#pragma unroll
            for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                nvcuda::wmma::load_matrix_sync(
                    b_frag[wn], &Bs[mm_fp32_16_bigbk_bs_idx(cur, ks, warp_col_base + wn * kMmFp32_16WmmaTile)],
                    kMmFp32_16WmmaBN);
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
                for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                    nvcuda::wmma::mma_sync(c_frag[wm][wn], a_frag[wm], b_frag[wn],
                                          c_frag[wm][wn]);
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm) {
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn) {
            nvcuda::wmma::store_matrix_sync(&warp_c[warp_id * kMmFp32_16WmmaTile * kMmFp32_16WmmaTile],
                                            c_frag[wm][wn], kMmFp32_16WmmaTile,
                                            nvcuda::wmma::mem_row_major);
            __syncwarp();
            size_t frag_row = block_row + static_cast<size_t>(warp_row_base) +
                              static_cast<size_t>(wm) * kMmFp32_16WmmaTile;
            size_t frag_col = block_col + static_cast<size_t>(warp_col_base) +
                              static_cast<size_t>(wn) * kMmFp32_16WmmaTile;
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                int elem = lane + 32 * e;
                int rr = elem / kMmFp32_16WmmaTile;
                int cc = elem % kMmFp32_16WmmaTile;
                size_t row = frag_row + static_cast<size_t>(rr);
                size_t col = frag_col + static_cast<size_t>(cc);
                if (row >= m || col >= n) continue;
                size_t cidx = row + col * ld_c;
                float acc_f =
                    warp_c[warp_id * kMmFp32_16WmmaTile * kMmFp32_16WmmaTile + rr * kMmFp32_16WmmaTile + cc];
                C[cidx] = static_cast<float>(alpha) * acc_f + static_cast<float>(beta) * C[cidx];
            }
            __syncwarp();
        }
    }
}

void mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk(TransposeType transA, TransposeType transB,
                                                 double alpha, dim<2> size_A, const uint16_t* wh,
                                                 size_t ld_a, dim<2> size_B, const float* B,
                                                 size_t ld_b, double beta, float* C, size_t ld_c) {
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE ||
        ld_a % 8 != 0 || m % 8 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_pure_half_wmma_cpasync_vec(transA, transB, alpha, size_A, wh, ld_a, size_B, B,
                                              ld_b, beta, C, ld_c);
        return;
    }
    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16BigBkSharedBytes));
        attr_set = true;
    }
    float f_alpha = static_cast<float>(alpha);
    float f_beta = static_cast<float>(beta);
    __half h_alpha = static_cast<__half>(f_alpha);
    __half h_beta = static_cast<__half>(f_beta);
    dim3 threads(kMmFp32_16WmmaThreads);
    dim3 blocks((n + kMmFp32_16WmmaBN - 1) / kMmFp32_16WmmaBN,
               (m + kMmFp32_16WmmaBM - 1) / kMmFp32_16WmmaBM);
    mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk_kernel<<<blocks, threads, kMmFp32_16BigBkSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
    cudaDeviceSynchronize();
}

namespace {
// Same tile/warp/BigBK=64 shape as mm_fp32_16_pure_half_wmma_cpasync_vec_
// bigbk_kernel, but As/Bs's shared-memory storage stride is padded from
// 128 halves (256 bytes -- exactly 2 full sweeps of the 32 shared-memory
// banks) to 136 -- ported from gemm_fp16_wmma_cpasync_vec_bigbk_pad
// (mm_cuda_kernels.cu) after THAT kernel's padding nearly DOUBLED
// throughput (bank conflicts on the ldmatrix instruction load_matrix_sync
// compiles to were evidently a dominant cost this whole tile/pipelining
// investigation never isolated on its own). No logical tile size or
// compute changes -- only where each element physically lives in shared
// memory; transform_tile's decode is unaffected since it already indexes
// through the same as_idx helper.
constexpr int kMmFp32_16WmmaPad = 8;
constexpr int kMmFp32_16WmmaBMPad = kMmFp32_16WmmaBM + kMmFp32_16WmmaPad;
constexpr int kMmFp32_16WmmaBNPad = kMmFp32_16WmmaBN + kMmFp32_16WmmaPad;
constexpr size_t kMmFp32_16PadAsBytes =
    2 * static_cast<size_t>(kMmFp32_16WmmaBigBK) * kMmFp32_16WmmaBMPad * sizeof(__half);
constexpr size_t kMmFp32_16PadBsBytes =
    2 * static_cast<size_t>(kMmFp32_16WmmaBigBK) * kMmFp32_16WmmaBNPad * sizeof(__half);
constexpr size_t kMmFp32_16PadWarpCBytes =
    static_cast<size_t>(kMmFp32_16WmmaWarps) * kMmFp32_16WmmaTile * kMmFp32_16WmmaTile * sizeof(float);
constexpr size_t kMmFp32_16PadAsOff = 0;
constexpr size_t kMmFp32_16PadBsOff = kMmFp32_16PadAsOff + kMmFp32_16PadAsBytes;
constexpr size_t kMmFp32_16PadWarpCOff = kMmFp32_16PadBsOff + kMmFp32_16PadBsBytes;
constexpr size_t kMmFp32_16PadSharedBytes = kMmFp32_16PadWarpCOff + kMmFp32_16PadWarpCBytes;
}  // namespace

__device__ __forceinline__ int mm_fp32_16_pad_as_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16WmmaBigBK + kk) * kMmFp32_16WmmaBMPad + i;
}
__device__ __forceinline__ int mm_fp32_16_pad_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16WmmaBigBK + kk) * kMmFp32_16WmmaBNPad + j;
}

__global__ __launch_bounds__(kMmFp32_16WmmaThreads, 2) void mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk_pad_kernel(
    __half alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    __half beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    __half* As = reinterpret_cast<__half*>(smem_raw + kMmFp32_16PadAsOff);
    __half* Bs = reinterpret_cast<__half*>(smem_raw + kMmFp32_16PadBsOff);
    float* warp_c = reinterpret_cast<float*>(smem_raw + kMmFp32_16PadWarpCOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16WmmaBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16WmmaBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane = tid % 32;
    const int warp_row = warp_id / kMmFp32_16WmmaWarpCols;
    const int warp_col = warp_id % kMmFp32_16WmmaWarpCols;
    const int warp_row_base = warp_row * (kMmFp32_16WmmaBM / kMmFp32_16WmmaWarpRows);
    const int warp_col_base = warp_col * (kMmFp32_16WmmaBN / kMmFp32_16WmmaWarpCols);

    const __half h_zero = static_cast<__half>(0.0f);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int idx = tid; idx < (kMmFp32_16WmmaBM / 8) * kMmFp32_16WmmaBigBK;
            idx += kMmFp32_16WmmaThreads) {
            int group = idx % (kMmFp32_16WmmaBM / 8);
            int kk = idx / (kMmFp32_16WmmaBM / 8);
            int i = group * 8;
            size_t row = block_row + static_cast<size_t>(i);
            size_t kg = k0 + static_cast<size_t>(kk);
            if (row < m && kg < k) {
                __pipeline_memcpy_async(
                    reinterpret_cast<uint16_t*>(&As[mm_fp32_16_pad_as_idx(buf, kk, i)]),
                    &wh[row + kg * ld_a], sizeof(uint16_t) * 8);
            } else {
#pragma unroll
                for (int e = 0; e < 8; ++e) As[mm_fp32_16_pad_as_idx(buf, kk, i + e)] = h_zero;
            }
        }
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBN * (kMmFp32_16WmmaBigBK / 4);
            idx += kMmFp32_16WmmaThreads) {
            int nn = idx % kMmFp32_16WmmaBN;
            int kk0 = (idx / kMmFp32_16WmmaBN) * 4;
            size_t col = block_col + static_cast<size_t>(nn);
            size_t kg0 = k0 + static_cast<size_t>(kk0);
            if (col < n && kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[kg0 + col * ld_b]);
                Bs[mm_fp32_16_pad_bs_idx(buf, kk0 + 0, nn)] = static_cast<__half>(t.x);
                Bs[mm_fp32_16_pad_bs_idx(buf, kk0 + 1, nn)] = static_cast<__half>(t.y);
                Bs[mm_fp32_16_pad_bs_idx(buf, kk0 + 2, nn)] = static_cast<__half>(t.z);
                Bs[mm_fp32_16_pad_bs_idx(buf, kk0 + 3, nn)] = static_cast<__half>(t.w);
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[mm_fp32_16_pad_bs_idx(buf, kk0 + e, nn)] = h_zero;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf) {
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBM * kMmFp32_16WmmaBigBK;
            idx += kMmFp32_16WmmaThreads) {
            int mm = idx % kMmFp32_16WmmaBM;
            int kk = idx / kMmFp32_16WmmaBM;
            uint16_t bits = *reinterpret_cast<uint16_t*>(&As[mm_fp32_16_pad_as_idx(buf, kk, mm)]);
            As[mm_fp32_16_pad_as_idx(buf, kk, mm)] = fp32_16_half_only_branchless_no_overflow_nomask(bits);
        }
    };

    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, kMmFp32_16WmmaTile,
                           kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, float>
        c_frag[kMmFp32_16WmmaFragM][kMmFp32_16WmmaFragN];
#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
            nvcuda::wmma::fill_fragment(c_frag[wm][wn], 0.0f);

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16WmmaBigBK) {
        size_t next_k0 = k0 + kMmFp32_16WmmaBigBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int ks = 0; ks < kMmFp32_16WmmaBigBK; ks += kMmFp32_16WmmaTile) {
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::col_major>
                a_frag[kMmFp32_16WmmaFragM];
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::row_major>
                b_frag[kMmFp32_16WmmaFragN];
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
                nvcuda::wmma::load_matrix_sync(
                    a_frag[wm], &As[mm_fp32_16_pad_as_idx(cur, ks, warp_row_base + wm * kMmFp32_16WmmaTile)],
                    kMmFp32_16WmmaBMPad);
#pragma unroll
            for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                nvcuda::wmma::load_matrix_sync(
                    b_frag[wn], &Bs[mm_fp32_16_pad_bs_idx(cur, ks, warp_col_base + wn * kMmFp32_16WmmaTile)],
                    kMmFp32_16WmmaBNPad);
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
                for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                    nvcuda::wmma::mma_sync(c_frag[wm][wn], a_frag[wm], b_frag[wn],
                                          c_frag[wm][wn]);
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm) {
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn) {
            nvcuda::wmma::store_matrix_sync(&warp_c[warp_id * kMmFp32_16WmmaTile * kMmFp32_16WmmaTile],
                                            c_frag[wm][wn], kMmFp32_16WmmaTile,
                                            nvcuda::wmma::mem_row_major);
            __syncwarp();
            size_t frag_row = block_row + static_cast<size_t>(warp_row_base) +
                              static_cast<size_t>(wm) * kMmFp32_16WmmaTile;
            size_t frag_col = block_col + static_cast<size_t>(warp_col_base) +
                              static_cast<size_t>(wn) * kMmFp32_16WmmaTile;
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                int elem = lane + 32 * e;
                int rr = elem / kMmFp32_16WmmaTile;
                int cc = elem % kMmFp32_16WmmaTile;
                size_t row = frag_row + static_cast<size_t>(rr);
                size_t col = frag_col + static_cast<size_t>(cc);
                if (row >= m || col >= n) continue;
                size_t cidx = row + col * ld_c;
                float acc_f =
                    warp_c[warp_id * kMmFp32_16WmmaTile * kMmFp32_16WmmaTile + rr * kMmFp32_16WmmaTile + cc];
                C[cidx] = static_cast<float>(alpha) * acc_f + static_cast<float>(beta) * C[cidx];
            }
            __syncwarp();
        }
    }
}

void mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk_pad(TransposeType transA, TransposeType transB,
                                                     double alpha, dim<2> size_A, const uint16_t* wh,
                                                     size_t ld_a, dim<2> size_B, const float* B,
                                                     size_t ld_b, double beta, float* C, size_t ld_c) {
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE ||
        ld_a % 8 != 0 || m % 8 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk(transA, transB, alpha, size_A, wh, ld_a, size_B, B,
                                                    ld_b, beta, C, ld_c);
        return;
    }
    static bool attr_set = false;
    if (!attr_set) {
        cudaFuncSetAttribute(mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk_pad_kernel,
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             static_cast<int>(kMmFp32_16PadSharedBytes));
        attr_set = true;
    }
    float f_alpha = static_cast<float>(alpha);
    float f_beta = static_cast<float>(beta);
    __half h_alpha = static_cast<__half>(f_alpha);
    __half h_beta = static_cast<__half>(f_beta);
    dim3 threads(kMmFp32_16WmmaThreads);
    dim3 blocks((n + kMmFp32_16WmmaBN - 1) / kMmFp32_16WmmaBN,
               (m + kMmFp32_16WmmaBM - 1) / kMmFp32_16WmmaBM);
    mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk_pad_kernel<<<blocks, threads, kMmFp32_16PadSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
    cudaDeviceSynchronize();
}

namespace {
// BK doubled again, 64 -> 128, on top of mm_fp32_16_pure_half_wmma_
// cpasync_vec_bigbk_pad_kernel's padded layout -- ported from gemm_fp16_
// wmma_cpasync_vec_hugebk (mm_cuda_kernels.cu) after THAT kernel measured
// a further ~10-15% win despite dropping from 2 resident blocks/SM to 1
// (the ~152KB As+Bs footprint at BK=128 leaves no shared-memory room for a
// second block on an A30/A100's ~163KB opt-in ceiling) -- the wider tile's
// arithmetic-intensity gain won that trade. __launch_bounds__(threads, 1)
// matches gemm_fp16_wmma_cpasync_vec_hugebk_kernel's reasoning: with
// occupancy already capped at 1 block/SM by shared memory, there's no
// reason to also force register spilling chasing a 2-block target that
// shared memory alone rules out.
constexpr int kMmFp32_16WmmaHugeBK = 128;
constexpr size_t kMmFp32_16HugeAsBytes =
    2 * static_cast<size_t>(kMmFp32_16WmmaHugeBK) * kMmFp32_16WmmaBMPad * sizeof(__half);
constexpr size_t kMmFp32_16HugeBsBytes =
    2 * static_cast<size_t>(kMmFp32_16WmmaHugeBK) * kMmFp32_16WmmaBNPad * sizeof(__half);
constexpr size_t kMmFp32_16HugeWarpCBytes =
    static_cast<size_t>(kMmFp32_16WmmaWarps) * kMmFp32_16WmmaTile * kMmFp32_16WmmaTile * sizeof(float);
constexpr size_t kMmFp32_16HugeAsOff = 0;
constexpr size_t kMmFp32_16HugeBsOff = kMmFp32_16HugeAsOff + kMmFp32_16HugeAsBytes;
constexpr size_t kMmFp32_16HugeWarpCOff = kMmFp32_16HugeBsOff + kMmFp32_16HugeBsBytes;
constexpr size_t kMmFp32_16HugeSharedBytes = kMmFp32_16HugeWarpCOff + kMmFp32_16HugeWarpCBytes;
}  // namespace

__device__ __forceinline__ int mm_fp32_16_huge_as_idx(int buf, int kk, int i) {
    return (buf * kMmFp32_16WmmaHugeBK + kk) * kMmFp32_16WmmaBMPad + i;
}
__device__ __forceinline__ int mm_fp32_16_huge_bs_idx(int buf, int kk, int j) {
    return (buf * kMmFp32_16WmmaHugeBK + kk) * kMmFp32_16WmmaBNPad + j;
}

__global__ __launch_bounds__(kMmFp32_16WmmaThreads, 1) void mm_fp32_16_pure_half_wmma_cpasync_vec_hugebk_kernel(
    __half alpha, size_t m, size_t k, size_t n,
    const uint16_t* __restrict__ wh, size_t ld_a,
    const float* __restrict__ B, size_t ld_b,
    __half beta, float* __restrict__ C, size_t ld_c) {
    extern __shared__ float4 smem_raw4[];
    unsigned char* smem_raw = reinterpret_cast<unsigned char*>(smem_raw4);
    __half* As = reinterpret_cast<__half*>(smem_raw + kMmFp32_16HugeAsOff);
    __half* Bs = reinterpret_cast<__half*>(smem_raw + kMmFp32_16HugeBsOff);
    float* warp_c = reinterpret_cast<float*>(smem_raw + kMmFp32_16HugeWarpCOff);

    const size_t block_row = static_cast<size_t>(blockIdx.y) * kMmFp32_16WmmaBM;
    const size_t block_col = static_cast<size_t>(blockIdx.x) * kMmFp32_16WmmaBN;

    const int tid = threadIdx.x;
    const int warp_id = tid / 32;
    const int lane = tid % 32;
    const int warp_row = warp_id / kMmFp32_16WmmaWarpCols;
    const int warp_col = warp_id % kMmFp32_16WmmaWarpCols;
    const int warp_row_base = warp_row * (kMmFp32_16WmmaBM / kMmFp32_16WmmaWarpRows);
    const int warp_col_base = warp_col * (kMmFp32_16WmmaBN / kMmFp32_16WmmaWarpCols);

    const __half h_zero = static_cast<__half>(0.0f);

    auto load_tile_async = [&](int buf, size_t k0) {
#pragma unroll
        for (int idx = tid; idx < (kMmFp32_16WmmaBM / 8) * kMmFp32_16WmmaHugeBK;
            idx += kMmFp32_16WmmaThreads) {
            int group = idx % (kMmFp32_16WmmaBM / 8);
            int kk = idx / (kMmFp32_16WmmaBM / 8);
            int i = group * 8;
            size_t row = block_row + static_cast<size_t>(i);
            size_t kg = k0 + static_cast<size_t>(kk);
            if (row < m && kg < k) {
                __pipeline_memcpy_async(
                    reinterpret_cast<uint16_t*>(&As[mm_fp32_16_huge_as_idx(buf, kk, i)]),
                    &wh[row + kg * ld_a], sizeof(uint16_t) * 8);
            } else {
#pragma unroll
                for (int e = 0; e < 8; ++e) As[mm_fp32_16_huge_as_idx(buf, kk, i + e)] = h_zero;
            }
        }
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBN * (kMmFp32_16WmmaHugeBK / 4);
            idx += kMmFp32_16WmmaThreads) {
            int nn = idx % kMmFp32_16WmmaBN;
            int kk0 = (idx / kMmFp32_16WmmaBN) * 4;
            size_t col = block_col + static_cast<size_t>(nn);
            size_t kg0 = k0 + static_cast<size_t>(kk0);
            if (col < n && kg0 < k) {
                float4 t = *reinterpret_cast<const float4*>(&B[kg0 + col * ld_b]);
                Bs[mm_fp32_16_huge_bs_idx(buf, kk0 + 0, nn)] = static_cast<__half>(t.x);
                Bs[mm_fp32_16_huge_bs_idx(buf, kk0 + 1, nn)] = static_cast<__half>(t.y);
                Bs[mm_fp32_16_huge_bs_idx(buf, kk0 + 2, nn)] = static_cast<__half>(t.z);
                Bs[mm_fp32_16_huge_bs_idx(buf, kk0 + 3, nn)] = static_cast<__half>(t.w);
            } else {
#pragma unroll
                for (int e = 0; e < 4; ++e) Bs[mm_fp32_16_huge_bs_idx(buf, kk0 + e, nn)] = h_zero;
            }
        }
        __pipeline_commit();
    };

    auto transform_tile = [&](int buf) {
#pragma unroll
        for (int idx = tid; idx < kMmFp32_16WmmaBM * kMmFp32_16WmmaHugeBK;
            idx += kMmFp32_16WmmaThreads) {
            int mm = idx % kMmFp32_16WmmaBM;
            int kk = idx / kMmFp32_16WmmaBM;
            uint16_t bits = *reinterpret_cast<uint16_t*>(&As[mm_fp32_16_huge_as_idx(buf, kk, mm)]);
            As[mm_fp32_16_huge_as_idx(buf, kk, mm)] = fp32_16_half_only_branchless_no_overflow_nomask(bits);
        }
    };

    nvcuda::wmma::fragment<nvcuda::wmma::accumulator, kMmFp32_16WmmaTile,
                           kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, float>
        c_frag[kMmFp32_16WmmaFragM][kMmFp32_16WmmaFragN];
#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
            nvcuda::wmma::fill_fragment(c_frag[wm][wn], 0.0f);

    load_tile_async(0, 0);
    __pipeline_wait_prior(0);
    transform_tile(0);
    __syncthreads();

    int cur = 0;
    for (size_t k0 = 0; k0 < k; k0 += kMmFp32_16WmmaHugeBK) {
        size_t next_k0 = k0 + kMmFp32_16WmmaHugeBK;
        int nxt = cur ^ 1;
        if (next_k0 < k) load_tile_async(nxt, next_k0);

#pragma unroll
        for (int ks = 0; ks < kMmFp32_16WmmaHugeBK; ks += kMmFp32_16WmmaTile) {
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_a, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::col_major>
                a_frag[kMmFp32_16WmmaFragM];
            nvcuda::wmma::fragment<nvcuda::wmma::matrix_b, kMmFp32_16WmmaTile,
                                   kMmFp32_16WmmaTile, kMmFp32_16WmmaTile, __half,
                                   nvcuda::wmma::row_major>
                b_frag[kMmFp32_16WmmaFragN];
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
                nvcuda::wmma::load_matrix_sync(
                    a_frag[wm], &As[mm_fp32_16_huge_as_idx(cur, ks, warp_row_base + wm * kMmFp32_16WmmaTile)],
                    kMmFp32_16WmmaBMPad);
#pragma unroll
            for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                nvcuda::wmma::load_matrix_sync(
                    b_frag[wn], &Bs[mm_fp32_16_huge_bs_idx(cur, ks, warp_col_base + wn * kMmFp32_16WmmaTile)],
                    kMmFp32_16WmmaBNPad);
#pragma unroll
            for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm)
#pragma unroll
                for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn)
                    nvcuda::wmma::mma_sync(c_frag[wm][wn], a_frag[wm], b_frag[wn],
                                          c_frag[wm][wn]);
        }

        if (next_k0 < k) {
            __pipeline_wait_prior(0);
            transform_tile(nxt);
        }
        __syncthreads();
        cur = nxt;
    }

#pragma unroll
    for (int wm = 0; wm < kMmFp32_16WmmaFragM; ++wm) {
#pragma unroll
        for (int wn = 0; wn < kMmFp32_16WmmaFragN; ++wn) {
            nvcuda::wmma::store_matrix_sync(&warp_c[warp_id * kMmFp32_16WmmaTile * kMmFp32_16WmmaTile],
                                            c_frag[wm][wn], kMmFp32_16WmmaTile,
                                            nvcuda::wmma::mem_row_major);
            __syncwarp();
            size_t frag_row = block_row + static_cast<size_t>(warp_row_base) +
                              static_cast<size_t>(wm) * kMmFp32_16WmmaTile;
            size_t frag_col = block_col + static_cast<size_t>(warp_col_base) +
                              static_cast<size_t>(wn) * kMmFp32_16WmmaTile;
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                int elem = lane + 32 * e;
                int rr = elem / kMmFp32_16WmmaTile;
                int cc = elem % kMmFp32_16WmmaTile;
                size_t row = frag_row + static_cast<size_t>(rr);
                size_t col = frag_col + static_cast<size_t>(cc);
                if (row >= m || col >= n) continue;
                size_t cidx = row + col * ld_c;
                float acc_f =
                    warp_c[warp_id * kMmFp32_16WmmaTile * kMmFp32_16WmmaTile + rr * kMmFp32_16WmmaTile + cc];
                C[cidx] = static_cast<float>(alpha) * acc_f + static_cast<float>(beta) * C[cidx];
            }
            __syncwarp();
        }
    }
}

void mm_fp32_16_pure_half_wmma_cpasync_vec_hugebk(TransposeType transA, TransposeType transB,
                                                  double alpha, dim<2> size_A, const uint16_t* wh,
                                                  size_t ld_a, dim<2> size_B, const float* B,
                                                  size_t ld_b, double beta, float* C, size_t ld_c) {
    size_t m = size_A[0];
    size_t k = size_A[1];
    size_t n = size_B[1];
    if (transA != TransposeType::NO_TRANSPOSE || transB != TransposeType::NO_TRANSPOSE ||
        ld_a % 8 != 0 || m % 8 != 0 || ld_b % 4 != 0 || k % 4 != 0) {
        mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk_pad(transA, transB, alpha, size_A, wh, ld_a, size_B, B,
                                                        ld_b, beta, C, ld_c);
        return;
    }
    static bool attr_set = false;
    if (!attr_set) {
        cudaError_t e = cudaFuncSetAttribute(mm_fp32_16_pure_half_wmma_cpasync_vec_hugebk_kernel,
                                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                                             static_cast<int>(kMmFp32_16HugeSharedBytes));
        if (e != cudaSuccess) {
            cudaGetLastError();
            mm_fp32_16_pure_half_wmma_cpasync_vec_bigbk_pad(transA, transB, alpha, size_A, wh, ld_a, size_B, B,
                                                            ld_b, beta, C, ld_c);
            return;
        }
        attr_set = true;
    }
    float f_alpha = static_cast<float>(alpha);
    float f_beta = static_cast<float>(beta);
    __half h_alpha = static_cast<__half>(f_alpha);
    __half h_beta = static_cast<__half>(f_beta);
    dim3 threads(kMmFp32_16WmmaThreads);
    dim3 blocks((n + kMmFp32_16WmmaBN - 1) / kMmFp32_16WmmaBN,
               (m + kMmFp32_16WmmaBM - 1) / kMmFp32_16WmmaBM);
    mm_fp32_16_pure_half_wmma_cpasync_vec_hugebk_kernel<<<blocks, threads, kMmFp32_16HugeSharedBytes>>>(h_alpha, m, k, n, wh, ld_a, B, ld_b, h_beta, C, ld_c);
    cudaDeviceSynchronize();
}

}  // namespace experimental

void mm_fp32_16_pure_half(TransposeType transA, TransposeType transB,
                          double alpha, dim<2> size_A, const uint16_t* wh,
                          size_t ld_a, dim<2> size_B, const float* B,
                          size_t ld_b, double beta, float* C, size_t ld_c) {
    experimental::mm_fp32_16_pure_half(transA, transB, alpha, size_A, wh, ld_a, size_B, B, ld_b, beta, C, ld_c);
}


// Alias giving the existing (unqualified experimental::/cuda::) pure_half
// decode set a name symmetrical with experimental::conditional:: below --
// same entities, nothing moved or duplicated. See conditional's own header
// comment for the full explanation.
namespace experimental { namespace branchless = tomos::cuda::experimental; }

// ===========================================================================
// CONDITIONAL-DECODE DUPLICATE SET (added for A/B comparison)
//
// Every kernel/host-wrapper in this file that decodes fp32_16 "wh" pure_half
// data now uses fp32_16_half_only_branchless_no_overflow_nomask (the
// branchless, no-overflow-guaranteed, redundant-mask-removed decode
// promoted from test-new -- see decode.md). This block duplicates the
// EXACT pre-promotion bodies of that same set of functions verbatim
// (unchanged: fp32_16_half_only / fp32_16_half_only_fast2 /
// fp32_16_half_only_branchless, all of which check `direction` and
// distinguish overflow from underflow correctly -- see those functions'
// own comments in fp32_16_pack.hpp), under the SAME names, nested inside
// a new `conditional` namespace, purely so both decode strategies can be
// benchmarked/ncu-profiled side by side without one shadowing the other.
//
// Naming: the default (unqualified experimental::X / cuda::X) names above
// this block are the "branchless" set -- see the
// `namespace branchless = tomos::cuda::experimental;` alias declared
// right after this file's own `experimental` namespace closes, which
// gives that existing set a symmetrical qualified name
// (tomos::cuda::experimental::branchless::X, identical entities, no code
// moved or duplicated) to pair with tomos::cuda::experimental::conditional::X
// below. Do not edit the two sets independently expecting them to diverge
// in anything but decode -- if the branchless set's non-decode logic
// changes, this block will silently go stale; it exists for a decode A/B
// comparison, not as a second copy to maintain long-term.
// ===========================================================================

namespace experimental {
namespace conditional {

__global__ void mv_fp32_16_fast_tiled_kernel(TransposeType trans,
                                             double alpha, size_t m, size_t n,
                                             const uint16_t* wh, size_t ld_a,
                                             const float* x, double beta,
                                             float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    __shared__ float x_tile[kMvTileSize];
    double acc = 0.0;
    for (size_t tile_start = 0; tile_start < cols_op;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              cols_op - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = x[tile_start + threadIdx.x];
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                acc += static_cast<double>(fp32_16_half_only(wh[idx])) *
                       static_cast<double>(x_tile[jj]);
            }
        }
        __syncthreads();
    }

    if (i >= rows_op) return;
    y[i] = (beta != 0.0)
              ? static_cast<float>(alpha * acc + beta * static_cast<double>(y[i]))
              : static_cast<float>(alpha * acc);
}
__global__ void mv_fp32_16_fast_narrow_vec_kernel(TransposeType trans,
                                                  double alpha, size_t m,
                                                  size_t n,
                                                  const uint16_t* wh,
                                                  size_t ld_a,
                                                  const float* __restrict__ x,
                                                  double beta, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    // The vectorized load also requires ld_a to be a multiple of
    // kMvRowsPerThread: base = i0 + j*ld_a must stay 8-byte-aligned for
    // every j, and i0 alone (a multiple of kMvRowsPerThread by
    // construction) only guarantees that for j==0 unless ld_a is too.
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    double acc0 = 0.0, acc1 = 0.0, acc2 = 0.0, acc3 = 0.0;
    for (size_t j = 0; j < cols_op; ++j) {
        double x_val = static_cast<double>(__ldg(&x[j]));
        if (vectorized) {
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 += static_cast<double>(fp32_16_half_only(raw.x)) * x_val;
            acc1 += static_cast<double>(fp32_16_half_only(raw.y)) * x_val;
            acc2 += static_cast<double>(fp32_16_half_only(raw.z)) * x_val;
            acc3 += static_cast<double>(fp32_16_half_only(raw.w)) * x_val;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                double term = static_cast<double>(fp32_16_half_only(wh[idx])) * x_val;
                switch (k) {
                    case 0: acc0 += term; break;
                    case 1: acc1 += term; break;
                    case 2: acc2 += term; break;
                    default: acc3 += term; break;
                }
            }
        }
    }

    double acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        y[i] = (beta != 0.0)
                  ? static_cast<float>(alpha * acc[k] + beta * static_cast<double>(y[i]))
                  : static_cast<float>(alpha * acc[k]);
    }
}
__global__ void mv_fp32_16_fast_wide_kernel(TransposeType trans, size_t m,
                                              size_t n, const uint16_t* wh,
                                              size_t ld_a, const float* x,
                                              size_t col_splits,
                                              double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ float x_tile[kMvTileSize];
    double acc = 0.0;
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = x[tile_start + threadIdx.x];
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                acc += static_cast<double>(fp32_16_half_only(wh[idx])) *
                       static_cast<double>(x_tile[jj]);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) partial[blockIdx.y * rows_op + i] = acc;
}
void mv_fp32_16_fast(TransposeType trans, double alpha, dim<2> size,
                     const uint16_t* wh, size_t ld_a, const float* x,
                     size_t ld_x, double beta, float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        // rows_op alone can't reach kMvTargetTotalThreads threads here --
        // whether because the matrix is genuinely wide (few rows) or just
        // moderately sized (e.g. a square matrix well under that target) --
        // so split-K.
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_fast_wide_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        // Narrow matrix, few columns (see kMvNarrowVecColThreshold's comment).
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_fast_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        // Narrow matrix with enough columns for the register-blocked
        // variant (see kMvNarrowVecColThreshold): kMvRowsPerThread output
        // rows/thread, so the thread/block count is divided accordingly.
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_fast_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}
__global__ void mv_fp32_16_fast_wide_regblock_kernel(TransposeType trans,
                                                     size_t m, size_t n,
                                                     const uint16_t* wh,
                                                     size_t ld_a,
                                                     const float* __restrict__ x,
                                                     size_t col_splits,
                                                     double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    double acc0 = 0.0, acc1 = 0.0, acc2 = 0.0, acc3 = 0.0;
    for (size_t j = col_start; j < col_end; ++j) {
        double x_val = static_cast<double>(__ldg(&x[j]));
        if (vectorized) {
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 += static_cast<double>(fp32_16_half_only(raw.x)) * x_val;
            acc1 += static_cast<double>(fp32_16_half_only(raw.y)) * x_val;
            acc2 += static_cast<double>(fp32_16_half_only(raw.z)) * x_val;
            acc3 += static_cast<double>(fp32_16_half_only(raw.w)) * x_val;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                double term = static_cast<double>(fp32_16_half_only(wh[idx])) * x_val;
                switch (k) {
                    case 0: acc0 += term; break;
                    case 1: acc1 += term; break;
                    case 2: acc2 += term; break;
                    default: acc3 += term; break;
                }
            }
        }
    }

    double acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        partial[blockIdx.y * rows_op + i] = acc[k];
    }
}
void mv_fp32_16_fast_wide_regblock(TransposeType trans, double alpha,
                                   dim<2> size, const uint16_t* wh,
                                   size_t ld_a, const float* x, size_t ld_x,
                                   double beta, float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int row_blocks = static_cast<int>((row_groups + kMvTileSize - 1) / kMvTileSize);
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_fast_wide_regblock_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_fast_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_fast_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}
__global__ void mv_fp32_16_fast_wide_ilp_shared_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh,
    size_t ld_a, const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ float x_tile[kMvTileSize];
    double acc0 = 0.0, acc1 = 0.0, acc2 = 0.0, acc3 = 0.0;
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = x[tile_start + threadIdx.x];
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                acc0 += static_cast<double>(fp32_16_half_only(wh[idx0])) *
                       static_cast<double>(x_tile[jj]);
                acc1 += static_cast<double>(fp32_16_half_only(wh[idx1])) *
                       static_cast<double>(x_tile[jj + 1]);
                acc2 += static_cast<double>(fp32_16_half_only(wh[idx2])) *
                       static_cast<double>(x_tile[jj + 2]);
                acc3 += static_cast<double>(fp32_16_half_only(wh[idx3])) *
                       static_cast<double>(x_tile[jj + 3]);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                acc0 += static_cast<double>(fp32_16_half_only(wh[idx])) *
                       static_cast<double>(x_tile[jj]);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        double acc = (acc0 + acc1) + (acc2 + acc3);
        partial[blockIdx.y * rows_op + i] = acc;
    }
}
void mv_fp32_16_fast_wide_ilp_shared(TransposeType trans, double alpha,
                                    dim<2> size, const uint16_t* wh,
                                    size_t ld_a, const float* x, size_t ld_x,
                                    double beta, float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_fast_wide_ilp_shared_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_fast_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_fast_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}
__global__ void mm_fp32_16_fast_kernel(TransposeType transA,
                                       TransposeType transB, double alpha,
                                       size_t m, size_t k, size_t n,
                                       const uint16_t* wh, size_t ld_a,
                                       const float* B, size_t ld_b,
                                       double beta, float* C, size_t ld_c) {
    size_t i = blockIdx.y * blockDim.y + threadIdx.y;
    size_t j = blockIdx.x * blockDim.x + threadIdx.x;
    if (i >= m || j >= n) return;

    double acc = 0.0;
    for (size_t l = 0; l < k; ++l) {
        size_t a_row = (transA == TransposeType::NO_TRANSPOSE) ? i : l;
        size_t a_col = (transA == TransposeType::NO_TRANSPOSE) ? l : i;
        size_t idx = a_row + a_col * ld_a;
        double a_val = static_cast<double>(fp32_16_half_only(wh[idx]));
        double b_val = (transB == TransposeType::NO_TRANSPOSE)
                          ? static_cast<double>(B[l + j * ld_b])
                          : static_cast<double>(B[j + l * ld_b]);
        acc += a_val * b_val;
    }
    C[i + j * ld_c] = (beta != 0.0)
                          ? static_cast<float>(alpha * acc + beta * static_cast<double>(
                                                                 C[i + j * ld_c]))
                          : static_cast<float>(alpha * acc);
}
void mm_fp32_16_fast(TransposeType transA, TransposeType transB, double alpha,
                     dim<2> size_A, const uint16_t* wh, size_t ld_a,
                     dim<2> size_B, const float* B, size_t ld_b, double beta,
                     float* C, size_t ld_c) {
    size_t m = (transA == TransposeType::NO_TRANSPOSE) ? size_A[0] : size_A[1];
    size_t k = (transA == TransposeType::NO_TRANSPOSE) ? size_A[1] : size_A[0];
    size_t n = (transB == TransposeType::NO_TRANSPOSE) ? size_B[1] : size_B[0];

    dim3 threads(32, 8);
    dim3 blocks((n + threads.x - 1) / threads.x, (m + threads.y - 1) / threads.y);
    mm_fp32_16_fast_kernel<<<blocks, threads>>>(transA, transB, alpha, m, k, n,
                                                wh, ld_a, B, ld_b, beta, C,
                                                ld_c);
    cudaDeviceSynchronize();
}
__global__ void mv_fp32_16_pure_half_tiled_kernel(TransposeType trans,
                                                   double alpha, size_t m,
                                                   size_t n,
                                                   const uint16_t* wh,
                                                   size_t ld_a, const float* x,
                                                   double beta, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    __shared__ __half x_tile[kMvTileSize];
    __half acc = static_cast<__half>(0.0f);
    for (size_t tile_start = 0; tile_start < cols_op;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              cols_op - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only(wh[idx]);
                acc = acc + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i >= rows_op) return;
    double acc_d = static_cast<double>(static_cast<float>(acc));
    y[i] = (beta != 0.0)
              ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
              : static_cast<float>(alpha * acc_d);
}
