        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        double acc_d = static_cast<double>(static_cast<float>(acc[k]));
        y[i] = (beta != 0.0)
                  ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                  : static_cast<float>(alpha * acc_d);
    }
}
__global__ void mv_fp32_16_pure_half_fast2_narrow_vec_cpasync_kernel(TransposeType trans,
                                                        double alpha,
                                                        size_t m, size_t n,
                                                        const uint16_t* wh,
                                                        size_t ld_a,
                                                        const float* __restrict__ x,
                                                        double beta,
                                                        float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);

    if (!vectorized) {
        for (size_t j = 0; j < cols_op; ++j) {
            __half x_val = static_cast<__half>(__ldg(&x[j]));
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_fast2(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    } else {
        __shared__ ushort4 stageWh[2][kMvTileSize];
        const int tid = threadIdx.x;

        if (cols_op > 0) {
            __pipeline_memcpy_async(&stageWh[0][tid], &wh[i0], sizeof(ushort4));
            __pipeline_commit();
            __pipeline_wait_prior(0);
        }

        int cur = 0;
        for (size_t j = 0; j < cols_op; ++j) {
            size_t next_j = j + 1;
            int nxt = cur ^ 1;
            if (next_j < cols_op) {
                size_t base = i0 + next_j * ld_a;
                __pipeline_memcpy_async(&stageWh[nxt][tid], &wh[base], sizeof(ushort4));
                __pipeline_commit();
            }

            __half x_val = static_cast<__half>(__ldg(&x[j]));
            ushort4 raw = stageWh[cur][tid];
            acc0 = acc0 + fp32_16_half_only_fast2(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only_fast2(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only_fast2(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only_fast2(raw.w) * x_val;

            if (next_j < cols_op) __pipeline_wait_prior(0);
            cur = nxt;
        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        double acc_d = static_cast<double>(static_cast<float>(acc[k]));
        y[i] = (beta != 0.0)
                  ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                  : static_cast<float>(alpha * acc_d);
    }
}
void mv_fp32_16_pure_half_fast2_narrow_vec_cpasync(TransposeType trans, double alpha, size_t m, size_t n,
                                                     const uint16_t* wh, size_t ld_a, const float* x, double beta,
                                                     float* y) {
    int threads = kMvTileSize;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
    int blocks = static_cast<int>((row_groups + threads - 1) / threads);
    mv_fp32_16_pure_half_fast2_narrow_vec_cpasync_kernel<<<blocks, threads>>>(trans, alpha, m, n, wh, ld_a, x, beta,
                                                                               y);
}
__global__ void mv_fp32_16_pure_half_wide_kernel(TransposeType trans,
                                                    size_t m, size_t n,
                                                    const uint16_t* wh,
                                                    size_t ld_a,
                                                    const float* x,
                                                    size_t col_splits,
                                                    double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __half x_tile[kMvTileSize];
    __half acc = static_cast<__half>(0.0f);
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            for (size_t jj = 0; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only(wh[idx]);
                acc = acc + a_val * x_tile[jj];
            }
        }
        __syncthreads();
    }

    if (i < rows_op)
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
}
void mv_fp32_16_pure_half(TransposeType trans, double alpha, dim<2> size,
                          const uint16_t* wh, size_t ld_a, const float* x,
                          size_t ld_x, double beta, float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        // rows_op alone can't reach kMvTargetTotalThreads threads here --
        // whether because the matrix is genuinely wide (few rows) or just
        // moderately sized (e.g. a square matrix well under that target) --
        // so split-K.
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        // Narrow matrix, few columns (see kMvNarrowVecColThreshold's comment).
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        // Narrow matrix with enough columns for the register-blocked
        // variant (see kMvNarrowVecColThreshold): kMvRowsPerThread output
        // rows/thread, so the thread/block count is divided accordingly.
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}
__global__ void mv_fp32_16_pure_half_wide_regblock_kernel(TransposeType trans,
                                                          size_t m, size_t n,
                                                          const uint16_t* wh,
                                                          size_t ld_a,
                                                          const float* __restrict__ x,
                                                          size_t col_splits,
                                                          double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i0 = (blockIdx.x * blockDim.x + threadIdx.x) *
               static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    for (size_t j = col_start; j < col_end; ++j) {
        __half x_val = static_cast<__half>(__ldg(&x[j]));
        if (vectorized) {
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 = acc0 + fp32_16_half_only(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only(raw.w) * x_val;
        } else {
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    }

    __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
    for (int k = 0; k < kMvRowsPerThread; ++k) {
        size_t i = i0 + static_cast<size_t>(k);
        if (i >= rows_op) break;
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc[k]));
    }
}
void mv_fp32_16_pure_half_wide_regblock(TransposeType trans, double alpha,
                                        dim<2> size, const uint16_t* wh,
                                        size_t ld_a, const float* x,
                                        size_t ld_x, double beta, float* y,
                                        size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int row_blocks = static_cast<int>((row_groups + kMvTileSize - 1) / kMvTileSize);
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_regblock_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}
void mv_fp32_16_pure_half_wide_diag(TransposeType trans, double alpha,
                                    dim<2> size, const uint16_t* wh,
                                    size_t ld_a, const float* x, size_t ld_x,
                                    double beta, float* y, size_t ld_y,
                                    float* main_kernel_ms,
                                    float* reduce_kernel_ms) {
    *main_kernel_ms = 0.0f;
    *reduce_kernel_ms = 0.0f;
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op >= kMvWideRowThreshold) {
        mv_fp32_16_pure_half(trans, alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
        return;
    }

    int col_splits = choose_col_splits(rows_op, cols_op);
    int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    double* partial = nullptr;
    cudaError_t err = cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
    if (err != cudaSuccess) {
        cudaGetLastError();
        return;
    }

    cudaEvent_t e_start, e_mid, e_end;
    cudaEventCreate(&e_start);
    cudaEventCreate(&e_mid);
    cudaEventCreate(&e_end);

    dim3 grid(row_blocks, col_splits);
    cudaEventRecord(e_start);
    mv_fp32_16_pure_half_wide_kernel<<<grid, kMvTileSize>>>(
        trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
    cudaEventRecord(e_mid);
    int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
    mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
        alpha, beta, rows_op, col_splits, partial, y);
    cudaEventRecord(e_end);
    cudaEventSynchronize(e_end);
    cudaEventElapsedTime(main_kernel_ms, e_start, e_mid);
    cudaEventElapsedTime(reduce_kernel_ms, e_mid, e_end);

    cudaEventDestroy(e_start);
    cudaEventDestroy(e_mid);
    cudaEventDestroy(e_end);
    cudaFree(partial);
}
__global__ void mv_fp32_16_pure_half_wide_ilp_kernel(TransposeType trans,
                                                     size_t m, size_t n,
                                                     const uint16_t* wh,
                                                     size_t ld_a,
                                                     const float* __restrict__ x,
                                                     size_t col_splits,
                                                     double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    if (i < rows_op) {
        size_t j = col_start;
        for (; j + 4 <= col_end; j += 4) {
            size_t j0 = j, j1 = j + 1, j2 = j + 2, j3 = j + 3;
            size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
            size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
            size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
            size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
            size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
            size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
            size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
            size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
            size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
            size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
            __half a0 = fp32_16_half_only(wh[idx0]);
            __half a1 = fp32_16_half_only(wh[idx1]);
            __half a2 = fp32_16_half_only(wh[idx2]);
            __half a3 = fp32_16_half_only(wh[idx3]);
            __half x0 = static_cast<__half>(__ldg(&x[j0]));
            __half x1 = static_cast<__half>(__ldg(&x[j1]));
            __half x2 = static_cast<__half>(__ldg(&x[j2]));
            __half x3 = static_cast<__half>(__ldg(&x[j3]));
            acc0 = acc0 + a0 * x0;
            acc1 = acc1 + a1 * x1;
            acc2 = acc2 + a2 * x2;
            acc3 = acc3 + a3 * x3;
        }
        for (; j < col_end; ++j) {
            size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
            size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
            size_t idx = a_row + a_col * ld_a;
            __half a_val = fp32_16_half_only(wh[idx]);
            __half x_val = static_cast<__half>(__ldg(&x[j]));
            acc0 = acc0 + a_val * x_val;
        }
    }

    if (i < rows_op) {
        __half acc = (acc0 + acc1) + (acc2 + acc3);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}
void mv_fp32_16_pure_half_wide_ilp(TransposeType trans, double alpha,
                                   dim<2> size, const uint16_t* wh,
                                   size_t ld_a, const float* x, size_t ld_x,
                                   double beta, float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}
__global__ void __launch_bounds__(kMvTileSize, 8)
