}
__global__ void mv_fp32_16_pure_half_wide_warpgroup_kernel(
    TransposeType trans, double alpha, size_t m, size_t n,
    const uint16_t* wh, size_t ld_a, const float* __restrict__ x,
    double beta, float* y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;

    size_t warp_id = (blockIdx.x * blockDim.x + threadIdx.x) / 32;
    int lane = threadIdx.x % 32;
    size_t i0 = warp_id * static_cast<size_t>(kMvRowsPerThread);
    if (i0 >= rows_op) return;
    bool vectorized = (trans == TransposeType::NO_TRANSPOSE) &&
                      (i0 + kMvRowsPerThread <= rows_op) &&
                      (ld_a % static_cast<size_t>(kMvRowsPerThread) == 0);

    __half acc0 = static_cast<__half>(0.0f), acc1 = static_cast<__half>(0.0f);
    __half acc2 = static_cast<__half>(0.0f), acc3 = static_cast<__half>(0.0f);
    if (vectorized) {
        for (size_t j = lane; j < cols_op; j += 32) {
            __half x_val = static_cast<__half>(__ldg(&x[j]));
            size_t base = i0 + j * ld_a;
            ushort4 raw = *reinterpret_cast<const ushort4*>(&wh[base]);
            acc0 = acc0 + fp32_16_half_only(raw.x) * x_val;
            acc1 = acc1 + fp32_16_half_only(raw.y) * x_val;
            acc2 = acc2 + fp32_16_half_only(raw.z) * x_val;
            acc3 = acc3 + fp32_16_half_only(raw.w) * x_val;
        }
    } else {
        for (size_t j = lane; j < cols_op; j += 32) {
            __half x_val = static_cast<__half>(__ldg(&x[j]));
            for (int k = 0; k < kMvRowsPerThread; ++k) {
                size_t i = i0 + static_cast<size_t>(k);
                if (i >= rows_op) break;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only(wh[idx]);
                __half term = a_val * x_val;
                switch (k) {
                    case 0: acc0 = acc0 + term; break;
                    case 1: acc1 = acc1 + term; break;
                    case 2: acc2 = acc2 + term; break;
                    default: acc3 = acc3 + term; break;
                }
            }
        }
    }

    // Warp-level reduction, one accumulator at a time, via bit
    // reinterpretation (__half_as_ushort/__ushort_as_half, not a
    // memcpy-based reinterpretation -- see mv_fp32_16_pure_half_narrow_
    // vec_kernel's comment on why that specific pattern is required for
    // correctness on sm_80).
#pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        unsigned b0 = __shfl_down_sync(
            0xFFFFFFFF, static_cast<unsigned>(__half_as_ushort(acc0)), offset);
        unsigned b1 = __shfl_down_sync(
            0xFFFFFFFF, static_cast<unsigned>(__half_as_ushort(acc1)), offset);
        unsigned b2 = __shfl_down_sync(
            0xFFFFFFFF, static_cast<unsigned>(__half_as_ushort(acc2)), offset);
        unsigned b3 = __shfl_down_sync(
            0xFFFFFFFF, static_cast<unsigned>(__half_as_ushort(acc3)), offset);
        acc0 = acc0 + __ushort_as_half(static_cast<unsigned short>(b0));
        acc1 = acc1 + __ushort_as_half(static_cast<unsigned short>(b1));
        acc2 = acc2 + __ushort_as_half(static_cast<unsigned short>(b2));
        acc3 = acc3 + __ushort_as_half(static_cast<unsigned short>(b3));
    }

    if (lane == 0) {
        __half acc[kMvRowsPerThread] = {acc0, acc1, acc2, acc3};
        for (int k = 0; k < kMvRowsPerThread; ++k) {
            size_t i = i0 + static_cast<size_t>(k);
            if (i >= rows_op) break;
            double acc_d = static_cast<double>(static_cast<float>(acc[k]));
            y[i] = (beta != 0.0)
                      ? static_cast<float>(alpha * acc_d + beta * static_cast<double>(y[i]))
                      : static_cast<float>(alpha * acc_d);
        }
    }
}
