    } else {
        // Covers the real LSQR matrix's own shape (rows_op >=
        // kMvWideRowThreshold) -- measured directly (GEVM benchmark) to
        // match --explicit-duplicates' native_mixed to within ~2% here,
        // unlike narrow_vec_cpasync's own confirmed ~1.8x deficit.
        mv_fp32_16_pure_half_fast2_wide_ilp_shared_half2_atomic_best(TransposeType::NO_TRANSPOSE, alpha, size, wh,
                                                                       ld_a, x, ld_x, beta, y, ld_y);
    }
}
