__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only(wh[idx0]);
                __half a1 = fp32_16_half_only(wh[idx1]);
                __half a2 = fp32_16_half_only(wh[idx2]);
                __half a3 = fp32_16_half_only(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}
void mv_fp32_16_pure_half_wide_ilp_shared_half2(TransposeType trans,
                                                double alpha, dim<2> size,
                                                const uint16_t* wh,
                                                size_t ld_a, const float* x,
                                                size_t ld_x, double beta,
                                                float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        double* partial = nullptr;
        cudaError_t err =
            cudaMalloc(&partial, rows_op * col_splits * sizeof(double));
        if (err != cudaSuccess) {
            cudaGetLastError();
            return;
        }
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, partial);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, partial, y);
        cudaFree(partial);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
    cudaDeviceSynchronize();
}
void mv_fp32_16_pure_half_wide_ilp_shared_half2_combine_best(TransposeType trans, double alpha, dim<2> size,
                                                              const uint16_t* wh, size_t ld_a, const float* x,
                                                              size_t ld_x, double beta, float* y, size_t ld_y) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    if (rows_op < kMvPureHalfCombineBestCrossoverThreshold) {
        mv_fp32_16_pure_half_wide_ilp_shared_half2(trans, alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
    } else {
        mv_fp32_16_pure_half_wide_ilp_shared_half2_atomic_best(trans, alpha, size, wh, ld_a, x, ld_x, beta, y, ld_y);
    }
}
__global__ void mv_fp32_16_pure_half_wide_ilp_shared_half2_branchless_kernel(
    TransposeType trans, size_t m, size_t n, const uint16_t* wh, size_t ld_a,
    const float* x, size_t col_splits, double* partial) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? m : n;
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? n : m;
    size_t i = blockIdx.x * blockDim.x + threadIdx.x;

    size_t chunk = (cols_op + col_splits - 1) / col_splits;
    size_t col_start = blockIdx.y * chunk;
    size_t col_end = min(col_start + chunk, cols_op);

    __shared__ __align__(4) __half x_tile[kMvTileSize];
    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));
    for (size_t tile_start = col_start; tile_start < col_end;
         tile_start += kMvTileSize) {
        size_t tile_len = min(static_cast<size_t>(kMvTileSize),
                              col_end - tile_start);
        if (threadIdx.x < tile_len)
            x_tile[threadIdx.x] = static_cast<__half>(x[tile_start + threadIdx.x]);
        __syncthreads();

        if (i < rows_op) {
            size_t jj = 0;
            for (; jj + 4 <= tile_len; jj += 4) {
                size_t j0 = tile_start + jj, j1 = j0 + 1, j2 = j0 + 2, j3 = j0 + 3;
                size_t r0 = (trans == TransposeType::NO_TRANSPOSE) ? i : j0;
                size_t c0 = (trans == TransposeType::NO_TRANSPOSE) ? j0 : i;
                size_t r1 = (trans == TransposeType::NO_TRANSPOSE) ? i : j1;
                size_t c1 = (trans == TransposeType::NO_TRANSPOSE) ? j1 : i;
                size_t r2 = (trans == TransposeType::NO_TRANSPOSE) ? i : j2;
                size_t c2 = (trans == TransposeType::NO_TRANSPOSE) ? j2 : i;
                size_t r3 = (trans == TransposeType::NO_TRANSPOSE) ? i : j3;
                size_t c3 = (trans == TransposeType::NO_TRANSPOSE) ? j3 : i;
                size_t idx0 = r0 + c0 * ld_a, idx1 = r1 + c1 * ld_a;
                size_t idx2 = r2 + c2 * ld_a, idx3 = r3 + c3 * ld_a;
                __half a0 = fp32_16_half_only_branchless(wh[idx0]);
                __half a1 = fp32_16_half_only_branchless(wh[idx1]);
                __half a2 = fp32_16_half_only_branchless(wh[idx2]);
                __half a3 = fp32_16_half_only_branchless(wh[idx3]);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&x_tile[jj]);
                __half2 x23 = *reinterpret_cast<__half2*>(&x_tile[jj + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
            for (; jj < tile_len; ++jj) {
                size_t j = tile_start + jj;
                size_t a_row = (trans == TransposeType::NO_TRANSPOSE) ? i : j;
                size_t a_col = (trans == TransposeType::NO_TRANSPOSE) ? j : i;
                size_t idx = a_row + a_col * ld_a;
                __half a_val = fp32_16_half_only_branchless(wh[idx]);
                __half2 a_pad = __halves2half2(a_val, static_cast<__half>(0.0f));
                __half2 x_pad =
                    __halves2half2(x_tile[jj], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
        __syncthreads();
    }

    if (i < rows_op) {
        __half2 acc_sum2 = __hadd2(acc01, acc23);
        __half acc = __low2half(acc_sum2) + __high2half(acc_sum2);
        partial[blockIdx.y * rows_op + i] =
            static_cast<double>(static_cast<float>(acc));
    }
}
void mv_fp32_16_pure_half_wide_ilp_shared_half2_branchless_workspace(TransposeType trans,
                                                                      double alpha, dim<2> size,
                                                                      const uint16_t* wh,
                                                                      size_t ld_a, const float* x,
                                                                      size_t ld_x, double beta,
                                                                      float* y, size_t ld_y,
                                                                      double* workspace) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_branchless_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, workspace);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, workspace, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}
void mv_fp32_16_pure_half_wide_ilp_shared_half2_workspace(TransposeType trans,
                                                           double alpha, dim<2> size,
                                                           const uint16_t* wh,
                                                           size_t ld_a, const float* x,
                                                           size_t ld_x, double beta,
                                                           float* y, size_t ld_y,
                                                           double* workspace) {
    size_t rows_op = (trans == TransposeType::NO_TRANSPOSE) ? size[0] : size[1];
    size_t cols_op = (trans == TransposeType::NO_TRANSPOSE) ? size[1] : size[0];
    if (rows_op < kMvWideRowThreshold) {
        int col_splits = choose_col_splits(rows_op, cols_op);
        int row_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        dim3 grid(row_blocks, col_splits);
        mv_fp32_16_pure_half_wide_ilp_shared_half2_kernel<<<grid, kMvTileSize>>>(
            trans, size[0], size[1], wh, ld_a, x, col_splits, workspace);
        int reduce_blocks = (rows_op + kMvTileSize - 1) / kMvTileSize;
        mv_fp32_16_wide_reduce_kernel<<<reduce_blocks, kMvTileSize>>>(
            alpha, beta, rows_op, col_splits, workspace, y);
    } else if (cols_op < kMvNarrowVecColThreshold) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_pure_half_tiled_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    } else {
        int threads = kMvTileSize;
        size_t row_groups = (rows_op + kMvRowsPerThread - 1) / kMvRowsPerThread;
        int blocks = static_cast<int>((row_groups + threads - 1) / threads);
        mv_fp32_16_pure_half_narrow_vec_kernel<<<blocks, threads>>>(
            trans, alpha, size[0], size[1], wh, ld_a, x, beta, y);
    }
}
__global__ void mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ y,
    int m, int k, int M_BLOCK, float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    if (col >= k) return;

    const int mStart = blockIdx.x * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ __half sx_half[];
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;

    // Scalar staging (float -> __half convert) -- x's own total traffic
    // per block (M_BLOCK floats, staged once, reused by all warpsPerBlock
    // warps) is negligible next to wh's own (M_BLOCK*k uint16_t reads
    // overall), so vectorizing THIS loop specifically buys little; the
    // wh load below is where the real fix lives.
    for (int r = mStart + tid; r < mEnd; r += nt) {
        sx_half[r - mStart] = __float2half(__ldg(&x[r]));
    }
    __syncthreads();

    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    __half2 acc01 = __half2half2(static_cast<__half>(0.0f));
    __half2 acc23 = __half2half2(static_cast<__half>(0.0f));

    const int vBeg = (mStart + 3) & ~3;
    const int vEnd = mEnd & ~3;

    // Scalar prefix: [mStart, min(vBeg, mEnd))
    for (int r = mStart + lane; r < min(vBeg, mEnd); r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    if (vBeg < vEnd) {
        const size_t idxBeg = colBase + static_cast<size_t>(vBeg);
        const uintptr_t pWh = reinterpret_cast<uintptr_t>(&wh[idxBeg]);
        const uintptr_t pX = reinterpret_cast<uintptr_t>(&sx_half[vBeg - mStart]);
        // wh needs 8-byte alignment for a ushort4 (4x uint16_t) load;
        // sx_half needs 4-byte alignment for a __half2 load.
        const bool aligned = ((pWh & 0x7) == 0) && ((pX & 0x3) == 0);

        if (aligned) {
            for (int r = vBeg + lane * 4; r + 3 < vEnd; r += 32 * 4) {
                const size_t idx = colBase + static_cast<size_t>(r);
                const ushort4 whv = *reinterpret_cast<const ushort4*>(&wh[idx]);
                __half a0 = fp32_16_half_only(whv.x);
                __half a1 = fp32_16_half_only(whv.y);
                __half a2 = fp32_16_half_only(whv.z);
                __half a3 = fp32_16_half_only(whv.w);
                __half2 a01 = __halves2half2(a0, a1);
                __half2 a23 = __halves2half2(a2, a3);
                __half2 x01 = *reinterpret_cast<__half2*>(&sx_half[r - mStart]);
                __half2 x23 = *reinterpret_cast<__half2*>(&sx_half[r - mStart + 2]);
                acc01 = __hfma2(a01, x01, acc01);
                acc23 = __hfma2(a23, x23, acc23);
            }
        } else {
            // Unaligned fallback -- still correct, just not vectorized.
            for (int r = vBeg + lane; r < vEnd; r += 32) {
                const size_t idx = colBase + static_cast<size_t>(r);
                __half a = fp32_16_half_only(wh[idx]);
                __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
                __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
                acc01 = __hfma2(a_pad, x_pad, acc01);
            }
        }
    }

    // Scalar suffix: [vEnd, mEnd)
    for (int r = vEnd + lane; r < mEnd; r += 32) {
        const size_t idx = colBase + static_cast<size_t>(r);
        __half a = fp32_16_half_only(wh[idx]);
        __half2 a_pad = __halves2half2(a, static_cast<__half>(0.0f));
        __half2 x_pad = __halves2half2(sx_half[r - mStart], static_cast<__half>(0.0f));
        acc01 = __hfma2(a_pad, x_pad, acc01);
    }

    __half2 acc2 = __hadd2(acc01, acc23);
    float accum = __half2float(__low2half(acc2)) + __half2float(__high2half(acc2));

    unsigned mask = 0xffffffffu;
#pragma unroll
    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0) atomicAdd(&y[col], alpha * accum);
}
void mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4(TransposeType trans, double alpha, dim<2> size,
                                                                    const uint16_t* wh, size_t ld_a, const float* x,
                                                                    size_t ld_x, double beta, float* y,
                                                                    size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(float));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvTransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, 1);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_kernel<<<grid, block, shmem>>>(
        wh, x, y, m, k, M_BLOCK, static_cast<float>(alpha));
}
void mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_retuned_floor(
    TransposeType trans, double alpha, dim<2> size, const uint16_t* wh, size_t ld_a, const float* x, size_t ld_x,
    double beta, float* y, size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(float));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_kernel<<<grid, block, shmem>>>(
        wh, x, y, m, k, M_BLOCK, static_cast<float>(alpha));
}
__global__ void mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_half_io_kernel(
    const uint16_t* __restrict__ wh, const __half* __restrict__ x, __half* __restrict__ y,
    int m, int k, int M_BLOCK, float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    if (col >= k) return;

