    for (int off = 16; off > 0; off >>= 1)
        accum += __shfl_down_sync(mask, accum, off);

    if (lane == 0) atomicAdd(&y[col], __float2half(alpha * accum));
}
void mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_half_io_retuned_floor(
    TransposeType trans, double alpha, dim<2> size, const uint16_t* wh, size_t ld_a, const __half* x, size_t ld_x,
    double beta, __half* y, size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(__half));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_half_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    int gridK = (k + kMvTransposeWarpsPerBlock - 1) / kMvTransposeWarpsPerBlock;
    int M_BLOCK = kMvTransposeMBlock;
    int target_gridM = (kMvFp32_16TransposeTargetGridBlocks + gridK - 1) / gridK;
    if (target_gridM > 1) {
        int scaled_block = (m + target_gridM - 1) / target_gridM;
        if (scaled_block < M_BLOCK) M_BLOCK = std::max(scaled_block, kMvFp32_16TransposeMinMBlock);
    }

    dim3 block(32, kMvTransposeWarpsPerBlock);
    int gridM = (m + M_BLOCK - 1) / M_BLOCK;
    dim3 grid(gridM, gridK);
    size_t shmem = static_cast<size_t>(std::min(M_BLOCK, m)) * sizeof(__half);

    mv_fp32_16_pure_half_transpose_atomiconly_scaled_mblock_vec4_half_io_kernel<<<grid, block, shmem>>>(
        wh, x, y, m, k, M_BLOCK, static_cast<float>(alpha));
}
__global__ void mv_fp32_16_pure_half_transpose_warp_owner_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, float* __restrict__ y,
    int m, int k, float alpha) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;

    __shared__ float x_sh[kMvFp32_16TransposeWarpdotMTile];

    float accum = 0.f;
    const size_t ld = static_cast<size_t>(m);
    const size_t colBase = static_cast<size_t>(col) * ld;

    for (int r0 = 0; r0 < m; r0 += kMvFp32_16TransposeWarpdotMTile) {
        const int tileLen = min(kMvFp32_16TransposeWarpdotMTile, m - r0);

        for (int t = warpId * 32 + lane; t < tileLen; t += warpsPerBlock * 32) {
            x_sh[t] = __ldg(&x[r0 + t]);
        }
        __syncthreads();

        if (col < k) {
            // Vectorized, alignment-safe pair processing: 2 rows at a
            // time per lane (adjacent rows in the same column-major
            // column are memory-adjacent uint16_t elements).
            for (int t = lane * 2; t + 1 < tileLen; t += 64) {
                const size_t idx = colBase + static_cast<size_t>(r0 + t);
                uint16_t lo, hi;
                fp32_16_load_pair_unaligned(&wh[idx], lo, hi);
                float a0 = __half2float(fp32_16_half_only(lo));
                float a1 = __half2float(fp32_16_half_only(hi));
                accum = fmaf(a0, x_sh[t], accum);
                accum = fmaf(a1, x_sh[t + 1], accum);
            }
            // Odd tail: handle the last leftover row once.
            if ((tileLen & 1) && lane == 0) {
                const int t1 = tileLen - 1;
                const size_t idx = colBase + static_cast<size_t>(r0 + t1);
                float a = __half2float(fp32_16_half_only(wh[idx]));
                accum = fmaf(a, x_sh[t1], accum);
            }
        }
        __syncthreads();
    }

    if (col < k) {
        unsigned mask = 0xffffffffu;
#pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            accum += __shfl_down_sync(mask, accum, off);

        if (lane == 0) y[col] += alpha * accum;
    }
}
void mv_fp32_16_pure_half_transpose_warp_owner(TransposeType trans, double alpha, dim<2> size, const uint16_t* wh,
                                                size_t ld_a, const float* x, size_t ld_x, double beta, float* y,
                                                size_t ld_y) {
    if (trans != TransposeType::TRANSPOSE || ld_a != size[0]) return;

    int m = static_cast<int>(size[0]);
    int k = static_cast<int>(size[1]);
    size_t rows_op = size[1];

    if (beta == 0.0) {
        cudaMemsetAsync(y, 0, rows_op * sizeof(float));
    } else if (beta != 1.0) {
        int threads = kMvTileSize;
        int blocks = (rows_op + threads - 1) / threads;
        mv_fp32_16_scale_y_kernel<<<blocks, threads>>>(rows_op, beta, y);
    }

    dim3 block(32, kMvFp32_16TransposeWarpdotWarpsPerBlock);
    dim3 grid(1, (k + kMvFp32_16TransposeWarpdotWarpsPerBlock - 1) / kMvFp32_16TransposeWarpdotWarpsPerBlock);

    mv_fp32_16_pure_half_transpose_warp_owner_kernel<<<grid, block>>>(wh, x, y, m, k, static_cast<float>(alpha));
}
__global__ void mv_fp32_16_pure_half_transpose_warp_owner_split_kernel(
    const uint16_t* __restrict__ wh, const float* __restrict__ x, double* __restrict__ partial,
    int m, int k, int M_BLOCK) {
    const int lane = threadIdx.x;
    const int warpId = threadIdx.y;
    const int warpsPerBlock = blockDim.y;

    const int col = blockIdx.y * warpsPerBlock + warpId;
    const int splitIdx = blockIdx.x;

    const int mStart = splitIdx * M_BLOCK;
    const int mEnd = min(m, mStart + M_BLOCK);
    if (mStart >= mEnd) return;

    extern __shared__ float x_sh[];
    const int tileLen = mEnd - mStart;
    const int tid = lane + 32 * warpId;
    const int nt = 32 * warpsPerBlock;
    for (int t = tid; t < tileLen; t += nt) x_sh[t] = __ldg(&x[mStart + t]);
    __syncthreads();

    if (col < k) {
        const size_t ld = static_cast<size_t>(m);
        const size_t colBase = static_cast<size_t>(col) * ld;

        float accum = 0.f;
        for (int t = lane * 2; t + 1 < tileLen; t += 64) {
            const size_t idx = colBase + static_cast<size_t>(mStart + t);
            uint16_t lo, hi;
            fp32_16_load_pair_unaligned(&wh[idx], lo, hi);
            float a0 = __half2float(fp32_16_half_only(lo));
            float a1 = __half2float(fp32_16_half_only(hi));
            accum = fmaf(a0, x_sh[t], accum);
            accum = fmaf(a1, x_sh[t + 1], accum);
        }
        if ((tileLen & 1) && lane == 0) {
            const int t1 = tileLen - 1;
            const size_t idx = colBase + static_cast<size_t>(mStart + t1);
            float a = __half2float(fp32_16_half_only(wh[idx]));
            accum = fmaf(a, x_sh[t1], accum);
        }

        unsigned mask = 0xffffffffu;
#pragma unroll
        for (int off = 16; off > 0; off >>= 1)
            accum += __shfl_down_sync(mask, accum, off);

        if (lane == 0)
            partial[static_cast<size_t>(splitIdx) * static_cast<size_t>(k) + static_cast<size_t>(col)] =
                static_cast<double>(accum);
    }
}
